#include "util.h"

static void oom(void) { fprintf(stderr, "tcc: error: memory full\n"); exit(1); }

void *xmalloc(size_t n) { void *p = malloc(n ? n : 1); if (!p) oom(); return p; }
void *xcalloc(size_t n) { void *p = calloc(1, n ? n : 1); if (!p) oom(); return p; }
void *xrealloc(void *p, size_t n) { p = realloc(p, n ? n : 1); if (!p) oom(); return p; }
char *xstrdup(const char *s) { return xstrndup(s, strlen(s)); }
char *xstrndup(const char *s, size_t n) { char *r = xmalloc(n + 1); memcpy(r, s, n); r[n] = 0; return r; }

void str_init(Str *b) { b->s = NULL; b->len = b->cap = 0; }
void str_free(Str *b) { free(b->s); str_init(b); }
void str_clear(Str *b) { b->len = 0; }
void str_grow(Str *b, int need)
{
    if (b->len + need + 1 > b->cap) {
        int nc = b->cap ? b->cap : 64;
        while (nc < b->len + need + 1) nc *= 2;
        b->s = xrealloc(b->s, nc);
        b->cap = nc;
    }
}
void str_putc(Str *b, int c) { str_grow(b, 1); b->s[b->len++] = (char)c; }
void str_putn(Str *b, const char *s, int n) { str_grow(b, n); memcpy(b->s + b->len, s, n); b->len += n; }
void str_puts(Str *b, const char *s) { str_putn(b, s, strlen(s)); }
void str_vprintf(Str *b, const char *fmt, va_list ap)
{
    va_list ap2;
    va_copy(ap2, ap);
    int n = vsnprintf(NULL, 0, fmt, ap2);
    va_end(ap2);
    str_grow(b, n + 1);
    vsnprintf(b->s + b->len, n + 1, fmt, ap);
    b->len += n;
}
void str_printf(Str *b, const char *fmt, ...)
{
    va_list ap; va_start(ap, fmt); str_vprintf(b, fmt, ap); va_end(ap);
}
char *str_cstr(Str *b) { str_grow(b, 1); b->s[b->len] = 0; return b->s; }

void pvec_push(PVec *p, void *x)
{
    if (p->n == p->cap) { p->cap = p->cap ? p->cap * 2 : 8; p->v = xrealloc(p->v, p->cap * sizeof(void *)); }
    p->v[p->n++] = x;
}

const char *path_basename(const char *p)
{
    const char *b = p;
    for (; *p; p++) if (*p == '/') b = p + 1;
    return b;
}
const char *path_ext(const char *p)
{
    const char *b = path_basename(p);
    const char *e = strrchr(b, '.');
    return e ? e : b + strlen(b);
}
int starts_with(const char *s, const char *pre, const char **rest)
{
    size_t n = strlen(pre);
    if (strncmp(s, pre, n)) return 0;
    if (rest) *rest = s + n;
    return 1;
}
