/* lexical analysis: source files, identifiers, raw tokens, diagnostics */
#include "cc.h"

SrcFile *file;
int tok;
TokVal tokc;
const int *mac_ptr;
int lexflags;
int tflags;
Str tokstr;
int pp_in_expr;
int nb_errors, nb_warnings;
SrcFile *inc_stack[64];
SrcFile **inc_sp = inc_stack;
int total_lines, total_idents, total_bytes;
jmp_buf err_jmp;
int err_jmp_set;
int in_cleanup_errors;

/* ------------------------------------------------------------ identifiers */
#define HASH_SIZE 16384
static Ident *hash_tab[HASH_SIZE];
static Ident **ident_arr;
static int ident_n, ident_cap;
static int next_tok = T_IDENT;

static const char *const kw_names[] = {
#define K(id, s) s,
#include "keywords.h"
#undef K
};

static unsigned hash_str(const char *s, int len)
{
    unsigned h = 1;
    for (int i = 0; i < len; i++) h = (h + (h << 5) + (h >> 27)) + (unsigned char)s[i];
    return h & (HASH_SIZE - 1);
}

Ident *ident_get(const char *s, int len)
{
    unsigned h = hash_str(s, len);
    Ident *p;
    for (p = hash_tab[h]; p; p = p->hnext)
        if (p->len == len && !memcmp(p->s, s, len))
            return p;
    p = xcalloc(sizeof(Ident) + len);
    memcpy(p->s, s, len);
    p->s[len] = 0;
    p->len = len;
    p->tok = next_tok++;
    p->hnext = hash_tab[h];
    hash_tab[h] = p;
    if (ident_n == ident_cap) {
        ident_cap = ident_cap ? ident_cap * 2 : 1024;
        ident_arr = xrealloc(ident_arr, ident_cap * sizeof(Ident *));
    }
    ident_arr[ident_n++] = p;
    total_idents++;
    return p;
}

int ident_tok(const char *s) { return ident_get(s, strlen(s))->tok; }

Ident *ident_of(int t)
{
    t &= ~(SYM_STRUCT | SYM_FIELD | NOEXP_BIT);
    if (t < T_IDENT || t >= next_tok) return NULL;
    return ident_arr[t - T_IDENT];
}

void lex_init_idents(void)
{
    for (unsigned i = 0; i < sizeof(kw_names) / sizeof(kw_names[0]); i++)
        ident_get(kw_names[i], strlen(kw_names[i]));
}

/* ------------------------------------------------------------ char classes */
int is_space_ch(int c) { return c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r'; }
int is_id_ch(int c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == '$' || c >= 0x80;
}
static int is_idnum(int c) { return is_id_ch(c) || (c >= '0' && c <= '9'); }

/* ------------------------------------------------------------ diagnostics */
static void diag(int kind, const char *fmt, va_list ap)
{
    /* kind: 0 warning, 1 error */
    Str b;
    str_init(&b);
    SrcFile *f = file;
    if (f) {
        for (SrcFile **pf = inc_stack; pf < inc_sp; pf++)
            str_printf(&b, "In file included from %s:%d:\n", (*pf)->name, (*pf)->line - 1);
        int ln = f->line;
        if ((tflags & TF_BOL) && !mac_ptr) ln--;
        str_printf(&b, "%s:%d: ", f->name, ln);
    } else {
