        str_vprintf(&b, fmt, ap);
    } else
        str_vprintf(&b, fmt, ap);
    str_putc(&b, '\n');
    fflush(stdout);
    fputs(str_cstr(&b), stderr);
    fflush(stderr);
    str_free(&b);
}

extern void pp_expr_error(void) __attribute__((noreturn));

static void do_abort(void)
{
    if (err_jmp_set)
        longjmp(err_jmp, 1);
    exit(1);
}

void error(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    if (pp_in_expr > 0) {
        va_end(ap);
        pp_expr_error();
    }
    diag(1, fmt, ap);
    va_end(ap);
    nb_errors++;
    do_abort();
}

void error_noabort(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    diag(1, fmt, ap);
    va_end(ap);
    nb_errors++;
}

void warning(const char *fmt, ...)
{
    va_list ap;
    if (opt.w_none) return;
    va_start(ap, fmt);
    if (opt.w_error) {
        diag(1, fmt, ap);
        nb_errors++;
    } else
        diag(0, fmt, ap);
    va_end(ap);
    nb_warnings++;
}

void warning_opt(int which, const char *fmt, ...)
{
    va_list ap;
    int on = 1, err = opt.w_error;
    switch (which) {
    case WOPT_IMPLICIT: on = opt.w_implicit_decl & 1; err |= opt.w_error_implicit_decl; break;
    case WOPT_DISCARDED: on = opt.w_discarded_qual & 1; err |= opt.w_error_discarded; break;
    case WOPT_WRITE_STRINGS: on = opt.w_write_strings & 1; err |= opt.w_error_write_strings; break;
    case WOPT_UNSUPPORTED: on = opt.w_unsupported & 1; err |= opt.w_error_unsupported; break;
    case WOPT_ALL: on = opt.w_all; break;
    }
    if (!on || opt.w_none) return;
    va_start(ap, fmt);
    if (err) {
        diag(1, fmt, ap);
        nb_errors++;
    } else
        diag(0, fmt, ap);
    va_end(ap);
    nb_warnings++;
}

/* ------------------------------------------------------------ token sequences */
void tseq_init(TokSeq *s) { memset(s, 0, sizeof *s); s->line = -1; }
TokSeq *tseq_new(void) { TokSeq *s = xcalloc(sizeof *s); s->line = -1; return s; }
void tseq_free_arr(int *a) { free(a); }
void tseq_free(TokSeq *s) { free(s->a); free(s); }

static int *tseq_room(TokSeq *s, int n)
{
    if (s->n + n > s->cap) {
        int c = s->cap ? s->cap : 16;
        while (c < s->n + n) c *= 2;
        s->a = xrealloc(s->a, c * sizeof(int));
        s->cap = c;
    }
    int *p = s->a + s->n;
    s->n += n;
    return p;
}

void tseq_add(TokSeq *s, int t)
{
    s->lastn = s->n;
    *tseq_room(s, 1) = t;
}

void tseq_add_val(TokSeq *s, int t, TokVal *cv)
{
    int len = s->n;
    s->lastn = len;
    switch (t) {
    case T_CHAR: case T_WCHAR: case T_INT: case T_UINT: case T_LINE:
    case T_LONG: case T_ULONG: case T_LLONG: case T_ULLONG: case T_DOUBLE: {
        int *p = tseq_room(s, 3);
        p[0] = t; memcpy(p + 1, &cv->i, 8);
        break;
    }
    case T_FLOAT: {
        int *p = tseq_room(s, 2);
        p[0] = t; memcpy(p + 1, &cv->f, 4);
        break;
    }
    case T_LDOUBLE: {
        int *p = tseq_room(s, 5);
        p[0] = t; memcpy(p + 1, &cv->ld, 16);
        break;
    }
    case T_STR: case T_WSTR: case T_PPNUM: case T_PPSTR: {
        int n = cv->str.n;
        int w = (n + 3) / 4;
        int *p = tseq_room(s, 2 + w);
        p[0] = t; p[1] = n;
        memcpy(p + 2, cv->str.s, n);
        break;
    }
    default:
        *tseq_room(s, 1) = t;
        break;
    }
}

/* add current token, recording line number changes */
void tseq_add_cur(TokSeq *s)
{
    if (file && s->line != file->line) {
        TokVal v;
        s->line = file->line;
        v.i = file->line;
        tseq_add_val(s, T_LINE, &v);
    }
    tseq_add_val(s, tok, &tokc);
}

void tseq_get(int *t, const int **pp, TokVal *cv)
{
    const int *p = *pp;
    int n;
    *t = n = *p;
    switch (n) {
    case T_CHAR: case T_WCHAR: case T_INT: case T_UINT: case T_LINE:
    case T_LONG: case T_ULONG: case T_LLONG: case T_ULLONG: case T_DOUBLE:
        memcpy(&cv->i, p + 1, 8); p += 3; break;
    case T_FLOAT:
        memcpy(&cv->f, p + 1, 4); p += 2; break;
    case T_LDOUBLE:
        memcpy(&cv->ld, p + 1, 16); p += 5; break;
    case T_STR: case T_WSTR: case T_PPNUM: case T_PPSTR:
        cv->str.n = p[1];
        cv->str.s = (char *)(p + 2);
        p += 2 + (p[1] + 3) / 4;
        break;
    default:
        p++;
        break;
    }
    *pp = p;
}

/* ------------------------------------------------------------ readers */
typedef struct Reader {
    struct Reader *prev;
    const int *saved_ptr;
    int *owned;     /* array to free */
    TokSeq *seq;    /* sequence to free */
    int saved_line;
    int kind;
} Reader;
static Reader *readers;

void push_reader(TokSeq *s, int owned)
{
    Reader *r = xcalloc(sizeof *r);
    r->prev = readers;
    r->saved_ptr = mac_ptr;
    r->kind = owned;
    if (owned == 1) r->seq = s;
    else if (owned == 3) r->owned = s->a;
    r->saved_line = file ? file->line : 0;
    readers = r;
    mac_ptr = s->a;
}

/* push raw int array */
void push_reader_arr(const int *a, int *owned)
{
    Reader *r = xcalloc(sizeof *r);
    r->prev = readers;
    r->saved_ptr = mac_ptr;
    r->owned = owned;
    r->saved_line = -1;
    readers = r;
    mac_ptr = a;
}

void pop_reader(void)
{
    Reader *r = readers;
    if (!r) { mac_ptr = NULL; return; }
    readers = r->prev;
    mac_ptr = r->saved_ptr;
    if (r->seq) tseq_free(r->seq);
    if (r->owned) free(r->owned);
    if (r->saved_line >= 0 && file && r->kind != 2)
        file->line = r->saved_line;
    free(r);
}

int reader_depth(void)
{
    int n = 0;
    for (Reader *r = readers; r; r = r->prev) n++;
    return n;
}

void *reader_top(void) { return readers; }

/* ------------------------------------------------------------ source files */
static SrcFile *src_alloc(const char *name, unsigned char *data, int len)
{
    SrcFile *f = xcalloc(sizeof *f);
    f->buf = data;
    f->p = data;
    f->end = data + len;
    snprintf(f->name, sizeof f->name, "%s", name);
    f->true_name = xstrdup(f->name);
    f->line = 1;
    f->up = file;
    f->cond_base = cond_sp;
    f->saved_tflags = tflags;
    file = f;
    tflags = TF_BOL | TF_BOF;
    return f;
}

void src_open_buf(const char *name, const char *data, int len)
{
    unsigned char *b = xmalloc(len + 4);
    memcpy(b, data, len);
    b[len] = 0; b[len+1] = 0; b[len+2] = 0;
    src_alloc(name, b, len);
}

int src_open(const char *fn)
{
    int fd;
    if (!strcmp(fn, "-"))
        fd = 0, fn = "<stdin>";
    else
        fd = open(fn, O_RDONLY);
    if (fd < 0) return -1;
    Str b;
    str_init(&b);
    char tmp[65536];
    for (;;) {
        ssize_t n = read(fd, tmp, sizeof tmp);
        if (n <= 0) break;
        str_putn(&b, tmp, n);
    }
    if (fd) close(fd);
    str_grow(&b, 4);
    memset(b.s + b.len, 0, 4);
    total_bytes += b.len;
    src_alloc(fn, (unsigned char *)b.s, b.len);
    return 0;
}

void src_close(void)
{
    SrcFile *f = file;
    if (!f) return;
    total_lines += f->line;
    file = f->up;
    tflags = f->saved_tflags;
    free(f->buf);
    free(f->true_name);
    free(f);
}

/* ------------------------------------------------------------ raw char access */
/* skip backslash-newline sequences at p */
static unsigned char *bsnl(unsigned char *p)
{
    while (*p == '\\') {
        if (p[1] == '\n') { file->line++; p += 2; }
        else if (p[1] == '\r' && p[2] == '\n') { file->line++; p += 3; }
        else break;
    }
    return p;
}

#define CH(p) ((p) < file->end ? *(p) : -1)

/* peek char at p after continuation handling; updates p */
static int pk(unsigned char **pp)
{
    unsigned char *p = *pp;
    if (*p == '\\') p = bsnl(p);
    *pp = p;
    return CH(p);
}

/* skip a C comment starting after the '/' '*', returns pointer after it */
static unsigned char *skip_comment(unsigned char *p)
{
    for (;;) {
        int c = CH(p);
        if (c == -1) {
            error("unexpected end of file in comment");
        }
        if (c == '\n') { file->line++; p++; continue; }
        if (c == '*') {
            p++;
            for (;;) {
                c = pk(&p);
                if (c == '*') { p++; continue; }
                break;
            }
            if (c == '/') return p + 1;
            continue;
        }
        p++;
    }
}

static unsigned char *skip_line_comment(unsigned char *p)
{
    for (;;) {
        int c = CH(p);
        if (c == -1 || c == '\n') return p;
        if (c == '\\') {
            unsigned char *q = bsnl(p);
            if (q != p) { p = q; continue; }
        }
        p++;
    }
}

unsigned char *lex_skip_comment(unsigned char *p) { return skip_comment(p); }
unsigned char *lex_skip_line_comment(unsigned char *p) { return skip_line_comment(p); }
int lex_peek(unsigned char **pp) { return pk(pp); }

/* parse a quoted string/char raw text into b (without quotes);
   p points after the opening quote. returns pointer after closing quote */
static unsigned char *parse_pp_string(unsigned char *p, int sep, Str *b)
{
    for (;;) {
        int c = pk(&p);
        if (c == sep) { p++; break; }
        if (c == '\\') {
            str_putc(b, c);
            p++;
            c = pk(&p);
            if (c == -1) goto unterminated;
            if (c == '\n') { file->line++; }
            str_putc(b, c);
            p++;
            continue;
        }
        if (c == '\n' || c == -1) {
        unterminated:
            if (lexflags & LX_ASM) { break; }
            error("missing terminating %c character", sep);
        }
        str_putc(b, c);
        p++;
    }
    return p;
}

/* ------------------------------------------------------------ tokenizer */
extern void pp_directive(int bof);
extern int pp_file_end(void);

static void lex_number(unsigned char **pp, int c0)
{
    unsigned char *p = *pp;
    str_clear(&tokstr);
    int c = c0, prev = 0;
    for (;;) {
        str_putc(&tokstr, c);
        prev = c;
        p++;
        c = pk(&p);
        if (is_idnum(c) || c == '.') continue;
        if ((c == '+' || c == '-') &&
            (prev == 'e' || prev == 'E' || prev == 'p' || prev == 'P'))
            continue;
        break;
    }
    str_putc(&tokstr, 0);
    tokstr.len--;
    tokc.str.s = tokstr.s;
    tokc.str.n = tokstr.len + 1;
    tok = T_PPNUM;
    *pp = p;
}

void next_raw(void)
{
    unsigned char *p;
    int c;
redo:
    p = file->p;
    c = pk(&p);
    switch (c) {
    case ' ': case '\t': case '\f': case '\v': case '\r':
        if (lexflags & LX_SPACES) {
            p++;
            tok = c;
            file->p = p;
            return;
        }
        p++;
        while (1) {
            c = pk(&p);
            if (!is_space_ch(c)) break;
            p++;
        }
        file->p = p;
        goto redo;
    case -1:
        file->p = p;
        if ((lexflags & LX_NL) && !(tflags & TF_BOL)) {
            /* implicit newline at end of file */
            tflags |= TF_BOL;
            tok = T_NL;
            return;
        }
        if (pp_file_end()) {
            tok = T_EOF;
            return;
        }
        goto redo;
    case '\n':
        file->line++;
        p++;
        file->p = p;
        tflags |= TF_BOL;
        if (!(lexflags & LX_NL)) goto redo;
        tok = T_NL;
        return;
    case '#':
        p++;
        c = pk(&p);
        if (c == '#') {
            p++;
            tok = T_PASTE;
        } else {
            if ((tflags & TF_BOL) && (lexflags & LX_PP)) {
                file->p = p;
                pp_directive(tflags & TF_BOF);
                goto redo;
            }
            tok = '#';
        }
        break;
    case '$':
    case 'a': case 'b': case 'c': case 'd': case 'e': case 'f': case 'g': case 'h':
    case 'i': case 'j': case 'k': case 'l': case 'm': case 'n': case 'o': case 'p':
    case 'q': case 'r': case 's': case 't': case 'u': case 'v': case 'w': case 'x':
    case 'y': case 'z':
    case 'A': case 'B': case 'C': case 'D': case 'E': case 'F': case 'G': case 'H':
    case 'I': case 'J': case 'K': case 'M': case 'N': case 'O': case 'P':
    case 'Q': case 'R': case 'S': case 'T': case 'U': case 'V': case 'W': case 'X':
    case 'Y': case 'Z': case '_':
    ident: {
        str_clear(&tokstr);
        for (;;) {
            str_putc(&tokstr, c);
            p++;
            c = pk(&p);
            if (!is_idnum(c)) break;
        }
        tok = ident_get(tokstr.s, tokstr.len)->tok;
        break;
    }
    case 'L': {
        unsigned char *q = p + 1;
        int c2 = pk(&q);
        if (c2 == '\'' || c2 == '"') {
            str_clear(&tokstr);
            str_putc(&tokstr, 'L');
            str_putc(&tokstr, c2);
            p = parse_pp_string(q + 1, c2, &tokstr);
            str_putc(&tokstr, c2);
            goto strdone;
        }
        goto ident;
    }
    case '0': case '1': case '2': case '3': case '4':
    case '5': case '6': case '7': case '8': case '9':
        lex_number(&p, c);
        file->p = p;
        tflags = 0;
        return;
    case '.': {
        unsigned char *q = p + 1;
        int c2 = pk(&q);
        if (c2 >= '0' && c2 <= '9') {
            str_clear(&tokstr);
            str_putc(&tokstr, '.');
            p = q;
            lex_number(&p, c2);
            /* lex_number reset the buffer: redo properly */
            {
                Str t2; str_init(&t2);
                str_putc(&t2, '.');
                str_puts(&t2, tokc.str.s);
                str_clear(&tokstr);
                str_puts(&tokstr, str_cstr(&t2));
                str_putc(&tokstr, 0);
                tokstr.len--;
                str_free(&t2);
                tokc.str.s = tokstr.s;
                tokc.str.n = tokstr.len + 1;
            }
            file->p = p;
            tflags = 0;
            return;
        }
        if (c2 == '.') {
            unsigned char *r = q + 1;
            int c3 = pk(&r);
            if (c3 == '.') { p = r + 1; tok = T_ELLIPSIS; break; }
            if (lexflags & LX_ASM) { p = q + 1; tok = T_DOTDOT; break; }
            /* '..' : return '.' only */
        }
        p++;
        tok = '.';
        if ((lexflags & LX_ASM) && is_id_ch(c2)) {
            /* assembler directive names like .text */
            str_clear(&tokstr);
            str_putc(&tokstr, '.');
            c = c2; p = q;
            for (;;) {
                str_putc(&tokstr, c);
                p++;
                c = pk(&p);
                if (!is_idnum(c)) break;
            }
            tok = ident_get(tokstr.s, tokstr.len)->tok;
        }
        break;
    }
    case '\'': case '"':
        str_clear(&tokstr);
        str_putc(&tokstr, c);
        p = parse_pp_string(p + 1, c, &tokstr);
        str_putc(&tokstr, c);
    strdone:
        str_putc(&tokstr, 0);
        tokstr.len--;
        tokc.str.s = tokstr.s;
        tokc.str.n = tokstr.len + 1;
        tok = T_PPSTR;
        break;
    case '<': {
        p++; c = pk(&p);
        if (c == '=') { p++; tok = T_LE; }
        else if (c == '<') {
            p++; c = pk(&p);
            if (c == '=') { p++; tok = T_SHLEQ; } else tok = T_SHL;
        } else tok = T_LT;
        break;
    }
    case '>': {
        p++; c = pk(&p);
        if (c == '=') { p++; tok = T_GE; }
        else if (c == '>') {
            p++; c = pk(&p);
            if (c == '=') { p++; tok = T_SAREQ; } else tok = T_SAR;
        } else tok = T_GT;
        break;
    }
    case '&':
        p++; c = pk(&p);
        if (c == '&') { p++; tok = T_ANDAND; }
        else if (c == '=') { p++; tok = T_ANDEQ; }
        else tok = '&';
        break;
    case '|':
        p++; c = pk(&p);
        if (c == '|') { p++; tok = T_OROR; }
        else if (c == '=') { p++; tok = T_OREQ; }
        else tok = '|';
        break;
    case '+':
        p++; c = pk(&p);
        if (c == '+') { p++; tok = T_INC; }
        else if (c == '=') { p++; tok = T_ADDEQ; }
        else tok = '+';
        break;
    case '-':
        p++; c = pk(&p);
        if (c == '-') { p++; tok = T_DEC; }
        else if (c == '=') { p++; tok = T_SUBEQ; }
        else if (c == '>') { p++; tok = T_ARROW; }
        else tok = '-';
        break;
    case '!':
        p++; c = pk(&p);
        if (c == '=') { p++; tok = T_NE; } else tok = '!';
        break;
    case '=':
        p++; c = pk(&p);
        if (c == '=') { p++; tok = T_EQ; } else tok = '=';
        break;
    case '*':
        p++; c = pk(&p);
        if (c == '=') { p++; tok = T_MULEQ; } else tok = '*';
        break;
    case '%':
        p++; c = pk(&p);
        if (c == '=') { p++; tok = T_MODEQ; } else tok = '%';
        break;
    case '^':
        p++; c = pk(&p);
        if (c == '=') { p++; tok = T_XOREQ; } else tok = '^';
        break;
    case '/':
        p++; c = pk(&p);
        if (c == '*') {
            p = skip_comment(p + 1);
            file->p = p;
            if (lexflags & LX_SPACES) {
                tok = ' ';
                return;
            }
            goto redo;
        } else if (c == '/') {
            p = skip_line_comment(p + 1);
            file->p = p;
            if (lexflags & LX_SPACES) {
                tok = ' ';
                return;
            }
            goto redo;
        } else if (c == '=') { p++; tok = T_DIVEQ; }
        else tok = '/';
        break;
    case '(': case ')': case '[': case ']': case '{': case '}':
    case ',': case ';': case ':': case '?': case '~': case '@':
        tok = c;
        p++;
        break;
    case '\\':
        if (!(lexflags & LX_STRAYS) && 0) {}
        tok = c;
        p++;
        break;
    default:
        if (c >= 0x80) goto ident;
        if ((lexflags & LX_ASM) && 0) {}
        if (lexflags & LX_STRAYS) { tok = c; p++; break; }
        file->p = p;
        error("unrecognized character \\x%02x", c);
    }
    tflags = 0;
    file->p = p;
}

/* ------------------------------------------------------------ token spelling */
static const struct { int t; const char *s; } op_names[] = {
    { T_LE, "<=" }, { T_GE, ">=" }, { T_NE, "!=" }, { T_ANDAND, "&&" },
    { T_OROR, "||" }, { T_INC, "++" }, { T_DEC, "--" }, { T_EQ, "==" },
    { T_SHL, "<<" }, { T_SAR, ">>" }, { T_ADDEQ, "+=" }, { T_SUBEQ, "-=" },
    { T_MULEQ, "*=" }, { T_DIVEQ, "/=" }, { T_MODEQ, "%=" }, { T_ANDEQ, "&=" },
    { T_XOREQ, "^=" }, { T_OREQ, "|=" }, { T_ARROW, "->" }, { T_ELLIPSIS, "..." },
    { T_PASTE, "##" }, { T_JOIN, "##" }, { T_SHLEQ, "<<=" }, { T_SAREQ, ">>=" },
    { T_LT, "<" }, { T_GT, ">" }, { T_DOTDOT, ".." },
    { 0, NULL }
};

void str_cat_esc(Str *b, const char *s, int len, int wide)
{
    (void)wide;
    for (int i = 0; i < len; i++) {
        unsigned char c = s[i];
        switch (c) {
        case '\n': str_puts(b, "\\n"); break;
        case '\t': str_puts(b, "\\t"); break;
        case '\r': str_puts(b, "\\r"); break;
        case '\v': str_puts(b, "\\v"); break;
        case '\f': str_puts(b, "\\f"); break;
        case '\a': str_puts(b, "\\a"); break;
        case '\b': str_puts(b, "\\b"); break;
        case '\\': str_puts(b, "\\\\"); break;
        case '"': str_puts(b, "\\\""); break;
        case '\'': str_puts(b, "\\'"); break;
        default:
            if (c < 32 || c == 127)
                str_printf(b, "\\%03o", c);
            else
                str_putc(b, c);
        }
    }
}

static Str tn_buf;

const char *tokname(int v, TokVal *cv)
{
    str_clear(&tn_buf);
    v &= ~NOEXP_BIT;
    switch (v) {
    case T_INT: case T_UINT: case T_LONG: case T_ULONG:
    case T_LLONG: case T_ULLONG:
        str_printf(&tn_buf, "%llu", (unsigned long long)(v == T_INT ? (unsigned long long)(long long)(int)cv->i : cv->i));
        if (v == T_INT || v == T_LLONG || v == T_LONG) {
            str_clear(&tn_buf);
            str_printf(&tn_buf, "%llu", (unsigned long long)cv->i);
        }
        return str_cstr(&tn_buf);
    case T_CHAR: case T_WCHAR:
        str_putc(&tn_buf, '\'');
        if (v == T_WCHAR) { str_clear(&tn_buf); str_puts(&tn_buf, "L'"); }
        {
            char ch = (char)cv->i;
            str_cat_esc(&tn_buf, &ch, 1, 0);
        }
        str_putc(&tn_buf, '\'');
        return str_cstr(&tn_buf);
    case T_PPNUM: case T_PPSTR:
        return cv->str.s;
    case T_WSTR:
        str_putc(&tn_buf, 'L');
        /* fallthrough */
    case T_STR:
        str_putc(&tn_buf, '"');
        if (v == T_STR)
            str_cat_esc(&tn_buf, cv->str.s, cv->str.n - 1, 0);
        else {
            int n = cv->str.n / 4 - 1;
            for (int i = 0; i < n; i++) {
                int ch = ((int *)cv->str.s)[i];
                char cc = (char)ch;
                str_cat_esc(&tn_buf, &cc, 1, 1);
            }
        }
        str_putc(&tn_buf, '"');
        return str_cstr(&tn_buf);
    case T_FLOAT: case T_DOUBLE: case T_LDOUBLE:
        return "<float>";
    case T_LINE:
        return "<linenumber>";
    case T_EOF:
        return "<eof>";
    case 0:
        return "<no name>";
    }
    if (v < T_IDENT) {
        for (int i = 0; op_names[i].s; i++)
            if (op_names[i].t == v) return op_names[i].s;
        if (v >= 0x80) {
            str_printf(&tn_buf, "<%02x>", v);
            return str_cstr(&tn_buf);
        }
        str_putc(&tn_buf, v);
        return str_cstr(&tn_buf);
    }
    Ident *id = ident_of(v);
    if (id) return id->s;
    str_printf(&tn_buf, "L.%u", v & ~(SYM_FIRST_ANOM | SYM_FIELD | SYM_STRUCT));
    return str_cstr(&tn_buf);
}

/* ------------------------------------------------------------ literal conversion */
static int hexval(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static void put_utf8(Str *b, unsigned c)
{
    if (c < 0x80) str_putc(b, c);
    else if (c < 0x800) { str_putc(b, 0xc0 | (c >> 6)); str_putc(b, 0x80 | (c & 0x3f)); }
    else if (c < 0x10000) { str_putc(b, 0xe0 | (c >> 12)); str_putc(b, 0x80 | ((c >> 6) & 0x3f)); str_putc(b, 0x80 | (c & 0x3f)); }
    else { str_putc(b, 0xf0 | (c >> 18)); str_putc(b, 0x80 | ((c >> 12) & 0x3f)); str_putc(b, 0x80 | ((c >> 6) & 0x3f)); str_putc(b, 0x80 | (c & 0x3f)); }
}

static void put_wide(Str *b, unsigned c)
{
    str_putn(b, (char *)&c, 4);
}

/* decode one UTF-8 sequence for wide strings */
static unsigned utf8_dec(const unsigned char **pp)
{
    const unsigned char *p = *pp;
    unsigned c = *p++;
    int n = 0;
    if (c >= 0xc0 && c < 0xe0) { c &= 0x1f; n = 1; }
    else if (c >= 0xe0 && c < 0xf0) { c &= 0x0f; n = 2; }
    else if (c >= 0xf0 && c < 0xf8) { c &= 0x07; n = 3; }
    for (int i = 0; i < n; i++) {
        if ((*p & 0xc0) != 0x80) break;
        c = (c << 6) | (*p++ & 0x3f);
    }
    *pp = p;
    return c;
}

/* convert pp string (with quotes, optional L prefix) into C token */
void parse_pp_str_tok(const char *s)
{
    int wide = 0, sep;
    if (*s == 'L') { wide = 1; s++; }
    sep = *s++;
    Str b;
    str_init(&b);
    const unsigned char *p = (const unsigned char *)s;
    int count = 0;
    unsigned lastc = 0;
    for (;;) {
        unsigned c = *p;
        if (c == (unsigned)sep && p[1] == 0) break;
        if (c == 0) break;
        if (c == '\\') {
            const unsigned char *esc = p;
            p++;
            c = *p;
            switch (c) {
            case '0': case '1': case '2': case '3':
            case '4': case '5': case '6': case '7': {
                unsigned n = c - '0';
                p++;
                if (*p >= '0' && *p <= '7') {
                    n = n * 8 + *p++ - '0';
                    if (*p >= '0' && *p <= '7') n = n * 8 + *p++ - '0';
                }
                c = n;
                goto add_char_nouc;
            }
            case 'x': case 'u': case 'U': {
                int maxd = c == 'u' ? 4 : c == 'U' ? 8 : -1;
                int nd = 0;
                unsigned n = 0;
                p++;
                for (;;) {
                    int h = hexval(*p);
                    if (h < 0) break;
                    n = n * 16 + h;
                    nd++;
                    p++;
                    if (nd == maxd) break;
                }
                if (nd == 0 || (maxd > 0 && nd != maxd)) {
                    error("more hex digits in universal-character-name expected");
                }
                c = n;
                if (maxd > 0) {
                    if (wide) { put_wide(&b, c); count++; lastc = c; continue; }
                    put_utf8(&b, c); count++; lastc = c;
                    continue;
                }
                goto add_char_nouc;
            }
            case 'a': c = '\a'; break;
            case 'b': c = '\b'; break;
            case 'f': c = '\f'; break;
            case 'n': c = '\n'; break;
            case 'r': c = '\r'; break;
            case 't': c = '\t'; break;
            case 'v': c = '\v'; break;
            case 'e': c = 27; break;
            case 'E': c = 27; break;
            case '\'': case '"': case '\\': case '?': break;
            default:
                if (c >= '!' && c <= '~')
                    warning("unknown escape sequence: '\\%c'", c);
                else
                    warning("unknown escape sequence: '\\x%x'", c);
                (void)esc;
                break;
            }
            p++;
        add_char_nouc:
            if (wide) put_wide(&b, c);
            else str_putc(&b, c);
            count++;
            lastc = c;
            continue;
        }
        if (wide) {
            if (c >= 0x80) c = utf8_dec(&p);
            else p++;
            put_wide(&b, c);
        } else {
            str_putc(&b, c);
            p++;
        }
        count++;
        lastc = c;
    }
    if (sep == '\'') {
        if (count == 0) error("empty character constant");
        if (wide) {
            tok = T_WCHAR;
            tokc.i = (int)lastc;
            if (count > 1) tokc.i = ((int *)b.s)[0] , tokc.i = (int)((unsigned *)b.s)[count-1];
        } else {
            /* multi char: combine bytes */
            int v = 0;
            for (int i = 0; i < count; i++)
                v = (v << 8) | (unsigned char)b.s[i];
            if (count == 1) v = (signed char)b.s[0];
            if (opt.char_unsigned && count == 1) v = (unsigned char)b.s[0];
            tok = T_CHAR;
            tokc.i = (long long)v;
        }
        str_free(&b);
        return;
    }
    if (wide) { put_wide(&b, 0); tok = T_WSTR; }
    else { str_putc(&b, 0); tok = T_STR; }
    str_clear(&tokstr);
    str_putn(&tokstr, b.s, b.len);
    str_free(&b);
    tokc.str.s = tokstr.s;
    tokc.str.n = tokstr.len;
}
EOF
echo ok"}

