/* lexical analysis: source files, identifiers, raw tokens, diagnostics */
#include "cc.h"

SrcFile *file;
int tok;
TokVal tokc;
const int *mac_ptr;
int lexflags;
int tflags;
Str tokstr;
int pp_in_expr;
int nb_errors, nb_warnings;
SrcFile *inc_stack[64];
SrcFile **inc_sp = inc_stack;
int total_lines, total_idents, total_bytes;
jmp_buf err_jmp;
int err_jmp_set;
int in_cleanup_errors;

/* ------------------------------------------------------------ identifiers */
#define HASH_SIZE 16384
static Ident *hash_tab[HASH_SIZE];
static Ident **ident_arr;
static int ident_n, ident_cap;
static int next_tok = T_IDENT;

static const char *const kw_names[] = {
#define K(id, s) s,
#include "keywords.h"
#undef K
};

static unsigned hash_str(const char *s, int len)
{
    unsigned h = 1;
    for (int i = 0; i < len; i++) h = (h + (h << 5) + (h >> 27)) + (unsigned char)s[i];
    return h & (HASH_SIZE - 1);
}

Ident *ident_get(const char *s, int len)
{
    unsigned h = hash_str(s, len);
    Ident *p;
    for (p = hash_tab[h]; p; p = p->hnext)
        if (p->len == len && !memcmp(p->s, s, len))
            return p;
    p = xcalloc(sizeof(Ident) + len);
    memcpy(p->s, s, len);
    p->s[len] = 0;
    p->len = len;
    p->tok = next_tok++;
    p->hnext = hash_tab[h];
    hash_tab[h] = p;
    if (ident_n == ident_cap) {
        ident_cap = ident_cap ? ident_cap * 2 : 1024;
        ident_arr = xrealloc(ident_arr, ident_cap * sizeof(Ident *));
    }
    ident_arr[ident_n++] = p;
    total_idents++;
    return p;
}

int ident_tok(const char *s) { return ident_get(s, strlen(s))->tok; }

Ident *ident_of(int t)
{
    t &= ~(SYM_STRUCT | SYM_FIELD | NOEXP_BIT);
    if (t < T_IDENT || t >= next_tok) return NULL;
    return ident_arr[t - T_IDENT];
}

void lex_init_idents(void)
{
    for (unsigned i = 0; i < sizeof(kw_names) / sizeof(kw_names[0]); i++)
        ident_get(kw_names[i], strlen(kw_names[i]));
}

/* ------------------------------------------------------------ char classes */
int is_space_ch(int c) { return c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r'; }
int is_id_ch(int c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == '$' || c >= 0x80;
}
static int is_idnum(int c) { return is_id_ch(c) || (c >= '0' && c <= '9'); }

/* ------------------------------------------------------------ diagnostics */
static void diag(int kind, const char *fmt, va_list ap)
{
    /* kind: 0 warning, 1 error */
    Str b;
    str_init(&b);
    SrcFile *f = file;
    if (f) {
        for (SrcFile **pf = inc_stack; pf < inc_sp; pf++)
            str_printf(&b, "In file included from %s:%d:\n", (*pf)->name, (*pf)->line - 1);
        int ln = f->line;
        if ((tflags & TF_BOL) && !mac_ptr) ln--;
        str_printf(&b, "%s:%d: ", f->name, ln);
    } else {
        str_puts(&b, "tcc: ");
    }
    str_puts(&b, kind ? "error: " : "warning: ");
    if (pp_in_expr && kind) {
        /* redirect expression errors */
        str_vprintf(&b, fmt, ap);
    } else
        str_vprintf(&b, fmt, ap);
    str_putc(&b, '\n');
    fflush(stdout);
    fputs(str_cstr(&b), stderr);
    fflush(stderr);
    str_free(&b);
}

extern void pp_expr_error(void) __attribute__((noreturn));

static void do_abort(void)
{
    if (err_jmp_set)
        longjmp(err_jmp, 1);
    exit(1);
}

void error(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    if (pp_in_expr > 0) {
        va_end(ap);
        pp_expr_error();
    }
    diag(1, fmt, ap);
    va_end(ap);
    nb_errors++;
    do_abort();
}

void error_noabort(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    diag(1, fmt, ap);
    va_end(ap);
    nb_errors++;
}

void warning(const char *fmt, ...)
{
    va_list ap;
    if (opt.w_none) return;
    va_start(ap, fmt);
    if (opt.w_error) {
        diag(1, fmt, ap);
        nb_errors++;
    } else
        diag(0, fmt, ap);
    va_end(ap);
    nb_warnings++;
}

void warning_opt(int which, const char *fmt, ...)
{
    va_list ap;
    int on = 1, err = opt.w_error;
    switch (which) {
    case WOPT_IMPLICIT: on = opt.w_implicit_decl & 1; err |= opt.w_error_implicit_decl; break;
    case WOPT_DISCARDED: on = opt.w_discarded_qual & 1; err |= opt.w_error_discarded; break;
    case WOPT_WRITE_STRINGS: on = opt.w_write_strings & 1; err |= opt.w_error_write_strings; break;
    case WOPT_UNSUPPORTED: on = opt.w_unsupported & 1; err |= opt.w_error_unsupported; break;
    case WOPT_ALL: on = opt.w_all; break;
    }
    if (!on || opt.w_none) return;
    va_start(ap, fmt);
    if (err) {
        diag(1, fmt, ap);
        nb_errors++;
    } else
        diag(0, fmt, ap);
    va_end(ap);
    nb_warnings++;
}

/* ------------------------------------------------------------ token sequences */
void tseq_init(TokSeq *s) { memset(s, 0, sizeof *s); s->line = -1; }
TokSeq *tseq_new(void) { TokSeq *s = xcalloc(sizeof *s); s->line = -1; return s; }
void tseq_free_arr(int *a) { free(a); }
void tseq_free(TokSeq *s) { free(s->a); free(s); }

static int *tseq_room(TokSeq *s, int n)
{
    if (s->n + n > s->cap) {
        int c = s->cap ? s->cap : 16;
        while (c < s->n + n) c *= 2;
        s->a = xrealloc(s->a, c * sizeof(int));
        s->cap = c;
    }
    int *p = s->a + s->n;
    s->n += n;
    return p;
}

void tseq_add(TokSeq *s, int t)
{
    s->lastn = s->n;
    *tseq_room(s, 1) = t;
}

void tseq_add_val(TokSeq *s, int t, TokVal *cv)
{
    int len = s->n;
    s->lastn = len;
    switch (t) {
    case T_CHAR: case T_WCHAR: case T_INT: case T_UINT: case T_LINE:
    case T_LONG: case T_ULONG: case T_LLONG: case T_ULLONG: case T_DOUBLE: {
        int *p = tseq_room(s, 3);
        p[0] = t; memcpy(p + 1, &cv->i, 8);
        break;
    }
    case T_FLOAT: {
        int *p = tseq_room(s, 2);
        p[0] = t; memcpy(p + 1, &cv->f, 4);
        break;
    }
    case T_LDOUBLE: {
        int *p = tseq_room(s, 5);
        p[0] = t; memcpy(p + 1, &cv->ld, 16);
        break;
    }
    case T_STR: case T_WSTR: case T_PPNUM: case T_PPSTR: {
        int n = cv->str.n;
        int w = (n + 3) / 4;
        int *p = tseq_room(s, 2 + w);
        p[0] = t; p[1] = n;
        memcpy(p + 2, cv->str.s, n);
        break;
    }
    default:
        *tseq_room(s, 1) = t;
        break;
    }
}

/* add current token, recording line number changes */
void tseq_add_cur(TokSeq *s)
{
    if (file && s->line != file->line) {
        TokVal v;
        s->line = file->line;
        v.i = file->line;
        tseq_add_val(s, T_LINE, &v);
    }
    tseq_add_val(s, tok, &tokc);
}

void tseq_get(int *t, const int **pp, TokVal *cv)
{
    const int *p = *pp;
    int n;
    *t = n = *p;
    switch (n) {
    case T_CHAR: case T_WCHAR: case T_INT: case T_UINT: case T_LINE:
    case T_LONG: case T_ULONG: case T_LLONG: case T_ULLONG: case T_DOUBLE:
        memcpy(&cv->i, p + 1, 8); p += 3; break;
    case T_FLOAT:
        memcpy(&cv->f, p + 1, 4); p += 2; break;
    case T_LDOUBLE:
        memcpy(&cv->ld, p + 1, 16); p += 5; break;
    case T_STR: case T_WSTR: case T_PPNUM: case T_PPSTR:
        cv->str.n = p[1];
        cv->str.s = (char *)(p + 2);
        p += 2 + (p[1] + 3) / 4;
        break;
    default:
        p++;
        break;
    }
    *pp = p;
}

/* ------------------------------------------------------------ readers */
typedef struct Reader {
    struct Reader *prev;
    const int *saved_ptr;
    int *owned;     /* array to free */
    TokSeq *seq;    /* sequence to free */
    int saved_line;
    int kind;
} Reader;
static Reader *readers;

void push_reader(TokSeq *s, int owned)
{
    Reader *r = xcalloc(sizeof *r);
    r->prev = readers;
    r->saved_ptr = mac_ptr;
    r->kind = owned;
    if (owned == 1) r->seq = s;
    else if (owned == 3) r->owned = s->a;
    r->saved_line = file ? file->line : 0;
    readers = r;
    mac_ptr = s->a;
}

/* push raw int array */
void push_reader_arr(const int *a, int *owned)
{
    Reader *r = xcalloc(sizeof *r);
    r->prev = readers;
    r->saved_ptr = mac_ptr;
    r->owned = owned;
    r->saved_line = -1;
    readers = r;
    mac_ptr = a;
}

void pop_reader(void)
{
    Reader *r = readers;
    if (!r) { mac_ptr = NULL; return; }
    readers = r->prev;
    mac_ptr = r->saved_ptr;
    if (r->seq) tseq_free(r->seq);
    if (r->owned) free(r->owned);
    if (r->saved_line >= 0 && file && r->kind != 2)
        file->line = r->saved_line;
    free(r);
}

int reader_depth(void)
{
    int n = 0;
    for (Reader *r = readers; r; r = r->prev) n++;
    return n;
}

void *reader_top(void) { return readers; }

/* ------------------------------------------------------------ source files */
static SrcFile *src_alloc(const char *name, unsigned char *data, int len)
{
