{
    unsigned char *b = xmalloc(len + 4);
    memcpy(b, data, len);
    b[len] = 0; b[len+1] = 0; b[len+2] = 0;
    src_alloc(name, b, len);
}

int src_open(const char *fn)
{
    int fd;
    if (!strcmp(fn, "-"))
        fd = 0, fn = "<stdin>";
    else
        fd = open(fn, O_RDONLY);
    if (fd < 0) return -1;
    Str b;
    str_init(&b);
    char tmp[65536];
    for (;;) {
        ssize_t n = read(fd, tmp, sizeof tmp);
        if (n <= 0) break;
        str_putn(&b, tmp, n);
