/* ------------------------------------------------------------ numbers */
static int up(int c) { return (c >= 'a' && c <= 'z') ? c - 32 : c; }

void parse_ppnum_tok(const char *s)
{
    const char *p = s;
    int b = 10;
    int c = *p;
    char buf[1024];
    int q = 0;

    if (c == '.') goto float_parse;
    if (c == '0' && (p[1] == 'x' || p[1] == 'X')) { b = 16; p += 2; }
    else if (c == '0' && (p[1] == 'b' || p[1] == 'B')) { b = 2; p += 2; }
    /* collect digits */
    for (;;) {
        int d;
        c = *p;
        if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else if (c >= '0' && c <= '9') d = c - '0';
        else break;
        if (d >= b) break;
        if (q < (int)sizeof(buf) - 2) buf[q++] = c;
        p++;
    }
    buf[q] = 0;
    if (c == '.' || ((c == 'e' || c == 'E') && b == 10) ||
        ((c == 'p' || c == 'P') && (b == 16 || b == 2))) {
        if (b != 10) {
            /* hexadecimal (or binary) float */
            long double m = 0;
            int shift = b == 16 ? 4 : 1;
            int frac_bits = 0;
            for (int i = 0; i < q; i++) {
                int d = buf[i] <= '9' ? buf[i] - '0' : up(buf[i]) - 'A' + 10;
                m = m * b + d;
            }
            if (c == '.') {
                p++;
                for (;;) {
                    int d;
                    c = *p;
                    if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
                    else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
                    else if (c >= '0' && c <= '9') d = c - '0';
                    else break;
                    if (d >= b) break;
                    m = m * b + d;
                    frac_bits += shift;
                    p++;
                }
            }
            if (c != 'p' && c != 'P') expect("exponent");
            p++;
            int sign = 1, e = 0;
            c = *p;
            if (c == '+') p++;
            else if (c == '-') { sign = -1; p++; }
            c = *p;
            if (!(c >= '0' && c <= '9')) expect("exponent digits");
            while (*p >= '0' && *p <= '9') { e = e * 10 + (*p - '0'); if (e > 100000) e = 100000; p++; }
            e = e * sign - frac_bits;
            long double v = ldexpl(m, e);
            c = up(*p);
            if (c == 'F') { p++; tok = T_FLOAT; tokc.f = (float)v; }
            else if (c == 'L') { p++; tok = T_LDOUBLE; tokc.ld = v; }
            else { tok = T_DOUBLE; tokc.d = (double)v; }
            if (*p) error("invalid number");
            return;
        }
    float_parse:
        {
            /* decimal float: validate syntax then use strtold */
            Str t;
            str_init(&t);
            const char *r = s;
            while (*r >= '0' && *r <= '9') str_putc(&t, *r++);
            if (*r == '.') {
                str_putc(&t, *r++);
                while (*r >= '0' && *r <= '9') str_putc(&t, *r++);
            }
            if (*r == 'e' || *r == 'E') {
                str_putc(&t, *r++);
                if (*r == '+' || *r == '-') str_putc(&t, *r++);
                if (!(*r >= '0' && *r <= '9')) { str_free(&t); expect("exponent digits"); }
                while (*r >= '0' && *r <= '9') str_putc(&t, *r++);
            }
            int cc = up(*r);
            char *ts = str_cstr(&t);
            if (cc == 'F') {
                r++;
                tok = T_FLOAT;
                tokc.f = strtof(ts, NULL);
            } else if (cc == 'L') {
                r++;
                tok = T_LDOUBLE;
                tokc.ld = strtold(ts, NULL);
            } else {
                tok = T_DOUBLE;
                tokc.d = strtod(ts, NULL);
            }
            str_free(&t);
            if (*r) error("invalid number");
            return;
        }
    }
    /* integer */
    {
        const char *digits = buf;
        int ov = 0;
        uint64_t n = 0, n1 = 0;
        if (b == 10 && buf[0] == '0') b = 8;
        for (int i = 0; i < q; i++) {
            int d = digits[i] <= '9' ? digits[i] - '0' : up(digits[i]) - 'A' + 10;
            if (d >= b) error("invalid digit");
            uint64_t nn;
            int o;
            if (b == 10) {
                o = n > (UINT64_MAX - d) / 10;
                nn = n * 10 + d;
            } else {
                int sh = b == 16 ? 4 : b == 8 ? 3 : 1;
                o = (n >> (64 - sh)) != 0;
                nn = (n << sh) + d;
            }
            if (o && !ov) { ov = 1; n1 = n; }
            n = nn;
        }
        if (!ov) n1 = n;
        int lcount = 0, ucount = 0;
        for (;;) {
            int t = up(*p);
            if (t == 'L') {
