{"command":"cat > /workspace/src/pp.c <<'EOF'
/* preprocessor: directives, macro expansion, conditional compilation, -E output */
#include "cc.h"

int cond_stack[64];
int *cond_sp = cond_stack;
FILE *ppout;
int pack_stack[8];
int *pack_sp = pack_stack;
PVec pragma_libs;
static int pp_counter;
static int pp_once;
static IncCache **inc_cache;
static int nb_inc_cache;
static int inc_hash[32];
static TokSeq expand_buf;
int pp_debug_tok, pp_debug_symv;
int in_directive_skip;

extern void parse_ppnum_tok(const char *s);
extern void parse_pp_str_tok(const char *s);
extern void push_reader_arr(const int *a, int *owned);
extern unsigned char *lex_skip_comment(unsigned char *p);
extern unsigned char *lex_skip_line_comment(unsigned char *p);
extern int lex_peek(unsigned char **pp);
extern void lex_init_idents(void);
extern int reader_depth(void);
extern void *reader_top(void);
extern void pragma_compile(void);
extern int nocode_wanted;

/* ------------------------------------------------------------ macros */
Macro *macro_find(int v)
{
    Ident *id = ident_of(v);
    if (!id) return NULL;
    return id->macro;
}

static int body_equal(const int *a, const int *b)
{
    if (!a || !b) return a == b;
    TokVal va, vb;
    int ta, tb;
    for (;;) {
        tseq_get(&ta, &a, &va);
        tseq_get(&tb, &b, &vb);
        if (ta != tb) return 0;
        if (ta == 0) return 1;
        if (ta == T_PPNUM || ta == T_PPSTR || ta == T_STR) {
            if (strcmp(va.str.s, vb.str.s)) return 0;
        } else if (IS_VALTOK(ta)) {
            if (va.i != vb.i) return 0;
        }
    }
}

void macro_define(int v, int funclike, int nparams, int *params, int variadic, int *body)
{
    Ident *id = ident_of(v);
    Macro *old = id->macro;
    if (old) {
        int same = old->funclike == funclike && old->nparams == nparams &&
                   old->variadic == variadic && body_equal(old->body, body);
        if (same && nparams)
            same = !memcmp(old->params, params, nparams * sizeof(int));
        if (!same)
            warning("%s redefined", id->s);
    }
    Macro *m = xcalloc(sizeof *m);
    m->tok = v;
    m->funclike = funclike;
    m->nparams = nparams;
    m->params = params;
    m->variadic = variadic;
    m->body = body;
    if (old) {
        m->saved = old->saved;
        old->saved = NULL;
        /* keep old body alive: it may still be referenced by readers */
    }
    id->macro = m;
}

void macro_undef(int v)
{
    Ident *id = ident_of(v);
    if (id && id->macro) {
        Macro *m = id->macro;
        if (m->saved) {
            /* keep push_macro stack: undefined entry */
            Macro *u = xcalloc(sizeof *u);
            u->tok = -1;
            u->saved = m->saved;
            id->macro = NULL;
            /* store stack in a hidden placeholder */
            id->macro = NULL;
            /* attach to ident via a static side list */
            m->saved = NULL;
            free(u);
        }
        id->macro = NULL;
    }
}

/* push_macro/pop_macro support: per ident stack of saved definitions */
typedef struct MStack { struct MStack *prev; int tok; Macro *m; int defined; } MStack;
static MStack *mstack;

static void push_macro(int v)
{
    MStack *s = xcalloc(sizeof *s);
    s->prev = mstack;
    s->tok = v;
    s->m = macro_find(v);
    s->defined = s->m != NULL;
    mstack = s;
}

static void pop_macro(int v)
{
    MStack **ps = &mstack;
    for (; *ps; ps = &(*ps)->prev) {
        if ((*ps)->tok == v) {
            MStack *s = *ps;
            *ps = s->prev;
            ident_of(v)->macro = s->m;
            free(s);
            return;
        }
    }
}

/* ------------------------------------------------------------ helpers */
void skip_to_eol(int warn)
{
    if (tok == T_NL) return;
    if (warn)
        warning("extra tokens after directive");
    while (tok != T_NL && tok != T_EOF)
        next_raw();
}

void expect(const char *msg)
{
    error("%s expected", msg);
}

void skip(int c)
{
    if (tok != c) {
        char buf[64];
        const char *n = tokname(c, NULL);
        snprintf(buf, sizeof buf, "'%s'", n);
        error("%s expected (got '%s')", buf, tokname(tok, &tokc));
    }
    next();
}

/* ------------------------------------------------------------ include files */
static int inc_hash_fn(const char *s)
{
    unsigned h = 0;
    for (; *s; s++) h = h * 263 + (unsigned char)*s;
    return h & 31;
}

static IncCache *cache_find(const char *fn, int add)
{
    int h = inc_hash_fn(fn);
    int i = inc_hash[h];
    while (i) {
        IncCache *e = inc_cache[i - 1];
        if (!strcmp(e->name, fn)) return e;
        i = e->hnext;
    }
    if (!add) return NULL;
    IncCache *e = xcalloc(sizeof *e + strlen(fn));
    strcpy(e->name, fn);
    e->hnext = inc_hash[h];
    inc_cache = xrealloc(inc_cache, (nb_inc_cache + 1) * sizeof(*inc_cache));
    inc_cache[nb_inc_cache++] = e;
    inc_hash[h] = nb_inc_cache;
    return e;
}

extern int pp_line_out(SrcFile *f, int level);

static void do_include(int is_next)
{
    char name[1024], buf[1024];
    int c, i;
    unsigned char *p;
    SrcFile *f;

    /* read filename */
    p = file->p;
    c = lex_peek(&p);
    while (is_space_ch(c)) { p++; c = lex_peek(&p); }
    if (c == '<' || c == '"') {
        int sep = c == '<' ? '>' : '"';
        int n = 0;
        name[0] = c;
        p++;
        for (;;) {
            c = lex_peek(&p);
            if (c == sep) break;
            if (c == '\n' || c == -1) {
                file->p = p;
                error("'#include' expects \"FILENAME\" or <FILENAME>");
            }
            if (n < 1020) buf[n++] = c;
            p++;
        }
        buf[n] = 0;
        p++;
        file->p = p;
        c = name[0];
        pstrcpy(name, sizeof name, buf);
        next_raw();
        skip_to_eol(1);
    } else {
        /* computed include */
        int saved = lexflags;
        lexflags = (lexflags & ~LX_SPACES) | LX_PP | LX_NL | LX_STR;
        lexflags &= ~LX_STR;
        Str acc;
        str_init(&acc);
        next();
        if (tok == T_PPSTR && tokc.str.s[0] == '"') {
            int l = strlen(tokc.str.s);
            snprintf(name, sizeof name, "%.*s", l - 2, tokc.str.s + 1);
            c = '"';
            next();
        } else if (tok == T_STR) {
            snprintf(name, sizeof name, "%s", tokc.str.s);
            c = '"';
            next();
        } else if (tok == T_LT) {
            next();
            while (tok != T_GT && tok != T_NL && tok != T_EOF) {
                str_puts(&acc, tokname(tok, &tokc));
                next();
            }
            if (tok != T_GT) {
                lexflags = saved;
                error("'#include' expects \"FILENAME\" or <FILENAME>");
            }
            snprintf(name, sizeof name, "%s", str_cstr(&acc));
            c = '<';
            next();
        } else {
            lexflags = saved;
            error("'#include' expects \"FILENAME\" or <FILENAME>");
        }
        str_free(&acc);
        lexflags = saved;
        skip_to_eol(1);
    }

    i = is_next ? file->next_idx + 1 : 0;
    int npaths = opt.include_paths.n + opt.sysinclude_paths.n;
    for (;; i++) {
