/* ------------------------------------------------------------ macros */
Macro *macro_find(int v)
{
    Ident *id = ident_of(v);
    if (!id) return NULL;
    return id->macro;
}

static int body_equal(const int *a, const int *b)
{
    if (!a || !b) return a == b;
    TokVal va, vb;
    int ta, tb;
    for (;;) {
        tseq_get(&ta, &a, &va);
        tseq_get(&tb, &b, &vb);
        if (ta != tb) return 0;
        if (ta == 0) return 1;
        if (ta == T_PPNUM || ta == T_PPSTR || ta == T_STR) {
            if (strcmp(va.str.s, vb.str.s)) return 0;
        } else if (IS_VALTOK(ta)) {
            if (va.i != vb.i) return 0;
        }
    }
}

void macro_define(int v, int funclike, int nparams, int *params, int variadic, int *body)
{
    Ident *id = ident_of(v);
    Macro *old = id->macro;
    if (old) {
        int same = old->funclike == funclike && old->nparams == nparams &&
                   old->variadic == variadic && body_equal(old->body, body);
        if (same && nparams)
            same = !memcmp(old->params, params, nparams * sizeof(int));
        if (!same)
            warning("%s redefined", id->s);
    }
    Macro *m = xcalloc(sizeof *m);
    m->tok = v;
    m->funclike = funclike;
    m->nparams = nparams;
    m->params = params;
    m->variadic = variadic;
    m->body = body;
    if (old) {
        m->saved = old->saved;
        old->saved = NULL;
        /* keep old body alive: it may still be referenced by readers */
    }
    id->macro = m;
}

void macro_undef(int v)
{
    Ident *id = ident_of(v);
    if (id && id->macro) {
        Macro *m = id->macro;
        if (m->saved) {
            /* keep push_macro stack: undefined entry */
            Macro *u = xcalloc(sizeof *u);
            u->tok = -1;
            u->saved = m->saved;
            id->macro = NULL;
            /* store stack in a hidden placeholder */
            id->macro = NULL;
            /* attach to ident via a static side list */
            m->saved = NULL;
            free(u);
        }
        id->macro = NULL;
    }
}

/* push_macro/pop_macro support: per ident stack of saved definitions */
typedef struct MStack { struct MStack *prev; int tok; Macro *m; int defined; } MStack;
static MStack *mstack;

static void push_macro(int v)
{
    MStack *s = xcalloc(sizeof *s);
    s->prev = mstack;
    s->tok = v;
    s->m = macro_find(v);
    s->defined = s->m != NULL;
    mstack = s;
}

static void pop_macro(int v)
{
    MStack **ps = &mstack;
    for (; *ps; ps = &(*ps)->prev) {
        if ((*ps)->tok == v) {
            MStack *s = *ps;
            *ps = s->prev;
            ident_of(v)->macro = s->m;
            free(s);
            return;
        }
    }
}

/* ------------------------------------------------------------ helpers */
void skip_to_eol(int warn)
{
    if (tok == T_NL) return;
    if (warn)
        warning("extra tokens after directive");
    while (tok != T_NL && tok != T_EOF)
        next_raw();
}

void expect(const char *msg)
{
    error("%s expected", msg);
}

void skip(int c)
{
    if (tok != c) {
        char buf[64];
        const char *n = tokname(c, NULL);
        snprintf(buf, sizeof buf, "'%s'", n);
        error("%s expected (got '%s')", buf, tokname(tok, &tokc));
    }
    next();
}

/* ------------------------------------------------------------ include files */
static int inc_hash_fn(const char *s)
{
    unsigned h = 0;
    for (; *s; s++) h = h * 263 + (unsigned char)*s;
    return h & 31;
}

static IncCache *cache_find(const char *fn, int add)
{
    int h = inc_hash_fn(fn);
    int i = inc_hash[h];
    while (i) {
        IncCache *e = inc_cache[i - 1];
        if (!strcmp(e->name, fn)) return e;
        i = e->hnext;
    }
    if (!add) return NULL;
    IncCache *e = xcalloc(sizeof *e + strlen(fn));
    strcpy(e->name, fn);
    e->hnext = inc_hash[h];
    inc_cache = xrealloc(inc_cache, (nb_inc_cache + 1) * sizeof(*inc_cache));
    inc_cache[nb_inc_cache++] = e;
    inc_hash[h] = nb_inc_cache;
    return e;
}

extern int pp_line_out(SrcFile *f, int level);

static void do_include(int is_next)
{
    char name[1024], buf[1024];
    int c, i;
    unsigned char *p;
    SrcFile *f;

    /* read filename */
    p = file->p;
    c = lex_peek(&p);
    while (is_space_ch(c)) { p++; c = lex_peek(&p); }
    if (c == '<' || c == '"') {
        int sep = c == '<' ? '>' : '"';
        int n = 0;
        name[0] = c;
        p++;
        for (;;) {
            c = lex_peek(&p);
            if (c == sep) break;
            if (c == '\n' || c == -1) {
                file->p = p;
                error("'#include' expects \"FILENAME\" or <FILENAME>");
            }
            if (n < 1020) buf[n++] = c;
            p++;
        }
        buf[n] = 0;
        p++;
        file->p = p;
        c = name[0];
        pstrcpy(name, sizeof name, buf);
        next_raw();
        skip_to_eol(1);
    } else {
        /* computed include */
        int saved = lexflags;
        lexflags = (lexflags & ~LX_SPACES) | LX_PP | LX_NL | LX_STR;
        lexflags &= ~LX_STR;
        Str acc;
        str_init(&acc);
        next();
        if (tok == T_PPSTR && tokc.str.s[0] == '"') {
            int l = strlen(tokc.str.s);
            snprintf(name, sizeof name, "%.*s", l - 2, tokc.str.s + 1);
            c = '"';
            next();
        } else if (tok == T_STR) {
            snprintf(name, sizeof name, "%s", tokc.str.s);
            c = '"';
            next();
        } else if (tok == T_LT) {
            next();
            while (tok != T_GT && tok != T_NL && tok != T_EOF) {
                str_puts(&acc, tokname(tok, &tokc));
                next();
            }
            if (tok != T_GT) {
                lexflags = saved;
                error("'#include' expects \"FILENAME\" or <FILENAME>");
            }
            snprintf(name, sizeof name, "%s", str_cstr(&acc));
            c = '<';
            next();
        } else {
            lexflags = saved;
            error("'#include' expects \"FILENAME\" or <FILENAME>");
        }
        str_free(&acc);
        lexflags = saved;
        skip_to_eol(1);
    }

    i = is_next ? file->next_idx + 1 : 0;
    int npaths = opt.include_paths.n + opt.sysinclude_paths.n;
    for (;; i++) {
        char path[2048];
        if (i == 0) {
            if (name[0] == '/') {
                pstrcpy(path, sizeof path, name);
            } else {
                if (c != '"') continue;
                /* current file directory */
                const char *fn = file->true_name;
                const char *b = path_basename(fn);
                int dl = b - fn;
                snprintf(path, sizeof path, "%.*s%s", dl, fn, name);
            }
        } else {
            if (i - 1 >= npaths) break;
            const char *dir;
            if (i - 1 < opt.include_paths.n) dir = opt.include_paths.v[i - 1];
            else dir = opt.sysinclude_paths.v[i - 1 - opt.include_paths.n];
            if (name[0] == '/') break;
            snprintf(path, sizeof path, "%s/%s", dir, name);
        }
        IncCache *e = cache_find(path, 0);
        if (e && (e->once || (e->guard && macro_find(e->guard)))) {
            return;
        }
        if (src_open(path) < 0)
            continue;
        file->next_idx = i;
        if (opt.gen_deps) {
            extern void add_dep(const char *fn, int sys);
            add_dep(path, i > opt.include_paths.n || (name[0] == '/' && 0));
        }
        if (inc_sp >= inc_stack + 32) {
            error("#include recursion too deep");
        }
        *inc_sp++ = file->up;
        tflags = TF_BOL | TF_BOF;
        if (opt.verbose >= 2 || 0) {
            extern int verbose_include_level(void);
            printf("%.*s %s\n", (int)(inc_sp - inc_stack), "->->->->->->->->->->->->->->->->->->->->->->->->->->->->->->->->", path);
        }
        return;
    }
    if (opt.gen_deps && 0) {}
    error("include file '%s' not found", name);
}

/* ------------------------------------------------------------ #if expression */
typedef struct PVal { uint64_t v; int u; } PVal;
static const int *ex_p;
static int ex_tok;
static TokVal ex_val;
static int ex_skip;
static Str ex_text;
static int ex_dir;

void pp_expr_error(void)
{
    pp_in_expr = 0;
    error("bad preprocessor expression: #%s %s", tokname(ex_dir, NULL), str_cstr(&ex_text));
}

static void ex_next(void) { tseq_get(&ex_tok, &ex_p, &ex_val); }
static PVal ex_cond(void);

static PVal ex_unary(void)
{
    PVal r = { 0, 0 };
    switch (ex_tok) {
    case T_INT: case T_LONG: case T_LLONG:
        r.v = ex_val.i; r.u = 0; ex_next(); break;
    case T_UINT: case T_ULONG: case T_ULLONG:
        r.v = ex_val.i; r.u = 1; ex_next(); break;
    case T_CHAR: case T_WCHAR:
        r.v = (int64_t)(int)ex_val.i; r.u = 0; ex_next(); break;
    case '(':
        ex_next();
        r = ex_cond();
        while (ex_tok == ',') { ex_next(); r = ex_cond(); }
        if (ex_tok != ')') pp_expr_error();
        ex_next();
        break;
    case '-':
        ex_next(); r = ex_unary(); r.v = -r.v; break;
    case '+':
        ex_next(); r = ex_unary(); break;
    case '~':
        ex_next(); r = ex_unary(); r.v = ~r.v; break;
    case '!':
        ex_next(); r = ex_unary(); r.v = !r.v; r.u = 0; break;
    default:
        pp_expr_error();
    }
    return r;
}

static int prec(int t)
{
    switch (t) {
    case '*': case '/': case '%': return 10;
    case '+': case '-': return 9;
    case T_SHL: case T_SAR: return 8;
    case T_LT: case T_GT: case T_LE: case T_GE: return 7;
    case T_EQ: case T_NE: return 6;
    case '&': return 5;
    case '^': return 4;
    case '|': return 3;
    case T_ANDAND: return 2;
    case T_OROR: return 1;
    }
    return 0;
}

static PVal ex_bin(int minp)
{
    PVal a = ex_unary();
    for (;;) {
        int op = ex_tok, p = prec(op);
        if (!p || p < minp) break;
        ex_next();
        PVal b;
        if (op == T_ANDAND) {
            int sk = ex_skip;
            if (!a.v) ex_skip = 1;
            b = ex_bin(p + 1);
            ex_skip = sk;
            a.v = a.v && b.v; a.u = 0;
            continue;
        }
        if (op == T_OROR) {
            int sk = ex_skip;
            if (a.v) ex_skip = 1;
            b = ex_bin(p + 1);
            ex_skip = sk;
            a.v = a.v || b.v; a.u = 0;
            continue;
        }
        b = ex_bin(p + 1);
        int u = a.u || b.u;
        switch (op) {
        case '*': a.v = a.v * b.v; a.u = u; break;
        case '/': case '%':
            if (b.v == 0) {
                if (!ex_skip) pp_expr_error();
                a.v = 0; a.u = u; break;
            }
            if (u) a.v = op == '/' ? a.v / b.v : a.v % b.v;
            else {
                int64_t x = a.v, y = b.v;
                if (y == -1) a.v = op == '/' ? -(uint64_t)x : 0;
                else a.v = op == '/' ? (uint64_t)(x / y) : (uint64_t)(x % y);
            }
            a.u = u;
            break;
        case '+': a.v += b.v; a.u = u; break;
        case '-': a.v -= b.v; a.u = u; break;
        case T_SHL: a.v = a.v << (b.v & 63); break;
        case T_SAR:
            if (a.u) a.v = a.v >> (b.v & 63);
            else a.v = (uint64_t)((int64_t)a.v >> (b.v & 63));
            break;
        case T_LT: a.v = u ? a.v < b.v : (int64_t)a.v < (int64_t)b.v; a.u = 0; break;
        case T_GT: a.v = u ? a.v > b.v : (int64_t)a.v > (int64_t)b.v; a.u = 0; break;
        case T_LE: a.v = u ? a.v <= b.v : (int64_t)a.v <= (int64_t)b.v; a.u = 0; break;
        case T_GE: a.v = u ? a.v >= b.v : (int64_t)a.v >= (int64_t)b.v; a.u = 0; break;
        case T_EQ: a.v = a.v == b.v; a.u = 0; break;
        case T_NE: a.v = a.v != b.v; a.u = 0; break;
        case '&': a.v &= b.v; a.u = u; break;
        case '^': a.v ^= b.v; a.u = u; break;
        case '|': a.v |= b.v; a.u = u; break;
        }
    }
    return a;
}

static PVal ex_cond(void)
{
    PVal c = ex_bin(1);
    if (ex_tok == '?') {
        ex_next();
        int sk = ex_skip;
        if (!c.v) ex_skip = 1;
        PVal a = ex_cond();
        ex_skip = sk;
        if (ex_tok != ':') pp_expr_error();
        ex_next();
        if (c.v) ex_skip = 1;
        PVal b = ex_cond();
        ex_skip = sk;
        PVal r = c.v ? a : b;
        r.u = a.u || b.u;
        return r;
    }
    return c;
}

static int parse_has_include(int is_next);

static int eval_pp_expr(int dir)
{
    TokSeq s;
    tseq_init(&s);
    str_clear(&ex_text);
    pp_in_expr = 1;
    for (;;) {
        next();
        int t = tok;
        if (tok < T_IDENT) {
            if (tok == T_NL || tok == T_EOF) break;
            if (tok >= T_STR && tok <= T_LDOUBLE) {
                pp_in_expr = 0;
                error("invalid constant in preprocessor expression");
            }
        } else if (tok == KW_DEFINED) {
            int saved = lexflags;
            lexflags &= ~LX_PP;
            next_raw();
            while (tok == ' ' || tok == '\t') next_raw();
            int paren = 0;
            if (tok == '(') {
                paren = 1;
                next_raw();
            }
            if (tok < T_IDENT) {
                lexflags = saved;
                pp_in_expr = 0;
                error("identifier after 'defined' expected");
            }
            int c = macro_find(tok) != NULL;
            if (paren) {
                next_raw();
                if (tok != ')') {
                    lexflags = saved;
                    pp_in_expr = 0;
                    expect("')'");
                }
            }
            lexflags = saved;
            tok = T_INT;
            tokc.i = c;
        } else if (tok == KW___HAS_INCLUDE || tok == KW___HAS_INCLUDE_NEXT) {
            int c = parse_has_include(t == KW___HAS_INCLUDE_NEXT);
            tok = T_INT;
            tokc.i = c;
        } else {
            tok = T_INT;
            tokc.i = 0;
        }
        if (tok == T_PPNUM) {
            str_puts(&ex_text, tokc.str.s);
        } else
            str_puts(&ex_text, tokname(tok, &tokc));
        str_putc(&ex_text, ' ');
        tseq_add_cur(&s);
        (void)t;
    }
    if (ex_text.len) ex_text.len--;
    str_cstr(&ex_text);
    if (s.n == 0) {
        pp_in_expr = 0;
        tseq_free_arr(s.a);
        error("#%s with no expression", tokname(dir, NULL));
    }
    tseq_add(&s, T_EOF);
    ex_dir = dir;
    /* evaluate */
    const int *p = s.a;
    ex_p = p;
    ex_skip = 0;
    /* skip line markers and convert numbers */
    TokSeq s2;
    tseq_init(&s2);
    {
        const int *q = s.a;
        int t; TokVal v;
        int saved_line = file->line;
        for (;;) {
            tseq_get(&t, &q, &v);
            if (t == T_LINE) { file->line = v.i; continue; }
            if (t == T_PPNUM) {
                int stok = tok; TokVal sv = tokc;
                pp_in_expr = 0;
                parse_ppnum_tok(v.str.s);
                pp_in_expr = 1;
                /* in preprocessor expressions, numbers are 64-bit */
                t = tok; v = tokc;
                if (t == T_INT || t == T_LONG) t = T_LLONG;
                else if (t == T_UINT || t == T_ULONG) t = T_ULLONG;
                tok = stok; tokc = sv;
            } else if (t == T_PPSTR) {
                int stok = tok; TokVal sv = tokc;
                pp_in_expr = 0;
                parse_pp_str_tok(v.str.s);
                pp_in_expr = 1;
                t = tok; v = tokc;
                tok = stok; tokc = sv;
                if (t == T_STR || t == T_WSTR) {
                    pp_in_expr = 0;
                    error("invalid constant in preprocessor expression");
                }
            }
            tseq_add_val(&s2, t, &v);
            if (t == T_EOF || t == 0) break;
        }
        (void)saved_line;
    }
    ex_p = s2.a;
    pp_in_expr = 1;
    ex_next();
    PVal r = ex_cond();
    if (ex_tok != T_EOF) pp_expr_error();
    pp_in_expr = 0;
    tseq_free_arr(s.a);
    tseq_free_arr(s2.a);
    return r.v != 0;
}

static int parse_has_include(int is_next)
{
    /* __has_include("file") or __has_include(<file>) */
    (void)is_next;
    next();
    if (tok != '(') { pp_in_expr = 0; expect("'('"); }
    int saved = lexflags;
    char name[1024];
    int c;
    unsigned char *p = file->p;
    if (mac_ptr) {
        next();
        if (tok == T_PPSTR) {
            int l = strlen(tokc.str.s);
            snprintf(name, sizeof name, "%.*s", l - 2, tokc.str.s + 1);
            c = '"';
        } else if (tok == T_LT) {
            Str a; str_init(&a);
            next();
            while (tok != T_GT && tok != T_NL && tok != T_EOF) { str_puts(&a, tokname(tok, &tokc)); next(); }
            snprintf(name, sizeof name, "%s", str_cstr(&a));
            str_free(&a);
            c = '<';
        } else {
            pp_in_expr = 0;
            error("'#include' expects \"FILENAME\" or <FILENAME>");
        }
    } else {
        c = lex_peek(&p);
        while (is_space_ch(c)) { p++; c = lex_peek(&p); }
        if (c != '<' && c != '"') {
            pp_in_expr = 0;
            file->p = p;
            error("'#include' expects \"FILENAME\" or <FILENAME>");
        }
        int sep = c == '<' ? '>' : '"', n = 0;
        p++;
        for (;;) {
            int ch = lex_peek(&p);
            if (ch == sep) break;
            if (ch == '\n' || ch == -1) { pp_in_expr = 0; file->p = p; error("'#include' expects \"FILENAME\" or <FILENAME>"); }
            if (n < 1020) name[n++] = ch;
            p++;
        }
        name[n] = 0;
        file->p = p + 1;
    }
    lexflags = saved;
    next();
    if (tok != ')') { pp_in_expr = 0; expect("')'"); }
    /* search */
    int npaths = opt.include_paths.n + opt.sysinclude_paths.n;
    int i0 = is_next ? file->next_idx + 1 : 0;
    for (int i = i0; i <= npaths; i++) {
        char path[2048];
        if (i == 0) {
            if (name[0] == '/') pstrcpy(path, sizeof path, name);
            else {
                if (c != '"') continue;
                const char *fn = file->true_name;
                const char *b = path_basename(fn);
                snprintf(path, sizeof path, "%.*s%s", (int)(b - fn), fn, name);
            }
        } else {
            const char *dir = i - 1 < opt.include_paths.n ? opt.include_paths.v[i - 1]
                              : opt.sysinclude_paths.v[i - 1 - opt.include_paths.n];
            snprintf(path, sizeof path, "%s/%s", dir, name);
        }
        if (access(path, R_OK) == 0) return 1;
    }
    return 0;
}

/* ------------------------------------------------------------ skipping */
static void pp_skip(void)
{
    int depth = 0;
    int start_of_line;
    int in_msg = 0;
    unsigned char *p = file->p;
    for (;;) {
    redo_start:
        start_of_line = 1;
        in_msg = 0;
        for (;;) {
            int c = lex_peek(&p);
            switch (c) {
            case ' ': case '\t': case '\f': case '\v': case '\r':
                p++;
                continue;
            case '\n':
                file->line++;
                p++;
                goto redo_start;
            case -1:
                file->p = p;
                /* end of file inside conditional: let lexer report */
                tflags |= TF_BOL;
                return;
            case '"': case '\'':
                if (in_msg) { p++; break; }
                {
                    int sep = c;
                    p++;
                    for (;;) {
                        int ch = lex_peek(&p);
                        if (ch == sep) { p++; break; }
                        if (ch == '\\') {
                            p++;
                            ch = lex_peek(&p);
                            if (ch == -1) break;
                            if (ch == '\n') file->line++;
                            p++;
                            continue;
                        }
                        if (ch == '\n' || ch == -1) break;
                        p++;
                    }
                }
                break;
            case '/': {
                if (in_msg) { p++; break; }
                p++;
                int c2 = lex_peek(&p);
                if (c2 == '*') p = lex_skip_comment(p + 1);
                else if (c2 == '/') p = lex_skip_line_comment(p + 1);
                break;
            }
            case '#':
                p++;
                if (start_of_line) {
                    file->p = p;
                    int saved = lexflags;
                    lexflags = (lexflags & ~(LX_SPACES)) | LX_NL;
                    lexflags &= ~LX_PP;
                    next_raw();
                    lexflags = saved;
                    p = file->p;
                    if (depth == 0 && (tok == KW_ELSE || tok == KW_ELIF || tok == KW_ENDIF)) {
                        file->p = p;
                        return;
                    }
                    if (tok == KW_IF || tok == KW_IFDEF || tok == KW_IFNDEF)
                        depth++;
                    else if (tok == KW_ENDIF)
                        depth--;
                    else if (tok == KW_ERROR || tok == KW_WARNING)
                        in_msg = 1;
                    else if (tok == T_NL)
                        goto redo_start;
                    else if (lexflags & LX_ASM)
                        p = lex_skip_line_comment(p);
                }
                break;
            default:
                p++;
                break;
            }
            start_of_line = 0;
        }
    }
}

/* ------------------------------------------------------------ #define */
static void parse_define(void)
{
    int v = tok;
    int funclike = 0, nparams = 0, variadic = 0;
    int *params = NULL;
    int saved = lexflags;
    if (v < T_IDENT || v == KW_DEFINED)
        error("invalid macro name '%s'", tokname(tok, &tokc));
    lexflags = (lexflags & ~LX_ASM) | LX_SPACES;
    next_raw();
    lexflags &= ~LX_SPACES;
    if (tok == '(') {
        int cap = 0;
        next_raw();
        if (tok != ')') for (;;) {
            int varg = tok;
            int isva = 0;
            next_raw();
            if (varg == T_ELLIPSIS) {
                varg = KW___VA_ARGS__;
                isva = 1;
            } else if (tok == T_ELLIPSIS && opt.gnu_ext) {
                isva = 1;
                next_raw();
            }
            if (varg < T_IDENT) {
            bad_list:
                error("bad macro parameter list");
            }
            if (nparams == cap) { cap = cap ? cap * 2 : 4; params = xrealloc(params, cap * sizeof(int)); }
            params[nparams++] = varg;
            if (isva) variadic = 1;
            if (tok == ')') break;
            if (tok != ',' || isva) goto bad_list;
            next_raw();
        }
        lexflags |= LX_SPACES;
        next_raw();
        funclike = 1;
    }
    /* body */
    TokSeq s;
    tseq_init(&s);
    int need_spc = 0, t0 = 0;
    lexflags |= LX_SPACES;
    while (tok != T_NL && tok != T_EOF) {
        if (is_space_ch(tok)) {
            need_spc |= 1;
        } else {
            if (tok == T_PASTE) {
                if (t0 == 0) goto bad_paste;
                tok = T_JOIN;
            }
            if (need_spc == 3) tseq_add(&s, ' ');
            need_spc = 2;
            tseq_add_val(&s, tok, &tokc);
            t0 = tok;
        }
        next_raw();
    }
    lexflags = saved;
    if (t0 == T_JOIN) {
    bad_paste:
        lexflags = saved;
        error("'##' cannot appear at either end of macro");
    }
    tseq_add(&s, 0);
    macro_define(v, funclike, nparams, params, variadic, s.a);
}

/* ------------------------------------------------------------ pragmas */
static int pragma_handle(void)
{
    /* returns 1 if consumed (not to be output in -E mode) */
    int saved = lexflags;
    next();
    if (tok == KW_once) {
        IncCache *e = cache_find(file->true_name, 1);
        e->once = pp_once;
        e->once = 1;
        return 1;
    }
    if (tok == KW_push_macro || tok == KW_pop_macro) {
        int t = tok;
        next();
        if (tok != '(') goto pragma_err;
        next();
        if (tok != T_STR && tok != T_PPSTR) goto pragma_err;
        {
            char nm[256];
            const char *s = tokc.str.s;
            if (tok == T_PPSTR) {
                int l = strlen(s);
                snprintf(nm, sizeof nm, "%.*s", l - 2, s + 1);
            } else snprintf(nm, sizeof nm, "%s", s);
            int v = ident_tok(nm);
            next();
            if (tok != ')') goto pragma_err;
            if (t == KW_push_macro) push_macro(v);
            else pop_macro(v);
        }
        return 1;
    }
    if (opt.output_type == OUT_PREPROCESS) {
        lexflags = saved;
        return 0;
    }
    if (tok == KW_pack) {
        next();
        if (tok != '(') goto pragma_err;
        next();
        if (tok == KW_pop) {
            next();
            if (pack_sp <= pack_stack) {
            stk_err:
                error("out of pack stack");
            }
            pack_sp--;
        } else {
            int val = 0;
            if (tok != ')') {
                if (tok == KW_push) {
                    next();
                    if (pack_sp >= pack_stack + 7) goto stk_err;
                    pack_sp[1] = pack_sp[0];
                    pack_sp++;
                    if (tok != ',') goto pack_end;
                    next();
                }
                if (tok != T_INT) goto pragma_err;
                val = tokc.i;
                if (val < 1 || val > 16 || (val & (val - 1)))
                    goto pragma_err;
                next();
            }
            *pack_sp = val;
        }
    pack_end:
        if (tok != ')') goto pragma_err;
    } else if (tok == KW_comment) {
        next();
        if (tok != '(') goto pragma_err;
        next();
        if (tok == KW_lib) {
            next();
            if (tok != ',') goto pragma_err;
            next();
            if (tok != T_STR) goto pragma_err;
            pvec_push(&pragma_libs, xstrdup(tokc.str.s));
            next();
            if (tok != ')') goto pragma_err;
        } else {
            while (tok != T_NL && tok != T_EOF) next();
        }
    } else if (tok == KW_option) {
        while (tok != T_NL && tok != T_EOF) next();
    } else {
        warning_opt(WOPT_UNSUPPORTED, "#pragma %s ignored", tokname(tok, &tokc));
        while (tok != T_NL && tok != T_EOF) next();
        return 1;
    }
    next();
    return 1;
pragma_err:
    error("malformed #pragma directive");
    return 1;
}

/* ------------------------------------------------------------ directives */
static int pp_line_ref_fix;

void pp_directive(int bof)
{
    int saved = lexflags;
    int c, n;
    lexflags = LX_PP | LX_NUM | LX_STR | LX_NL | (lexflags & LX_ASM);
    next_raw();
redo:
    switch (tok) {
    case KW_DEFINE:
        next_raw();
        parse_define();
        break;
    case KW_UNDEF:
        next_raw();
        macro_undef(tok);
        next_raw();
        skip_to_eol(1);
        break;
    case KW_INCLUDE:
    case KW_INCLUDE_NEXT:
        do_include(tok == KW_INCLUDE_NEXT);
        lexflags = saved;
        if (opt.output_type == OUT_PREPROCESS) {}
        return;
    case KW_IFNDEF:
        c = 1;
        goto do_ifdef;
    case KW_IF:
        c = eval_pp_expr(KW_IF);
        goto do_if;
    case KW_IFDEF:
        c = 0;
    do_ifdef:
        next_raw();
        if (tok < T_IDENT)
            error("invalid argument for '#if%sdef'", c ? "n" : "");
        if (bof) {
            if (c) {
                file->guard_tok = tok;
            }
        }
        c = (macro_find(tok) != NULL) ^ c;
        next_raw();
        skip_to_eol(1);
    do_if:
        if (cond_sp >= cond_stack + 64)
            error("memory full (ifdef)");
        *cond_sp++ = c;
        goto test_skip;
    case KW_ELSE:
        if (cond_sp == cond_stack)
            error("#else without matching #if");
        if (cond_sp[-1] & 2)
            error("#else after #else");
        c = (cond_sp[-1] ^= 3);
        next_raw();
        skip_to_eol(1);
        goto test_else;
    case KW_ELIF:
        if (cond_sp == cond_stack)
            error("#elif without matching #if");
        c = cond_sp[-1];
        if (c > 1)
            error("#elif after #else");
        if (c == 1) {
            c = 0;
        } else {
            c = eval_pp_expr(KW_ELIF);
            cond_sp[-1] = c;
        }
    test_else:
        if (cond_sp == file->cond_base + 1)
            file->guard_tok = 0;
    test_skip:
        if (!(c & 1)) {
            pp_skip();
            /* tok is now else/elif/endif */
            goto redo;
        }
        break;
    case KW_ENDIF:
        if (cond_sp <= file->cond_base)
            error("#endif without matching #if");
        cond_sp--;
        if (file->guard_tok && cond_sp == file->cond_base) {
            /* possibly end of include guard: remember */
            file->guard_saved = file->guard_tok;
            tflags |= TF_ENDIF;
        }
        next_raw();
        skip_to_eol(1);
        break;
    case T_PPNUM:
        n = 1;
        goto do_line;
    case KW_LINE:
        n = 0;
        next();
    do_line: {
        if (tok != T_PPNUM) {
        line_err:
            error("wrong #line format");
        }
        parse_ppnum_tok(tokc.str.s);
        if (tok != T_INT && tok != T_UINT && tok != T_LONG && tok != T_ULONG &&
            tok != T_LLONG && tok != T_ULLONG)
            goto line_err;
        int ln = (int)tokc.i;
        next();
        if (tok != T_NL) {
            if (tok == T_STR) {
                if (file->true_name == NULL || 1) {}
                pstrcpy(file->name, sizeof file->name, tokc.str.s);
            } else if (tok == T_PPSTR && tokc.str.s[0] == '"') {
                const char *s = tokc.str.s;
                int l = strlen(s);
                snprintf(file->name, sizeof file->name, "%.*s", l - 2, s + 1);
            } else
                goto line_err;
            if (n) {
                /* gnu line marker: allow flags */
                while (tok != T_NL && tok != T_EOF) next_raw();
            } else {
                next_raw();
                skip_to_eol(1);
            }
            /* leave it to -E printer */
            if (opt.output_type == OUT_PREPROCESS) {}
        }
        if (file->true_name && 0) {}
        file->line = ln;
        pp_line_ref_fix = 1;
        if (opt.output_type == OUT_PREPROCESS) {
            extern void pp_line_reset(void);
            pp_line_reset();
        }
        break;
    }
    case KW_ERROR:
    case KW_WARNING: {
        int t = tok;
        Str msg;
        str_init(&msg);
        unsigned char *p = file->p;
        int ch = lex_peek(&p);
        while (is_space_ch(ch)) { p++; ch = lex_peek(&p); }
        while (ch != '\n' && ch != -1) {
            str_putc(&msg, ch);
            p++;
            ch = lex_peek(&p);
        }
        file->p = p;
        if (t == KW_ERROR)
            error("#error %s", str_cstr(&msg));
        warning("#warning %s", str_cstr(&msg));
        str_free(&msg);
        next_raw();
        break;
    }
    case KW_PRAGMA:
        if (!pragma_handle()) {
            /* -E: pass the pragma line through */
            extern void pp_pass_pragma(void);
            pp_pass_pragma();
            lexflags = saved;
            return;
        }
        if (tok != T_NL) {
            while (tok != T_NL && tok != T_EOF) next_raw();
        }
        break;
    case T_NL:
        lexflags = saved;
        return;
    default:
        if (tok == '!' && bof) {
            /* shebang line */
            unsigned char *p = file->p;
            int ch = lex_peek(&p);
            while (ch != '\n' && ch != -1) { p++; ch = lex_peek(&p); }
            file->p = p;
            next_raw();
            break;
        }
        if (lexflags & LX_ASM) {
            while (tok != T_NL && tok != T_EOF) next_raw();
            break;
        }
        warning("ignoring unknown preprocessing directive #%s", tokname(tok, &tokc));
        while (tok != T_NL && tok != T_EOF) next_raw();
        break;
    }
    lexflags = saved;
    /* the newline that ended the directive has been consumed by next_raw */
    if (tok == T_EOF) {
        /* reached end of file inside directive: let the lexer handle eof */
    }
}

/* called by lexer at end of a file; returns 1 if end of all input */
int pp_file_end(void)
{
    if (cond_sp != file->cond_base)
        error("missing #endif");
    if (inc_sp == inc_stack) {
        tflags = 0;
        return 1;
    }
    /* include guard detection */
    if (file->guard_saved && (tflags & TF_ENDIF || 1)) {
        IncCache *e = cache_find(file->true_name, 1);
        if (!e->guard) e->guard = file->guard_saved;
    }
    src_close();
    inc_sp--;
    tflags = TF_BOL;
    return 0;
}

/* ------------------------------------------------------------ macro expansion */
static void subst(TokSeq *out, Ident **nested, int *nn, const int *body);

static int check_space(int t, int *spc)
{
    if (t < 256 && (is_space_ch(t) || t == T_NL)) {
        if (*spc) return 1;
        *spc = 1;
    } else
        *spc = 0;
    return 0;
}

#define NEST_MAX 4096
static int nest_has(Ident **nested, int nn, int t)
{
    for (int i = 0; i < nn; i++)
        if (nested[i] && nested[i]->tok == t) return 1;
    return 0;
}

/* read next token for macro argument collection. If ws is non-NULL,
   accumulate whitespace and return the next non-space char/token kind. */
static int next_argstream(Ident **nested, int *nn, TokSeq *ws)
{
    for (;;) {
        if (mac_ptr) {
            const int *p = mac_ptr;
            int t = *p;
            if (ws) {
                while (t == ' ' || t == '\t' || t == T_NL || t == T_PLACEHOLDER || is_space_ch(t)) {
                    tseq_add(ws, t);
                    t = *++p;
                }
                mac_ptr = p;
            }
            if (t == 0) {
                pop_reader();
                /* end of scope for macros expanded in the finished string */
                for (int i = *nn - 1; i >= 0; i--)
                    if (nested[i]) { nested[i] = NULL; break; }
                continue;
            }
            if (ws) return t & ~NOEXP_BIT;
            next_raw_or_seq: ;
            {
                int tt; TokVal v;
                tseq_get(&tt, &mac_ptr, &v);
                if (tt == T_LINE) { file->line = v.i; continue; }
                tok = tt & ~NOEXP_BIT;
                tokc = v;
                return tok;
            }
            goto next_raw_or_seq;
        } else {
            unsigned char *p = file->p;
            int ch = lex_peek(&p);
            if (ws) {
                while (is_space_ch(ch) || ch == '\n' || ch == '/') {
                    if (ch == '/') {
                        unsigned char *q = p + 1;
                        int c2 = lex_peek(&q);
                        if (c2 == '*') {
                            p = lex_skip_comment(q + 1);
                        } else if (c2 == '/') {
                            p = lex_skip_line_comment(q + 1);
                        } else
                            break;
                        ch = ' ';
                        tseq_add(ws, ch);
                        ch = lex_peek(&p);
                        continue;
                    }
                    if (ch == '\n') file->line++;
                    if (!(ch == '\f' || ch == '\v' || ch == '\r'))
                        tseq_add(ws, ch);
                    p++;
                    ch = lex_peek(&p);
                }
            }
            file->p = p;
            if (ws) return ch;
            next_raw();
            return tok;
        }
    }
}

/* substitute macro arguments into body */
static int *arg_subst(Ident **nested, int *nn, const int *body, Macro *m, int **args)
{
    TokSeq out;
    tseq_init(&out);
    int t, t0 = 0, t1 = 0;
    TokVal cv;
    int **expanded = xcalloc(sizeof(int *) * (m->nparams + 1));
    for (;;) {
        tseq_get(&t, &body, &cv);
        if (!t) break;
        if (t == '#' && m->funclike) {
            tseq_get(&t, &body, &cv);
            if (!t) goto bad_stringy;
            int ai = -1;
            for (int i = 0; i < m->nparams; i++) if (m->params[i] == t) ai = i;
            if (ai < 0) {
            bad_stringy:
                expect("macro parameter after '#'");
            }
            Str cs;
            str_init(&cs);
            str_putc(&cs, '"');
            const int *st = args[ai];
            int spc = 0;
            int at; TokVal av;
            for (;;) {
                if (*st < 0 || *st == 0) break;
                tseq_get(&at, &st, &av);
                if (at == T_LINE) continue;
                if (at != T_PLACEHOLDER && at != T_NOEXP && !check_space(at, &spc)) {
                    const char *s = tokname(at, &av);
                    for (; *s; s++) {
                        if (at == T_PPSTR && *s != '\'') {
                            /* escape quotes and backslashes in strings */
                            if (*s == '"' || *s == '\\') str_putc(&cs, '\\');
                            str_putc(&cs, *s);
                        } else
                            str_putc(&cs, *s);
                    }
                }
            }
            cs.len -= spc;
            str_putc(&cs, '"');
            str_putc(&cs, 0);
            TokVal sv;
            sv.str.s = cs.s;
            sv.str.n = cs.len;
            tseq_add_val(&out, T_PPSTR, &sv);
            str_free(&cs);
        } else if (t >= T_IDENT) {
            int ai = -1;
            for (int i = 0; i < m->nparams; i++) if (m->params[i] == t) ai = i;
            if (ai >= 0) {
                int l0 = out.n;
                const int *st = args[ai];
                int isva = m->variadic && ai == m->nparams - 1;
                if (*body == T_JOIN || t1 == T_JOIN) {
                    /* no expansion next to ## */
                    if (t1 == T_JOIN && t0 == ',' && opt.gnu_ext && isva) {
                        if (*st <= 0) {
                            /* remove ', ##' */
                            out.n -= 2;
                        } else {
                            out.n--;
                            goto add_var;
                        }
                    }
                } else {
                add_var:
                    if (!expanded[ai]) {
                        TokSeq s2;
                        tseq_init(&s2);
                        subst(&s2, nested, nn, st);
                        tseq_add(&s2, 0);
                        expanded[ai] = s2.a;
                    }
                    st = expanded[ai];
                }
                for (;;) {
                    int t2; TokVal v2;
                    tseq_get(&t2, &st, &v2);
                    if (t2 <= 0) break;
                    tseq_add_val(&out, t2, &v2);
                }
                if (out.n == l0)
                    tseq_add(&out, T_PLACEHOLDER);
            } else
                tseq_add(&out, t);
        } else
            tseq_add_val(&out, t, &cv);
        t0 = t1;
        t1 = t;
    }
    tseq_add(&out, 0);
    for (int i = 0; i < m->nparams; i++) free(expanded[i]);
    free(expanded);
    return out.a;
}

/* handle ## operators */
extern int pp_paste_tokens(int t1, TokVal *v1, int t2, TokVal *v2, int *rt, TokVal *rv);

static int *do_paste(const int *ptr0)
{
    const int *p = ptr0;
    int t;
    TokVal cv;
    int has = 0;
    /* quick scan */
    {
        const int *q = ptr0;
        for (;;) {
            tseq_get(&t, &q, &cv);
            if (!t) break;
            if (t == T_JOIN) { has = 1; break; }
        }
    }
    if (!has) return NULL;
    TokSeq out;
    tseq_init(&out);
    for (;;) {
        tseq_get(&t, &p, &cv);
        if (!t) break;
        if (t == T_JOIN) continue;
        /* look ahead for ## */
        const int *q = p;
        while (*q == ' ') q++;
        if (*q == T_JOIN) {
            Str buf;
            str_init(&buf);
            int t1 = t; TokVal v1 = cv;
            if (t1 != T_PLACEHOLDER) str_puts(&buf, tokname(t1, &v1));
            int first_ok = t1 != T_PLACEHOLDER;
            const char *s1copy = xstrdup(str_cstr(&buf));
            while (*q == T_JOIN) {
                q++;
                while (*q == ' ') q++;
                int t2; TokVal v2;
                tseq_get(&t2, &q, &v2);
                if (t2 == T_PLACEHOLDER) {
                } else {
                    const char *s2 = tokname(t2, &v2);
                    /* try to lex combined */
                    Str comb;
                    str_init(&comb);
                    str_puts(&comb, str_cstr(&buf));
                    str_puts(&comb, s2);
                    if (first_ok) {
                        /* validate: must lex as a single token */
                        extern int pp_relex_single(const char *s);
                        if (!pp_relex_single(str_cstr(&comb))) {
                            warning("pasting \"%s\" and \"%s\" does not give a valid preprocessing token",
                                    str_cstr(&buf), s2);
                            /* keep tokens separate */
                            {
                                /* emit buf tokens as-is then continue with t2 */
                                extern void pp_relex_into(TokSeq *out, const char *s);
                                pp_relex_into(&out, str_cstr(&buf));
                                str_clear(&buf);
                                str_puts(&buf, s2);
                                str_free(&comb);
                                first_ok = 1;
                                while (*q == ' ') q++;
                                continue;
                            }
                        }
                    }
                    str_clear(&buf);
                    str_puts(&buf, str_cstr(&comb));
                    str_free(&comb);
                    first_ok = 1;
                }
                while (*q == ' ') { const int *r = q; while (*r == ' ') r++; if (*r == T_JOIN) q = r; else break; }
            }
            free((void *)s1copy);
            p = q;
            if (buf.len) {
                extern void pp_relex_into(TokSeq *out, const char *s);
                pp_relex_into(&out, str_cstr(&buf));
            } else
                tseq_add(&out, T_PLACEHOLDER);
            str_free(&buf);
        } else {
            tseq_add_val(&out, t, &cv);
        }
    }
    tseq_add(&out, 0);
    return out.a;
}

static void stack_nested(Ident **nested, int *nn, Ident *id)
{
    if (*nn < NEST_MAX) nested[(*nn)++] = id;
}

/* expand macro m whose name is the current token; append result to out.
   returns 0 normally */
static int expand_macro(TokSeq *out, Ident **nested, int *nn, Macro *m)
{
    int t = tok;
    char buf[64];
    TokVal cv;
    if (t == KW___LINE__ || t == KW___COUNTER__) {
        snprintf(buf, sizeof buf, "%d", t == KW___LINE__ ? file->line : pp_counter++);
        cv.str.s = buf;
        cv.str.n = strlen(buf) + 1;
        tseq_add_val(out, T_PPNUM, &cv);
        return 0;
    }
    if (t == KW___FILE__) {
        cv.str.s = file->name;
        cv.str.n = strlen(file->name) + 1;
        tseq_add_val(out, T_STR, &cv);
        return 0;
    }
    if (t == KW___DATE__ || t == KW___TIME__) {
        time_t ti;
        struct tm *tm;
        static const char mon[12][4] = { "Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec" };
        time(&ti);
        tm = localtime(&ti);
        if (t == KW___DATE__)
            snprintf(buf, sizeof buf, "%s %2d %d", mon[tm->tm_mon], tm->tm_mday, tm->tm_year + 1900);
        else
            snprintf(buf, sizeof buf, "%02d:%02d:%02d", tm->tm_hour, tm->tm_min, tm->tm_sec);
        cv.str.s = buf;
        cv.str.n = strlen(buf) + 1;
        tseq_add_val(out, T_STR, &cv);
        return 0;
    }
    int saved = lexflags;
    const int *mstr = m->body;
    int *mstr_alloc = NULL;
    if (m->funclike) {
        TokSeq ws;
        tseq_init(&ws);
        lexflags |= LX_SPACES | LX_NL | LX_STRAYS;
        int c = next_argstream(nested, nn, &ws);
        if (c != '(') {
            lexflags = saved;
            tseq_add(out, t);
            if (lexflags & LX_SPACES) {
                for (int i = 0; i < ws.n; i++) tseq_add(out, ws.a[i]);
            }
            if (ws.n && ws.a[ws.n - 1] == '\n')
                tflags |= TF_BOL;
            free(ws.a);
            return 0;
        }
        free(ws.a);
        do {
            next_argstream(nested, nn, NULL); /* eat '(' */
            if (!mac_ptr && tok == '(') break;
        } while (tok == T_PLACEHOLDER || is_space_ch(tok));
        if (tok == '(') { /* consumed */ }
        int **args = xcalloc(sizeof(int *) * (m->nparams + 1));
        int ai = 0;
        for (;;) {
            do {
                next_argstream(nested, nn, NULL);
            } while (tok == T_PLACEHOLDER || is_space_ch(tok) || tok == T_NL);
        empty_arg:
            if (ai == 0 && m->nparams == 0 && tok == ')')
                break;
            if (ai >= m->nparams)
                error("macro '%s' used with too many args", tokname(m->tok, NULL));
            TokSeq a;
            tseq_init(&a);
            int par = 0, spc = 0;
            int isva = m->variadic && ai == m->nparams - 1;
            while (par > 0 || (tok != ')' && (tok != ',' || isva))) {
                if (tok == T_EOF || tok == 0)
                    break;
                if (tok == '(') par++;
                else if (tok == ')') par--;
                if (tok == T_NL) tok = ' ';
                if (!check_space(tok, &spc))
                    tseq_add_val(&a, tok, &tokc);
                next_argstream(nested, nn, NULL);
            }
            if (tok == T_EOF || tok == 0) {
                if (tok == T_EOF || 1)
                    error("EOF in invocation of macro '%s'", tokname(m->tok, NULL));
            }
            a.n -= spc;
            tseq_add(&a, -1);
            tseq_add(&a, 0);
            args[ai++] = a.a;
            if (tok == ')') {
                if (ai < m->nparams && m->variadic && ai == m->nparams - 1 && opt.gnu_ext)
                    goto empty_arg;
                break;
            }
            if (tok != ',')
                expect("','");
        }
        if (ai < m->nparams)
            error("macro '%s' used with too few args", tokname(m->tok, NULL));
        mstr = mstr_alloc = arg_subst(nested, nn, m->body, m, args);
        for (int i = 0; i < ai; i++) free(args[i]);
        free(args);
        lexflags = saved;
    }
    stack_nested(nested, nn, ident_of(t));
    int *joined = do_paste(mstr);
    subst(out, nested, nn, joined ? joined : mstr);
    /* pop */
    (*nn)--;
    free(joined);
    free(mstr_alloc);
    return 0;
}

static void subst(TokSeq *out, Ident **nested, int *nn, const int *body)
{
    int t, spc = 0, nosubst = 0;
    TokVal cv;
    for (;;) {
        tseq_get(&t, &body, &cv);
        if (t <= 0) break;
        if (t >= T_IDENT && !(t & NOEXP_BIT) && !nosubst) {
            Macro *m = macro_find(t);
            if (!m) goto no_subst;
            if (nest_has(nested, *nn, t)) {
                tseq_add(out, t | NOEXP_BIT);
                t = t | NOEXP_BIT;
                spc = 0;
                goto after;
            }
            {
                TokSeq *rs = xcalloc(sizeof *rs);
                rs->a = (int *)body;
                push_reader(rs, 2);
                void *top = reader_top();
                tok = t;
                expand_macro(out, nested, nn, m);
                if (reader_top() != top) {
                    /* string consumed while reading macro arguments */
                    free(rs);
                    break;
                }
                body = mac_ptr;
                /* pop without freeing body */
                rs->a = NULL;
                pop_reader();
                free(rs);
            }
            if (out->n) {
                int lt = out->a[out->lastn];
                spc = lt < 256 && is_space_ch(lt);
            }
        } else {
        no_subst:
            if (!check_space(t, &spc))
                tseq_add_val(out, t, &cv);
            if (nosubst) {
                if (nosubst > 1 && (spc || (++nosubst == 3 && t == '(')))
                    continue;
                nosubst = 0;
            }
            if (t == T_NOEXP)
                nosubst = 1;
        }
    after:
        if (t == KW_DEFINED && pp_in_expr)
            nosubst = 2;
    }
}

/* ------------------------------------------------------------ next() */
void next(void)
{
    int t;
    for (;;) {
        if (mac_ptr) {
            t = *mac_ptr;
            if (IS_VALTOK(t)) {
                tseq_get(&tok, &mac_ptr, &tokc);
                if (t == T_LINE) {
                    file->line = tokc.i;
                    continue;
                }
                goto convert;
            } else if (t == 0) {
                pop_reader();
                continue;
            } else if (t == T_EOF) {
                tok = t;
                return;
            } else {
                mac_ptr++;
                t &= ~NOEXP_BIT;
                if (t == '\\' && !(lexflags & LX_STRAYS))
                    error("stray '\\' in program");
            }
            tok = t;
            return;
        }
        next_raw();
        t = tok;
        if (t >= T_IDENT && (lexflags & LX_PP)) {
            Macro *m = macro_find(t);
            if (m) {
                static Ident *nested[NEST_MAX];
                int nn = 0;
                expand_buf.n = 0;
                expand_macro(&expand_buf, nested, &nn, m);
                tseq_add(&expand_buf, 0);
                TokSeq *s = xcalloc(sizeof *s);
                s->a = xmalloc(expand_buf.n * sizeof(int));
                memcpy(s->a, expand_buf.a, expand_buf.n * sizeof(int));
                s->n = expand_buf.n;
                push_reader(s, 1);
                continue;
            }
            return;
        }
        break;
    }
convert:
    if (tok == T_PPNUM) {
        if (lexflags & LX_NUM)
            parse_ppnum_tok(tokc.str.s);
    } else if (tok == T_PPSTR) {
        if (lexflags & LX_STR)
            parse_pp_str_tok(tokc.str.s);
    }
}

/* push back current token, making 'last' the current one */
void unget_tok(int last)
{
    TokSeq *s = tseq_new();
    tseq_add_val(s, tok, &tokc);
    tseq_add(s, 0);
    push_reader(s, 1);
    tok = last;
}

/* ------------------------------------------------------------ token re-lexing for ## */
static int relex_buf(const char *s, TokSeq *out)
{
    /* lex string s into tokens, returns number of tokens */
    SrcFile *sf = file;
    int st = tok; TokVal sv = tokc;
    int sflags = lexflags, stf = tflags;
    const int *smp = mac_ptr;
    mac_ptr = NULL;
    int n = 0;
    src_open_buf(":paste:", s, strlen(s));
    file->line = sf ? sf->line : 1;
    lexflags = 0;
    for (;;) {
        unsigned char *p = file->p;
        if (p >= file->end) break;
        next_raw();
        if (tok == T_EOF) break;
        n++;
        if (out) tseq_add_val(out, tok, &tokc);
        if (file->p >= file->end) break;
    }
    /* close without touching include stack */
    SrcFile *f = file;
    file = f->up;
    free(f->buf);
    free(f->true_name);
    free(f);
    file = sf;
    tok = st; tokc = sv;
    lexflags = sflags; tflags = stf;
    mac_ptr = smp;
    return n;
}

int pp_relex_single(const char *s)
{
    TokSeq tmp;
    tseq_init(&tmp);
    int n = relex_buf(s, &tmp);
    free(tmp.a);
    return n == 1;
}

void pp_relex_into(TokSeq *out, const char *s)
{
    relex_buf(s, out);
}

