static void add_path_list(PVec *v, const char *in, const char *base)
{
    /* split on ':' and expand {B} */
    const char *p = in;
    while (1) {
        const char *q = strchr(p, ':');
        int len = q ? q - p : (int)strlen(p);
        Str s;
        str_init(&s);
        for (int i = 0; i < len; i++) {
            if (p[i] == '{' && !strncmp(p + i, "{B}", 3) && base) {
                str_puts(&s, base);
                i += 2;
            } else
                str_putc(&s, p[i]);
        }
        if (s.len) pvec_push(v, xstrdup(str_cstr(&s)));
        str_free(&s);
        if (!q) break;
        p = q + 1;
    }
}

