    int on = 1;
    const char *r;
    if (starts_with(s, "no-", &r)) { on = 0; s = r; }
    if (!strcmp(s, "all")) {
        opt.w_all = on;
        if (!(opt.w_implicit_decl & 2)) opt.w_implicit_decl = on;
        if (!(opt.w_discarded_qual & 2)) opt.w_discarded_qual = on;
        return 0;
    }
    if (starts_with(s, "error", &r)) {
        if (*r == 0) { opt.w_error = on; return 0; }
        if (*r == '=') {
            r++;
            if (!strcmp(r, "implicit-function-declaration")) { opt.w_error_implicit_decl = on; if (on) opt.w_implicit_decl = 3; return 0; }
            if (!strcmp(r, "discarded-qualifiers")) { opt.w_error_discarded = on; if (on) opt.w_discarded_qual = 3; return 0; }
            if (!strcmp(r, "write-strings")) { opt.w_error_write_strings = on; if (on) opt.w_write_strings = 3; return 0; }
            if (!strcmp(r, "unsupported")) { opt.w_error_unsupported = on; if (on) opt.w_unsupported = 3; return 0; }
            return -1;
        }
        return -1;
    }
    if (!strcmp(s, "write-strings")) return warn_flag(s, &opt.w_write_strings, on);
    if (!strcmp(s, "unsupported")) return warn_flag(s, &opt.w_unsupported, on);
    if (!strcmp(s, "implicit-function-declaration")) return warn_flag(s, &opt.w_implicit_decl, on);
    if (!strcmp(s, "discarded-qualifiers")) return warn_flag(s, &opt.w_discarded_qual, on);
    return -1;
}

static int set_f(const char *s)
{
    int on = 1;
    const char *r;
    if (starts_with(s, "no-", &r)) { on = 0; s = r; }
    if (!strcmp(s, "unsigned-char")) { opt.char_unsigned = on; return 0; }
    if (!strcmp(s, "signed-char")) { opt.char_unsigned = !on; return 0; }
    if (!strcmp(s, "common")) { opt.nocommon = !on; return 0; }
    if (!strcmp(s, "leading-underscore")) { opt.leading_underscore = on; return 0; }
    if (!strcmp(s, "ms-extensions")) { opt.ms_ext = on; return 0; }
    if (!strcmp(s, "dollars-in-identifiers")) { opt.dollars = on; return 0; }
    if (!strcmp(s, "reverse-funcargs")) { opt.reverse_funcargs = on; return 0; }
    if (!strcmp(s, "gnu89-inline")) { opt.gnu89_inline = on; return 0; }
    if (!strcmp(s, "asynchronous-unwind-tables")) { opt.unwind_tables = on; return 0; }
    if (!strcmp(s, "test-coverage")) { opt.tcov = on; return 0; }
    return -1;
}

static int set_m(const char *s)
{
    if (!strcmp(s, "ms-bitfields")) { opt.ms_bitfields = 1; return 0; }
    if (!strcmp(s, "no-sse")) { opt.nosse = 1; return 0; }
    return -1;
}

static int link_opt(const char *s, const char *name, const char **val)
{
    /* match linker option name, possibly with '=' or ',' value */
    const char *p = s;
    if (*p == '-') { p++; if (*p == '-') p++; }
    size_t n = strlen(name);
    if (strncmp(p, name, n)) return 0;
    p += n;
    if (*p == 0) { *val = p; return 1; }
    if (*p == '=' || *p == ',') { *val = p + 1; return 1; }
    return 0;
}

static char *strdup_until(const char *s)
{
    const char *e = strchr(s, ',');
    return e ? xstrndup(s, e - s) : xstrdup(s);
}

static int set_linker(const char *optarg)
{
    const char *p = optarg, *v;
    while (p && *p) {
        int ignore = 0;
        const char *end = NULL;
        if (link_opt(p, "Bsymbolic", &v)) { opt.symbolic = 1; end = v; }
        else if (link_opt(p, "nostdlib", &v)) { opt.nostdlib = 1; end = v; }
        else if (link_opt(p, "e", &v) || link_opt(p, "entry", &v)) { opt.entry = strdup_until(v); end = v; }
        else if (link_opt(p, "image-base", &v) || link_opt(p, "Ttext", &v)) {
            char *e;
            opt.text_addr = strtoull(v, &e, 16);
            opt.has_text_addr = 1;
            end = v;
        }
        else if (link_opt(p, "init", &v)) { opt.init_sym = strdup_until(v); ignore = 1; end = v; }
        else if (link_opt(p, "fini", &v)) { opt.fini_sym = strdup_until(v); ignore = 1; end = v; }
        else if (link_opt(p, "Map", &v)) { ignore = 1; end = v; }
        else if (link_opt(p, "oformat", &v)) { end = v; }
        else if (link_opt(p, "as-needed", &v)) { ignore = 1; end = v; }
        else if (link_opt(p, "O", &v)) { ignore = 1; end = v; }
        else if (link_opt(p, "export-all-symbols", &v) || link_opt(p, "export-dynamic", &v)) { opt.rdynamic = 1; end = v; }
        else if (link_opt(p, "rpath", &v)) { opt.rpath = strdup_until(v); end = v; }
        else if (link_opt(p, "enable-new-dtags", &v)) { opt.new_dtags = 1; end = v; }
        else if (link_opt(p, "section-alignment", &v)) { end = v; }
        else if (link_opt(p, "soname", &v)) { opt.soname = strdup_until(v); end = v; }
        else if (link_opt(p, "I", &v) || link_opt(p, "dynamic-linker", &v)) { opt.elfint = strdup_until(v); end = v; }
        else if (link_opt(p, "whole-archive", &v)) { opt.filetype_next |= 0x80; end = v; }
        else if (link_opt(p, "no-whole-archive", &v)) { opt.filetype_next &= ~0x80; end = v; }
        else if (link_opt(p, "z", &v)) { ignore = 1; end = v; }
        else {
            char *e = strdup_until(p);
            error("unsupported linker option '%s'", e);
        }
        (void)ignore;
        /* advance to next comma-separated option */
        if (end) {
            const char *c = strchr(end, ',');
            p = c ? c + 1 : NULL;
        } else p = NULL;
    }
    return 0;
}

static int args_parsed_noaction;

static char **expand_listfile(const char *fn, int *pn)
{
    int fd = open(fn, O_RDONLY);
    if (fd < 0) error("listfile '%s' not found", fn);
    Str b; str_init(&b);
    char tmp[4096];
    ssize_t n;
    while ((n = read(fd, tmp, sizeof tmp)) > 0) str_putn(&b, tmp, n);
    close(fd);
    char *s = str_cstr(&b);
    PVec v = { 0 };
    while (*s) {
        while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
        if (!*s) break;
        Str a; str_init(&a);
        int q = 0;
        while (*s && (q || !(*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r'))) {
            if (*s == '"') { q = !q; s++; continue; }
            if (*s == '\\' && s[1]) { s++; }
            str_putc(&a, *s++);
        }
        pvec_push(&v, xstrdup(str_cstr(&a)));
        str_free(&a);
    }
    *pn = v.n;
    return (char **)v.v;
}

static const char *run_opts;

/* returns 0 for normal operation, O_xxx for special, -1 on error */
int parse_args(int argc, char **argv, int first)
{
    int i = first;
    int noaction = 0, nopts = 0;
    int tool = 0;
    int run = 0;
    PVec args = { 0 };
    for (int k = first; k < argc; k++) pvec_push(&args, argv[k]);
    for (i = 0; i < args.n; i++) {
        const char *r = args.v[i];
        if (r[0] == '@' && r[1]) {
            int n;
            char **la = expand_listfile(r + 1, &n);
            /* splice */
            PVec na = { 0 };
            for (int k = 0; k < i; k++) pvec_push(&na, args.v[k]);
            for (int k = 0; k < n; k++) pvec_push(&na, la[k]);
            for (int k = i + 1; k < args.n; k++) pvec_push(&na, args.v[k]);
            args = na;
            i--;
            continue;
        }
        nopts++;
        if (r[0] != '-' || r[1] == 0) {
            add_file_spec(r, opt.filetype_next);
            if (run) {
                opt.run_argc = args.n - i;
                opt.run_argv = (char **)args.v + i;
                break;
            }
            continue;
        }
        if (r[1] == '-' && r[2] == 0 && run) {
            /* '--' terminates options for -run */
            opt.run_argc = args.n - i - 1;
            opt.run_argv = (char **)args.v + i + 1;
            if (opt.run_argc > 0) {
                add_file_spec(opt.run_argv[0], opt.filetype_next);
            }
            break;
        }
        int found = -1;
        const char *optarg = NULL;
        for (int t = 0; opt_table[t].name; t++) {
            const char *rest;
            if (!starts_with(r + 1, opt_table[t].name, &rest)) continue;
            if (opt_table[t].flags & HAS_ARG) {
                if (*rest == 0 && !(opt_table[t].flags & NOSEP)) {
                    if (i + 1 >= args.n)
                        error("argument to '%s' is missing", r);
                    rest = args.v[++i];
                }
            } else if (*rest)
                continue;
            found = t;
            optarg = rest;
            break;
        }
        if (found < 0)
            error("invalid option -- '%s'", r);
        int id = opt_table[found].id;
        int out_type = 0;
        switch (id) {
        case OPT_help:
            tool = O_HELP;
            goto extra_action;
        case OPT_help2:
            tool = O_HELP2;
            goto extra_action;
        case OPT_print_search_dirs:
            tool = O_PRINT_DIRS;
            goto extra_action;
        case OPT_ar:
            tool = O_AR;
        extra_action:
            if (nopts - 1 != noaction)
                error("cannot parse %s here", r);
            free(args.v);
            return tool;
        case OPT_dumpversion:
            printf("%s\n", "0.9.28rc");
            exit(0);
        case OPT_v:
            do ++opt.verbose; while (*optarg++ == 'v');
            ++noaction;
            break;
        case OPT_I:
            pvec_push(&opt.include_paths, xstrdup(optarg));
            break;
        case OPT_D: {
            const char *eq = strchr(optarg, '=');
            if (eq)
                str_printf(&opt.cmdline_defs, "#define %.*s %s\n", (int)(eq - optarg), optarg, eq + 1);
            else
                str_printf(&opt.cmdline_defs, "#define %s 1\n", optarg);
            break;
        }
        case OPT_U:
            str_printf(&opt.cmdline_defs, "#undef %s\n", optarg);
            break;
        case OPT_P:
            opt.Pflag = atoi(optarg) + 1;
            break;
        case OPT_L:
            pvec_push(&opt.library_paths, xstrdup(optarg));
            break;
        case OPT_B:
            free(opt.tcc_lib_path);
            opt.tcc_lib_path = xstrdup(optarg);
            break;
        case OPT_l:
            add_file_spec(optarg, FT_LIB | (opt.filetype_next & ~0x7f));
            break;
        case OPT_bench:
            opt.bench = 1;
            break;
        case OPT_bt:
            opt.rt_num_callers = atoi(optarg);
            opt.backtrace = 1;
            opt.debug = opt.debug ? opt.debug : 1;
            break;
        case OPT_b:
            opt.bcheck = 1;
            opt.backtrace = 1;
            opt.debug = opt.debug ? opt.debug : 1;
            break;
        case OPT_g:
            opt.debug = 2;
            if (starts_with(optarg, "dwarf", NULL)) opt.dwarf = 5;
            break;
        case OPT_c:
            out_type = OUT_OBJ;
            goto set_output_type;
        case OPT_d:
            if (*optarg == 'D') opt.dflag = 3;
            else if (*optarg == 'M') opt.dflag = 7;
            else if (*optarg == 't') opt.dflag = 16;
            else if (isdigit((unsigned char)*optarg)) opt.dflag = atoi(optarg);
            else goto unsupported_option;
            break;
        case OPT_static:
            opt.static_link = 1;
            break;
        case OPT_std:
            if (!strcmp(optarg, "=c11") || !strcmp(optarg, "=gnu11"))
                opt.cversion = 201112;
            break;
        case OPT_shared:
            out_type = OUT_DLL;
            goto set_output_type;
        case OPT_soname:
            opt.soname = xstrdup(optarg);
            break;
        case OPT_o:
            if (opt.outfile) {
                warning("multiple -o option");
                free(opt.outfile);
            }
            opt.outfile = xstrdup(optarg);
            break;
        case OPT_r:
            opt.option_r = 1;
            out_type = OUT_OBJ;
            goto set_output_type;
        case OPT_isystem:
            pvec_push(&opt.sysinclude_paths, xstrdup(optarg));
            break;
        case OPT_include:
            str_printf(&opt.cmdline_incl, "#include \"%s\"\n", optarg);
            break;
        case OPT_nostdinc:
            opt.nostdinc = 1;
            break;
        case OPT_nostdlib:
            opt.nostdlib = 1;
            break;
        case OPT_run:
            run_opts = optarg;
            run = 1;
            out_type = OUT_MEMORY;
            goto set_output_type;
        case OPT_rstdin:
            opt.rstdin = xstrdup(optarg);
            break;
        case OPT_E:
            out_type = OUT_PREPROCESS;
        set_output_type:
            if (opt.output_type)
                warning("-%s: overriding compiler action already specified", opt_table[found].name);
            opt.output_type = out_type;
            break;
        case OPT_pthread:
            opt.pthread = 1;
            break;
        case OPT_rdynamic:
            opt.rdynamic = 1;
            break;
        case OPT_Wl:
            if (opt.output_type == 0 && 0) {}
            set_linker(optarg);
            break;
        case OPT_Wp:
            /* pass through as preprocessor options */
            {
                Str s; str_init(&s);
                for (const char *c = optarg; *c; c++) str_putc(&s, *c == ',' ? ' ' : *c);
                char *sargv[64];
                int sargc = 1;
                char *tk = strtok(str_cstr(&s), " ");
                sargv[0] = "tcc";
                while (tk && sargc < 63) { sargv[sargc++] = tk; tk = strtok(NULL, " "); }
                parse_args(sargc, sargv, 1);
            }
            break;
        case OPT_W:
            if (set_W(optarg) < 0) goto unsupported_option;
            break;
        case OPT_w:
            opt.w_none = 1;
            break;
        case OPT_O:
            opt.optimize = strcmp(optarg, "0") ? 1 : 0;
            if (!*optarg) opt.optimize = 1;
            break;
        case OPT_m:
            if (!strcmp(optarg, "32") || !strcmp(optarg, "64")) {
                if (optarg[0] == '3') {
                    free(args.v);
                    return O_M32;
                }
                break;
            }
            if (set_m(optarg) < 0) goto unsupported_option;
            break;
        case OPT_f:
            if (set_f(optarg) < 0) goto unsupported_option;
            break;
        case OPT_M:
            opt.just_deps = 1;
            if (!opt.deps_outfile) opt.deps_outfile = xstrdup("-");
            /* fallthrough */
        case OPT_MD:
            opt.gen_deps = 1;
            opt.sys_deps = 1;
            break;
        case OPT_MM:
            opt.just_deps = 1;
            if (!opt.deps_outfile) opt.deps_outfile = xstrdup("-");
            /* fallthrough */
        case OPT_MMD:
            opt.gen_deps = 1;
            break;
        case OPT_MF:
            opt.deps_outfile = xstrdup(optarg);
            break;
        case OPT_MP:
            opt.phony_deps = 1;
            break;
        case OPT_x: {
            int c = *optarg;
            if (c == 'c') opt.filetype_next = (opt.filetype_next & 0x80) | FT_C;
            else if (c == 'a') opt.filetype_next = (opt.filetype_next & 0x80) | FT_ASMPP;
            else if (c == 'b') opt.filetype_next = (opt.filetype_next & 0x80) | FT_BIN;
            else if (c == 'n') opt.filetype_next = opt.filetype_next & 0x80;
            else warning("unsupported language '%s'", optarg);
            break;
        }
        case OPT_ignored:
            if (opt.w_unsupported & 1) warning("unsupported option '%s'", r);
            break;
        default:
        unsupported_option:
            warning_opt(WOPT_UNSUPPORTED, "unsupported option '%s'", r);
            break;
        }
    }
    free(args.v);
    if (opt.pthread && opt.output_type != OUT_OBJ) {}
    if (nopts != noaction)
        return 0;
    if (opt.verbose == 2)
        return O_PRINT_DIRS;
    if (opt.verbose)
        return O_V;
    return O_HELP;
}

static void print_dirs_list(const char *msg, PVec *v)
{
    printf("%s:\n%s", msg, v->n ? "" : "  -\n");
    for (int i = 0; i < v->n; i++)
        printf("  %s\n", (char *)v->v[i]);
}

void setup_paths(void)
{
    const char *lib = opt.tcc_lib_path;
    /* default include paths */
    if (!opt.nostdinc) {
        PVec sys = { 0 };
        add_path_list(&sys, "{B}/include:/usr/local/include/x86_64-linux-gnu:/usr/local/include:/usr/include/x86_64-linux-gnu:/usr/include", lib);
        /* prepend user -isystem paths */
        for (int i = 0; i < sys.n; i++) pvec_push(&opt.sysinclude_paths, sys.v[i]);
        free(sys.v);
    }
    const char *e;
    if ((e = getenv("CPATH"))) add_path_list(&opt.include_paths, e, lib);
    if ((e = getenv("C_INCLUDE_PATH"))) add_path_list(&opt.sysinclude_paths, e, lib);
    if ((e = getenv("LIBRARY_PATH"))) add_path_list(&opt.library_paths, e, lib);
    if (!opt.nostdlib || 1) {
        add_path_list(&opt.library_paths,
            "{B}:/usr/lib/x86_64-linux-gnu:/usr/lib:/lib/x86_64-linux-gnu:/lib:/usr/local/lib/x86_64-linux-gnu:/usr/local/lib", lib);
        add_path_list(&opt.crt_paths, "/usr/lib/x86_64-linux-gnu", lib);
    }
}

void print_search_dirs(void)
{
    printf("install: %s\n", opt.tcc_lib_path);
    print_dirs_list("include", &opt.sysinclude_paths);
    print_dirs_list("libraries", &opt.library_paths);
    printf("libtcc1:\n  %s/%s\n", opt.tcc_lib_path, "libtcc1.a");
    print_dirs_list("crt", &opt.crt_paths);
    printf("elfinterp:\n  %s\n", "/lib64/ld-linux-x86-64.so.2");
}

static char *default_outfile(const char *first)
{
    char buf[1024];
    const char *name = "a";
    if (first && strcmp(first, "-"))
        name = path_basename(first);
    snprintf(buf, sizeof buf, "%s", name);
    char *ext = (char *)path_ext(buf);
    if ((opt.just_deps || opt.output_type == OUT_OBJ) && !opt.option_r && *ext)
        strcpy(ext, ".o");
    else
        strcpy(buf, "a.out");
    return xstrdup(buf);
}

extern int compile_all(int nfiles_start, int nfiles_end, const char **first_file);
extern int link_and_output(const char *outfile, const char *first_file);
extern int run_compiled(int argc, char **argv);
extern void gen_makedeps(const char *target, const char *filename);
extern int do_preprocess_files(int start, int end);
extern int run_dt_tests(void);

static int process(int start, int one_only, int *pnext, int first_round)
{
    int n = opt.files.n;
    int ret = 0;
    const char *first_file = NULL;
    (void)first_round;
    int end = one_only ? start + 1 : n;
    if (setjmp(err_jmp)) {
        return 1;
    }
    err_jmp_set = 1;
    ret = compile_all(start, end, &first_file);
    *pnext = end;
    if (opt.output_type == OUT_PREPROCESS) {
        if (ppout && ppout != stdout) fclose(ppout);
        else fflush(stdout);
        return ret;
    }
    if (ret) return ret;
    if (nb_errors) return 1;
    if (opt.output_type == OUT_MEMORY) {
        return run_compiled(opt.run_argc, opt.run_argv);
    }
    if (!opt.outfile) opt.outfile = default_outfile(first_file);
    if (!opt.just_deps) {
        if (link_and_output(opt.outfile, first_file))
            return 1;
    }
    if (opt.gen_deps)
        gen_makedeps(opt.outfile, opt.deps_outfile);
    return 0;
}

static void reset_options(void)
{
    memset(&opt, 0, sizeof opt);
    opt.tcc_lib_path = xstrdup("/usr/local/lib/tcc");
    opt.cversion = 199901;
    opt.gnu_ext = 1;
    opt.tcc_ext = 1;
    opt.w_implicit_decl = 1;
    opt.unwind_tables = 1;
    opt.dollars = 1;
    opt.w_discarded_qual = 1;
    opt.w_write_strings = 0;
}

int main(int argc, char **argv)
{
    int ret;
    int start = 0;
    int round = 0;

    if (argc > 1 && !strcmp(argv[1], "-ar")) {
        return tool_ar(argc - 1, argv + 1);
    }
redo:
    reset_options();
    pp_init();
    {
        int o;
        if (setjmp(err_jmp)) return 1;
        err_jmp_set = 1;
        o = parse_args(argc, argv, 1);
        err_jmp_set = 0;
        if (o < 0) return 1;
        if (opt.files.n == 0 || o > 0) {
            if (o == O_HELP) {
                fputs(help_text, stdout);
                if (!opt.verbose) return 0;
                o = O_HELP2;
            }
            if (o == O_HELP2) {
                fputs(help2_text, stdout);
                return 0;
            }
            if (o == O_M32) {
                /* defer to cross compiler */
                char path[1024];
                const char *a0 = argv[0];
                const char *b = path_basename(a0);
                snprintf(path, sizeof path, "%.*si386-tcc", (int)(b - a0), a0);
                char cwd[1024];
                if (path[0] != '/') {
                    if (getcwd(cwd, sizeof cwd)) {
                        char p2[2100];
                        const char *rel = path;
                        if (rel[0] == '.' && rel[1] == '/') rel += 2;
                        snprintf(p2, sizeof p2, "%s/%s", cwd, rel);
                        snprintf(path, sizeof path, "%s", p2);
                    }
                }
                execvp(path, argv);
                fprintf(stderr, "tcc: could not run '%s'\n", path);
                return 1;
            }
            if (opt.verbose) printf("%s", version_line);
            if (o == O_AR) return tool_ar(argc - 1, argv + 1);
            if (o == O_V) return 0;
            if (o == O_PRINT_DIRS) {
                setup_paths();
                print_search_dirs();
                return 0;
            }
            if (opt.files.n == 0) {
                fflush(stdout);
                fprintf(stderr, "tcc: error: no input files\n");
                return 1;
            }
        }
    }
    if (opt.verbose && round == 0) printf("%s", version_line);
    int n = opt.files.n;
    if (setjmp(err_jmp)) return 1;
    err_jmp_set = 1;
    ppout = stdout;
    if (opt.output_type == OUT_PREPROCESS) {
        if (opt.outfile && strcmp(opt.outfile, "-")) {
            ppout = fopen(opt.outfile, "wb");
            if (!ppout) error("could not write '%s'", opt.outfile);
        }
    } else if (opt.output_type == OUT_OBJ && !opt.option_r) {
        if (opt.nb_libraries)
            error("cannot specify libraries with -c");
        if (n > 1 && opt.outfile)
            error("cannot specify output file with -c many files");
    }
    if (opt.output_type == 0) opt.output_type = OUT_EXE;
    setup_paths();
    int one = opt.output_type == OUT_OBJ && !opt.option_r;
    /* skip files of previous rounds */
    int nextf = start;
    if (one) {
        /* skip to first non-library file at index >= start */
        fflush(stdout);
        pid_t pid = fork();
        if (pid == 0) {
            ret = process(start, 1, &nextf, round == 0);
            fflush(stdout);
            _exit(ret);
        }
        int st;
        waitpid(pid, &st, 0);
        ret = WIFEXITED(st) ? WEXITSTATUS(st) : 1;
        nextf = start + 1;
        if (ret == 0 && nextf < n) {
            start = nextf;
            round++;
            goto redo;
        }
        return ret;
    }
    ret = process(start, 0, &nextf, 1);
    fflush(stdout);
    return ret ? 1 : 0;
}
EOF
echo ok"}

