/* compile or preprocess one C/asm source file */
static int compile_source(const char *fn, int type)
{
    Str cl;
    int is_pp = opt.output_type == OUT_PREPROCESS;
    int is_asm = type == FT_ASM || type == FT_ASMPP;
    if (src_open(fn) < 0) {
        error("file '%s' not found", fn);
    }
    if (opt.gen_deps) add_dep(file->name, 0);
    pp_begin(type);
