        if (opt.cmdline_defs.len) str_putn(&cl, opt.cmdline_defs.s, opt.cmdline_defs.len);
        if (opt.cmdline_incl.len) str_putn(&cl, opt.cmdline_incl.s, opt.cmdline_incl.len);
    }
    *inc_sp++ = file;
    src_open_buf("<command line>", cl.s ? cl.s : "", cl.len);
    str_free(&cl);
    tflags = TF_BOL | TF_BOF;
    if (is_pp) {
        pp_run();
    } else if (is_asm) {
        asm_compile_unit(type == FT_ASMPP);
    } else {
        gen_compile_unit();
    }
    pp_end();
    while (file) src_close();
    inc_sp = inc_stack;
    return nb_errors ? 1 : 0;
}

int add_input_file(const char *fn, int flags)
{
    int type = flags & 0x4f;
    if (type == 0) {
        const char *ext = path_ext(fn);
        if (*ext) {
            ext++;
            if (!strcmp(ext, "S")) type = FT_ASMPP;
            else if (!strcmp(ext, "s")) type = FT_ASM;
            else if (!strcmp(ext, "c") || !strcmp(ext, "h") || !strcmp(ext, "i")) type = FT_C;
            else type = FT_BIN;
        } else
            type = FT_C;
    }
    if (type == FT_C || type == FT_ASM || type == FT_ASMPP) {
        if (strcmp(fn, "-") && access(fn, R_OK) != 0) {
            error_noabort("file '%s' not found", fn);
            return -1;
        }
        return compile_source(fn, type);
    }
    /* binary */
    int fd = open(fn, O_RDONLY);
    if (fd < 0) {
        error_noabort("file '%s' not found", fn);
        return -1;
    }
    return load_input_binary(fn, fd, flags);
}

int compile_all(int start, int end, const char **first_file)
{
    int ret = 0;
    gen_global_init();
    for (int i = start; i < end && ret == 0; i++) {
        InFile *f = opt.files.v[i];
        if (f->type & FT_LIB) {
            if (opt.output_type == OUT_PREPROCESS) continue;
            ret = add_library_err(f->name);
        } else {
            if (opt.verbose == 1)
                printf("-> %s\n", f->name);
            if (!*first_file) *first_file = f->name;
            ret = add_input_file(f->name, f->type);
        }
    }
    return ret;
}
