/* called by lexer at end of a file; returns 1 if end of all input */
int pp_file_end(void)
{
    if (cond_sp != file->cond_base)
        error("missing #endif");
    if (inc_sp == inc_stack) {
        tflags = 0;
        return 1;
    }
    /* include guard detection */
    if (file->guard_saved) {
        IncCache *e = cache_find(file->true_name, 1);
        if (!e->guard) e->guard = file->guard_saved;
    }
    src_close();
    inc_sp--;
    tflags = TF_BOL;
    return 0;
}

/* ------------------------------------------------------------ macro expansion */
#define NEST_MAX 4096
typedef struct Nest { int tok[NEST_MAX]; int n; } Nest;

static void subst(TokSeq *out, Nest *nest, const int *body);

static int check_space(int t, int *spc)
{
    if (t < 256 && (is_space_ch(t) || t == T_NL)) {
        if (*spc) return 1;
        *spc = 1;
    } else
        *spc = 0;
    return 0;
}

static int nest_has(Nest *nest, int t)
{
    for (int i = 0; i < nest->n; i++)
        if (nest->tok[i] == t) return 1;
    return 0;
}

/* read next token while collecting macro arguments. When ws is given,
   only peek: accumulate whitespace into ws and return next char/token. */
static int next_argstream(Nest *nest, TokSeq *ws)
{
    for (;;) {
        if (mac_ptr) {
            const int *p = mac_ptr;
            int t = *p;
            if (ws) {
                while ((t < 256 && t > 0 && (is_space_ch(t) || t == T_NL)) || t == T_PLACEHOLDER) {
                    tseq_add(ws, t);
                    t = *++p;
                }
                mac_ptr = p;
            }
            if (t == 0) {
                pop_reader();
                /* end of scope of the innermost nested macro which was
                   fully read */
                for (int i = nest->n - 1; i >= 0; i--)
                    if (nest->tok[i]) { nest->tok[i] = 0; break; }
                continue;
            }
            if (ws) return t & ~NOEXP_BIT;
            {
                int tt;
                TokVal v;
                tseq_get(&tt, &mac_ptr, &v);
                if (tt == T_LINE) { file->line = v.i; continue; }
                tok = tt & ~NOEXP_BIT;
                tokc = v;
                return tok;
            }
        } else {
            unsigned char *p = file->p;
            int ch = lex_peek(&p);
            if (ws) {
                while (is_space_ch(ch) || ch == '\n' || ch == '/') {
                    if (ch == '/') {
                        unsigned char *q = p + 1;
                        int c2 = lex_peek(&q);
                        if (c2 == '*')
                            p = lex_skip_comment(q + 1);
                        else if (c2 == '/')
                            p = lex_skip_line_comment(q + 1);
                        else
                            break;
                        tseq_add(ws, ' ');
                        ch = lex_peek(&p);
                        continue;
                    }
                    if (ch == '\n') file->line++;
                    if (!(ch == '\f' || ch == '\v' || ch == '\r'))
                        tseq_add(ws, ch);
                    p++;
                    ch = lex_peek(&p);
                }
            }
            file->p = p;
            if (ws) return ch;
            next_raw();
            return tok;
        }
    }
}

static int param_index(Macro *m, int t)
{
    for (int i = 0; i < m->nparams; i++)
        if (m->params[i] == t) return i;
    return -1;
}

/* substitute macro arguments into body */
static int *arg_subst(Nest *nest, const int *body, Macro *m, int **args)
{
    TokSeq out;
    tseq_init(&out);
    int t, t0 = 0, t1 = 0;
    TokVal cv;
    int **expanded = xcalloc(sizeof(int *) * (m->nparams + 1));
    for (;;) {
        tseq_get(&t, &body, &cv);
        if (!t) break;
        if (t == '#') {
            tseq_get(&t, &body, &cv);
            if (!t) goto bad_stringy;
            int ai = param_index(m, t);
            if (ai < 0) {
            bad_stringy:
                expect("macro parameter after '#'");
            }
            Str cs;
            str_init(&cs);
            str_putc(&cs, '"');
            const int *st = args[ai];
            int spc = 0;
            int at;
            TokVal av;
            while (*st > 0) {
                tseq_get(&at, &st, &av);
                if (at == T_LINE) continue;
                if (at != T_PLACEHOLDER && at != T_NOEXP && !check_space(at, &spc)) {
                    const char *s = tokname(at, &av);
                    for (; *s; s++) {
                        if (at == T_PPSTR && *s != '\'' && (*s == '"' || *s == '\\'))
                            str_putc(&cs, '\\');
                        str_putc(&cs, *s);
                    }
                }
            }
            cs.len -= spc;
            str_putc(&cs, '"');
            str_putc(&cs, 0);
            TokVal sv;
            sv.str.s = cs.s;
            sv.str.n = cs.len;
            tseq_add_val(&out, T_PPSTR, &sv);
            str_free(&cs);
        } else if (t >= T_IDENT) {
            int ai = param_index(m, t);
            if (ai >= 0) {
                int l0 = out.n;
                const int *st = args[ai];
                int isva = m->variadic && ai == m->nparams - 1;
                if (*body == T_JOIN || t1 == T_JOIN) {
                    /* no expansion next to ## */
                    if (t1 == T_JOIN && t0 == ',' && opt.gnu_ext && isva) {
                        if (*st <= 0) {
                            /* remove ', ##' */
                            out.n -= 2;
                        } else {
                            out.n--;
                            goto add_var;
                        }
                    }
                } else {
                add_var:
                    if (!expanded[ai]) {
                        TokSeq s2;
                        tseq_init(&s2);
                        subst(&s2, nest, st);
                        tseq_add(&s2, 0);
                        expanded[ai] = s2.a;
                    }
                    st = expanded[ai];
                }
                for (;;) {
                    int t2;
                    TokVal v2;
                    tseq_get(&t2, &st, &v2);
                    if (t2 <= 0) break;
                    tseq_add_val(&out, t2, &v2);
                }
                if (out.n == l0)
                    tseq_add(&out, T_PLACEHOLDER);
            } else
                tseq_add(&out, t);
        } else
            tseq_add_val(&out, t, &cv);
        t0 = t1;
        t1 = t;
    }
    tseq_add(&out, 0);
    for (int i = 0; i < m->nparams; i++) free(expanded[i]);
    free(expanded);
    return out.a;
}

/* ------------------------------------------------------------ token pasting */
static int relex_buf(const char *s, TokSeq *out);

/* paste tokens around ## operators */
static int *do_paste(const int *ptr0)
{
    const int *p = ptr0;
    int t;
    TokVal cv;
    int has = 0;
    {
        const int *q = ptr0;
        for (;;) {
            tseq_get(&t, &q, &cv);
            if (!t) break;
            if (t == T_JOIN) { has = 1; break; }
        }
    }
    if (!has) return NULL;
    TokSeq out;
    tseq_init(&out);
    for (;;) {
        tseq_get(&t, &p, &cv);
        if (!t) break;
        const int *q = p;
        while (*q == ' ') q++;
        if (*q != T_JOIN) {
            tseq_add_val(&out, t, &cv);
            continue;
        }
        /* t ## ... */
        Str cur;
        str_init(&cur);
        if (t != T_PLACEHOLDER)
            str_puts(&cur, tokname(t, &cv));
        while (*q == T_JOIN) {
            q++;
            while (*q == ' ') q++;
            int t2;
            TokVal v2;
            tseq_get(&t2, &q, &v2);
            if (t2 != T_PLACEHOLDER) {
                const char *s2 = tokname(t2, &v2);
                if (cur.len == 0) {
                    str_puts(&cur, s2);
                } else {
                    Str comb;
                    str_init(&comb);
                    str_puts(&comb, str_cstr(&cur));
                    str_puts(&comb, s2);
                    TokSeq tmp;
                    tseq_init(&tmp);
                    int n = relex_buf(str_cstr(&comb), &tmp);
                    free(tmp.a);
                    if (n != 1) {
                        warning("pasting \"%s\" and \"%s\" does not give a valid preprocessing token",
                                str_cstr(&cur), s2);
                        relex_buf(str_cstr(&cur), &out);
                        str_clear(&cur);
                        str_puts(&cur, s2);
                    } else {
                        str_clear(&cur);
                        str_puts(&cur, str_cstr(&comb));
                    }
                    str_free(&comb);
                }
            }
            const int *r = q;
            while (*r == ' ') r++;
            if (*r == T_JOIN) q = r;
        }
        p = q;
        if (cur.len)
            relex_buf(str_cstr(&cur), &out);
        else
            tseq_add(&out, T_PLACEHOLDER);
        str_free(&cur);
    }
    tseq_add(&out, 0);
    return out.a;
}

/* expand macro m whose name is the current token; append result to out */
static void expand_macro(TokSeq *out, Nest *nest, Macro *m)
{
    int t = tok;
    char buf[64];
    TokVal cv;
    if (t == KW___LINE__ || t == KW___COUNTER__) {
        snprintf(buf, sizeof buf, "%d", t == KW___LINE__ ? file->line : pp_counter++);
        cv.str.s = buf;
        cv.str.n = strlen(buf) + 1;
        tseq_add_val(out, T_PPNUM, &cv);
        return;
    }
    if (t == KW___FILE__) {
        cv.str.s = file->name;
        cv.str.n = strlen(file->name) + 1;
        tseq_add_val(out, T_STR, &cv);
        return;
    }
    if (t == KW___DATE__ || t == KW___TIME__) {
        time_t ti;
        struct tm *tm;
        static const char mon[12][4] = { "Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec" };
        time(&ti);
        tm = localtime(&ti);
        if (t == KW___DATE__)
            snprintf(buf, sizeof buf, "%s %2d %d", mon[tm->tm_mon], tm->tm_mday, tm->tm_year + 1900);
        else
            snprintf(buf, sizeof buf, "%02d:%02d:%02d", tm->tm_hour, tm->tm_min, tm->tm_sec);
        cv.str.s = buf;
        cv.str.n = strlen(buf) + 1;
        tseq_add_val(out, T_STR, &cv);
        return;
    }
    int saved = lexflags;
    const int *mstr = m->body;
    int *mstr_alloc = NULL;
    if (m->funclike) {
        TokSeq ws;
        tseq_init(&ws);
        lexflags |= LX_SPACES | LX_NL | LX_STRAYS;
        int c = next_argstream(nest, &ws);
        if (c != '(') {
            lexflags = saved;
            tseq_add(out, t);
            if (lexflags & LX_SPACES) {
                for (int i = 0; i < ws.n; i++) tseq_add(out, ws.a[i]);
            }
            if (ws.n && ws.a[ws.n - 1] == '\n')
                tflags |= TF_BOL;
            free(ws.a);
            return;
        }
        free(ws.a);
        do {
            next_raw_or_reader:
            next_argstream(nest, NULL); /* eat '(' */
        } while (tok == T_PLACEHOLDER || (tok < 256 && is_space_ch(tok)));
        int **args = xcalloc(sizeof(int *) * (m->nparams + 1));
        int ai = 0;
        for (;;) {
            do {
                next_argstream(nest, NULL);
            } while (tok == T_PLACEHOLDER || (tok < 256 && tok > 0 && is_space_ch(tok)) || tok == T_NL);
        empty_arg:
            if (ai == 0 && m->nparams == 0 && tok == ')')
                break;
            if (ai >= m->nparams)
                error("macro '%s' used with too many args", tokname(m->tok, NULL));
            TokSeq a;
            tseq_init(&a);
            int par = 0, spc = 0;
            int isva = m->variadic && ai == m->nparams - 1;
            while (par > 0 || (tok != ')' && (tok != ',' || isva))) {
                if (tok == T_EOF || tok == 0)
                    break;
                if (tok == '(') par++;
                else if (tok == ')') par--;
                if (tok == T_NL) tok = ' ';
                if (!check_space(tok, &spc))
                    tseq_add_val(&a, tok, &tokc);
                next_argstream(nest, NULL);
            }
            if (tok == T_EOF || tok == 0)
                error("EOF in invocation of macro '%s'", tokname(m->tok, NULL));
            a.n -= spc;
            tseq_add(&a, -1);
            tseq_add(&a, 0);
            args[ai++] = a.a;
            if (tok == ')') {
                if (ai == m->nparams - 1 && m->variadic && opt.gnu_ext)
                    goto empty_arg;
                break;
            }
            if (tok != ',')
                expect("','");
        }
        if (ai < m->nparams)
            error("macro '%s' used with too few args", tokname(m->tok, NULL));
        mstr = mstr_alloc = arg_subst(nest, m->body, m, args);
        for (int i = 0; i < ai; i++) free(args[i]);
        free(args);
        lexflags = saved;
        (void)&&next_raw_or_reader;
    }
    if (nest->n < NEST_MAX) nest->tok[nest->n++] = t;
    int *joined = do_paste(mstr);
    subst(out, nest, joined ? joined : mstr);
    nest->n--;
    free(joined);
    free(mstr_alloc);
}

static void subst(TokSeq *out, Nest *nest, const int *body)
{
    int t, spc = 0, nosubst = 0;
    TokVal cv;
    for (;;) {
        tseq_get(&t, &body, &cv);
        if (t <= 0) break;
        if (t >= T_IDENT && !(t & NOEXP_BIT) && !nosubst) {
            Macro *m = macro_find(t);
            if (!m) goto no_subst;
            if (nest_has(nest, t)) {
                /* painted: never expand again */
                t |= NOEXP_BIT;
                goto no_subst;
            }
            {
                TokSeq *rs = xcalloc(sizeof *rs);
                rs->a = (int *)body;
                push_reader(rs, 2);
                void *top = reader_top();
                tok = t;
                expand_macro(out, nest, m);
                if (reader_top() != top) {
                    /* string consumed while reading macro arguments */
                    free(rs);
                    break;
                }
                body = mac_ptr;
                pop_reader();
                free(rs);
            }
            if (out->n) {
                int lt = out->a[out->lastn];
                spc = lt < 256 && lt > 0 && is_space_ch(lt);
            }
        } else {
        no_subst:
            if (!check_space(t, &spc))
                tseq_add_val(out, t, &cv);
            if (nosubst) {
                if (nosubst > 1 && (spc || (++nosubst == 3 && t == '(')))
                    continue;
                nosubst = 0;
            }
            if (t == T_NOEXP)
                nosubst = 1;
        }
        if (t == KW_DEFINED && pp_in_expr)
            nosubst = 2;
    }
}

/* ------------------------------------------------------------ next() */
void next(void)
{
    int t;
    for (;;) {
        if (mac_ptr) {
            t = *mac_ptr;
            if (IS_VALTOK(t)) {
                tseq_get(&tok, &mac_ptr, &tokc);
                if (t == T_LINE) {
                    file->line = tokc.i;
                    continue;
                }
                goto convert;
            } else if (t == 0) {
                pop_reader();
                continue;
            } else if (t == T_EOF) {
                tok = t;
                return;
            } else {
                mac_ptr++;
                t &= ~NOEXP_BIT;
                if (t == '\\' && !(lexflags & LX_STRAYS))
                    error("stray '\\' in program");
            }
            tok = t;
            return;
        }
        next_raw();
        t = tok;
        if (t >= T_IDENT && (lexflags & LX_PP)) {
            Macro *m = macro_find(t);
            if (m) {
                static Nest nest;
                nest.n = 0;
                expand_buf.n = 0;
                expand_macro(&expand_buf, &nest, m);
                tseq_add(&expand_buf, 0);
                TokSeq *s = xcalloc(sizeof *s);
                s->a = xmalloc(expand_buf.n * sizeof(int));
                memcpy(s->a, expand_buf.a, expand_buf.n * sizeof(int));
                s->n = expand_buf.n;
                push_reader(s, 1);
                continue;
            }
            return;
        }
        if (t == '\\' && !(lexflags & LX_STRAYS))
            error("stray '\\' in program");
        break;
    }
convert:
    if (tok == T_PPNUM) {
        if (lexflags & LX_NUM)
            parse_ppnum_tok(tokc.str.s);
    } else if (tok == T_PPSTR) {
        if (lexflags & LX_STR)
            parse_pp_str_tok(tokc.str.s);
    }
}

/* push back current token, making 'last' the current one */
void unget_tok(int last)
{
    TokSeq *s = tseq_new();
    tseq_add_val(s, tok, &tokc);
    tseq_add(s, 0);
    push_reader(s, 1);
    tok = last;
}

/* ------------------------------------------------------------ re-lexing for ## */
static int relex_buf(const char *s, TokSeq *out)
{
    SrcFile *sf = file;
    int st = tok;
    TokVal sv = tokc;
    int sflags = lexflags, stf = tflags;
    const int *smp = mac_ptr;
    char *saved_tokstr = NULL;
    if (tokstr.len) saved_tokstr = xstrndup(tokstr.s, tokstr.len);
    int saved_len = tokstr.len;
    mac_ptr = NULL;
    int n = 0;
    SrcFile *f = xcalloc(sizeof *f);
    int len = strlen(s);
    f->buf = xmalloc(len + 4);
    memcpy(f->buf, s, len);
    memset(f->buf + len, 0, 4);
    f->p = f->buf;
    f->end = f->buf + len;
    f->line = sf ? sf->line : 1;
    f->up = NULL;
    snprintf(f->name, sizeof f->name, "%s", sf ? sf->name : "");
    f->true_name = NULL;
    file = f;
    lexflags = 0;
    tflags = 0;
    /* a lone '#' or other char must not trigger directives */
    while (file->p < file->end) {
        unsigned char *p0 = file->p;
        if (*p0 == ' ' || *p0 == '\t') { file->p++; continue; }
        next_raw();
        if (tok == T_EOF) break;
        n++;
        if (out) tseq_add_val(out, tok, &tokc);
    }
    file = sf;
    free(f->buf);
    free(f);
    if (saved_tokstr) {
        str_clear(&tokstr);
        str_putn(&tokstr, saved_tokstr, saved_len);
        free(saved_tokstr);
    }
    tok = st;
    tokc = sv;
    if (tok == T_PPNUM || tok == T_PPSTR || tok == T_STR) tokc.str.s = tokstr.s;
    lexflags = sflags;
    tflags = stf;
    mac_ptr = smp;
    return n;
}

