                } else {
                    Str comb;
                    str_init(&comb);
                    str_puts(&comb, str_cstr(&cur));
                    str_puts(&comb, s2);
                    TokSeq tmp;
                    tseq_init(&tmp);
                    int n = relex_buf(str_cstr(&comb), &tmp);
                    free(tmp.a);
                    if (n != 1) {
                        warning("pasting \"%s\" and \"%s\" does not give a valid preprocessing token",
                                str_cstr(&cur), s2);
                        relex_buf(str_cstr(&cur), &out);
                        str_clear(&cur);
                        str_puts(&cur, s2);
                    } else {
                        str_clear(&cur);
                        str_puts(&cur, str_cstr(&comb));
                    }
                    str_free(&comb);
                }
            }
            const int *r = q;
            while (*r == ' ') r++;
            if (*r == T_JOIN) q = r;
        }
        p = q;
        if (cur.len)
            relex_buf(str_cstr(&cur), &out);
        else
            tseq_add(&out, T_PLACEHOLDER);
        str_free(&cur);
    }
    tseq_add(&out, 0);
    return out.a;
}

/* expand macro m whose name is the current token; append result to out */
static void expand_macro(TokSeq *out, Nest *nest, Macro *m)
{
    int t = tok;
    char buf[64];
    TokVal cv;
    if (t == KW___LINE__ || t == KW___COUNTER__) {
        snprintf(buf, sizeof buf, "%d", t == KW___LINE__ ? file->line : pp_counter++);
        cv.str.s = buf;
        cv.str.n = strlen(buf) + 1;
        tseq_add_val(out, T_PPNUM, &cv);
        return;
    }
    if (t == KW___FILE__) {
        cv.str.s = file->name;
        cv.str.n = strlen(file->name) + 1;
        tseq_add_val(out, T_STR, &cv);
        return;
    }
    if (t == KW___DATE__ || t == KW___TIME__) {
        time_t ti;
        struct tm *tm;
        static const char mon[12][4] = { "Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec" };
        time(&ti);
        tm = localtime(&ti);
        if (t == KW___DATE__)
            snprintf(buf, sizeof buf, "%s %2d %d", mon[tm->tm_mon], tm->tm_mday, tm->tm_year + 1900);
        else
            snprintf(buf, sizeof buf, "%02d:%02d:%02d", tm->tm_hour, tm->tm_min, tm->tm_sec);
        cv.str.s = buf;
        cv.str.n = strlen(buf) + 1;
        tseq_add_val(out, T_STR, &cv);
        return;
    }
    int saved = lexflags;
    const int *mstr = m->body;
    int *mstr_alloc = NULL;
    if (m->funclike) {
        TokSeq ws;
        tseq_init(&ws);
        lexflags |= LX_SPACES | LX_NL | LX_STRAYS;
        int c = next_argstream(nest, &ws);
        if (c != '(') {
            lexflags = saved;
            tseq_add(out, t);
            if (lexflags & LX_SPACES) {
                for (int i = 0; i < ws.n; i++) tseq_add(out, ws.a[i]);
            }
            if (ws.n && ws.a[ws.n - 1] == '\n')
                tflags |= TF_BOL;
            free(ws.a);
            return;
        }
        free(ws.a);
        do {
            next_raw_or_reader:
            next_argstream(nest, NULL); /* eat '(' */
        } while (tok == T_PLACEHOLDER || (tok < 256 && is_space_ch(tok)));
        int **args = xcalloc(sizeof(int *) * (m->nparams + 1));
        int ai = 0;
        for (;;) {
            do {
                next_argstream(nest, NULL);
            } while (tok == T_PLACEHOLDER || (tok < 256 && tok > 0 && is_space_ch(tok)) || tok == T_NL);
        empty_arg:
            if (ai == 0 && m->nparams == 0 && tok == ')')
                break;
            if (ai >= m->nparams)
                error("macro '%s' used with too many args", tokname(m->tok, NULL));
            TokSeq a;
            tseq_init(&a);
            int par = 0, spc = 0;
            int isva = m->variadic && ai == m->nparams - 1;
            while (par > 0 || (tok != ')' && (tok != ',' || isva))) {
                if (tok == T_EOF || tok == 0)
                    break;
                if (tok == '(') par++;
                else if (tok == ')') par--;
                if (tok == T_NL) tok = ' ';
                if (!check_space(tok, &spc))
                    tseq_add_val(&a, tok, &tokc);
                next_argstream(nest, NULL);
            }
            if (tok == T_EOF || tok == 0)
                error("EOF in invocation of macro '%s'", tokname(m->tok, NULL));
            a.n -= spc;
            tseq_add(&a, -1);
            tseq_add(&a, 0);
            args[ai++] = a.a;
            if (tok == ')') {
                if (ai == m->nparams - 1 && m->variadic && opt.gnu_ext)
                    goto empty_arg;
                break;
            }
            if (tok != ',')
                expect("','");
        }
        if (ai < m->nparams)
            error("macro '%s' used with too few args", tokname(m->tok, NULL));
        mstr = mstr_alloc = arg_subst(nest, m->body, m, args);
        for (int i = 0; i < ai; i++) free(args[i]);
        free(args);
        lexflags = saved;
        (void)&&next_raw_or_reader;
    }
    if (nest->n < NEST_MAX) nest->tok[nest->n++] = t;
    int *joined = do_paste(mstr);
    subst(out, nest, joined ? joined : mstr);
    nest->n--;
    free(joined);
    free(mstr_alloc);
}

static void subst(TokSeq *out, Nest *nest, const int *body)
{
    int t, spc = 0, nosubst = 0;
    TokVal cv;
    for (;;) {
        tseq_get(&t, &body, &cv);
        if (t <= 0) break;
        if (t >= T_IDENT && !(t & NOEXP_BIT) && !nosubst) {
            Macro *m = macro_find(t);
            if (!m) goto no_subst;
            if (nest_has(nest, t)) {
                /* painted: never expand again */
                t |= NOEXP_BIT;
                goto no_subst;
            }
            {
                TokSeq *rs = xcalloc(sizeof *rs);
                rs->a = (int *)body;
                push_reader(rs, 2);
                void *top = reader_top();
                tok = t;
                expand_macro(out, nest, m);
                if (reader_top() != top) {
                    /* string consumed while reading macro arguments */
                    free(rs);
                    break;
                }
                body = mac_ptr;
                pop_reader();
                free(rs);
            }
            if (out->n) {
                int lt = out->a[out->lastn];
                spc = lt < 256 && lt > 0 && is_space_ch(lt);
            }
        } else {
        no_subst:
            if (!check_space(t, &spc))
                tseq_add_val(out, t, &cv);
            if (nosubst) {
                if (nosubst > 1 && (spc || (++nosubst == 3 && t == '(')))
                    continue;
                nosubst = 0;
            }
            if (t == T_NOEXP)
                nosubst = 1;
        }
        if (t == KW_DEFINED && pp_in_expr)
            nosubst = 2;
    }
}

/* ------------------------------------------------------------ next() */
void next(void)
{
    int t;
    for (;;) {
        if (mac_ptr) {
            t = *mac_ptr;
            if (IS_VALTOK(t)) {
                tseq_get(&tok, &mac_ptr, &tokc);
                if (t == T_LINE) {
                    file->line = tokc.i;
                    continue;
                }
                goto convert;
            } else if (t == 0) {
                pop_reader();
                continue;
            } else if (t == T_EOF) {
                tok = t;
                return;
            } else {
                mac_ptr++;
                t &= ~NOEXP_BIT;
                if (t == '\\' && !(lexflags & LX_STRAYS))
                    error("stray '\\' in program");
            }
            tok = t;
            return;
        }
        next_raw();
        t = tok;
        if (t >= T_IDENT && (lexflags & LX_PP)) {
            Macro *m = macro_find(t);
            if (m) {
                static Nest nest;
                nest.n = 0;
                expand_buf.n = 0;
                expand_macro(&expand_buf, &nest, m);
                tseq_add(&expand_buf, 0);
                TokSeq *s = xcalloc(sizeof *s);
                s->a = xmalloc(expand_buf.n * sizeof(int));
                memcpy(s->a, expand_buf.a, expand_buf.n * sizeof(int));
                s->n = expand_buf.n;
                push_reader(s, 1);
                continue;
            }
            return;
        }
        if (t == '\\' && !(lexflags & LX_STRAYS))
            error("stray '\\' in program");
        break;
    }
convert:
    if (tok == T_PPNUM) {
        if (lexflags & LX_NUM)
            parse_ppnum_tok(tokc.str.s);
    } else if (tok == T_PPSTR) {
        if (lexflags & LX_STR)
            parse_pp_str_tok(tokc.str.s);
    }
}

/* push back current token, making 'last' the current one */
void unget_tok(int last)
{
    TokSeq *s = tseq_new();
    tseq_add_val(s, tok, &tokc);
    tseq_add(s, 0);
    push_reader(s, 1);
    tok = last;
}

/* ------------------------------------------------------------ re-lexing for ## */
static int relex_buf(const char *s, TokSeq *out)
{
    SrcFile *sf = file;
    int st = tok;
    TokVal sv = tokc;
    int sflags = lexflags, stf = tflags;
    const int *smp = mac_ptr;
    char *saved_tokstr = NULL;
    if (tokstr.len) saved_tokstr = xstrndup(tokstr.s, tokstr.len);
    int saved_len = tokstr.len;
    mac_ptr = NULL;
    int n = 0;
    SrcFile *f = xcalloc(sizeof *f);
    int len = strlen(s);
    f->buf = xmalloc(len + 4);
    memcpy(f->buf, s, len);
    memset(f->buf + len, 0, 4);
    f->p = f->buf;
    f->end = f->buf + len;
    f->line = sf ? sf->line : 1;
    f->up = NULL;
    snprintf(f->name, sizeof f->name, "%s", sf ? sf->name : "");
    f->true_name = NULL;
    file = f;
    lexflags = 0;
    tflags = 0;
    /* a lone '#' or other char must not trigger directives */
    while (file->p < file->end) {
        unsigned char *p0 = file->p;
        if (*p0 == ' ' || *p0 == '\t') { file->p++; continue; }
        next_raw();
        if (tok == T_EOF) break;
        n++;
        if (out) tseq_add_val(out, tok, &tokc);
    }
    file = sf;
    free(f->buf);
    free(f);
    if (saved_tokstr) {
        str_clear(&tokstr);
        str_putn(&tokstr, saved_tokstr, saved_len);
        free(saved_tokstr);
    }
    tok = st;
    tokc = sv;
    if (tok == T_PPNUM || tok == T_PPSTR || tok == T_STR) tokc.str.s = tokstr.s;
    lexflags = sflags;
    tflags = stf;
    mac_ptr = smp;
    return n;
}

/* ------------------------------------------------------------ command line defines */
void define_symbol(const char *sym, const char *val) { (void)sym; (void)val; }

/* ------------------------------------------------------------ init */
void pp_init(void)
{
    lex_init_idents();
}

void pp_begin(int filetype)
{
    cond_sp = cond_stack;
    pack_sp = pack_stack;
    *pack_sp = 0;
    pp_counter = 0;
    lexflags = LX_PP | LX_NUM | LX_STR;
    tflags = TF_BOL | TF_BOF;
    if (filetype == FT_ASM || filetype == FT_ASMPP) lexflags |= LX_ASM;
}

void pp_end(void)
{
    while (mac_ptr) pop_reader();
}

/* ------------------------------------------------------------ -E output */
static int pp_need_space(int a, int b)
{
    return 'E' == a ? '+' == b || '-' == b
        : '+' == a ? T_INC == b || '+' == b
        : '-' == a ? T_DEC == b || '-' == b
        : a >= T_IDENT || a == T_PPNUM ? b >= T_IDENT || b == T_PPNUM
        : 0;
}

static int pp_check_hexE(int t, const char *p)
{
    if (t == T_PPNUM) {
        int l = strlen(p);
        if (l && (p[l - 1] == 'e' || p[l - 1] == 'E')) return 'E';
    }
    return t;
}

int pp_line_out(SrcFile *f, int level)
{
    int d = f->line - f->line_ref;
    if (opt.dflag & 4) return 0;
    if (opt.Pflag == 1) {
        ;
    } else if (level == 0 && f->line_ref && d < 8) {
        while (d > 0) { fputc('\n', ppout); --d; }
    } else if (opt.Pflag == 2) {
        fprintf(ppout, "#line %d \"%s\"\n", f->line, f->name);
    } else {
        fprintf(ppout, "# %d \"%s\"%s\n", f->line, f->name,
                level > 0 ? " 1" : level < 0 ? " 2" : "");
    }
    f->line_ref = f->line;
    return 0;
}

/* pass "#pragma ..." through in -E mode */
static void pp_pass_pragma(void)
{
    TokSeq *s = tseq_new();
    tseq_add(s, T_NL);
    tseq_add(s, '#');
    tseq_add(s, KW_PRAGMA);
    tseq_add(s, ' ');
    tseq_add_val(s, tok, &tokc);
    tseq_add(s, 0);
    push_reader(s, 1);
}

