            } else if (sym_bind == STB_WEAK && esym_bind == STB_GLOBAL) {
            } else if (sym_bind == STB_WEAK && esym_bind == STB_WEAK) {
            } else if (sym_vis == STV_HIDDEN || sym_vis == STV_INTERNAL) {
            } else if ((esym->st_shndx == SHN_COMMON || esym->st_shndx == bss_section->sh_num)
                       && (shndx < SHN_LORESERVE && shndx != bss_section->sh_num)) {
                goto do_patch;
            } else if (shndx == SHN_COMMON || shndx == bss_section->sh_num) {
            } else if (s->sh_flags & SHF_DYNSYM) {
            } else if (esym->st_other & 0x80 /* ST_ASM_SET */) {
                goto do_patch;
            } else {
                error_noabort("'%s' defined twice", name);
            }
        } else {
        do_patch:
            esym->st_info = ELFW(ST_INFO)(sym_bind, sym_type);
            esym->st_shndx = shndx;
            esym->st_value = value;
            esym->st_size = size;
            esym->st_other = other;
        }
    } else {
    do_def:
        sym_index = put_elf_sym(s, value, size, ELFW(ST_INFO)(sym_bind, sym_type), other, shndx, name);
    }
    return sym_index;
}

void put_elf_reloca(Section *symtab, Section *s, unsigned long offset, int type, int symbol, uint64_t addend)
{
    char buf[256];
    Section *sr;
    ElfW(Rela) *rel;
    sr = s->reloc;
    if (!sr) {
        snprintf(buf, sizeof(buf), ".rela%s", s->name);
        sr = new_section(buf, SHT_RELA, symtab->sh_flags);
        sr->sh_entsize = sizeof(ElfW(Rela));
        sr->link = symtab;
        sr->sh_info = s->sh_num;
        s->reloc = sr;
    }
    rel = section_ptr_add(sr, sizeof(ElfW(Rela)));
    rel->r_offset = offset;
    rel->r_info = ELFW(R_INFO)(symbol, type);
    rel->r_addend = addend;
}

/* ------------------------------------------------------------ init */
void elf_new(void)
{
    sections = NULL;
    nb_sections = 0;
    nb_priv_sections = 0;
    memset(&symhash, 0, sizeof symhash);
    new_section("", SHT_NULL, 0); /* index 0 */
    text_section = new_section(".text", SHT_PROGBITS, SHF_ALLOC | SHF_EXECINSTR);
    data_section = new_section(".data", SHT_PROGBITS, SHF_ALLOC | SHF_WRITE);
    rodata_section = new_section(".data.ro", SHT_PROGBITS, SHF_ALLOC);
    bss_section = new_section(".bss", SHT_NOBITS, SHF_ALLOC | SHF_WRITE);
    common_section = new_section(".common", SHT_NOBITS, SHF_PRIVATE);
    common_section->sh_num = SHN_COMMON;
    symtab_section = new_section(".symtab", SHT_SYMTAB, 0);
    symtab_section->sh_entsize = sizeof(ElfW(Sym));
    strtab_section = new_section(".strtab", SHT_STRTAB, 0);
    put_elf_str(strtab_section, "");
    symtab_section->link = strtab_section;
    put_elf_sym(symtab_section, 0, 0, 0, 0, 0, NULL);
    cur_text_section = text_section;
}

/* ------------------------------------------------------------ eh_frame */
static void eh_uleb(Section *s, unsigned v)
{
    do {
        unsigned char b = v & 0x7f;
        v >>= 7;
        if (v) b |= 0x80;
        *(unsigned char *)section_ptr_add(s, 1) = b;
    } while (v);
}
static void eh_sleb(Section *s, int v)
{
    int more = 1;
    while (more) {
        unsigned char b = v & 0x7f;
        v >>= 7;
        if ((v == 0 && !(b & 0x40)) || (v == -1 && (b & 0x40))) more = 0;
        else b |= 0x80;
        *(unsigned char *)section_ptr_add(s, 1) = b;
    }
}
static void eh_byte(Section *s, int b) { *(unsigned char *)section_ptr_add(s, 1) = b; }
static void eh_u32(Section *s, unsigned v) { write32le(section_ptr_add(s, 4), v); }

static unsigned long eh_start;

void eh_frame_start(void)
{
    if (!opt.unwind_tables) return;
    eh_frame_section = new_section(".eh_frame", SHT_PROGBITS, SHF_ALLOC);
    Section *s = eh_frame_section;
    s->sh_addralign = 8;
    eh_start = s->data_offset;
    /* CIE */
    eh_u32(s, 0); /* length placeholder */
    eh_u32(s, 0); /* CIE id */
    eh_byte(s, 1); /* version */
    eh_byte(s, 'z'); eh_byte(s, 'R'); eh_byte(s, 0);
    eh_uleb(s, 1); /* code align */
    eh_sleb(s, -8); /* data align */
    eh_uleb(s, 16); /* return reg */
    eh_uleb(s, 1); /* augmentation len */
    eh_byte(s, 0x1b); /* pcrel sdata4 */
    eh_byte(s, 0x0c); eh_uleb(s, 7); eh_uleb(s, 8); /* def_cfa rsp 8 */
    eh_byte(s, 0x80 | 16); eh_uleb(s, 1); /* offset rip cfa-8 */
    while ((s->data_offset - eh_start) & 3) eh_byte(s, 0);
    /* pad to 8 */
    while ((s->data_offset - eh_start) % 8 != 0) eh_byte(s, 0);
    write32le(s->data + eh_start, s->data_offset - eh_start - 4);
}

void eh_frame_func(unsigned long func_start, unsigned long func_size)
{
    Section *s = eh_frame_section;
    if (!s) return;
    unsigned long fde = s->data_offset;
    eh_u32(s, 0); /* length */
    eh_u32(s, fde + 4 - eh_start); /* cie pointer */
    /* pc begin: relocated */
    int secsym = put_elf_sym(symtab_section, 0, 0, ELFW(ST_INFO)(STB_LOCAL, STT_SECTION), 0, cur_text_section->sh_num, NULL);
    put_elf_reloca(symtab_section, s, s->data_offset, R_X86_64_PC32, secsym, func_start);
    eh_u32(s, 0);
    eh_u32(s, func_size);
    eh_uleb(s, 0); /* augmentation length */
    eh_byte(s, 0x40 | 1); /* advance 1 */
    eh_byte(s, 0x0e); eh_uleb(s, 16); /* def_cfa_offset 16 */
    eh_byte(s, 0x80 | 6); eh_uleb(s, 2); /* offset rbp cfa-16 */
    eh_byte(s, 0x40 | 3); /* advance 3 */
    eh_byte(s, 0x0d); eh_uleb(s, 6); /* def_cfa_register rbp */
    eh_byte(s, 0x04); eh_u32(s, func_size - 5); /* advance_loc4 */
    eh_byte(s, 0x0c); eh_uleb(s, 7); eh_uleb(s, 8); /* def_cfa rsp 8 */
    while ((s->data_offset - fde) % 8 != 4) eh_byte(s, 0);
    write32le(s->data + fde, s->data_offset - fde - 4);
}

void eh_frame_end(void)
{
    Section *s = eh_frame_section;
    if (!s) return;
    eh_u32(s, 0); /* terminator */
}

/* ------------------------------------------------------------ object output */
static void sort_syms(Section *s)
{
    int nb = s->data_offset / sizeof(ElfW(Sym));
    ElfW(Sym) *new_syms = xmalloc(nb * sizeof(ElfW(Sym)));
    int *old_to_new = xmalloc(nb * sizeof(int));
    ElfW(Sym) *p = (ElfW(Sym) *)s->data;
    ElfW(Sym) *q = new_syms;
    for (int i = 0; i < nb; i++) {
        if (ELFW(ST_BIND)(p[i].st_info) == STB_LOCAL) {
            old_to_new[i] = q - new_syms;
            *q++ = p[i];
        }
    }
    if (s->sh_size) {}
    s->sh_info = q - new_syms;
    for (int i = 0; i < nb; i++) {
        if (ELFW(ST_BIND)(p[i].st_info) != STB_LOCAL) {
            old_to_new[i] = q - new_syms;
            *q++ = p[i];
        }
    }
    memcpy(s->data, new_syms, nb * sizeof(ElfW(Sym)));
    free(new_syms);
    for (int i = 1; i < nb_sections; i++) {
        Section *sr = sections[i];
        if (sr->sh_type == SHT_RELA && sr->link == s) {
            ElfW(Rela) *r = (ElfW(Rela) *)sr->data;
            ElfW(Rela) *e = (ElfW(Rela) *)(sr->data + sr->data_offset);
            for (; r < e; r++) {
                int si = ELFW(R_SYM)(r->r_info);
                int ty = ELFW(R_TYPE)(r->r_info);
                r->r_info = ELFW(R_INFO)(old_to_new[si], ty);
            }
        }
    }
    free(old_to_new);
}

extern int verbose_print_out;

int write_object_file(const char *filename)
{
    Section *shstr;
    FILE *f;
    int fd;
    sort_syms(symtab_section);
    shstr = new_section(".shstrtab", SHT_STRTAB, 0);
    put_elf_str(shstr, "");
    for (int i = 1; i < nb_sections; i++)
        sections[i]->sh_name = put_elf_str(shstr, sections[i]->name);
    /* layout */
    unsigned long off = sizeof(ElfW(Ehdr)) + nb_sections * sizeof(ElfW(Shdr));
    for (int i = 1; i < nb_sections; i++) {
        Section *s = sections[i];
        off = (off + 15) & ~15UL;
        s->sh_offset = off;
        s->sh_size = s->data_offset;
        if (s->sh_type != SHT_NOBITS)
            off += s->sh_size;
    }
    unlink(filename);
    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (fd < 0 || (f = fdopen(fd, "wb")) == NULL) {
        error_noabort("could not write '%s: %s'", filename, strerror(errno));
        return -1;
    }
    if (opt.verbose)
        printf("<- %s\n", filename);
    ElfW(Ehdr) eh;
    memset(&eh, 0, sizeof eh);
    eh.e_ident[0] = ELFMAG0; eh.e_ident[1] = ELFMAG1; eh.e_ident[2] = ELFMAG2; eh.e_ident[3] = ELFMAG3;
    eh.e_ident[4] = ELFCLASS64;
    eh.e_ident[5] = ELFDATA2LSB;
    eh.e_ident[6] = EV_CURRENT;
    eh.e_type = ET_REL;
    eh.e_machine = EM_X86_64;
    eh.e_version = EV_CURRENT;
    eh.e_shoff = sizeof(ElfW(Ehdr));
    eh.e_ehsize = sizeof(ElfW(Ehdr));
    eh.e_shentsize = sizeof(ElfW(Shdr));
    eh.e_shnum = nb_sections;
    eh.e_shstrndx = nb_sections - 1;
    fwrite(&eh, 1, sizeof eh, f);
    for (int i = 0; i < nb_sections; i++) {
        Section *s = sections[i];
        ElfW(Shdr) sh;
        memset(&sh, 0, sizeof sh);
        if (i) {
            sh.sh_name = s->sh_name;
            sh.sh_type = s->sh_type;
            sh.sh_flags = s->sh_flags;
            sh.sh_entsize = s->sh_entsize;
            sh.sh_info = s->sh_info;
            if (s->link) sh.sh_link = s->link->sh_num;
            sh.sh_addralign = s->sh_addralign;
            sh.sh_addr = s->sh_addr;
            sh.sh_offset = s->sh_offset;
            sh.sh_size = s->sh_size;
        }
        fwrite(&sh, 1, sizeof sh, f);
    }
    unsigned long pos = sizeof(ElfW(Ehdr)) + nb_sections * sizeof(ElfW(Shdr));
    for (int i = 1; i < nb_sections; i++) {
        Section *s = sections[i];
        if (s->sh_type == SHT_NOBITS) continue;
        while (pos < s->sh_offset) { fputc(0, f); pos++; }
        if (s->data_offset) fwrite(s->data, 1, s->data_offset, f);
        pos += s->data_offset;
    }
    fclose(f);
    return 0;
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/elf.c <<'EOF'
/* ELF sections, symbols, relocations and relocatable object output */
#include "cc.h"

Section *text_section, *data_section, *rodata_section, *bss_section,
    *common_section, *cur_text_section, *symtab_section, *strtab_section,
    *eh_frame_section;
Section **sections;
int nb_sections;
static Section **priv_sections;
static int nb_priv_sections;

/* symbol hash for symtab lookup */
typedef struct SymHash { int *buckets; int nb; int *chain; int nchain; } SymHash;
static SymHash symhash;

Section *new_section(const char *name, int sh_type, int sh_flags)
{
    Section *sec = xcalloc(sizeof(Section) + strlen(name));
    strcpy(sec->name, name);
    sec->sh_type = sh_type;
    sec->sh_flags = sh_flags;
    switch (sh_type) {
    case SHT_GNU_versym:
        sec->sh_addralign = 2;
        break;
    case SHT_HASH:
    case SHT_REL:
    case SHT_RELA:
    case SHT_DYNSYM:
    case SHT_SYMTAB:
    case SHT_DYNAMIC:
    case SHT_GNU_verneed:
    case SHT_GNU_verdef:
        sec->sh_addralign = 8;
        break;
    case SHT_STRTAB:
        sec->sh_addralign = 1;
        break;
    default:
        sec->sh_addralign = 8;
        break;
    }
    if (sh_flags & SHF_PRIVATE) {
        priv_sections = xrealloc(priv_sections, (nb_priv_sections + 1) * sizeof(Section *));
        priv_sections[nb_priv_sections++] = sec;
    } else {
        sec->sh_num = nb_sections;
        sections = xrealloc(sections, (nb_sections + 1) * sizeof(Section *));
        sections[nb_sections++] = sec;
    }
    return sec;
}

void section_realloc(Section *sec, unsigned long new_size)
{
    unsigned long size = sec->data_allocated;
    if (size >= new_size) return;
    if (size == 0) size = 1;
    while (size < new_size) size *= 2;
    sec->data = xrealloc(sec->data, size);
    memset(sec->data + sec->data_allocated, 0, size - sec->data_allocated);
    sec->data_allocated = size;
}

size_t section_add(Section *sec, uint64_t size, int align)
{
    size_t offset = (sec->data_offset + align - 1) & -align;
    size_t offset1 = offset + size;
    if (sec->sh_type != SHT_NOBITS && offset1 > sec->data_allocated)
        section_realloc(sec, offset1);
    sec->data_offset = offset1;
    if (align > sec->sh_addralign)
        sec->sh_addralign = align;
    return offset;
}

void *section_ptr_add(Section *sec, uint64_t size)
{
    size_t offset = section_add(sec, size, 1);
    return sec->data + offset;
}

Section *find_section(const char *name)
{
    for (int i = 1; i < nb_sections; i++)
        if (!strcmp(name, sections[i]->name))
            return sections[i];
    return new_section(name, SHT_PROGBITS, SHF_ALLOC);
}

Section *find_section_noadd(const char *name)
{
    for (int i = 1; i < nb_sections; i++)
        if (!strcmp(name, sections[i]->name))
            return sections[i];
    return NULL;
}

int put_elf_str(Section *s, const char *sym)
{
    size_t len = strlen(sym) + 1;
    size_t offset = s->data_offset;
    char *ptr = section_ptr_add(s, len);
    memmove(ptr, sym, len);
    return offset;
}

static unsigned elf_hash(const unsigned char *name)
{
    unsigned h = 0, g;
    while (*name) {
        h = (h << 4) + *name++;
        g = h & 0xf0000000;
        if (g) h ^= g >> 24;
        h &= ~g;
    }
    return h;
}

static void symhash_add(Section *s, int idx)
{
    if (s != symtab_section) return;
    ElfW(Sym) *sym = &((ElfW(Sym) *)s->data)[idx];
    if (!sym->st_name) return;
    if (idx >= symhash.nchain) {
        int n = symhash.nchain ? symhash.nchain * 2 : 256;
        while (n <= idx) n *= 2;
        symhash.chain = xrealloc(symhash.chain, n * sizeof(int));
        memset(symhash.chain + symhash.nchain, 0, (n - symhash.nchain) * sizeof(int));
        symhash.nchain = n;
    }
    if (!symhash.nb) {
        symhash.nb = 4096;
        symhash.buckets = xcalloc(symhash.nb * sizeof(int));
    }
    unsigned h = elf_hash((unsigned char *)s->link->data + sym->st_name) % symhash.nb;
    symhash.chain[idx] = symhash.buckets[h];
    symhash.buckets[h] = idx;
}

void symhash_rebuild(Section *s)
{
    if (s != symtab_section) return;
    if (symhash.nb) memset(symhash.buckets, 0, symhash.nb * sizeof(int));
    int n = s->data_offset / sizeof(ElfW(Sym));
    for (int i = 1; i < n; i++) {
        ElfW(Sym) *sym = &((ElfW(Sym) *)s->data)[i];
        if (ELFW(ST_BIND)(sym->st_info) != STB_LOCAL)
            symhash_add(s, i);
    }
}

int put_elf_sym(Section *s, uint64_t value, unsigned long size, int info, int other, int shndx, const char *name)
{
    int name_offset, sym_index;
    ElfW(Sym) *sym;
    sym = section_ptr_add(s, sizeof(ElfW(Sym)));
    if (name && name[0])
        name_offset = put_elf_str(s->link, name);
    else
        name_offset = 0;
    sym->st_name = name_offset;
    sym->st_value = value;
    sym->st_size = size;
    sym->st_info = info;
    sym->st_other = other;
    sym->st_shndx = shndx;
    sym_index = sym - (ElfW(Sym) *)s->data;
    if (ELFW(ST_BIND)(info) != STB_LOCAL)
        symhash_add(s, sym_index);
    return sym_index;
}

int find_elf_sym(Section *s, const char *name)
{
    if (s == symtab_section) {
        if (!symhash.nb) return 0;
        unsigned h = elf_hash((const unsigned char *)name) % symhash.nb;
        int i = symhash.buckets[h];
        while (i) {
            ElfW(Sym) *sym = &((ElfW(Sym) *)s->data)[i];
            if (!strcmp(name, (char *)s->link->data + sym->st_name)) return i;
            i = symhash.chain[i];
        }
        return 0;
    }
    int n = s->data_offset / sizeof(ElfW(Sym));
    for (int i = 1; i < n; i++) {
        ElfW(Sym) *sym = &((ElfW(Sym) *)s->data)[i];
        if (ELFW(ST_BIND)(sym->st_info) == STB_LOCAL) continue;
        if (!strcmp(name, (char *)s->link->data + sym->st_name)) return i;
    }
    return 0;
}

/* add or update a global symbol (used by linker) */
int set_elf_sym(Section *s, uint64_t value, unsigned long size, int info, int other, int shndx, const char *name)
{
    ElfW(Sym) *esym;
    int sym_bind, sym_index, sym_type, esym_bind;
    unsigned char sym_vis, esym_vis, new_vis;

    sym_bind = ELFW(ST_BIND)(info);
    sym_type = ELFW(ST_TYPE)(info);
    sym_vis = ELFW(ST_VISIBILITY)(other);

    if (sym_bind != STB_LOCAL) {
        sym_index = find_elf_sym(s, name);
        if (!sym_index)
            goto do_def;
        esym = &((ElfW(Sym) *)s->data)[sym_index];
        if (esym->st_value == value && esym->st_size == size && esym->st_info == info
            && esym->st_other == other && esym->st_shndx == shndx)
            return sym_index;
        if (esym->st_shndx != SHN_UNDEF) {
            esym_bind = ELFW(ST_BIND)(esym->st_info);
            esym_vis = ELFW(ST_VISIBILITY)(esym->st_other);
            if (esym_vis == STV_DEFAULT) new_vis = sym_vis;
            else if (sym_vis == STV_DEFAULT) new_vis = esym_vis;
            else new_vis = (esym_vis < sym_vis) ? esym_vis : sym_vis;
            esym->st_other = (esym->st_other & ~ELFW(ST_VISIBILITY)(-1)) | new_vis;
            if (shndx == SHN_UNDEF) {
                /* ignore adding of undefined symbol if the corresponding symbol is already defined */
            } else if (sym_bind == STB_GLOBAL && esym_bind == STB_WEAK) {
                goto do_patch;
            } else if (sym_bind == STB_WEAK && esym_bind == STB_GLOBAL) {
            } else if (sym_bind == STB_WEAK && esym_bind == STB_WEAK) {
            } else if (sym_vis == STV_HIDDEN || sym_vis == STV_INTERNAL) {
            } else if ((esym->st_shndx == SHN_COMMON || esym->st_shndx == bss_section->sh_num)
                       && (shndx < SHN_LORESERVE && shndx != bss_section->sh_num)) {
                goto do_patch;
            } else if (shndx == SHN_COMMON || shndx == bss_section->sh_num) {
            } else if (s->sh_flags & SHF_DYNSYM) {
            } else if (esym->st_other & 0x80 /* ST_ASM_SET */) {
                goto do_patch;
            } else {
                error_noabort("'%s' defined twice", name);
            }
        } else {
        do_patch:
            esym->st_info = ELFW(ST_INFO)(sym_bind, sym_type);
            esym->st_shndx = shndx;
            esym->st_value = value;
            esym->st_size = size;
            esym->st_other = other;
        }
    } else {
    do_def:
        sym_index = put_elf_sym(s, value, size, ELFW(ST_INFO)(sym_bind, sym_type), other, shndx, name);
    }
    return sym_index;
}

void put_elf_reloca(Section *symtab, Section *s, unsigned long offset, int type, int symbol, uint64_t addend)
{
    char buf[256];
    Section *sr;
    ElfW(Rela) *rel;
    sr = s->reloc;
    if (!sr) {
        snprintf(buf, sizeof(buf), ".rela%s", s->name);
        sr = new_section(buf, SHT_RELA, symtab->sh_flags);
        sr->sh_entsize = sizeof(ElfW(Rela));
        sr->link = symtab;
        sr->sh_info = s->sh_num;
        s->reloc = sr;
    }
    rel = section_ptr_add(sr, sizeof(ElfW(Rela)));
    rel->r_offset = offset;
    rel->r_info = ELFW(R_INFO)(symbol, type);
    rel->r_addend = addend;
}

/* ------------------------------------------------------------ init */
void elf_new(void)
{
    sections = NULL;
    nb_sections = 0;
    nb_priv_sections = 0;
    memset(&symhash, 0, sizeof symhash);
    new_section("", SHT_NULL, 0); /* index 0 */
    text_section = new_section(".text", SHT_PROGBITS, SHF_ALLOC | SHF_EXECINSTR);
    data_section = new_section(".data", SHT_PROGBITS, SHF_ALLOC | SHF_WRITE);
    rodata_section = new_section(".data.ro", SHT_PROGBITS, SHF_ALLOC);
    bss_section = new_section(".bss", SHT_NOBITS, SHF_ALLOC | SHF_WRITE);
    common_section = new_section(".common", SHT_NOBITS, SHF_PRIVATE);
    common_section->sh_num = SHN_COMMON;
    symtab_section = new_section(".symtab", SHT_SYMTAB, 0);
    symtab_section->sh_entsize = sizeof(ElfW(Sym));
    strtab_section = new_section(".strtab", SHT_STRTAB, 0);
    put_elf_str(strtab_section, "");
    symtab_section->link = strtab_section;
    put_elf_sym(symtab_section, 0, 0, 0, 0, 0, NULL);
    cur_text_section = text_section;
}

/* ------------------------------------------------------------ eh_frame */
static void eh_uleb(Section *s, unsigned v)
{
    do {
        unsigned char b = v & 0x7f;
        v >>= 7;
        if (v) b |= 0x80;
        *(unsigned char *)section_ptr_add(s, 1) = b;
    } while (v);
}
static void eh_sleb(Section *s, int v)
{
    int more = 1;
    while (more) {
        unsigned char b = v & 0x7f;
        v >>= 7;
        if ((v == 0 && !(b & 0x40)) || (v == -1 && (b & 0x40))) more = 0;
        else b |= 0x80;
        *(unsigned char *)section_ptr_add(s, 1) = b;
    }
}
static void eh_byte(Section *s, int b) { *(unsigned char *)section_ptr_add(s, 1) = b; }
static void eh_u32(Section *s, unsigned v) { write32le(section_ptr_add(s, 4), v); }

static unsigned long eh_start;

void eh_frame_start(void)
{
    if (!opt.unwind_tables) return;
    eh_frame_section = new_section(".eh_frame", SHT_PROGBITS, SHF_ALLOC);
    Section *s = eh_frame_section;
    s->sh_addralign = 8;
    eh_start = s->data_offset;
    /* CIE */
    eh_u32(s, 0); /* length placeholder */
    eh_u32(s, 0); /* CIE id */
    eh_byte(s, 1); /* version */
    eh_byte(s, 'z'); eh_byte(s, 'R'); eh_byte(s, 0);
    eh_uleb(s, 1); /* code align */
    eh_sleb(s, -8); /* data align */
    eh_uleb(s, 16); /* return reg */
    eh_uleb(s, 1); /* augmentation len */
    eh_byte(s, 0x1b); /* pcrel sdata4 */
    eh_byte(s, 0x0c); eh_uleb(s, 7); eh_uleb(s, 8); /* def_cfa rsp 8 */
    eh_byte(s, 0x80 | 16); eh_uleb(s, 1); /* offset rip cfa-8 */
    while ((s->data_offset - eh_start) & 3) eh_byte(s, 0);
    /* pad to 8 */
    while ((s->data_offset - eh_start) % 8 != 0) eh_byte(s, 0);
    write32le(s->data + eh_start, s->data_offset - eh_start - 4);
}

void eh_frame_func(unsigned long func_start, unsigned long func_size)
{
    Section *s = eh_frame_section;
    if (!s) return;
    unsigned long fde = s->data_offset;
    eh_u32(s, 0); /* length */
    eh_u32(s, fde + 4 - eh_start); /* cie pointer */
    /* pc begin: relocated */
    int secsym = put_elf_sym(symtab_section, 0, 0, ELFW(ST_INFO)(STB_LOCAL, STT_SECTION), 0, cur_text_section->sh_num, NULL);
    put_elf_reloca(symtab_section, s, s->data_offset, R_X86_64_PC32, secsym, func_start);
    eh_u32(s, 0);
    eh_u32(s, func_size);
    eh_uleb(s, 0); /* augmentation length */
    eh_byte(s, 0x40 | 1); /* advance 1 */
    eh_byte(s, 0x0e); eh_uleb(s, 16); /* def_cfa_offset 16 */
    eh_byte(s, 0x80 | 6); eh_uleb(s, 2); /* offset rbp cfa-16 */
    eh_byte(s, 0x40 | 3); /* advance 3 */
    eh_byte(s, 0x0d); eh_uleb(s, 6); /* def_cfa_register rbp */
    eh_byte(s, 0x04); eh_u32(s, func_size - 5); /* advance_loc4 */
    eh_byte(s, 0x0c); eh_uleb(s, 7); eh_uleb(s, 8); /* def_cfa rsp 8 */
    while ((s->data_offset - fde) % 8 != 4) eh_byte(s, 0);
    write32le(s->data + fde, s->data_offset - fde - 4);
}

void eh_frame_end(void)
{
    Section *s = eh_frame_section;
    if (!s) return;
    eh_u32(s, 0); /* terminator */
}

/* ------------------------------------------------------------ object output */
static void sort_syms(Section *s)
{
    int nb = s->data_offset / sizeof(ElfW(Sym));
    ElfW(Sym) *new_syms = xmalloc(nb * sizeof(ElfW(Sym)));
    int *old_to_new = xmalloc(nb * sizeof(int));
    ElfW(Sym) *p = (ElfW(Sym) *)s->data;
    ElfW(Sym) *q = new_syms;
    for (int i = 0; i < nb; i++) {
        if (ELFW(ST_BIND)(p[i].st_info) == STB_LOCAL) {
            old_to_new[i] = q - new_syms;
            *q++ = p[i];
        }
    }
    if (s->sh_size) {}
    s->sh_info = q - new_syms;
    for (int i = 0; i < nb; i++) {
        if (ELFW(ST_BIND)(p[i].st_info) != STB_LOCAL) {
            old_to_new[i] = q - new_syms;
            *q++ = p[i];
        }
    }
    memcpy(s->data, new_syms, nb * sizeof(ElfW(Sym)));
    free(new_syms);
    for (int i = 1; i < nb_sections; i++) {
        Section *sr = sections[i];
        if (sr->sh_type == SHT_RELA && sr->link == s) {
            ElfW(Rela) *r = (ElfW(Rela) *)sr->data;
            ElfW(Rela) *e = (ElfW(Rela) *)(sr->data + sr->data_offset);
            for (; r < e; r++) {
                int si = ELFW(R_SYM)(r->r_info);
                int ty = ELFW(R_TYPE)(r->r_info);
                r->r_info = ELFW(R_INFO)(old_to_new[si], ty);
            }
        }
    }
    free(old_to_new);
}

extern int verbose_print_out;

int write_object_file(const char *filename)
{
    Section *shstr;
    FILE *f;
    int fd;
    sort_syms(symtab_section);
    shstr = new_section(".shstrtab", SHT_STRTAB, 0);
    put_elf_str(shstr, "");
    for (int i = 1; i < nb_sections; i++)
        sections[i]->sh_name = put_elf_str(shstr, sections[i]->name);
    /* layout */
    unsigned long off = sizeof(ElfW(Ehdr)) + nb_sections * sizeof(ElfW(Shdr));
    for (int i = 1; i < nb_sections; i++) {
        Section *s = sections[i];
        off = (off + 15) & ~15UL;
        s->sh_offset = off;
        s->sh_size = s->data_offset;
        if (s->sh_type != SHT_NOBITS)
            off += s->sh_size;
    }
    unlink(filename);
    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (fd < 0 || (f = fdopen(fd, "wb")) == NULL) {
        error_noabort("could not write '%s: %s'", filename, strerror(errno));
        return -1;
    }
    if (opt.verbose)
        printf("<- %s\n", filename);
    ElfW(Ehdr) eh;
    memset(&eh, 0, sizeof eh);
    eh.e_ident[0] = ELFMAG0; eh.e_ident[1] = ELFMAG1; eh.e_ident[2] = ELFMAG2; eh.e_ident[3] = ELFMAG3;
    eh.e_ident[4] = ELFCLASS64;
    eh.e_ident[5] = ELFDATA2LSB;
    eh.e_ident[6] = EV_CURRENT;
    eh.e_type = ET_REL;
    eh.e_machine = EM_X86_64;
    eh.e_version = EV_CURRENT;
    eh.e_shoff = sizeof(ElfW(Ehdr));
    eh.e_ehsize = sizeof(ElfW(Ehdr));
    eh.e_shentsize = sizeof(ElfW(Shdr));
    eh.e_shnum = nb_sections;
    eh.e_shstrndx = nb_sections - 1;
    fwrite(&eh, 1, sizeof eh, f);
    for (int i = 0; i < nb_sections; i++) {
        Section *s = sections[i];
        ElfW(Shdr) sh;
        memset(&sh, 0, sizeof sh);
        if (i) {
            sh.sh_name = s->sh_name;
            sh.sh_type = s->sh_type;
            sh.sh_flags = s->sh_flags;
            sh.sh_entsize = s->sh_entsize;
            sh.sh_info = s->sh_info;
            if (s->link) sh.sh_link = s->link->sh_num;
            sh.sh_addralign = s->sh_addralign;
            sh.sh_addr = s->sh_addr;
            sh.sh_offset = s->sh_offset;
            sh.sh_size = s->sh_size;
        }
        fwrite(&sh, 1, sizeof sh, f);
    }
    unsigned long pos = sizeof(ElfW(Ehdr)) + nb_sections * sizeof(ElfW(Shdr));
    for (int i = 1; i < nb_sections; i++) {
        Section *s = sections[i];
        if (s->sh_type == SHT_NOBITS) continue;
        while (pos < s->sh_offset) { fputc(0, f); pos++; }
        if (s->data_offset) fwrite(s->data, 1, s->data_offset, f);
        pos += s->data_offset;
    }
    fclose(f);
    return 0;
}
