/* ------------------------------------------------------------ symbols */
static Sym *sym_free_first;

static Sym *sym_alloc(void)
{
    Sym *s = sym_free_first;
    if (s) {
        sym_free_first = s->next;
        memset(s, 0, sizeof *s);
        return s;
    }
    return xcalloc(sizeof(Sym));
}

void sym_free(Sym *s)
{
    s->next = sym_free_first;
    sym_free_first = s;
}

Sym *sym_push2(Sym **ps, int v, int t, long long c)
{
    Sym *s = sym_alloc();
    s->v = v;
    s->type.t = t;
    s->c = c;
    s->prev = *ps;
    *ps = s;
    return s;
}

Sym *sym_find2(Sym *s, int v)
{
    while (s) {
        if (s->v == v) return s;
        if (s->v == -1) return NULL;
        s = s->prev;
    }
    return NULL;
}

Sym *struct_find(int v)
{
    Ident *id = ident_of(v);
    return id ? id->sym_tag : NULL;
}

Sym *sym_find(int v)
{
    Ident *id = ident_of(v);
    return id ? id->sym_id : NULL;
}

Sym *sym_push(int v, Type *type, int r, long long c)
{
    Sym *s, **ps;
    ps = local_stack ? &local_stack : &global_stack;
    s = sym_push2(ps, v, type->t, c);
    s->type.ref = type->ref;
    s->r = r;
    if (!(v & SYM_FIELD) && (v & ~SYM_STRUCT) < SYM_FIRST_ANOM) {
        Ident *id = ident_of(v & ~SYM_STRUCT);
        ps = (v & SYM_STRUCT) ? &id->sym_tag : &id->sym_id;
        s->shadow = *ps;
        *ps = s;
        s->scope = local_scope;
        if (s->shadow && s->shadow->scope == s->scope)
            error("redeclaration of '%s'", tokname(v & ~SYM_STRUCT, NULL));
    }
    return s;
}

Sym *global_identifier_push(int v, int t, long long c)
{
    Sym *s, **ps;
    s = sym_push2(&global_stack, v, t, c);
    s->r = VL_CONST | VF_SYM;
    if (v < SYM_FIRST_ANOM) {
        ps = &ident_of(v)->sym_id;
        while (*ps != NULL && (*ps)->scope)
            ps = &(*ps)->shadow;
        s->shadow = *ps;
        *ps = s;
    }
    return s;
}

void sym_pop(Sym **ptop, Sym *b, int keep)
{
    Sym *s, *ss, **ps;
    int v;
    s = *ptop;
    while (s != b) {
        ss = s->prev;
        v = s->v;
        if (!(v & SYM_FIELD) && (v & ~SYM_STRUCT) < SYM_FIRST_ANOM) {
            Ident *id = ident_of(v & ~SYM_STRUCT);
            ps = (v & SYM_STRUCT) ? &id->sym_tag : &id->sym_id;
            *ps = s->shadow;
        }
        if (!keep)
            sym_free(s);
        s = ss;
    }
    if (!keep)
        *ptop = b;
}

Sym *label_find(int v)
{
