    return id ? id->sym_label : NULL;
}

Sym *label_push(Sym **ptop, int v, int flags)
{
    Sym *s, **ps;
    s = sym_push2(ptop, v, VL_CONST, 0);
    s->r = flags;
    ps = &ident_of(v)->sym_label;
    if (ptop == &global_label_stack) {
        while (*ps != NULL)
            ps = &(*ps)->shadow;
