}

/* ------------------------------------------------------------ types */
int is_float(int t)
{
    int bt = t & TY_MASK;
    return bt == TY_F80 || bt == TY_F64 || bt == TY_F32 || bt == TY_F128;
}

int is_integer_btype(int bt)
{
    return bt == TY_I8 || bt == TY_BOOL || bt == TY_I16 || bt == TY_I32 || bt == TY_I64;
}

int btype_size(int bt)
{
    return bt == TY_I8 || bt == TY_BOOL ? 1 :
           bt == TY_I16 ? 2 :
           bt == TY_I32 ? 4 :
           bt == TY_I64 ? 8 :
           bt == TY_PTR ? PTR_SIZE : 0;
}

int type_size(Type *type, int *a)
{
    Sym *s;
    int bt = type->t & TY_MASK;
    if (bt == TY_STRUCT) {
        s = type->ref;
        *a = s->r;
        return s->c;
    } else if (bt == TY_PTR) {
        if (type->t & TQ_ARRAY) {
            int ts;
            s = type->ref;
            ts = type_size(&s->type, a);
            if (ts < 0 && s->c < 0)
                ts = -ts;
            return ts * s->c;
        } else {
            *a = PTR_SIZE;
            return PTR_SIZE;
        }
    } else if (IS_ENUM(type->t) && type->ref->c < 0) {
        *a = 0;
        return -1;
    } else if (bt == TY_F80) {
        *a = 16;
        return 16;
    } else if (bt == TY_F64 || bt == TY_I64) {
        *a = 8;
        return 8;
    } else if (bt == TY_I32 || bt == TY_F32) {
        *a = 4;
        return 4;
    } else if (bt == TY_I16) {
        *a = 2;
        return 2;
    } else if (bt == TY_I128 || bt == TY_F128) {
        *a = 8;
        return 16;
    } else {
        *a = 1;
        return 1;
    }
}

Type *pointed_type(Type *type)
{
    return &type->ref->type;
}

int pointed_size(Type *type)
{
    int align;
    return type_size(pointed_type(type), &align);
}

void mk_pointer(Type *type)
{
    Sym *s;
    s = sym_push(SYM_FIELD, type, 0, -1);
    type->t = TY_PTR | (type->t & SC_MASK);
    type->ref = s;
}

int exact_log2p1(int i)
{
    int ret;
    if (!i) return 0;
    for (ret = 1; i >= 1 << 8; ret += 8) i >>= 8;
    if (i >= 1 << 4) ret += 4, i >>= 4;
    if (i >= 1 << 2) ret += 2, i >>= 2;
    if (i >= 1 << 1) ret++;
    return ret;
}

static int compare_types(Type *type1, Type *type2, int unqualified);

int is_compatible_func(Type *type1, Type *type2)
{
    Sym *s1, *s2;
    s1 = type1->ref;
    s2 = type2->ref;
    if (s1->func_call != s2->func_call)
        return 0;
    if (!is_compatible_types(&s1->type, &s2->type))
        return 0;
    if (s1->functype == FUNC_OLD || s2->functype == FUNC_OLD)
        return 1;
    if (s1->functype != s2->functype)
        return 0;
    while (s1 != NULL) {
        if (s2 == NULL)
            return 0;
        if (!is_compatible_unqualified_types(&s1->type, &s2->type))
            return 0;
        s1 = s1->next;
        s2 = s2->next;
    }
    if (s2)
        return 0;
    return 1;
}

static int compare_types(Type *type1, Type *type2, int unqualified)
{
    int bt1, t1, t2;
    t1 = type1->t & TY_TYPEBITS;
    t2 = type2->t & TY_TYPEBITS;
    if (unqualified) {
        t1 &= ~(TQ_CONST | TQ_VOLATILE);
        t2 &= ~(TQ_CONST | TQ_VOLATILE);
    }
    /* default vs explicit signedness only matters for char */
    if ((t1 & TY_MASK) != TY_I8) {
        t1 &= ~TQ_DEFSIGN;
        t2 &= ~TQ_DEFSIGN;
    }
    if (t1 != t2)
        return 0;
    if ((t1 & TQ_ARRAY) && !(type1->ref->c < 0 || type2->ref->c < 0 || type1->ref->c == type2->ref->c))
        return 0;
    bt1 = t1 & TY_MASK;
    if (bt1 == TY_PTR) {
        type1 = pointed_type(type1);
        type2 = pointed_type(type2);
        return is_compatible_types(type1, type2);
    } else if (bt1 == TY_STRUCT) {
        return type1->ref == type2->ref;
    } else if (bt1 == TY_FUNC) {
        return is_compatible_func(type1, type2);
    } else if (IS_ENUM(type1->t) && IS_ENUM(type2->t)) {
        return type1->ref == type2->ref;
    } else {
        return 1;
    }
}

int is_compatible_types(Type *type1, Type *type2)
{
    return compare_types(type1, type2, 0);
}

int is_compatible_unqualified_types(Type *type1, Type *type2)
{
    return compare_types(type1, type2, 1);
}

static void pstrcat_(char *buf, int size, const char *s)
{
    int len = strlen(buf);
    if (len < size) pstrcpy(buf + len, size - len, s);
}

void type_to_str(char *buf, int buf_size, Type *type, const char *varstr)
{
    int bt, v, t;
    Sym *s, *sa;
    char buf1[256];
    const char *tstr;

    t = type->t;
    bt = t & TY_MASK;
    buf[0] = '\0';

    if (t & SC_EXTERN)
        pstrcat_(buf, buf_size, "extern ");
    if (t & SC_STATIC)
        pstrcat_(buf, buf_size, "static ");
    if (t & SC_TYPEDEF)
        pstrcat_(buf, buf_size, "typedef ");
    if (t & SC_INLINE)
        pstrcat_(buf, buf_size, "inline ");
    if (bt != TY_PTR) {
        if (t & TQ_VOLATILE)
            pstrcat_(buf, buf_size, "volatile ");
        if (t & TQ_CONST)
            pstrcat_(buf, buf_size, "const ");
    }
    if (((t & TQ_DEFSIGN) && bt == TY_I8)
        || ((t & TQ_UNSIGNED)
            && (bt == TY_I16 || bt == TY_I32 || bt == TY_I64)
            && !IS_ENUM(t)))
        pstrcat_(buf, buf_size, (t & TQ_UNSIGNED) ? "unsigned " : "signed ");

    buf_size -= strlen(buf);
    buf += strlen(buf);

    switch (bt) {
    case TY_VOID:
        tstr = "void";
        goto add_tstr;
    case TY_BOOL:
        tstr = "_Bool";
        goto add_tstr;
    case TY_I8:
        tstr = "char";
        goto add_tstr;
    case TY_I16:
        tstr = "short";
        goto add_tstr;
    case TY_I32:
        tstr = "int";
        goto maybe_long;
    case TY_I64:
        tstr = "long long";
    maybe_long:
        if (t & TQ_LONG)
            tstr = "long";
        if (!IS_ENUM(t))
            goto add_tstr;
        tstr = "enum ";
        goto tstruct;
    case TY_F32:
        tstr = "float";
        goto add_tstr;
    case TY_F64:
        tstr = "double";
        if (!(t & TQ_LONG))
            goto add_tstr;
        /* fallthrough */
    case TY_F80:
        tstr = "long double";
    add_tstr:
        pstrcat_(buf, buf_size, tstr);
        break;
    case TY_STRUCT:
        tstr = "struct ";
        if (IS_UNION(t))
            tstr = "union ";
    tstruct:
        pstrcat_(buf, buf_size, tstr);
        v = type->ref->v & ~SYM_STRUCT;
        if (v >= SYM_FIRST_ANOM)
            pstrcat_(buf, buf_size, "<anonymous>");
        else
            pstrcat_(buf, buf_size, tokname(v, NULL));
        break;
    case TY_FUNC:
        s = type->ref;
        buf1[0] = 0;
        if (varstr && '*' == *varstr) {
            pstrcat_(buf1, sizeof(buf1), "(");
            pstrcat_(buf1, sizeof(buf1), varstr);
            pstrcat_(buf1, sizeof(buf1), ")");
        }
        pstrcat_(buf1, sizeof(buf1), "(");
        sa = s->next;
        while (sa != NULL) {
            char buf2[256];
            type_to_str(buf2, sizeof(buf2), &sa->type, NULL);
            pstrcat_(buf1, sizeof(buf1), buf2);
            sa = sa->next;
            if (sa)
                pstrcat_(buf1, sizeof(buf1), ", ");
        }
        if (s->functype == FUNC_ELLIPSIS)
            pstrcat_(buf1, sizeof(buf1), ", ...");
        pstrcat_(buf1, sizeof(buf1), ")");
        type_to_str(buf, buf_size, &s->type, buf1);
        goto no_var;
    case TY_PTR:
        s = type->ref;
        if (t & TQ_ARRAY) {
            if (varstr && '*' == *varstr)
                snprintf(buf1, sizeof(buf1), "(%s)[%lld]", varstr, s->c);
            else
                snprintf(buf1, sizeof(buf1), "%s[%lld]", varstr ? varstr : "", s->c);
            type_to_str(buf, buf_size, &s->type, buf1);
            goto no_var;
        }
        pstrcpy(buf1, sizeof(buf1), "*");
        if (t & TQ_CONST)
            pstrcat_(buf1, buf_size, "const ");
        if (t & TQ_VOLATILE)
            pstrcat_(buf1, buf_size, "volatile ");
        if (varstr)
            pstrcat_(buf1, sizeof(buf1), varstr);
        type_to_str(buf, buf_size, &s->type, buf1);
        goto no_var;
    }
    if (varstr) {
        pstrcat_(buf, buf_size, " ");
        pstrcat_(buf, buf_size, varstr);
    }
no_var:;
}

void type_incomplete_check(Type *type, const char *msg)
{
    (void)type; (void)msg;
}

/* ------------------------------------------------------------ ELF symbol helpers */
ElfW(Sym) *elfsym(Sym *s)
{
    if (!s || !s->elfsym)
        return NULL;
    return &((ElfW(Sym) *)symtab_section->data)[s->elfsym];
}

void update_storage(Sym *sym)
{
    ElfW(Sym) *esym;
    int sym_bind, old_sym_bind;
    esym = elfsym(sym);
    if (!esym)
        return;
    if (sym->visibility)
        esym->st_other = (esym->st_other & ~ELFW(ST_VISIBILITY)(-1)) | sym->visibility;
    if (sym->type.t & (SC_STATIC | SC_INLINE))
        sym_bind = STB_LOCAL;
    else if (sym->weak)
        sym_bind = STB_WEAK;
    else
        sym_bind = STB_GLOBAL;
    old_sym_bind = ELFW(ST_BIND)(esym->st_info);
    if (sym_bind != old_sym_bind) {
        esym->st_info = ELFW(ST_INFO)(sym_bind, ELFW(ST_TYPE)(esym->st_info));
    }
}

extern void symhash_rebuild(Section *s);

void put_extern_sym2(Sym *sym, int sh_num, uint64_t value, unsigned long size, int can_add_underscore)
{
    int sym_type, sym_bind, info, other, t;
    ElfW(Sym) *esym;
    const char *name;
    char buf1[256];

    if (!sym->elfsym) {
        name = tokname(sym->v, NULL);
        t = sym->type.t;
        if ((t & TY_MASK) == TY_FUNC) {
            sym_type = STT_FUNC;
        } else if ((t & TY_MASK) == TY_VOID) {
            sym_type = STT_NOTYPE;
            if ((t & (TY_MASK | SC_STATIC)) == SC_STATIC)  /* asm label */
                sym_type = STT_NOTYPE;
        } else {
            sym_type = STT_OBJECT;
        }
        if (t & (SC_STATIC | SC_INLINE))
            sym_bind = STB_LOCAL;
        else
            sym_bind = STB_GLOBAL;
        other = 0;
        if (sym->asm_label) {
            name = tokname(sym->asm_label, NULL);
            can_add_underscore = 0;
        }
        if (opt.leading_underscore && can_add_underscore) {
            buf1[0] = '_';
            pstrcpy(buf1 + 1, sizeof(buf1) - 1, name);
            name = buf1;
        }
        info = ELFW(ST_INFO)(sym_bind, sym_type);
        sym->elfsym = put_elf_sym(symtab_section, value, size, info, other, sh_num, name);
    } else {
        esym = elfsym(sym);
        esym->st_value = value;
        esym->st_size = size;
        esym->st_shndx = sh_num;
    }
    update_storage(sym);
}

void put_extern_sym(Sym *sym, Section *section, uint64_t value, unsigned long size)
{
    int sh_num = section ? section->sh_num : SHN_UNDEF;
    put_extern_sym2(sym, sh_num, value, size, 1);
}

void greloca(Section *s, Sym *sym, unsigned long offset, int type, uint64_t addend)
{
    int c = 0;
    if (nocode_wanted && s == cur_text_section)
        return;
    if (sym) {
        if (0 == sym->elfsym)
            put_extern_sym(sym, NULL, 0, 0);
        c = sym->elfsym;
    }
    put_elf_reloca(symtab_section, s, offset, type, c, addend);
}

void greloc(Section *s, Sym *sym, unsigned long offset, int type)
{
    greloca(s, sym, offset, type, 0);
}

Sym *get_sym_ref(Type *type, Section *sec, unsigned long offset, unsigned long size)
{
    int v;
    Sym *sym;
    v = anon_sym++;
    sym = sym_push(v, type, VL_CONST | VF_SYM, 0);
    sym->type.t |= SC_STATIC;
    put_extern_sym(sym, sec, offset, size);
    return sym;
}

Sym *external_global_sym(int v, Type *type)
{
    Sym *s;
    s = sym_find(v);
    if (!s) {
        s = global_identifier_push(v, type->t | SC_EXTERN, 0);
        s->type.ref = type->ref;
    } else if (IS_ASM_SYM_(s)) {
        s->type.t = type->t | (s->type.t & SC_EXTERN);
        s->type.ref = type->ref;
        update_storage(s);
    }
    return s;
}

Sym *external_helper_sym(int v)
{
    Type ct = { TY_FUNC, NULL };
    ct.ref = func_old_type.ref;
    return external_global_sym(v, &ct);
}

void vpush_helper_func(int v)
{
    vpushsym(&func_old_type, external_helper_sym(v));
}

/* ------------------------------------------------------------ vstack */
static void vsetc(Type *type, int r, CVal *vc)
{
    if (vtop >= vstack + (VSTACK_SIZE - 1))
        error("memory full (vstack)");
    if (vtop >= vstack && !nocode_wanted)
        vcheck_cmp();
    vtop++;
    vtop->type = *type;
    vtop->r = r;
    vtop->r2 = VL_CONST;
    vtop->c = *vc;
    vtop->sym = NULL;
}

void vcheck_cmp(void)
{
    if (vtop->r == VL_CMP && !nocode_wanted)
        gv(RC_INT);
}

void vswap(void)
{
    Val tmp;
    vcheck_cmp();
    tmp = vtop[0];
    vtop[0] = vtop[-1];
    vtop[-1] = tmp;
}

void vpop(void)
{
    int v;
    v = vtop->r & VL_MASK;
    if (v == R_ST0) {
        o(0xd8dd); /* fstp %st(0) */
    } else if (v == VL_CMP) {
        gsym(vtop->jtrue);
        gsym(vtop->jfalse);
    }
    vtop--;
}

void vpush(Type *type)
{
    vset(type, VL_CONST, 0);
}

void vpushi(int v)
{
    CVal cval;
    cval.i = v;
    vsetc(&int_type, VL_CONST, &cval);
}

void vpush64(int ty, unsigned long long v)
{
    CVal cval;
    Type ctype;
    ctype.t = ty;
    ctype.ref = NULL;
    cval.i = v;
    vsetc(&ctype, VL_CONST, &cval);
}

void vpushs(long long v)
{
    vpush64(TY_I64 | TQ_LONG | TQ_UNSIGNED, v);
}

void vpushll(long long v)
{
    vpush64(TY_I64, v);
}

void vset(Type *type, int r, long long v)
{
    CVal cval;
    cval.i = v;
    vsetc(type, r, &cval);
}

void vseti(int r, int v)
{
    Type type;
    type.t = TY_I32;
    type.ref = NULL;
    vset(&type, r, v);
}

void vpushv(Val *v)
{
    if (vtop >= vstack + (VSTACK_SIZE - 1))
        error("memory full (vstack)");
    vtop++;
    *vtop = *v;
}

void vdup(void)
{
    vpushv(vtop);
}

void vrotb(int n)
{
    int i;
    Val tmp;
    vcheck_cmp();
    tmp = vtop[-n + 1];
    for (i = -n + 1; i != 0; i++)
        vtop[i] = vtop[i + 1];
    vtop[0] = tmp;
}

void vrott(int n)
{
    int i;
    Val tmp;
    vcheck_cmp();
    tmp = vtop[0];
    for (i = 0; i < n - 1; i++)
        vtop[-i] = vtop[-i - 1];
    vtop[-n + 1] = tmp;
}

void vrev(int n)
{
    int i;
    Val tmp;
    vcheck_cmp();
    for (i = 0, n = -n; i > ++n; --i)
        tmp = vtop[i], vtop[i] = vtop[n], vtop[n] = tmp;
}

void vpushsym(Type *type, Sym *sym)
{
    CVal cval;
    cval.i = 0;
    vsetc(type, VL_CONST | VF_SYM, &cval);
    vtop->sym = sym;
}

void vpush_ref(Type *type, Section *sec, unsigned long offset, unsigned long size)
{
    vpushsym(type, get_sym_ref(type, sec, offset, size));
}

void vset_VT_CMP(int op)
{
    vtop->r = VL_CMP;
    vtop->cmp_op = op;
    vtop->jfalse = 0;
    vtop->jtrue = 0;
}

static void vset_VT_JMP(void)
{
    int op = vtop->cmp_op;
    if (vtop->jtrue || vtop->jfalse) {
        int origt = vtop->type.t;
        int inv = op & (op < 2);
        vseti(VL_JMP + inv, gvtst(inv, 0));
        vtop->type.t |= origt & (TQ_UNSIGNED | TQ_DEFSIGN);
    } else {
        vtop->c.i = op;
        if (op < 2)
            vtop->r = VL_CONST;
    }
}

void vtop_reset(void)
{
    vtop = vstack - 1;
}

/* ------------------------------------------------------------ jumps */
void gsym(int t)
{
    if (t) {
        gsym_addr(t, ind);
        CODE_ON();
    }
}

int gjmp_acs(int t)
{
    if (nocode_wanted)
        return t;
    return gjmp(t);
}

void gjmp_addr_acs(int t)
{
    if (!nocode_wanted)
        gjmp_addr(t);
}

int gind(void)
{
    int t = ind;
    CODE_ON();
    if (debug_modes) {}
    return t;
}

/* ------------------------------------------------------------ registers */
typedef struct TempVar { int location; short size; short align; } TempVar;
static TempVar temp_vars[8];
int nb_temp_local_vars;

int get_temp_local_var(int size, int align)
{
    int i;
    TempVar *tv;
    int found_var;
    Val *p;
    int r;
    char free_ = 0;
    char found = 0;
    for (i = 0; i < nb_temp_local_vars; i++) {
        tv = &temp_vars[i];
        if (tv->size < size || align != tv->align)
            continue;
        free_ = 1;
        for (p = vstack; p <= vtop; p++) {
            r = p->r & VL_MASK;
            if (r == VL_LOCAL || r == VL_LLOCAL) {
                if (p->c.i == tv->location) {
                    free_ = 0;
                    break;
                }
            }
        }
        if (free_) {
            found_var = tv->location;
            found = 1;
            break;
        }
    }
    if (!found) {
        loc = (loc - size) & -align;
        if (nb_temp_local_vars < 8) {
            tv = &temp_vars[i];
            tv->location = loc;
            tv->size = size;
            tv->align = align;
            nb_temp_local_vars++;
        }
        found_var = loc;
    }
    return found_var;
}

void clear_temp_local_var_list(void)
{
    nb_temp_local_vars = 0;
}

void save_reg_upstack(int r, int n)
{
    int l, size, align, bt;
    Val *p, *p1, sv;

    if ((r &= VL_MASK) >= VL_CONST)
        return;
    if (nocode_wanted)
        return;
    l = 0;
    for (p = vstack, p1 = vtop - n; p <= p1; p++) {
        if ((p->r & VL_MASK) == r || p->r2 == r) {
            if (!l) {
                bt = p->type.t & TY_MASK;
                if (bt == TY_VOID)
                    continue;
                if ((p->r & VF_LVAL) || bt == TY_FUNC)
                    bt = TY_PTR;
                sv.type.t = bt;
                size = type_size(&sv.type, &align);
                l = get_temp_local_var(size, align);
                sv.r = VL_LOCAL | VF_LVAL;
                sv.c.i = l;
                store(p->r & VL_MASK, &sv);
                if (r == R_ST0) {
                    o(0xd8dd); /* fstp %st(0) */
                }
            }
            if (p->r & VF_LVAL) {
                p->r = (p->r & ~VL_MASK) | VL_LLOCAL;
            } else {
                p->r = VF_LVAL | VL_LOCAL;
                p->type.t &= ~TQ_ARRAY;
            }
            p->sym = NULL;
            p->r2 = VL_CONST;
            p->c.i = l;
        }
    }
}

void save_reg(int r)
{
    save_reg_upstack(r, 0);
}

int get_reg(int rc)
{
    int r;
    Val *p;
    for (r = 0; r < NB_REGS; r++) {
        if (reg_classes[r] & rc) {
            if (nocode_wanted)
                return r;
            for (p = vstack; p <= vtop; p++) {
                if ((p->r & VL_MASK) == r || p->r2 == r)
                    goto notfound;
            }
            return r;
        }
    notfound:;
    }
    for (p = vstack; p <= vtop; p++) {
        r = p->r2;
        if (r < VL_CONST && (reg_classes[r] & rc))
            goto save_found;
        r = p->r & VL_MASK;
        if (r < VL_CONST && (reg_classes[r] & rc)) {
        save_found:
            save_reg(r);
            return r;
        }
    }
    return -1;
}

void save_regs(int n)
{
    Val *p, *p1;
    for (p = vstack, p1 = vtop - n; p <= p1; p++)
        save_reg(p->r);
}

void move_reg(int r, int s, int t)
{
    Val sv;
    if (r != s) {
        save_reg(r);
        sv.type.t = t;
        sv.type.ref = NULL;
        sv.r = s;
        sv.c.i = 0;
        load(r, &sv);
    }
}

void gaddrof(void)
{
    vtop->r &= ~VF_LVAL;
    if ((vtop->r & VL_MASK) == VL_LLOCAL)
        vtop->r = (vtop->r & ~VL_MASK) | VL_LOCAL | VF_LVAL;
}

/* ------------------------------------------------------------ gv */
extern void init_putv_rodata(Type *type, Section *sec, unsigned long c);

static int RC2_TYPE(int bt, int rc)
{
    (void)bt; (void)rc;
    return 0;
}

int gv(int rc)
{
    int r, r2, r_ok, r2_ok, rc2, bt;
    int bit_pos, bit_size, size, align;

    if (vtop->type.t & TQ_BITFIELD) {
        Type type;
        bit_pos = BIT_POS(vtop->type.t);
        bit_size = BIT_SIZE(vtop->type.t);
        vtop->type.t &= ~TQ_BITFIELD;
        type.ref = NULL;
        type.t = vtop->type.t & TQ_UNSIGNED;
        if ((vtop->type.t & TY_MASK) == TY_BOOL)
            type.t |= TQ_UNSIGNED;
        r = adjust_bf(vtop, bit_pos, bit_size);
        if ((vtop->type.t & TY_MASK) == TY_I64)
            type.t |= TY_I64;
        else
            type.t |= TY_I32;
        if (r == TY_STRUCT) {
            load_packed_bf(&type, bit_pos, bit_size);
        } else {
            int bits = (type.t & TY_MASK) == TY_I64 ? 64 : 32;
            gen_cast(&type);
            vpushi(bits - (bit_pos + bit_size));
            gen_op(T_SHL);
            vpushi(bits - bit_size);
            gen_op(T_SAR);
        }
        r = gv(rc);
    } else {
        if (is_float(vtop->type.t) &&
            (vtop->r & (VL_MASK | VF_LVAL)) == VL_CONST) {
            unsigned long offset;
            size = type_size(&vtop->type, &align);
            if (NODATA_WANTED)
                size = 0, align = 1;
            offset = section_add(rodata_section, size, align);
            vpush_ref(&vtop->type, rodata_section, offset, size);
            vswap();
            init_putv_rodata(&vtop->type, rodata_section, offset);
            vtop->r |= VF_LVAL;
        }
        bt = vtop->type.t & TY_MASK;
        rc2 = RC2_TYPE(bt, rc);
        if (vtop->r == VL_CMP)
            vset_VT_JMP();
        r = vtop->r & VL_MASK;
        r_ok = !(vtop->r & VF_LVAL) && (r < VL_CONST) && (reg_classes[r] & rc);
        r2_ok = !rc2 || ((vtop->r2 < VL_CONST) && (reg_classes[vtop->r2] & rc2));
        if (!r_ok || !r2_ok) {
            if (!r_ok) {
                if (1 && r < VL_CONST && (reg_classes[r] & rc) && !rc2)
                    save_reg_upstack(r, 1);
                r = get_reg(rc);
            }
            if (rc2) {
                (void)r2;
            } else {
                load(r, vtop);
            }
            vtop->r = r;
        }
    }
    return r;
}

void gv2(int rc1, int rc2)
{
    if (vtop->r != VL_CMP && rc1 <= rc2) {
        vswap();
        gv(rc1);
        vswap();
        gv(rc2);
        if ((vtop[-1].r & VL_MASK) >= VL_CONST) {
            vswap();
            gv(rc1);
            vswap();
        }
    } else {
        gv(rc2);
        vswap();
        gv(rc1);
        vswap();
        if ((vtop[0].r & VL_MASK) >= VL_CONST) {
            gv(rc2);
        }
    }
}

void gv_dup(void)
{
    int t, rc, r;
    Val sv;
    t = vtop->type.t;
    rc = RC_INT;
    sv.type.t = TY_I32;
    if (is_float(t)) {
        rc = RC_FLOAT;
        if ((t & TY_MASK) == TY_F80)
            rc = RC_ST0;
        sv.type.t = t;
    }
    r = gv(rc);
    int r1 = get_reg(rc);
    sv.r = r;
    sv.c.i = 0;
    sv.type.ref = NULL;
    load(r1, &sv);
    vdup();
    if (r != r1)
        vtop->r = r1;
}

void gvtst_set(int inv, int t)
{
    int *p;
    if (vtop->r != VL_CMP) {
        vpushi(0);
        gen_op(T_NE);
        if (vtop->r != VL_CMP)
            vset_VT_CMP(vtop->c.i != 0);
    }
    p = inv ? &vtop->jfalse : &vtop->jtrue;
    *p = gjmp_append(*p, t);
}

int gvtst(int inv, int t)
{
    int op, x, u;
    gvtst_set(inv, t);
    t = vtop->jtrue, u = vtop->jfalse;
    if (inv)
        x = u, u = t, t = x;
    op = vtop->cmp_op;
    if (op > 1)
        t = gjmp_cond(op ^ inv, t);
    else if (op != inv)
        t = gjmp(t);
    gsym(u);
    vtop--;
    return t;
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/gen_core.c <<'EOF'
/* code generator core: symbols, types, value stack, registers, operators */
#include "gen.h"

Val vstack_buf[VSTACK_SIZE + 1];
Val *vtop;
int ind, loc, rsym, anon_sym;
int nocode_wanted, const_wanted;
Type func_vt;
int func_var, func_vc, func_ind;
const char *funcname;
Sym *global_stack, *local_stack, *global_label_stack, *local_label_stack;
Type int_type, char_type, char_pointer_type, func_old_type, size_type, ptrdiff_type;
int local_scope;
int in_sizeof;
int debug_modes;
Sym *cur_func_sym;
int last_line_num;

/* ------------------------------------------------------------ symbols */
static Sym *sym_free_first;

static Sym *sym_alloc(void)
{
    Sym *s = sym_free_first;
    if (s) {
        sym_free_first = s->next;
        memset(s, 0, sizeof *s);
        return s;
    }
    return xcalloc(sizeof(Sym));
}

void sym_free(Sym *s)
{
    s->next = sym_free_first;
    sym_free_first = s;
}

Sym *sym_push2(Sym **ps, int v, int t, long long c)
{
    Sym *s = sym_alloc();
    s->v = v;
    s->type.t = t;
    s->c = c;
    s->prev = *ps;
    *ps = s;
    return s;
}

Sym *sym_find2(Sym *s, int v)
{
    while (s) {
        if (s->v == v) return s;
        if (s->v == -1) return NULL;
        s = s->prev;
    }
    return NULL;
}

Sym *struct_find(int v)
{
    Ident *id = ident_of(v);
    return id ? id->sym_tag : NULL;
}

Sym *sym_find(int v)
{
    Ident *id = ident_of(v);
    return id ? id->sym_id : NULL;
}

Sym *sym_push(int v, Type *type, int r, long long c)
{
    Sym *s, **ps;
    ps = local_stack ? &local_stack : &global_stack;
    s = sym_push2(ps, v, type->t, c);
    s->type.ref = type->ref;
    s->r = r;
    if (!(v & SYM_FIELD) && (v & ~SYM_STRUCT) < SYM_FIRST_ANOM) {
        Ident *id = ident_of(v & ~SYM_STRUCT);
        ps = (v & SYM_STRUCT) ? &id->sym_tag : &id->sym_id;
        s->shadow = *ps;
        *ps = s;
        s->scope = local_scope;
        if (s->shadow && s->shadow->scope == s->scope)
            error("redeclaration of '%s'", tokname(v & ~SYM_STRUCT, NULL));
    }
    return s;
}

Sym *global_identifier_push(int v, int t, long long c)
{
    Sym *s, **ps;
    s = sym_push2(&global_stack, v, t, c);
    s->r = VL_CONST | VF_SYM;
    if (v < SYM_FIRST_ANOM) {
        ps = &ident_of(v)->sym_id;
        while (*ps != NULL && (*ps)->scope)
            ps = &(*ps)->shadow;
        s->shadow = *ps;
        *ps = s;
    }
    return s;
}

void sym_pop(Sym **ptop, Sym *b, int keep)
{
    Sym *s, *ss, **ps;
    int v;
    s = *ptop;
    while (s != b) {
        ss = s->prev;
        v = s->v;
        if (!(v & SYM_FIELD) && (v & ~SYM_STRUCT) < SYM_FIRST_ANOM) {
            Ident *id = ident_of(v & ~SYM_STRUCT);
            ps = (v & SYM_STRUCT) ? &id->sym_tag : &id->sym_id;
            *ps = s->shadow;
        }
        if (!keep)
            sym_free(s);
        s = ss;
    }
    if (!keep)
        *ptop = b;
}

Sym *label_find(int v)
{
    Ident *id = ident_of(v);
    return id ? id->sym_label : NULL;
}

Sym *label_push(Sym **ptop, int v, int flags)
{
    Sym *s, **ps;
    s = sym_push2(ptop, v, VL_CONST, 0);
    s->r = flags;
    ps = &ident_of(v)->sym_label;
    if (ptop == &global_label_stack) {
        while (*ps != NULL)
            ps = &(*ps)->shadow;
    }
    s->shadow = *ps;
    *ps = s;
    return s;
}

/* ------------------------------------------------------------ types */
int is_float(int t)
{
    int bt = t & TY_MASK;
    return bt == TY_F80 || bt == TY_F64 || bt == TY_F32 || bt == TY_F128;
}

int is_integer_btype(int bt)
{
    return bt == TY_I8 || bt == TY_BOOL || bt == TY_I16 || bt == TY_I32 || bt == TY_I64;
}

int btype_size(int bt)
{
    return bt == TY_I8 || bt == TY_BOOL ? 1 :
           bt == TY_I16 ? 2 :
           bt == TY_I32 ? 4 :
           bt == TY_I64 ? 8 :
           bt == TY_PTR ? PTR_SIZE : 0;
}

int type_size(Type *type, int *a)
{
    Sym *s;
    int bt = type->t & TY_MASK;
    if (bt == TY_STRUCT) {
        s = type->ref;
        *a = s->r;
        return s->c;
    } else if (bt == TY_PTR) {
        if (type->t & TQ_ARRAY) {
            int ts;
            s = type->ref;
            ts = type_size(&s->type, a);
            if (ts < 0 && s->c < 0)
                ts = -ts;
            return ts * s->c;
        } else {
            *a = PTR_SIZE;
            return PTR_SIZE;
        }
    } else if (IS_ENUM(type->t) && type->ref->c < 0) {
        *a = 0;
        return -1;
    } else if (bt == TY_F80) {
        *a = 16;
        return 16;
    } else if (bt == TY_F64 || bt == TY_I64) {
        *a = 8;
        return 8;
    } else if (bt == TY_I32 || bt == TY_F32) {
        *a = 4;
        return 4;
    } else if (bt == TY_I16) {
        *a = 2;
        return 2;
    } else if (bt == TY_I128 || bt == TY_F128) {
        *a = 8;
        return 16;
    } else {
        *a = 1;
        return 1;
    }
}

Type *pointed_type(Type *type)
{
    return &type->ref->type;
}

int pointed_size(Type *type)
{
    int align;
    return type_size(pointed_type(type), &align);
}

void mk_pointer(Type *type)
{
    Sym *s;
    s = sym_push(SYM_FIELD, type, 0, -1);
    type->t = TY_PTR | (type->t & SC_MASK);
    type->ref = s;
}

int exact_log2p1(int i)
{
    int ret;
    if (!i) return 0;
    for (ret = 1; i >= 1 << 8; ret += 8) i >>= 8;
    if (i >= 1 << 4) ret += 4, i >>= 4;
    if (i >= 1 << 2) ret += 2, i >>= 2;
    if (i >= 1 << 1) ret++;
    return ret;
}

static int compare_types(Type *type1, Type *type2, int unqualified);

int is_compatible_func(Type *type1, Type *type2)
{
    Sym *s1, *s2;
    s1 = type1->ref;
    s2 = type2->ref;
    if (s1->func_call != s2->func_call)
        return 0;
    if (!is_compatible_types(&s1->type, &s2->type))
        return 0;
    if (s1->functype == FUNC_OLD || s2->functype == FUNC_OLD)
        return 1;
    if (s1->functype != s2->functype)
        return 0;
    while (s1 != NULL) {
        if (s2 == NULL)
            return 0;
        if (!is_compatible_unqualified_types(&s1->type, &s2->type))
            return 0;
        s1 = s1->next;
        s2 = s2->next;
    }
    if (s2)
        return 0;
    return 1;
}

static int compare_types(Type *type1, Type *type2, int unqualified)
{
    int bt1, t1, t2;
    t1 = type1->t & TY_TYPEBITS;
    t2 = type2->t & TY_TYPEBITS;
    if (unqualified) {
        t1 &= ~(TQ_CONST | TQ_VOLATILE);
        t2 &= ~(TQ_CONST | TQ_VOLATILE);
    }
    /* default vs explicit signedness only matters for char */
    if ((t1 & TY_MASK) != TY_I8) {
        t1 &= ~TQ_DEFSIGN;
        t2 &= ~TQ_DEFSIGN;
    }
    if (t1 != t2)
        return 0;
    if ((t1 & TQ_ARRAY) && !(type1->ref->c < 0 || type2->ref->c < 0 || type1->ref->c == type2->ref->c))
        return 0;
    bt1 = t1 & TY_MASK;
    if (bt1 == TY_PTR) {
        type1 = pointed_type(type1);
        type2 = pointed_type(type2);
        return is_compatible_types(type1, type2);
    } else if (bt1 == TY_STRUCT) {
        return type1->ref == type2->ref;
    } else if (bt1 == TY_FUNC) {
        return is_compatible_func(type1, type2);
    } else if (IS_ENUM(type1->t) && IS_ENUM(type2->t)) {
        return type1->ref == type2->ref;
    } else {
        return 1;
    }
}

int is_compatible_types(Type *type1, Type *type2)
{
    return compare_types(type1, type2, 0);
}

int is_compatible_unqualified_types(Type *type1, Type *type2)
{
    return compare_types(type1, type2, 1);
}

static void pstrcat_(char *buf, int size, const char *s)
{
    int len = strlen(buf);
    if (len < size) pstrcpy(buf + len, size - len, s);
}

void type_to_str(char *buf, int buf_size, Type *type, const char *varstr)
{
    int bt, v, t;
    Sym *s, *sa;
    char buf1[256];
    const char *tstr;

    t = type->t;
    bt = t & TY_MASK;
    buf[0] = '\0';

    if (t & SC_EXTERN)
        pstrcat_(buf, buf_size, "extern ");
    if (t & SC_STATIC)
        pstrcat_(buf, buf_size, "static ");
    if (t & SC_TYPEDEF)
        pstrcat_(buf, buf_size, "typedef ");
    if (t & SC_INLINE)
        pstrcat_(buf, buf_size, "inline ");
    if (bt != TY_PTR) {
        if (t & TQ_VOLATILE)
            pstrcat_(buf, buf_size, "volatile ");
        if (t & TQ_CONST)
            pstrcat_(buf, buf_size, "const ");
    }
    if (((t & TQ_DEFSIGN) && bt == TY_I8)
        || ((t & TQ_UNSIGNED)
            && (bt == TY_I16 || bt == TY_I32 || bt == TY_I64)
            && !IS_ENUM(t)))
        pstrcat_(buf, buf_size, (t & TQ_UNSIGNED) ? "unsigned " : "signed ");

    buf_size -= strlen(buf);
    buf += strlen(buf);

    switch (bt) {
    case TY_VOID:
        tstr = "void";
        goto add_tstr;
    case TY_BOOL:
        tstr = "_Bool";
        goto add_tstr;
    case TY_I8:
        tstr = "char";
        goto add_tstr;
    case TY_I16:
        tstr = "short";
        goto add_tstr;
    case TY_I32:
        tstr = "int";
        goto maybe_long;
    case TY_I64:
        tstr = "long long";
    maybe_long:
        if (t & TQ_LONG)
            tstr = "long";
        if (!IS_ENUM(t))
            goto add_tstr;
        tstr = "enum ";
        goto tstruct;
    case TY_F32:
        tstr = "float";
        goto add_tstr;
    case TY_F64:
        tstr = "double";
        if (!(t & TQ_LONG))
            goto add_tstr;
        /* fallthrough */
    case TY_F80:
        tstr = "long double";
    add_tstr:
        pstrcat_(buf, buf_size, tstr);
        break;
    case TY_STRUCT:
        tstr = "struct ";
        if (IS_UNION(t))
            tstr = "union ";
    tstruct:
        pstrcat_(buf, buf_size, tstr);
        v = type->ref->v & ~SYM_STRUCT;
        if (v >= SYM_FIRST_ANOM)
            pstrcat_(buf, buf_size, "<anonymous>");
        else
            pstrcat_(buf, buf_size, tokname(v, NULL));
        break;
    case TY_FUNC:
        s = type->ref;
        buf1[0] = 0;
        if (varstr && '*' == *varstr) {
            pstrcat_(buf1, sizeof(buf1), "(");
            pstrcat_(buf1, sizeof(buf1), varstr);
            pstrcat_(buf1, sizeof(buf1), ")");
        }
        pstrcat_(buf1, sizeof(buf1), "(");
        sa = s->next;
        while (sa != NULL) {
            char buf2[256];
            type_to_str(buf2, sizeof(buf2), &sa->type, NULL);
            pstrcat_(buf1, sizeof(buf1), buf2);
            sa = sa->next;
            if (sa)
                pstrcat_(buf1, sizeof(buf1), ", ");
        }
        if (s->functype == FUNC_ELLIPSIS)
            pstrcat_(buf1, sizeof(buf1), ", ...");
        pstrcat_(buf1, sizeof(buf1), ")");
        type_to_str(buf, buf_size, &s->type, buf1);
        goto no_var;
    case TY_PTR:
        s = type->ref;
        if (t & TQ_ARRAY) {
            if (varstr && '*' == *varstr)
                snprintf(buf1, sizeof(buf1), "(%s)[%lld]", varstr, s->c);
            else
                snprintf(buf1, sizeof(buf1), "%s[%lld]", varstr ? varstr : "", s->c);
            type_to_str(buf, buf_size, &s->type, buf1);
            goto no_var;
        }
        pstrcpy(buf1, sizeof(buf1), "*");
        if (t & TQ_CONST)
            pstrcat_(buf1, buf_size, "const ");
        if (t & TQ_VOLATILE)
            pstrcat_(buf1, buf_size, "volatile ");
        if (varstr)
            pstrcat_(buf1, sizeof(buf1), varstr);
        type_to_str(buf, buf_size, &s->type, buf1);
        goto no_var;
    }
    if (varstr) {
        pstrcat_(buf, buf_size, " ");
        pstrcat_(buf, buf_size, varstr);
    }
no_var:;
}

void type_incomplete_check(Type *type, const char *msg)
{
    (void)type; (void)msg;
}

/* ------------------------------------------------------------ ELF symbol helpers */
ElfW(Sym) *elfsym(Sym *s)
{
    if (!s || !s->elfsym)
        return NULL;
    return &((ElfW(Sym) *)symtab_section->data)[s->elfsym];
}

void update_storage(Sym *sym)
{
    ElfW(Sym) *esym;
    int sym_bind, old_sym_bind;
    esym = elfsym(sym);
    if (!esym)
        return;
    if (sym->visibility)
        esym->st_other = (esym->st_other & ~ELFW(ST_VISIBILITY)(-1)) | sym->visibility;
    if (sym->type.t & (SC_STATIC | SC_INLINE))
        sym_bind = STB_LOCAL;
    else if (sym->weak)
        sym_bind = STB_WEAK;
    else
        sym_bind = STB_GLOBAL;
    old_sym_bind = ELFW(ST_BIND)(esym->st_info);
    if (sym_bind != old_sym_bind) {
        esym->st_info = ELFW(ST_INFO)(sym_bind, ELFW(ST_TYPE)(esym->st_info));
    }
}

extern void symhash_rebuild(Section *s);

void put_extern_sym2(Sym *sym, int sh_num, uint64_t value, unsigned long size, int can_add_underscore)
{
    int sym_type, sym_bind, info, other, t;
    ElfW(Sym) *esym;
    const char *name;
    char buf1[256];

    if (!sym->elfsym) {
        name = tokname(sym->v, NULL);
        t = sym->type.t;
        if ((t & TY_MASK) == TY_FUNC) {
            sym_type = STT_FUNC;
        } else if ((t & TY_MASK) == TY_VOID) {
            sym_type = STT_NOTYPE;
            if ((t & (TY_MASK | SC_STATIC)) == SC_STATIC)  /* asm label */
                sym_type = STT_NOTYPE;
        } else {
            sym_type = STT_OBJECT;
        }
        if (t & (SC_STATIC | SC_INLINE))
            sym_bind = STB_LOCAL;
        else
            sym_bind = STB_GLOBAL;
        other = 0;
        if (sym->asm_label) {
            name = tokname(sym->asm_label, NULL);
            can_add_underscore = 0;
        }
        if (opt.leading_underscore && can_add_underscore) {
            buf1[0] = '_';
            pstrcpy(buf1 + 1, sizeof(buf1) - 1, name);
            name = buf1;
        }
        info = ELFW(ST_INFO)(sym_bind, sym_type);
        sym->elfsym = put_elf_sym(symtab_section, value, size, info, other, sh_num, name);
    } else {
        esym = elfsym(sym);
        esym->st_value = value;
        esym->st_size = size;
        esym->st_shndx = sh_num;
    }
    update_storage(sym);
}

void put_extern_sym(Sym *sym, Section *section, uint64_t value, unsigned long size)
{
    int sh_num = section ? section->sh_num : SHN_UNDEF;
    put_extern_sym2(sym, sh_num, value, size, 1);
}

void greloca(Section *s, Sym *sym, unsigned long offset, int type, uint64_t addend)
{
    int c = 0;
    if (nocode_wanted && s == cur_text_section)
        return;
    if (sym) {
        if (0 == sym->elfsym)
            put_extern_sym(sym, NULL, 0, 0);
        c = sym->elfsym;
    }
    put_elf_reloca(symtab_section, s, offset, type, c, addend);
}

void greloc(Section *s, Sym *sym, unsigned long offset, int type)
{
    greloca(s, sym, offset, type, 0);
}

Sym *get_sym_ref(Type *type, Section *sec, unsigned long offset, unsigned long size)
{
    int v;
    Sym *sym;
    v = anon_sym++;
    sym = sym_push(v, type, VL_CONST | VF_SYM, 0);
    sym->type.t |= SC_STATIC;
    put_extern_sym(sym, sec, offset, size);
    return sym;
}

Sym *external_global_sym(int v, Type *type)
{
    Sym *s;
    s = sym_find(v);
    if (!s) {
        s = global_identifier_push(v, type->t | SC_EXTERN, 0);
        s->type.ref = type->ref;
    } else if (IS_ASM_SYM_(s)) {
        s->type.t = type->t | (s->type.t & SC_EXTERN);
        s->type.ref = type->ref;
        update_storage(s);
    }
    return s;
}

Sym *external_helper_sym(int v)
{
    Type ct = { TY_FUNC, NULL };
    ct.ref = func_old_type.ref;
    return external_global_sym(v, &ct);
}

void vpush_helper_func(int v)
{
    vpushsym(&func_old_type, external_helper_sym(v));
}

/* ------------------------------------------------------------ vstack */
static void vsetc(Type *type, int r, CVal *vc)
{
    if (vtop >= vstack + (VSTACK_SIZE - 1))
        error("memory full (vstack)");
    if (vtop >= vstack && !nocode_wanted)
        vcheck_cmp();
    vtop++;
    vtop->type = *type;
    vtop->r = r;
    vtop->r2 = VL_CONST;
    vtop->c = *vc;
    vtop->sym = NULL;
}

void vcheck_cmp(void)
{
    if (vtop->r == VL_CMP && !nocode_wanted)
        gv(RC_INT);
}

void vswap(void)
{
    Val tmp;
    vcheck_cmp();
    tmp = vtop[0];
    vtop[0] = vtop[-1];
    vtop[-1] = tmp;
}

void vpop(void)
{
    int v;
    v = vtop->r & VL_MASK;
    if (v == R_ST0) {
        o(0xd8dd); /* fstp %st(0) */
    } else if (v == VL_CMP) {
        gsym(vtop->jtrue);
        gsym(vtop->jfalse);
    }
    vtop--;
}

void vpush(Type *type)
{
    vset(type, VL_CONST, 0);
}

void vpushi(int v)
{
    CVal cval;
    cval.i = v;
    vsetc(&int_type, VL_CONST, &cval);
}

void vpush64(int ty, unsigned long long v)
{
    CVal cval;
    Type ctype;
    ctype.t = ty;
    ctype.ref = NULL;
    cval.i = v;
    vsetc(&ctype, VL_CONST, &cval);
}

void vpushs(long long v)
{
    vpush64(TY_I64 | TQ_LONG | TQ_UNSIGNED, v);
}

void vpushll(long long v)
{
    vpush64(TY_I64, v);
}

void vset(Type *type, int r, long long v)
{
    CVal cval;
    cval.i = v;
    vsetc(type, r, &cval);
}

void vseti(int r, int v)
{
    Type type;
    type.t = TY_I32;
    type.ref = NULL;
    vset(&type, r, v);
}

void vpushv(Val *v)
{
    if (vtop >= vstack + (VSTACK_SIZE - 1))
        error("memory full (vstack)");
    vtop++;
    *vtop = *v;
}

void vdup(void)
{
    vpushv(vtop);
}

void vrotb(int n)
{
    int i;
    Val tmp;
    vcheck_cmp();
    tmp = vtop[-n + 1];
    for (i = -n + 1; i != 0; i++)
        vtop[i] = vtop[i + 1];
    vtop[0] = tmp;
}

void vrott(int n)
{
    int i;
    Val tmp;
    vcheck_cmp();
    tmp = vtop[0];
    for (i = 0; i < n - 1; i++)
        vtop[-i] = vtop[-i - 1];
    vtop[-n + 1] = tmp;
}

void vrev(int n)
{
    int i;
    Val tmp;
    vcheck_cmp();
    for (i = 0, n = -n; i > ++n; --i)
        tmp = vtop[i], vtop[i] = vtop[n], vtop[n] = tmp;
}

void vpushsym(Type *type, Sym *sym)
{
    CVal cval;
    cval.i = 0;
    vsetc(type, VL_CONST | VF_SYM, &cval);
    vtop->sym = sym;
}

void vpush_ref(Type *type, Section *sec, unsigned long offset, unsigned long size)
{
    vpushsym(type, get_sym_ref(type, sec, offset, size));
}

void vset_VT_CMP(int op)
{
    vtop->r = VL_CMP;
    vtop->cmp_op = op;
    vtop->jfalse = 0;
    vtop->jtrue = 0;
}

static void vset_VT_JMP(void)
{
    int op = vtop->cmp_op;
    if (vtop->jtrue || vtop->jfalse) {
        int origt = vtop->type.t;
        int inv = op & (op < 2);
        vseti(VL_JMP + inv, gvtst(inv, 0));
        vtop->type.t |= origt & (TQ_UNSIGNED | TQ_DEFSIGN);
    } else {
        vtop->c.i = op;
        if (op < 2)
            vtop->r = VL_CONST;
    }
}

void vtop_reset(void)
{
    vtop = vstack - 1;
}

