/* ------------------------------------------------------------ registers */
typedef struct TempVar { int location; short size; short align; } TempVar;
static TempVar temp_vars[8];
int nb_temp_local_vars;

int get_temp_local_var(int size, int align)
{
    int i;
    TempVar *tv;
    int found_var;
    Val *p;
    int r;
    char free_ = 0;
    char found = 0;
    for (i = 0; i < nb_temp_local_vars; i++) {
        tv = &temp_vars[i];
        if (tv->size < size || align != tv->align)
            continue;
        free_ = 1;
        for (p = vstack; p <= vtop; p++) {
            r = p->r & VL_MASK;
            if (r == VL_LOCAL || r == VL_LLOCAL) {
                if (p->c.i == tv->location) {
                    free_ = 0;
                    break;
                }
            }
        }
        if (free_) {
            found_var = tv->location;
            found = 1;
            break;
        }
    }
    if (!found) {
        loc = (loc - size) & -align;
        if (nb_temp_local_vars < 8) {
            tv = &temp_vars[i];
            tv->location = loc;
            tv->size = size;
            tv->align = align;
            nb_temp_local_vars++;
        }
        found_var = loc;
    }
    return found_var;
}

void clear_temp_local_var_list(void)
{
    nb_temp_local_vars = 0;
}

void save_reg_upstack(int r, int n)
{
    int l, size, align, bt;
    Val *p, *p1, sv;

    if ((r &= VL_MASK) >= VL_CONST)
        return;
    if (nocode_wanted)
        return;
    l = 0;
    for (p = vstack, p1 = vtop - n; p <= p1; p++) {
        if ((p->r & VL_MASK) == r || p->r2 == r) {
            if (!l) {
                bt = p->type.t & TY_MASK;
                if (bt == TY_VOID)
                    continue;
                if ((p->r & VF_LVAL) || bt == TY_FUNC)
                    bt = TY_PTR;
                sv.type.t = bt;
                size = type_size(&sv.type, &align);
                l = get_temp_local_var(size, align);
                sv.r = VL_LOCAL | VF_LVAL;
                sv.c.i = l;
                store(p->r & VL_MASK, &sv);
                if (r == R_ST0) {
                    o(0xd8dd); /* fstp %st(0) */
                }
            }
            if (p->r & VF_LVAL) {
                p->r = (p->r & ~VL_MASK) | VL_LLOCAL;
            } else {
                p->r = VF_LVAL | VL_LOCAL;
                p->type.t &= ~TQ_ARRAY;
            }
            p->sym = NULL;
            p->r2 = VL_CONST;
            p->c.i = l;
        }
    }
}

void save_reg(int r)
{
    save_reg_upstack(r, 0);
}

int get_reg(int rc)
{
    int r;
    Val *p;
    for (r = 0; r < NB_REGS; r++) {
        if (reg_classes[r] & rc) {
            if (nocode_wanted)
                return r;
            for (p = vstack; p <= vtop; p++) {
                if ((p->r & VL_MASK) == r || p->r2 == r)
                    goto notfound;
            }
            return r;
        }
    notfound:;
    }
    for (p = vstack; p <= vtop; p++) {
        r = p->r2;
        if (r < VL_CONST && (reg_classes[r] & rc))
            goto save_found;
        r = p->r & VL_MASK;
        if (r < VL_CONST && (reg_classes[r] & rc)) {
        save_found:
            save_reg(r);
            return r;
        }
    }
    return -1;
}

void save_regs(int n)
{
    Val *p, *p1;
    for (p = vstack, p1 = vtop - n; p <= p1; p++)
        save_reg(p->r);
}

void move_reg(int r, int s, int t)
{
    Val sv;
    if (r != s) {
        save_reg(r);
        sv.type.t = t;
        sv.type.ref = NULL;
        sv.r = s;
        sv.c.i = 0;
        load(r, &sv);
    }
}

void gaddrof(void)
{
    vtop->r &= ~VF_LVAL;
    if ((vtop->r & VL_MASK) == VL_LLOCAL)
        vtop->r = (vtop->r & ~VL_MASK) | VL_LOCAL | VF_LVAL;
}

/* ------------------------------------------------------------ gv */
extern void init_putv_rodata(Type *type, Section *sec, unsigned long c);

static int RC2_TYPE(int bt, int rc)
{
    (void)bt; (void)rc;
    return 0;
}

int gv(int rc)
{
    int r, r2, r_ok, r2_ok, rc2, bt;
    int bit_pos, bit_size, size, align;

    if (vtop->type.t & TQ_BITFIELD) {
        Type type;
        bit_pos = BIT_POS(vtop->type.t);
        bit_size = BIT_SIZE(vtop->type.t);
        vtop->type.t &= ~TQ_BITFIELD;
