}

void gv2(int rc1, int rc2)
{
    if (vtop->r != VL_CMP && rc1 <= rc2) {
        vswap();
        gv(rc1);
        vswap();
        gv(rc2);
        if ((vtop[-1].r & VL_MASK) >= VL_CONST) {
            vswap();
            gv(rc1);
            vswap();
        }
    } else {
        gv(rc2);
        vswap();
        gv(rc1);
        vswap();
        if ((vtop[0].r & VL_MASK) >= VL_CONST) {
            gv(rc2);
        }
    }
}

void gv_dup(void)
{
    int t, rc, r;
    Val sv;
    t = vtop->type.t;
    rc = RC_INT;
    sv.type.t = TY_I32;
    if (is_float(t)) {
        rc = RC_FLOAT;
        if ((t & TY_MASK) == TY_F80)
            rc = RC_ST0;
        sv.type.t = t;
    }
    r = gv(rc);
    int r1 = get_reg(rc);
    sv.r = r;
    sv.c.i = 0;
    sv.type.ref = NULL;
    load(r1, &sv);
    vdup();
    if (r != r1)
        vtop->r = r1;
}

void gvtst_set(int inv, int t)
{
    int *p;
    if (vtop->r != VL_CMP) {
        vpushi(0);
        gen_op(T_NE);
        if (vtop->r != VL_CMP)
            vset_VT_CMP(vtop->c.i != 0);
    }
    p = inv ? &vtop->jfalse : &vtop->jtrue;
    *p = gjmp_append(*p, t);
}

int gvtst(int inv, int t)
{
    int op, x, u;
    gvtst_set(inv, t);
    t = vtop->jtrue, u = vtop->jfalse;
    if (inv)
        x = u, u = t, t = x;
    op = vtop->cmp_op;
    if (op > 1)
        t = gjmp_cond(op ^ inv, t);
    else if (op != inv)
        t = gjmp(t);
    gsym(u);
    vtop--;
    return t;
}
