    }
}

void gen_cast_s(int t)
{
    Type type;
    type.t = t;
    type.ref = NULL;
    gen_cast(&type);
}

void gen_cast(Type *type)
{
    int sbt, dbt, sf, df, c;
    int dbt_bt, sbt_bt, ds, ss, bits, trunc;

    if (vtop->r & VF_MUSTCAST)
        force_charshort_cast();

    if (vtop->type.t & TQ_BITFIELD)
        gv(RC_INT);

    if (IS_ENUM(type->t) && type->ref->c < 0)
        error("cast to incomplete type");

    dbt = type->t & (TY_MASK | TQ_UNSIGNED);
    sbt = vtop->type.t & (TY_MASK | TQ_UNSIGNED);
    if (sbt == TY_FUNC)
        sbt = TY_PTR;

again:
    if (sbt != dbt) {
        sf = is_float(sbt);
        df = is_float(dbt);
        dbt_bt = dbt & TY_MASK;
        sbt_bt = sbt & TY_MASK;
        if (dbt_bt == TY_VOID)
            goto done;
        if (sbt_bt == TY_VOID) {
        err:
            cast_error(&vtop->type, type);
        }

        c = (vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST;
        if (c) {
            if (sbt == TY_F32)
                vtop->c.ld = vtop->c.f;
            else if (sbt == TY_F64)
                vtop->c.ld = vtop->c.d;

            if (df) {
                if (sbt_bt == TY_I64) {
                    if ((sbt & TQ_UNSIGNED) || !(vtop->c.i >> 63))
                        vtop->c.ld = vtop->c.i;
                    else
                        vtop->c.ld = -(long double)-vtop->c.i;
                } else if (!sf) {
                    if ((sbt & TQ_UNSIGNED) || !(vtop->c.i >> 31))
                        vtop->c.ld = (uint32_t)vtop->c.i;
                    else
                        vtop->c.ld = -(long double)-(uint32_t)vtop->c.i;
                }
                if (dbt == TY_F32)
                    vtop->c.f = (float)vtop->c.ld;
                else if (dbt == TY_F64)
                    vtop->c.d = (double)vtop->c.ld;
            } else if (sf && dbt == TY_BOOL) {
                vtop->c.i = (vtop->c.ld != 0);
            } else {
                if (sf) {
                    long double v = vtop->c.ld;
                    if (dbt & TQ_UNSIGNED && dbt_bt == TY_I64) {
                        if (v >= 9223372036854775808.0L)
                            vtop->c.i = (uint64_t)(int64_t)(v - 9223372036854775808.0L) + (1ULL << 63);
                        else
                            vtop->c.i = (int64_t)v;
                    } else
                        vtop->c.i = (int64_t)v;
                } else if (sbt_bt == TY_I64 || sbt == TY_PTR)
                    ;
                else if (sbt & TQ_UNSIGNED)
                    vtop->c.i = (uint32_t)vtop->c.i;
                else
                    vtop->c.i = ((uint32_t)vtop->c.i | -(vtop->c.i & 0x80000000));

                if (dbt_bt == TY_I64 || dbt == TY_PTR)
                    ;
                else if (dbt == TY_BOOL)
                    vtop->c.i = (vtop->c.i != 0);
                else {
                    uint32_t m = dbt_bt == TY_I8 ? 0xff :
                                 dbt_bt == TY_I16 ? 0xffff :
                                 0xffffffff;
                    vtop->c.i &= m;
                    if (!(dbt & TQ_UNSIGNED))
                        vtop->c.i |= -(vtop->c.i & ((m >> 1) + 1));
                }
            }
            goto done;
        } else if (dbt == TY_BOOL
                   && (vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == (VL_CONST | VF_SYM)) {
            vtop->r = VL_CONST;
            vtop->c.i = 1;
            goto done;
        }

        if (STATIC_DATA_WANTED)
            goto done;

        if (dbt == TY_BOOL) {
            gen_test_zero(T_NE);
            goto done;
        }

        if (sf || df) {
            if (sf && df) {
                gen_cvt_ftof(dbt);
            } else if (df) {
                gen_cvt_itof(dbt);
            } else {
                sbt = dbt;
                if (dbt_bt != TY_I64 && dbt_bt != TY_I32)
                    sbt = TY_I32;
                gen_cvt_ftoi(sbt);
                goto again;
            }
            goto done;
        }

        ds = btype_size(dbt_bt);
        ss = btype_size(sbt_bt);
        if (ds == 0 || ss == 0)
            goto err;

        if (IS_ENUM(type->t) && type->ref->c < 0)
            error("cast to incomplete type");

        if (ds == ss && ds >= 4)
            goto done;
        if (dbt_bt == TY_PTR || sbt_bt == TY_PTR) {
            warning("cast between pointer and integer of different size");
            if (sbt_bt == TY_PTR) {
                vtop->type.t = TY_I64;
            }
        }

        if (vtop->r & VF_LVAL) {
            if (ds <= ss)
                goto done;
            if (ds <= 4 && !(dbt == (TY_I16 | TQ_UNSIGNED) && sbt == TY_I8)) {
                gv(RC_INT);
                goto done;
            }
        }
        gv(RC_INT);

        trunc = 0;
        if (ds == 8) {
            if (sbt & TQ_UNSIGNED) {
                goto done;
            } else {
                gen_cvt_sxtw();
                goto done;
            }
        } else if (ss == 8) {
            trunc = 32;
        } else {
            ss = 4;
        }

        if (ds >= ss)
            goto done;
        if (ss == 4) {
            gen_cvt_csti(dbt);
            goto done;
        }
        bits = (ss - ds) * 8;
        vtop->type.t = (ss == 8 ? TY_I64 : TY_I32) | (dbt & TQ_UNSIGNED);
        vpushi(bits);
        gen_op(T_SHL);
        vpushi(bits - trunc);
        gen_op(T_SAR);
        vpushi(trunc);
        gen_op(OP_SHR);
    }
done:
    vtop->type = *type;
    vtop->type.t &= ~(TQ_CONST | TQ_VOLATILE | TQ_ARRAY);
}

/* ------------------------------------------------------------ assignment */
void verify_assign_cast(Type *dt)
{
    Type *st, *type1, *type2;
    int dbt, sbt, qualwarn, lvl;

    st = &vtop->type;
    dbt = dt->t & TY_MASK;
    sbt = st->t & TY_MASK;
    if (dt->t & TQ_CONST)
        warning("assignment of read-only location");
    switch (dbt) {
    case TY_VOID:
        if (sbt != dbt)
            error("assignment to void expression");
        break;
    case TY_PTR:
        if (is_null_pointer(vtop))
            break;
        if (is_integer_btype(sbt)) {
            warning("assignment makes pointer from integer without a cast");
            break;
        }
        type1 = pointed_type(dt);
        if (sbt == TY_PTR)
            type2 = pointed_type(st);
        else if (sbt == TY_FUNC)
            type2 = st;
        else
            goto err;
        if (is_compatible_types(type1, type2))
            break;
        for (qualwarn = lvl = 0;; ++lvl) {
            if (((type2->t & TQ_CONST) && !(type1->t & TQ_CONST)) ||
                ((type2->t & TQ_VOLATILE) && !(type1->t & TQ_VOLATILE)))
                qualwarn = 1;
            dbt = type1->t & (TY_MASK | TQ_LONG);
            sbt = type2->t & (TY_MASK | TQ_LONG);
            if (dbt != TY_PTR || sbt != TY_PTR)
                break;
            type1 = pointed_type(type1);
            type2 = pointed_type(type2);
        }
        if (!is_compatible_unqualified_types(type1, type2)) {
            if ((dbt == TY_VOID || sbt == TY_VOID) && lvl == 0) {
            } else if (dbt == sbt
                       && is_integer_btype(sbt & TY_MASK)
                       && IS_ENUM(type1->t) + IS_ENUM(type2->t)
                       + !!((type1->t ^ type2->t) & TQ_UNSIGNED) < 2) {
            } else {
                warning("assignment from incompatible pointer type");
                break;
            }
        }
        if (qualwarn)
            warning_opt(WOPT_DISCARDED, "assignment discards qualifiers from pointer target type");
        break;
    case TY_I8:
    case TY_I16:
    case TY_I32:
    case TY_I64:
        if (sbt == TY_PTR || sbt == TY_FUNC) {
            warning("assignment makes integer from pointer without a cast");
        } else if (sbt == TY_STRUCT) {
            goto case_struct;
        }
        break;
    case TY_STRUCT:
    case_struct:
        if (!is_compatible_unqualified_types(dt, st)) {
        err:
            cast_error(st, dt);
        }
        break;
    }
}

void gen_assign_cast(Type *dt)
{
    verify_assign_cast(dt);
    gen_cast(dt);
}

void test_lvalue(void)
{
    if (!(vtop->r & VF_LVAL))
        expect("lvalue");
}

void indir(void)
{
    if ((vtop->type.t & TY_MASK) != TY_PTR) {
        if ((vtop->type.t & TY_MASK) == TY_FUNC)
            return;
        expect("pointer");
    }
    if (vtop->r & VF_LVAL)
        gv(RC_INT);
    vtop->type = *pointed_type(&vtop->type);
    if (!(vtop->type.t & (TQ_ARRAY | TQ_VLA))
        && (vtop->type.t & TY_MASK) != TY_FUNC) {
        vtop->r |= VF_LVAL;
    }
}

/* ------------------------------------------------------------ bitfields */
static int adjust_bf(Val *sv, int bit_pos, int bit_size)
{
    int t;
    if (0 == sv->type.ref)
        return 0;
    t = sv->type.ref->auxtype_;
    if (t != -1 && t != TY_STRUCT) {
        sv->type.t = (sv->type.t & ~(TY_MASK | TQ_LONG)) | t;
        sv->r |= VF_LVAL;
    }
    return t;
}

static void incr_offset(int offset)
{
    int t = vtop->type.t;
    gaddrof();
    vtop->type.t = TY_PTR;
    vpushs(offset);
    gen_op('+');
    vtop->r |= VF_LVAL;
    vtop->type.t = t;
}

static void incr_bf_adr(int o_)
{
    vtop->type.t = TY_I8 | TQ_UNSIGNED;
    incr_offset(o_);
}

static void load_packed_bf(Type *type, int bit_pos, int bit_size)
{
    int n, o_, bits;
    save_reg_upstack(vtop->r, 1);
    vpush64(type->t & TY_MASK, 0);
    bits = 0, o_ = bit_pos >> 3, bit_pos &= 7;
    do {
        vswap();
        incr_bf_adr(o_);
        vdup();
        n = 8 - bit_pos;
        if (n > bit_size)
            n = bit_size;
        if (bit_pos)
            vpushi(bit_pos), gen_op(OP_SHR), bit_pos = 0;
        if (n < 8)
            vpushi((1 << n) - 1), gen_op('&');
        gen_cast(type);
        if (bits)
            vpushi(bits), gen_op(T_SHL);
        vrotb(3);
        gen_op('|');
        bits += n, bit_size -= n, o_ = 1;
    } while (bit_size);
    vswap(), vpop();
    if (!(type->t & TQ_UNSIGNED)) {
        n = ((type->t & TY_MASK) == TY_I64 ? 64 : 32) - bits;
        vpushi(n), gen_op(T_SHL);
        vpushi(n), gen_op(T_SAR);
    }
}

static void store_packed_bf(int bit_pos, int bit_size)
{
    int bits, n, o_, m, c;
    c = (vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST;
    vswap();
    save_reg_upstack(vtop->r, 1);
    bits = 0, o_ = bit_pos >> 3, bit_pos &= 7;
    do {
        incr_bf_adr(o_);
        vswap();
        c ? vdup() : gv_dup();
        vrott(3);
        if (bits)
            vpushi(bits), gen_op(OP_SHR);
        if (bit_pos)
            vpushi(bit_pos), gen_op(T_SHL);
        n = 8 - bit_pos;
        if (n > bit_size)
            n = bit_size;
        if (n < 8) {
            m = ((1 << n) - 1) << bit_pos;
            vpushi(m), gen_op('&');
            vpushv(vtop - 1);
            vpushi(m & 0x80 ? ~m & 0x7f : ~m);
            gen_op('&');
            gen_op('|');
        }
        vdup(), vtop[-1] = vtop[-2];
        vstore(), vpop();
        bits += n, bit_size -= n, bit_pos = 0, o_ = 1;
    } while (bit_size);
    vpop(), vpop();
}

/* ------------------------------------------------------------ store */
void vstore(void)
{
    int sbt, dbt, ft, r, size, align, bit_size, bit_pos, delayed_cast;

    ft = vtop[-1].type.t;
    sbt = vtop->type.t & TY_MASK;
    dbt = ft & TY_MASK;
    verify_assign_cast(&vtop[-1].type);

    if (sbt == TY_STRUCT) {
        size = type_size(&vtop->type, &align);
        vpushv(vtop - 1);
        vtop->type.t = TY_PTR;
        gaddrof();
        vswap();
        vtop->type.t = TY_PTR;
        gaddrof();
        gen_struct_copy(size);
    } else if (ft & TQ_BITFIELD) {
        vdup(), vtop[-1] = vtop[-2];
        bit_pos = BIT_POS(ft);
        bit_size = BIT_SIZE(ft);
        vtop[-1].type.t = ft & ~TY_SMASK;
        if (dbt == TY_BOOL) {
            gen_cast(&vtop[-1].type);
            vtop[-1].type.t = (vtop[-1].type.t & ~TY_MASK) | (TY_I8 | TQ_UNSIGNED);
        }
        r = adjust_bf(vtop - 1, bit_pos, bit_size);
        if (dbt != TY_BOOL) {
            gen_cast(&vtop[-1].type);
            dbt = vtop[-1].type.t & TY_MASK;
        }
        if (r == TY_STRUCT) {
            store_packed_bf(bit_pos, bit_size);
        } else {
            unsigned long long mask = (1ULL << bit_size) - 1;
            if (dbt != TY_BOOL) {
                if (dbt == TY_I64)
                    vpushll(mask);
                else
                    vpushi((unsigned)mask);
                gen_op('&');
            }
            vpushi(bit_pos);
            gen_op(T_SHL);
            vswap();
            vdup();
            vrott(3);
            if (dbt == TY_I64)
                vpushll(~(mask << bit_pos));
            else
                vpushi(~((unsigned)mask << bit_pos));
            gen_op('&');
            gen_op('|');
            vstore();
            vpop();
        }
    } else if (dbt == TY_VOID) {
        --vtop;
    } else {
        delayed_cast = 0;
        if ((dbt == TY_I8 || dbt == TY_I16) && is_integer_btype(sbt)) {
            if ((vtop->r & VF_MUSTCAST) && btype_size(dbt) > btype_size(sbt))
                force_charshort_cast();
            delayed_cast = 1;
        } else {
            gen_cast(&vtop[-1].type);
        }
        gv(is_float(dbt) ? (dbt == TY_F80 ? RC_ST0 : RC_FLOAT) : RC_INT);
        if (delayed_cast) {
            vtop->r |= ((sbt == TY_I64) + 1) << 10;
            vtop->type.t = ft & TY_TYPEBITS;
        }
        if ((vtop[-1].r & VL_MASK) == VL_LLOCAL) {
            Val sv;
            r = get_reg(RC_INT);
            sv.type.t = TY_I64 | TQ_LONG;
            sv.r = VL_LOCAL | VF_LVAL;
            sv.c.i = vtop[-1].c.i;
            load(r, &sv);
            vtop[-1].r = r | VF_LVAL;
        }
        r = vtop->r & VL_MASK;
        store(r, vtop - 1);
        vswap();
        vtop--;
    }
}

void inc(int post, int c)
{
    test_lvalue();
    vdup();
    if (post) {
        gv_dup();
        vrotb(3);
        vrotb(3);
    }
    vpushi(c - T_NEG);
    gen_op('+');
    vstore();
    if (post)
        vpop();
}
