/* ------------------------------------------------------------ constant folding */
static uint64_t gen_opic_sdiv(uint64_t a, uint64_t b)
{
    uint64_t x = (a >> 63 ? -a : a) / (b >> 63 ? -b : b);
    return (a ^ b) >> 63 ? -x : x;
}

static int gen_opic_lt(uint64_t a, uint64_t b)
{
    return (a ^ (uint64_t)1 << 63) < (b ^ (uint64_t)1 << 63);
}

void gen_opic(int op)
{
    Val *v1 = vtop - 1;
    Val *v2 = vtop;
    int t1 = v1->type.t & TY_MASK;
    int t2 = v2->type.t & TY_MASK;
    int c1 = (v1->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST;
    int c2 = (v2->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST;
    uint64_t l1 = c1 ? v1->c.i : 0;
    uint64_t l2 = c2 ? v2->c.i : 0;
    int shm = (t1 == TY_I64) ? 63 : 31;

    if (t1 != TY_I64 && t1 != TY_PTR)
        l1 = ((uint32_t)l1 | (v1->type.t & TQ_UNSIGNED ? 0 : -(l1 & 0x80000000)));
    if (t2 != TY_I64 && t2 != TY_PTR)
        l2 = ((uint32_t)l2 | (v2->type.t & TQ_UNSIGNED ? 0 : -(l2 & 0x80000000)));

    if (c1 && c2) {
        switch (op) {
        case '+': l1 += l2; break;
        case '-': l1 -= l2; break;
        case '&': l1 &= l2; break;
        case '^': l1 ^= l2; break;
        case '|': l1 |= l2; break;
        case '*': l1 *= l2; break;
        case OP_PDIV:
        case '/':
        case '%':
        case OP_UDIV:
        case OP_UMOD:
            if (l2 == 0) {
                if (const_wanted && !(nocode_wanted & unevalmask))
                    error("division by zero in constant");
                goto general_case;
            }
            switch (op) {
            default: l1 = gen_opic_sdiv(l1, l2); break;
            case '%': l1 = l1 - l2 * gen_opic_sdiv(l1, l2); break;
            case OP_UDIV: l1 = l1 / l2; break;
            case OP_UMOD: l1 = l1 % l2; break;
            }
            break;
        case T_SHL: l1 <<= (l2 & shm); break;
        case OP_SHR: l1 >>= (l2 & shm); break;
        case T_SAR:
            l1 = (l1 >> 63) ? ~(~l1 >> (l2 & shm)) : l1 >> (l2 & shm);
            break;
        case T_ULT: l1 = l1 < l2; break;
        case T_UGE: l1 = l1 >= l2; break;
        case T_EQ: l1 = l1 == l2; break;
        case T_NE: l1 = l1 != l2; break;
        case T_ULE: l1 = l1 <= l2; break;
        case T_UGT: l1 = l1 > l2; break;
        case T_LT: l1 = gen_opic_lt(l1, l2); break;
        case T_GE: l1 = !gen_opic_lt(l1, l2); break;
        case T_LE: l1 = !gen_opic_lt(l2, l1); break;
        case T_GT: l1 = gen_opic_lt(l2, l1); break;
        case T_ANDAND: l1 = l1 && l2; break;
        case T_OROR: l1 = l1 || l2; break;
        default:
            goto general_case;
        }
        if (t1 != TY_I64 && t1 != TY_PTR)
            l1 = ((uint32_t)l1 | (v1->type.t & TQ_UNSIGNED ? 0 : -(l1 & 0x80000000)));
        v1->c.i = l1;
        vtop--;
    } else {
        if (c1 && (op == '+' || op == '&' || op == '^' ||
                   op == '|' || op == '*' || op == T_EQ || op == T_NE)) {
            vswap();
            c2 = c1;
            l2 = l1;
        }
        if (!const_wanted &&
            c1 && ((l1 == 0 && (op == T_SHL || op == OP_SHR || op == T_SAR)) ||
                   (l1 == (uint64_t)-1 && op == T_SAR))) {
            vtop--;
        } else if (!const_wanted &&
                   c2 && ((l2 == 0 && (op == '&' || op == '*')) ||
                          (op == '|' && (l2 == (uint64_t)-1 || (l2 == 0xFFFFFFFF && t2 != TY_I64))) ||
                          (l2 == 1 && (op == '%' || op == OP_UMOD)))) {
            if (l2 == 1)
                vtop->c.i = 0;
            vswap();
            vtop--;
        } else if (c2 && (((op == '*' || op == '/' || op == OP_UDIV || op == OP_PDIV) && l2 == 1) ||
                          ((op == '+' || op == '-' || op == '|' || op == '^' ||
                            op == T_SHL || op == OP_SHR || op == T_SAR) && l2 == 0) ||
                          (op == '&' && (l2 == (uint64_t)-1 || (l2 == 0xFFFFFFFF && t2 != TY_I64))))) {
            vtop--;
        } else if (c2 && (op == '*' || op == OP_PDIV || op == OP_UDIV)) {
            if (l2 > 0 && (l2 & (l2 - 1)) == 0) {
                int n = -1;
                while (l2) {
                    l2 >>= 1;
                    n++;
                }
                vtop->c.i = n;
                if (op == '*')
                    op = T_SHL;
                else if (op == OP_PDIV)
                    op = T_SAR;
                else
                    op = OP_SHR;
