            if (op == '-')
                l2 = -l2;
            l2 += vtop[-1].c.i;
            if ((int)l2 != (long long)l2)
                goto general_case;
            vtop--;
            vtop->c.i = l2;
        } else {
        general_case:
            gen_opi(op);
        }
        if (vtop->r == VL_CONST)
            vtop->r |= VF_NONCONST;
    }
}

/* float constant folding */
void gen_opif(int op)
{
    int c1, c2, i, bt;
    Val *v1, *v2;
    long double f1, f2;

    v1 = vtop - 1;
    v2 = vtop;
    if (op == T_NEG)
        v1 = v2;
    bt = v1->type.t & TY_MASK;

    c1 = (v1->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST;
    c2 = (v2->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST;
    if (c1 && c2) {
        if (bt == TY_F32) {
            f1 = v1->c.f;
            f2 = v2->c.f;
        } else if (bt == TY_F64) {
            f1 = v1->c.d;
            f2 = v2->c.d;
        } else {
            f1 = v1->c.ld;
            f2 = v2->c.ld;
        }
        /* NOTE: we only do constant propagation if finite number (not
           NaN or infinity) (ANSI spec) */
        if (!(isfinite((double)f1) || const_wanted) || !(isfinite((double)f2) || const_wanted))
            goto general_case;
        switch (op) {
        case '+': f1 += f2; break;
        case '-': f1 -= f2; break;
        case '*': f1 *= f2; break;
        case '/':
            if (f2 == 0.0) {
                union { float f; unsigned u; } x1, x2, y;
                if (!const_wanted)
                    goto general_case;
                /* 0/0 etc */
                x1.f = f1; x2.f = f2;
                (void)x1; (void)x2; (void)y;
                f1 = f1 / f2;
                break;
            }
            f1 /= f2;
            break;
        case T_NEG:
            f1 = -f1;
            goto unary_result;
        case T_EQ: i = f1 == f2; make_int: vtop -= 2; vpushi(i); return;
        case T_NE: i = f1 != f2; goto make_int;
        case T_LT: i = f1 < f2; goto make_int;
        case T_GE: i = f1 >= f2; goto make_int;
        case T_LE: i = f1 <= f2; goto make_int;
        case T_GT: i = f1 > f2; goto make_int;
        default:
            goto general_case;
        }
        vtop--;
    unary_result:
        if (bt == TY_F32) {
            v1->c.f = f1;
        } else if (bt == TY_F64) {
            v1->c.d = f1;
        } else {
            v1->c.ld = f1;
        }
    } else {
    general_case:
        if (op == T_NEG) {
            gen_opf(op);
        } else {
            gen_opf(op);
        }
    }
}

/* ------------------------------------------------------------ type combination */
int is_null_pointer(Val *p)
{
    if ((p->r & (VL_MASK | VF_LVAL | VF_SYM | VF_NONCONST)) != VL_CONST)
        return 0;
    return ((p->type.t & TY_MASK) == TY_I32 && (uint32_t)p->c.i == 0) ||
        ((p->type.t & TY_MASK) == TY_I64 && p->c.i == 0) ||
        ((p->type.t & TY_MASK) == TY_PTR &&
         (PTR_SIZE == 4 ? (uint32_t)p->c.i == 0 : p->c.i == 0) &&
         ((pointed_type(&p->type)->t & TY_MASK) == TY_VOID) &&
         0 == (pointed_type(&p->type)->t & (TQ_CONST | TQ_VOLATILE)));
}

static void type_incompatibility_warning(Type *st, Type *dt, const char *fmt)
{
    char buf1[256], buf2[256];
    type_to_str(buf1, sizeof(buf1), st, NULL);
    type_to_str(buf2, sizeof(buf2), dt, NULL);
    warning(fmt, buf1, buf2);
}

static int combine_types(Type *dest, Val *op1, Val *op2, int op)
{
    Type *type1 = &op1->type, *type2 = &op2->type, type;
    int t1 = type1->t, t2 = type2->t, bt1 = t1 & TY_MASK, bt2 = t2 & TY_MASK;
    int ret = 1;

    type.t = TY_VOID;
    type.ref = NULL;

    if (bt1 == TY_VOID || bt2 == TY_VOID) {
        ret = op == '?' ? 1 : 0;
        type.t = TY_VOID;
    } else if (bt1 == TY_PTR || bt2 == TY_PTR) {
        if (op == '+')
            ;
        else if (is_null_pointer(op2))
            type = *type1;
        else if (is_null_pointer(op1))
            type = *type2;
        else if (bt1 != bt2) {
            if ((op == '?' || TOK_ISCOND_(op))
                && (is_integer_btype(bt1) || is_integer_btype(bt2)))
                warning("pointer/integer mismatch in %s",
                        op == '?' ? "conditional expression" : "comparison");
            else if (op != '-' || !is_integer_btype(bt2))
                ret = 0;
            type = *(bt1 == TY_PTR ? type1 : type2);
        } else {
            Type *pt1 = pointed_type(type1);
            Type *pt2 = pointed_type(type2);
            int pbt1 = pt1->t & TY_MASK;
            int pbt2 = pt2->t & TY_MASK;
            int newquals, copied = 0;
            if (pbt1 != TY_VOID && pbt2 != TY_VOID
                && !is_compatible_unqualified_types(pt1, pt2)) {
                if (op != '?' && !TOK_ISCOND_(op))
                    ret = 0;
                else
                    type_incompatibility_warning(type1, type2,
                        op == '?'
                        ? "pointer type mismatch in conditional expression ('%s' and '%s')"
                        : "comparison between distinct pointer types ('%s' and '%s')");
            }
            if (op == '?') {
                type = *((pbt1 == TY_VOID) ? type1 : type2);
                newquals = ((pt1->t | pt2->t) & (TQ_CONST | TQ_VOLATILE));
                if ((~pointed_type(&type)->t & (TQ_CONST | TQ_VOLATILE)) & newquals) {
                    type.ref = sym_push(SYM_FIELD, &type.ref->type, 0, type.ref->c);
                    copied = 1;
                    pointed_type(&type)->t |= newquals;
                }
                if (pt1->t & TQ_ARRAY
                    && pt2->t & TQ_ARRAY
                    && pointed_type(&type)->ref->c < 0
                    && (pt1->ref->c > 0 || pt2->ref->c > 0)) {
                    if (!copied)
                        type.ref = sym_push(SYM_FIELD, &type.ref->type, 0, type.ref->c);
                    pointed_type(&type)->ref =
                        sym_push(SYM_FIELD, &pointed_type(&type)->ref->type, 0, pointed_type(&type)->ref->c);
                    pointed_type(&type)->ref->c = 0 < pt1->ref->c ? pt1->ref->c : pt2->ref->c;
                }
            }
        }
        if (TOK_ISCOND_(op))
            type.t = TY_I64 | TQ_LONG | TQ_UNSIGNED;
    } else if (bt1 == TY_STRUCT || bt2 == TY_STRUCT) {
        if (op != '?' || !is_compatible_unqualified_types(type1, type2))
            ret = 0;
        type = *type1;
    } else if (is_float(bt1) || is_float(bt2)) {
        if (bt1 == TY_F80 || bt2 == TY_F80) {
            type.t = TY_F80;
        } else if (bt1 == TY_F64 || bt2 == TY_F64) {
            type.t = TY_F64;
        } else {
            type.t = TY_F32;
        }
    } else if (bt1 == TY_I64 || bt2 == TY_I64) {
        type.t = TY_I64 | TQ_LONG;
        if (bt1 == TY_I64)
            type.t &= t1;
        if (bt2 == TY_I64)
            type.t &= t2;
        if ((t1 & (TY_MASK | TQ_UNSIGNED | TQ_BITFIELD)) == (TY_I64 | TQ_UNSIGNED) ||
            (t2 & (TY_MASK | TQ_UNSIGNED | TQ_BITFIELD)) == (TY_I64 | TQ_UNSIGNED))
            type.t |= TQ_UNSIGNED;
    } else {
        type.t = TY_I32 | (TQ_LONG & (t1 | t2));
        if ((t1 & (TY_MASK | TQ_UNSIGNED | TQ_BITFIELD)) == (TY_I32 | TQ_UNSIGNED) ||
            (t2 & (TY_MASK | TQ_UNSIGNED | TQ_BITFIELD)) == (TY_I32 | TQ_UNSIGNED))
            type.t |= TQ_UNSIGNED;
    }
    if (dest)
        *dest = type;
    return ret;
}

int combine_types_pub(Type *dest, Val *op1, Val *op2, int op)
{
    return combine_types(dest, op1, op2, op);
}

void vpush_type_size(Type *type, int *a)
{
    if (type->t & TQ_VLA) {
        extern void vpush_vla_size(Type *type);
        vpush_vla_size(type);
        *a = type->ref->r;
    } else {
        int size = type_size(type, a);
        if (size < 0)
            error("unknown type size");
        vpushs(size);
    }
}

void gen_op(int op)
{
    int t1, t2, bt1, bt2, t;
    Type type1, combtype;

redo:
    t1 = vtop[-1].type.t;
    t2 = vtop[0].type.t;
    bt1 = t1 & TY_MASK;
    bt2 = t2 & TY_MASK;

    if (bt1 == TY_FUNC || bt2 == TY_FUNC) {
        if (bt2 == TY_FUNC) {
            mk_pointer(&vtop->type);
            gaddrof();
        }
        if (bt1 == TY_FUNC) {
            vswap();
            mk_pointer(&vtop->type);
            gaddrof();
            vswap();
        }
        goto redo;
    } else if (!combine_types(&combtype, vtop - 1, vtop, op)) {
    op_err:
        error_noabort("invalid operand types for binary operation");
        vpop();
    } else if (bt1 == TY_PTR || bt2 == TY_PTR) {
        int align;
        if (TOK_ISCOND_(op))
            goto std_op;
        if (bt1 == TY_PTR && bt2 == TY_PTR) {
            if (op != '-')
                goto op_err;
            vpush_type_size(pointed_type(&vtop[-1].type), &align);
            vtop->type.t &= ~TQ_UNSIGNED;
            vrott(3);
            gen_opic(op);
            vtop->type.t = TY_I64 | TQ_LONG;
            vswap();
            gen_op(OP_PDIV);
        } else {
            if (op != '-' && op != '+')
                goto op_err;
            if (bt2 == TY_PTR) {
                vswap();
                t = t1, t1 = t2, t2 = t;
                bt2 = bt1;
            }
            type1 = vtop[-1].type;
            vpush_type_size(pointed_type(&vtop[-1].type), &align);
            gen_op('*');
            gen_opic(op);
            type1.t &= ~(TQ_ARRAY | TQ_VLA);
            vtop->type = type1;
        }
    } else {
        if (is_float(combtype.t)
            && op != '+' && op != '-' && op != '*' && op != '/'
            && !TOK_ISCOND_(op))
            goto op_err;
    std_op:
        t = t2 = combtype.t;
        if (op == OP_SHR || op == T_SAR || op == T_SHL)
            t2 = TY_I32;
        if (t & TQ_UNSIGNED) {
            if (op == T_SAR)
                op = OP_SHR;
            else if (op == '/')
                op = OP_UDIV;
            else if (op == '%')
                op = OP_UMOD;
            else if (op == T_LT)
                op = T_ULT;
            else if (op == T_GT)
                op = T_UGT;
            else if (op == T_LE)
                op = T_ULE;
            else if (op == T_GE)
                op = T_UGE;
        }
        vswap();
        gen_cast_s(t);
        vswap();
        gen_cast_s(t2);
        if (is_float(t))
            gen_opif(op);
        else
            gen_opic(op);
        if (TOK_ISCOND_(op)) {
            vtop->type.t = TY_I32;
        } else {
            vtop->type.t = t;
        }
    }
    if (vtop->r & VF_LVAL)
        gv(is_float(vtop->type.t & TY_MASK) ? RC_FLOAT : RC_INT);
}

/* ------------------------------------------------------------ casts */
static void cast_error(Type *st, Type *dt)
{
    char buf1[256], buf2[256];
    type_to_str(buf1, sizeof(buf1), st, NULL);
    type_to_str(buf2, sizeof(buf2), dt, NULL);
    error("cannot convert '%s' to '%s'", buf1, buf2);
}

#define MUSTCAST_GET(r) (((r) >> 10) & 3)

static void force_charshort_cast(void)
{
    int sbt = MUSTCAST_GET(vtop->r) == 2 ? TY_I64 : TY_I32;
    int dbt = vtop->type.t;
    vtop->r &= ~VF_MUSTCAST;
    vtop->type.t = sbt;
    gen_cast_s(dbt == TY_BOOL ? TY_I8 | TQ_UNSIGNED : dbt);
    vtop->type.t = dbt;
}

static void gen_test_zero(int op)
{
    if (vtop->r == VL_CMP) {
        Val *v = vtop;
        if (op == T_EQ) {
            if (v->cmp_op > 1)
                v->cmp_op ^= 1;
            else
                v->cmp_op = !v->cmp_op;
            int x = v->jtrue; v->jtrue = v->jfalse; v->jfalse = x;
        }
    } else {
        vpushi(0);
        gen_op(op);
    }
}

void gen_cast_s(int t)
{
    Type type;
    type.t = t;
    type.ref = NULL;
    gen_cast(&type);
}

void gen_cast(Type *type)
{
    int sbt, dbt, sf, df, c;
    int dbt_bt, sbt_bt, ds, ss, bits, trunc;

    if (vtop->r & VF_MUSTCAST)
        force_charshort_cast();

    if (vtop->type.t & TQ_BITFIELD)
        gv(RC_INT);

    if (IS_ENUM(type->t) && type->ref->c < 0)
        error("cast to incomplete type");

    dbt = type->t & (TY_MASK | TQ_UNSIGNED);
    sbt = vtop->type.t & (TY_MASK | TQ_UNSIGNED);
    if (sbt == TY_FUNC)
        sbt = TY_PTR;

again:
    if (sbt != dbt) {
        sf = is_float(sbt);
        df = is_float(dbt);
        dbt_bt = dbt & TY_MASK;
        sbt_bt = sbt & TY_MASK;
        if (dbt_bt == TY_VOID)
            goto done;
        if (sbt_bt == TY_VOID) {
        err:
            cast_error(&vtop->type, type);
        }

        c = (vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST;
        if (c) {
            if (sbt == TY_F32)
                vtop->c.ld = vtop->c.f;
            else if (sbt == TY_F64)
                vtop->c.ld = vtop->c.d;

            if (df) {
                if (sbt_bt == TY_I64) {
                    if ((sbt & TQ_UNSIGNED) || !(vtop->c.i >> 63))
                        vtop->c.ld = vtop->c.i;
                    else
                        vtop->c.ld = -(long double)-vtop->c.i;
                } else if (!sf) {
                    if ((sbt & TQ_UNSIGNED) || !(vtop->c.i >> 31))
                        vtop->c.ld = (uint32_t)vtop->c.i;
                    else
                        vtop->c.ld = -(long double)-(uint32_t)vtop->c.i;
                }
                if (dbt == TY_F32)
                    vtop->c.f = (float)vtop->c.ld;
                else if (dbt == TY_F64)
                    vtop->c.d = (double)vtop->c.ld;
            } else if (sf && dbt == TY_BOOL) {
                vtop->c.i = (vtop->c.ld != 0);
            } else {
                if (sf) {
                    long double v = vtop->c.ld;
                    if (dbt & TQ_UNSIGNED && dbt_bt == TY_I64) {
                        if (v >= 9223372036854775808.0L)
                            vtop->c.i = (uint64_t)(int64_t)(v - 9223372036854775808.0L) + (1ULL << 63);
                        else
                            vtop->c.i = (int64_t)v;
                    } else
                        vtop->c.i = (int64_t)v;
                } else if (sbt_bt == TY_I64 || sbt == TY_PTR)
                    ;
                else if (sbt & TQ_UNSIGNED)
                    vtop->c.i = (uint32_t)vtop->c.i;
                else
                    vtop->c.i = ((uint32_t)vtop->c.i | -(vtop->c.i & 0x80000000));

                if (dbt_bt == TY_I64 || dbt == TY_PTR)
                    ;
                else if (dbt == TY_BOOL)
                    vtop->c.i = (vtop->c.i != 0);
                else {
                    uint32_t m = dbt_bt == TY_I8 ? 0xff :
                                 dbt_bt == TY_I16 ? 0xffff :
                                 0xffffffff;
                    vtop->c.i &= m;
                    if (!(dbt & TQ_UNSIGNED))
                        vtop->c.i |= -(vtop->c.i & ((m >> 1) + 1));
                }
            }
            goto done;
        } else if (dbt == TY_BOOL
                   && (vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == (VL_CONST | VF_SYM)) {
            vtop->r = VL_CONST;
            vtop->c.i = 1;
            goto done;
        }

        if (STATIC_DATA_WANTED)
            goto done;

        if (dbt == TY_BOOL) {
            gen_test_zero(T_NE);
            goto done;
        }

        if (sf || df) {
            if (sf && df) {
                gen_cvt_ftof(dbt);
            } else if (df) {
                gen_cvt_itof(dbt);
            } else {
                sbt = dbt;
                if (dbt_bt != TY_I64 && dbt_bt != TY_I32)
                    sbt = TY_I32;
                gen_cvt_ftoi(sbt);
                goto again;
            }
            goto done;
        }

        ds = btype_size(dbt_bt);
        ss = btype_size(sbt_bt);
        if (ds == 0 || ss == 0)
            goto err;

        if (IS_ENUM(type->t) && type->ref->c < 0)
            error("cast to incomplete type");

        if (ds == ss && ds >= 4)
            goto done;
        if (dbt_bt == TY_PTR || sbt_bt == TY_PTR) {
            warning("cast between pointer and integer of different size");
            if (sbt_bt == TY_PTR) {
                vtop->type.t = TY_I64;
            }
        }

        if (vtop->r & VF_LVAL) {
            if (ds <= ss)
                goto done;
            if (ds <= 4 && !(dbt == (TY_I16 | TQ_UNSIGNED) && sbt == TY_I8)) {
                gv(RC_INT);
                goto done;
            }
        }
        gv(RC_INT);

        trunc = 0;
        if (ds == 8) {
            if (sbt & TQ_UNSIGNED) {
                goto done;
            } else {
                gen_cvt_sxtw();
                goto done;
            }
        } else if (ss == 8) {
            trunc = 32;
        } else {
            ss = 4;
        }

        if (ds >= ss)
            goto done;
        if (ss == 4) {
            gen_cvt_csti(dbt);
            goto done;
        }
        bits = (ss - ds) * 8;
        vtop->type.t = (ss == 8 ? TY_I64 : TY_I32) | (dbt & TQ_UNSIGNED);
        vpushi(bits);
        gen_op(T_SHL);
        vpushi(bits - trunc);
        gen_op(T_SAR);
        vpushi(trunc);
        gen_op(OP_SHR);
    }
done:
    vtop->type = *type;
    vtop->type.t &= ~(TQ_CONST | TQ_VOLATILE | TQ_ARRAY);
}

/* ------------------------------------------------------------ assignment */
void verify_assign_cast(Type *dt)
{
    Type *st, *type1, *type2;
    int dbt, sbt, qualwarn, lvl;

    st = &vtop->type;
    dbt = dt->t & TY_MASK;
    sbt = st->t & TY_MASK;
    if (dt->t & TQ_CONST)
        warning("assignment of read-only location");
    switch (dbt) {
    case TY_VOID:
        if (sbt != dbt)
            error("assignment to void expression");
        break;
    case TY_PTR:
        if (is_null_pointer(vtop))
            break;
        if (is_integer_btype(sbt)) {
            warning("assignment makes pointer from integer without a cast");
            break;
        }
        type1 = pointed_type(dt);
        if (sbt == TY_PTR)
            type2 = pointed_type(st);
        else if (sbt == TY_FUNC)
            type2 = st;
        else
            goto err;
        if (is_compatible_types(type1, type2))
            break;
        for (qualwarn = lvl = 0;; ++lvl) {
            if (((type2->t & TQ_CONST) && !(type1->t & TQ_CONST)) ||
                ((type2->t & TQ_VOLATILE) && !(type1->t & TQ_VOLATILE)))
                qualwarn = 1;
            dbt = type1->t & (TY_MASK | TQ_LONG);
            sbt = type2->t & (TY_MASK | TQ_LONG);
            if (dbt != TY_PTR || sbt != TY_PTR)
                break;
            type1 = pointed_type(type1);
            type2 = pointed_type(type2);
        }
        if (!is_compatible_unqualified_types(type1, type2)) {
            if ((dbt == TY_VOID || sbt == TY_VOID) && lvl == 0) {
            } else if (dbt == sbt
                       && is_integer_btype(sbt & TY_MASK)
                       && IS_ENUM(type1->t) + IS_ENUM(type2->t)
                       + !!((type1->t ^ type2->t) & TQ_UNSIGNED) < 2) {
            } else {
                warning("assignment from incompatible pointer type");
                break;
            }
        }
        if (qualwarn)
            warning_opt(WOPT_DISCARDED, "assignment discards qualifiers from pointer target type");
        break;
    case TY_I8:
    case TY_I16:
    case TY_I32:
    case TY_I64:
        if (sbt == TY_PTR || sbt == TY_FUNC) {
            warning("assignment makes integer from pointer without a cast");
        } else if (sbt == TY_STRUCT) {
            goto case_struct;
        }
        break;
    case TY_STRUCT:
    case_struct:
        if (!is_compatible_unqualified_types(dt, st)) {
        err:
            cast_error(st, dt);
        }
        break;
    }
}

void gen_assign_cast(Type *dt)
{
    verify_assign_cast(dt);
    gen_cast(dt);
}

void test_lvalue(void)
{
    if (!(vtop->r & VF_LVAL))
        expect("lvalue");
}

void indir(void)
{
    if ((vtop->type.t & TY_MASK) != TY_PTR) {
        if ((vtop->type.t & TY_MASK) == TY_FUNC)
            return;
        expect("pointer");
    }
    if (vtop->r & VF_LVAL)
        gv(RC_INT);
    vtop->type = *pointed_type(&vtop->type);
    if (!(vtop->type.t & (TQ_ARRAY | TQ_VLA))
        && (vtop->type.t & TY_MASK) != TY_FUNC) {
        vtop->r |= VF_LVAL;
    }
}

/* ------------------------------------------------------------ bitfields */
static int adjust_bf(Val *sv, int bit_pos, int bit_size)
{
    int t;
    if (0 == sv->type.ref)
        return 0;
    t = sv->type.ref->auxtype_;
    if (t != -1 && t != TY_STRUCT) {
        sv->type.t = (sv->type.t & ~(TY_MASK | TQ_LONG)) | t;
        sv->r |= VF_LVAL;
    }
    return t;
}

static void incr_offset(int offset)
{
    int t = vtop->type.t;
    gaddrof();
    vtop->type.t = TY_PTR;
    vpushs(offset);
    gen_op('+');
    vtop->r |= VF_LVAL;
    vtop->type.t = t;
}

static void incr_bf_adr(int o_)
{
    vtop->type.t = TY_I8 | TQ_UNSIGNED;
    incr_offset(o_);
}

static void load_packed_bf(Type *type, int bit_pos, int bit_size)
{
    int n, o_, bits;
    save_reg_upstack(vtop->r, 1);
    vpush64(type->t & TY_MASK, 0);
    bits = 0, o_ = bit_pos >> 3, bit_pos &= 7;
    do {
        vswap();
        incr_bf_adr(o_);
        vdup();
        n = 8 - bit_pos;
        if (n > bit_size)
            n = bit_size;
        if (bit_pos)
            vpushi(bit_pos), gen_op(OP_SHR), bit_pos = 0;
        if (n < 8)
            vpushi((1 << n) - 1), gen_op('&');
        gen_cast(type);
        if (bits)
            vpushi(bits), gen_op(T_SHL);
