            gen_modrm64(op64, r, v->r, v->sym, fc);
        } else if (fr != r) {
            orex(1, fr, r, op64);
            o(0xc0 + fr + r * 8);
        }
    } else {
        if (fr == VL_CONST || fr == VL_LOCAL || (v->r & VF_LVAL)) {
            gen_modrm(r, v->r, v->sym, fc);
        } else if (fr != r) {
            o(0xc0 + fr + r * 8);
        }
    }
}

static void gcall_or_jmp(int is_jmp)
{
    int r;
    if ((vtop->r & (VL_MASK | VF_LVAL)) == VL_CONST &&
        ((vtop->r & VF_SYM) && (long long)(vtop->c.i - 4) == (int)(vtop->c.i - 4))) {
        greloca(cur_text_section, vtop->sym, ind + 1, R_X86_64_PLT32, (int)(vtop->c.i - 4));
        oad(0xe8 + is_jmp, 0);
    } else {
        r = R_R11;
        load(r, vtop);
        o(0x41);
        o(0xff);
        o(0xd0 + REG_VALUE(r) + (is_jmp << 4));
    }
}

static const uint8_t arg_regs[] = { R_RDI, R_RSI, R_RDX, R_RCX, R_R8, R_R9 };
#define REGN 6

typedef enum X86_64_Mode {
    mode_none, mode_memory, mode_integer, mode_sse, mode_x87
} X86_64_Mode;

static X86_64_Mode classify_merge(X86_64_Mode a, X86_64_Mode b)
{
    if (a == b) return a;
    else if (a == mode_none) return b;
    else if (b == mode_none) return a;
    else if (a == mode_memory || b == mode_memory) return mode_memory;
    else if (a == mode_integer || b == mode_integer) return mode_integer;
    else if (a == mode_x87 || b == mode_x87) return mode_memory;
    else return mode_sse;
}

static X86_64_Mode classify_inner(Type *ty)
{
    X86_64_Mode mode;
    Sym *f;
    switch (ty->t & TY_MASK) {
    case TY_VOID: return mode_none;
    case TY_I32: case TY_I8: case TY_I16: case TY_I64: case TY_BOOL:
    case TY_PTR: case TY_FUNC:
        return mode_integer;
    case TY_F32: case TY_F64: return mode_sse;
    case TY_F80: return mode_x87;
    case TY_STRUCT:
        f = ty->ref;
        mode = mode_none;
        for (f = f->next; f; f = f->next)
            mode = classify_merge(mode, classify_inner(&f->type));
        return mode;
    }
    return mode_none;
}

static X86_64_Mode classify_arg(Type *ty, Type *ret, int *psize, int *palign, int *reg_count)
{
    X86_64_Mode mode;
    int size, align, ret_t = 0;

    if (ty->t & (TQ_BITFIELD | TQ_ARRAY)) {
        *psize = 8;
        *palign = 8;
        *reg_count = 1;
        ret_t = ty->t;
        mode = mode_integer;
    } else {
        size = type_size(ty, &align);
        *psize = (size + 7) & ~7;
        *palign = (align + 7) & ~7;
        *reg_count = 0;
        if (size > 16) {
            mode = mode_memory;
        } else {
            mode = classify_inner(ty);
            switch (mode) {
            case mode_integer:
                if (size > 8) {
                    *reg_count = 2;
                    ret_t = TY_I128;
                } else {
                    *reg_count = 1;
                    if (size > 4)
                        ret_t = TY_I64;
                    else if (size > 2)
                        ret_t = TY_I32;
                    else if (size > 1)
                        ret_t = TY_I16;
                    else
                        ret_t = TY_I8;
                    if ((ty->t & TY_MASK) == TY_STRUCT || (ty->t & TQ_UNSIGNED))
                        ret_t |= TQ_UNSIGNED;
                }
                break;
            case mode_x87:
                *reg_count = 1;
                ret_t = TY_F80;
                break;
            case mode_sse:
                if (size > 8) {
                    *reg_count = 2;
                    ret_t = TY_F128;
                } else {
                    *reg_count = 1;
                    ret_t = (size > 4) ? TY_F64 : TY_F32;
                }
                break;
            default:
                break;
            }
        }
    }
    if (ret) {
        ret->ref = NULL;
        ret->t = ret_t;
    }
    return mode;
}

int classify_x86_64_va_arg(Type *ty)
{
    enum { __va_gen_reg, __va_float_reg, __va_stack };
    int size, align, reg_count;
    X86_64_Mode mode = classify_arg(ty, NULL, &size, &align, &reg_count);
    switch (mode) {
    default: return __va_stack;
    case mode_integer: return __va_gen_reg;
    case mode_sse: return __va_float_reg;
    }
}

int gfunc_sret(Type *vt, int variadic, Type *ret, int *ret_align, int *regsize)
{
    int size, align, reg_count;
    (void)variadic;
    if (classify_arg(vt, ret, &size, &align, &reg_count) == mode_memory)
        return 0;
    *ret_align = 1;
    *regsize = 8;
    return reg_count;
}

static int arg_prepare_reg(int idx)
{
    if (idx == 2 || idx == 3)
        return idx + 8;
    else
        return arg_regs[idx];
}

static void gadd_sp(int val)
{
    if (val == (char)val) {
        o(0xc48348);
        g(val);
    } else {
        oad(0xc48148, val);
    }
}

void gfunc_call(int nb_args)
{
    X86_64_Mode mode;
    Type type;
    int size, align, r, args_size, stack_adjust, i, reg_count, k;
    int nb_reg_args = 0;
    int nb_sse_args = 0;
    int sse_reg, gen_reg;
    char *onstack = xmalloc((nb_args + 1) * sizeof(char));

    stack_adjust = 0;
    for (i = nb_args - 1; i >= 0; i--) {
        mode = classify_arg(&vtop[-i].type, NULL, &size, &align, &reg_count);
        if (size == 0) continue;
        if (mode == mode_sse && nb_sse_args + reg_count <= 8) {
            nb_sse_args += reg_count;
            onstack[i] = 0;
        } else if (mode == mode_integer && nb_reg_args + reg_count <= REGN) {
            nb_reg_args += reg_count;
            onstack[i] = 0;
        } else if (mode == mode_none) {
            onstack[i] = 0;
        } else {
            if (align == 16 && (stack_adjust &= 15)) {
                onstack[i] = 2;
                stack_adjust = 0;
            } else
                onstack[i] = 1;
            stack_adjust += size;
        }
    }

    if (nb_sse_args && opt.nosse)
        error("SSE disabled but floating point arguments passed");

    if ((vtop->r & VL_MASK) == VL_CMP)
        gv(RC_INT);

    gen_reg = nb_reg_args;
    sse_reg = nb_sse_args;
    args_size = 0;
    stack_adjust &= 15;
    for (i = k = 0; i < nb_args;) {
        mode = classify_arg(&vtop[-i].type, NULL, &size, &align, &reg_count);
        if (size) {
            if (!onstack[i + k]) {
                ++i;
                continue;
            }
            if (stack_adjust) {
                o(0x50);
                args_size += 8;
                stack_adjust = 0;
            }
            if (onstack[i + k] == 2)
                stack_adjust = 1;
        }

        vrotb(i + 1);

        switch (vtop->type.t & TY_MASK) {
        case TY_STRUCT:
            o(0x48);
            oad(0xec81, size);
            r = get_reg(RC_INT);
            orex(1, r, 0, 0x89);
            o(0xe0 + REG_VALUE(r));
            vset(&vtop->type, r | VF_LVAL, 0);
            vswap();
            o(0x10ec8348);
            o(0xf0e48348);
            orex(0, r, 0, 0x50 + REG_VALUE(r));
            o(0x08ec8348);
            vstore();
            o(0x08c48348);
            o(0x5c);
            break;
        case TY_F80:
            gv(RC_ST0);
            oad(0xec8148, size);
            o(0x7cdb);
            g(0x24);
            g(0x00);
            break;
        case TY_F32:
        case TY_F64:
            r = gv(RC_FLOAT);
            o(0x50);
            o(0xd60f66);
            o(0x04 + REG_VALUE(r) * 8);
            o(0x24);
            break;
        default:
            r = gv(RC_INT);
            orex(0, r, 0, 0x50 + REG_VALUE(r));
            break;
        }
        args_size += size;

        vpop();
        --nb_args;
        k++;
    }

    free(onstack);

    save_regs(0);

    for (i = 0; i < nb_args; i++) {
        mode = classify_arg(&vtop->type, &type, &size, &align, &reg_count);
        if (size == 0) continue;
        vtop->type = type;
        if (mode == mode_sse) {
            if (reg_count == 2) {
                sse_reg -= 2;
                gv(RC_FRET);
                if (sse_reg) {
                    o(0x280f);
                    o(0xc1 + ((sse_reg + 1) << 3));
                    o(0x280f);
                    o(0xc0 + (sse_reg << 3));
                }
            } else {
                --sse_reg;
                gv(RC_XMM0 << sse_reg);
            }
        } else if (mode == mode_integer) {
            int d;
            gen_reg -= reg_count;
            r = gv(RC_INT);
            d = arg_prepare_reg(gen_reg);
            orex(1, d, r, 0x89);
            o(0xc0 + REG_VALUE(r) * 8 + REG_VALUE(d));
            if (reg_count == 2) {
                d = arg_prepare_reg(gen_reg + 1);
                orex(1, d, vtop->r2, 0x89);
                o(0xc0 + REG_VALUE(vtop->r2) * 8 + REG_VALUE(d));
            }
        }
        vtop--;
    }

    save_regs(0);

    if (nb_reg_args > 2) {
        o(0xd2894c);
        if (nb_reg_args > 3) {
            o(0xd9894c);
        }
    }

    if (vtop->type.ref->functype != FUNC_NEW)
        oad(0xb8, nb_sse_args < 8 ? nb_sse_args : 8);
    gcall_or_jmp(0);
    if (args_size)
        gadd_sp(args_size);
    vtop--;
}

static void push_arg_reg(int i)
{
    loc -= 8;
    gen_modrm64(0x89, arg_regs[i], VL_LOCAL, NULL, loc);
}

void gfunc_prolog(Sym *func_sym)
{
    Type *func_type = &func_sym->type;
    X86_64_Mode mode, ret_mode;
    int i, addr, align, size, reg_count;
    int param_addr = 0, reg_param_index, sse_param_index;
    Sym *sym;
    Type *type;

    sym = func_type->ref;
    addr = PTR_SIZE * 2;
    loc = 0;
    ind += FUNC_PROLOG_SIZE;
    func_sub_sp_offset = ind;
    func_ret_sub = 0;
    ret_mode = classify_arg(&sym->type, NULL, &size, &align, &reg_count);

    if (func_var) {
        int seen_reg_num, seen_sse_num, seen_stack_size;
        seen_reg_num = ret_mode == mode_memory;
        seen_sse_num = 0;
        seen_stack_size = PTR_SIZE * 2;
        sym = func_type->ref;
        while ((sym = sym->next) != NULL) {
            type = &sym->type;
            mode = classify_arg(type, NULL, &size, &align, &reg_count);
            switch (mode) {
            default:
            stack_arg:
                seen_stack_size = ((seen_stack_size + align - 1) & -align) + size;
                break;
            case mode_integer:
                if (seen_reg_num + reg_count > REGN)
                    goto stack_arg;
                seen_reg_num += reg_count;
                break;
            case mode_sse:
                if (seen_sse_num + reg_count > 8)
                    goto stack_arg;
                seen_sse_num += reg_count;
                break;
            }
        }

        loc -= 24;
        o(0xe845c7);
        gen_le32(seen_reg_num * 8);
        o(0xec45c7);
        gen_le32(seen_sse_num * 16 + 48);
        o(0x9d8d4c);
        gen_le32(seen_stack_size);
        o(0xf05d894c);
        o(0x9d8d4c);
        gen_le32(-176 - 24);
        o(0xf85d894c);

        for (i = 0; i < 8; i++) {
            loc -= 16;
            if (!opt.nosse) {
                o(0xd60f66);
                gen_modrm(7 - i, VL_LOCAL, NULL, loc);
            }
            o(0x85c748);
            gen_le32(loc + 8);
            gen_le32(0);
        }
        for (i = 0; i < REGN; i++) {
            push_arg_reg(REGN - 1 - i);
        }
    }

    sym = func_type->ref;
    reg_param_index = 0;
    sse_param_index = 0;

    if (ret_mode == mode_memory) {
        push_arg_reg(reg_param_index);
        func_vc = loc;
        reg_param_index++;
    }
    while ((sym = sym->next) != NULL) {
        type = &sym->type;
        mode = classify_arg(type, NULL, &size, &align, &reg_count);
        switch (mode) {
        case mode_sse:
            if (opt.nosse)
                error("SSE disabled but floating point arguments used");
            if (sse_param_index + reg_count <= 8) {
                loc -= reg_count * 8;
                param_addr = loc;
                for (i = 0; i < reg_count; ++i) {
                    o(0xd60f66);
                    gen_modrm(sse_param_index, VL_LOCAL, NULL, param_addr + i * 8);
                    ++sse_param_index;
                }
            } else {
                addr = (addr + align - 1) & -align;
                param_addr = addr;
                addr += size;
            }
            break;
        case mode_memory:
        case mode_x87:
            addr = (addr + align - 1) & -align;
            param_addr = addr;
            addr += size;
            break;
        case mode_integer: {
            if (reg_param_index + reg_count <= REGN) {
                loc -= reg_count * 8;
                param_addr = loc;
                for (i = 0; i < reg_count; ++i) {
                    gen_modrm64(0x89, arg_regs[reg_param_index], VL_LOCAL, NULL, param_addr + i * 8);
                    ++reg_param_index;
                }
            } else {
                addr = (addr + align - 1) & -align;
                param_addr = addr;
                addr += size;
            }
            break;
        }
        default:
            break;
        }
        sym_push(sym->v & ~SYM_FIELD, type, VL_LOCAL | VF_LVAL, param_addr);
    }
}

void gfunc_epilog(void)
{
    int v, saved_ind;
    o(0xc9);
    if (func_ret_sub == 0) {
        o(0xc3);
    } else {
        o(0xc2);
        g(func_ret_sub);
        g(func_ret_sub >> 8);
    }
    v = (-loc + 15) & -16;
    saved_ind = ind;
    ind = func_sub_sp_offset - FUNC_PROLOG_SIZE;
    o(0xe5894855);
    o(0xec8148);
    gen_le32(v);
    ind = saved_ind;
}

void gen_fill_nops(int bytes)
{
    while (bytes--)
        g(0x90);
}

int gjmp(int t)
{
    return oad(0xe9, t);
}

void gjmp_addr(int a)
{
    int r;
    r = a - ind - 2;
    if (r == (char)r) {
        g(0xeb);
        g(r);
    } else {
        oad(0xe9, a - ind - 5);
    }
}

int gjmp_append(int n, int t)
{
    void *p;
    if (n) {
        uint32_t n1 = n, n2;
        while ((n2 = read32le(p = cur_text_section->data + n1)))
            n1 = n2;
        write32le(p, t);
        t = n;
    }
    return t;
}

int gjmp_cond(int op, int t)
{
    if (op & 0x100) {
        int v = vtop->cmp_r;
        op &= ~0x100;
        if (op ^ v ^ (v != T_NE))
            o(0x067a);
        else {
            g(0x0f);
            t = oad(0x8a, t);
        }
    }
    g(0x0f);
    t = oad(op - 16, t);
    return t;
}

void gjmp_cond_addr(int a, int op)
{
    int r = a - ind - 2;
    if (r == (char)r)
        g(op - 32), g(r);
    else
        g(0x0f), gjmp_addr_cond_(a, op);
}

void gen_opi(int op)
{
    int r, fr, opc, c;
    int ll, uu, cc;

    ll = is64_type(vtop[-1].type.t);
    uu = (vtop[-1].type.t & TQ_UNSIGNED) != 0;
    cc = (vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST;

    switch (op) {
    case '+':
    case OP_ADDC1:
        opc = 0;
    gen_op8:
        if (cc && (!ll || (int)vtop->c.i == (long long)vtop->c.i)) {
            vswap();
            r = gv(RC_INT);
            vswap();
            c = vtop->c.i;
            if (c == (char)c) {
                orex(ll, r, 0, 0x83);
                o(0xc0 | (opc << 3) | REG_VALUE(r));
                g(c);
            } else {
                orex(ll, r, 0, 0x81);
                oad(0xc0 | (opc << 3) | REG_VALUE(r), c);
            }
        } else {
            gv2(RC_INT, RC_INT);
            r = vtop[-1].r;
            fr = vtop[0].r;
            orex(ll, r, fr, (opc << 3) | 0x01);
            o(0xc0 + REG_VALUE(r) + REG_VALUE(fr) * 8);
        }
        vtop--;
        if (op >= T_ULT && op <= T_GT)
            vset_VT_CMP(op);
        break;
    case '-':
    case OP_SUBC1:
        opc = 5;
        goto gen_op8;
    case OP_ADDC2:
        opc = 2;
        goto gen_op8;
    case OP_SUBC2:
        opc = 3;
        goto gen_op8;
    case '&':
        opc = 4;
        goto gen_op8;
    case '^':
        opc = 6;
        goto gen_op8;
    case '|':
        opc = 1;
        goto gen_op8;
    case '*':
        gv2(RC_INT, RC_INT);
        r = vtop[-1].r;
        fr = vtop[0].r;
        orex(ll, fr, r, 0xaf0f);
        o(0xc0 + REG_VALUE(fr) + REG_VALUE(r) * 8);
        vtop--;
        break;
    case T_SHL:
        opc = 4;
        goto gen_shift;
    case OP_SHR:
        opc = 5;
        goto gen_shift;
    case T_SAR:
        opc = 7;
    gen_shift:
        opc = 0xc0 | (opc << 3);
        if (cc) {
            vswap();
            r = gv(RC_INT);
            vswap();
            orex(ll, r, 0, 0xc1);
            o(opc | REG_VALUE(r));
            g(vtop->c.i & (ll ? 63 : 31));
        } else {
            gv2(RC_INT, RC_RCX);
            r = vtop[-1].r;
            orex(ll, r, 0, 0xd3);
            o(opc | REG_VALUE(r));
        }
        vtop--;
        break;
    case OP_UDIV:
    case OP_UMOD:
        uu = 1;
        goto divmod;
    case '/':
    case '%':
    case OP_PDIV:
        uu = 0;
    divmod:
        gv2(RC_RAX, RC_RCX);
        r = vtop[-1].r;
        fr = vtop[0].r;
        vtop--;
        save_reg(R_RDX);
        orex(ll, 0, 0, uu ? 0xd231 : 0x99);
        orex(ll, fr, 0, 0xf7);
        o((uu ? 0xf0 : 0xf8) + REG_VALUE(fr));
        if (op == '%' || op == OP_UMOD)
            r = R_RDX;
        else
            r = R_RAX;
        vtop->r = r;
        break;
    default:
        opc = 7;
        goto gen_op8;
    }
}

void gen_opf(int op)
{
    int a, ft, fc, swapped, r;
    int bt = vtop->type.t & TY_MASK;
    int float_type = bt == TY_F80 ? RC_ST0 : RC_FLOAT;

    if (op == T_NEG) {
        gv(float_type);
        if (float_type == RC_ST0) {
            o(0xe0d9);
        } else {
            int size, align;
            size = type_size(&vtop->type, &align);
            save_reg(vtop->r);
            /* xorb $0x80, (size-1)(lval) */
            o(0x80);
            gen_modrm(6, vtop->r, vtop->sym, vtop->c.i + size - 1);
            g(0x80);
        }
        return;
    }

    if ((vtop[-1].r & (VL_MASK | VF_LVAL)) == VL_CONST) {
        vswap();
        gv(float_type);
        vswap();
    }
    if ((vtop[0].r & (VL_MASK | VF_LVAL)) == VL_CONST)
        gv(float_type);

    if ((vtop[-1].r & VF_LVAL) && (vtop[0].r & VF_LVAL)) {
        vswap();
        gv(float_type);
        vswap();
    }
    swapped = 0;
    if (vtop[-1].r & VF_LVAL) {
        vswap();
        swapped = 1;
    }
    if ((vtop->type.t & TY_MASK) == TY_F80) {
        if (op >= T_ULT && op <= T_GT) {
            load(R_ST0, vtop);
            save_reg(R_RAX);
            if (op == T_GE || op == T_GT)
                swapped = !swapped;
            else if (op == T_EQ || op == T_NE)
                swapped = 0;
            if (swapped)
                o(0xc9d9);
            if (op == T_EQ || op == T_NE)
                o(0xe9da);
            else
                o(0xd9de);
            o(0xe0df);
            if (op == T_EQ) {
                o(0x45e480);
                o(0x40fC80);
            } else if (op == T_NE) {
                o(0x45e480);
                o(0x40f480);
                op = T_NE;
            } else if (op == T_GE || op == T_LE) {
                o(0x05c4f6);
                op = T_EQ;
            } else {
                o(0x45c4f6);
                op = T_EQ;
            }
            vtop--;
            vset_VT_CMP(op);
        } else {
            load(R_ST0, vtop);
            swapped = !swapped;
            switch (op) {
            default:
            case '+':
                a = 0;
                break;
            case '-':
                a = 4;
                if (swapped)
                    a++;
                break;
            case '*':
                a = 1;
                break;
            case '/':
                a = 6;
                if (swapped)
                    a++;
                break;
            }
            ft = vtop->type.t;
            fc = vtop->c.i;
            o(0xde);
            o(0xc1 + (a << 3));
            vtop--;
        }
    } else {
        if (op >= T_ULT && op <= T_GT) {
            r = vtop->r;
            fc = vtop->c.i;
            if ((r & VL_MASK) == VL_LLOCAL) {
                Val v1;
                r = get_reg(RC_INT);
                v1.type.t = TY_PTR;
                v1.r = VL_LOCAL | VF_LVAL;
                v1.c.i = fc;
                load(r, &v1);
                fc = 0;
