/* x86-64 code emitter */
#include "gen.h"

#define RC_RSI 0x20
#define RC_RDI 0x40

const int reg_classes[NB_REGS] = {
    RC_INT | RC_RAX,
    RC_INT | RC_RCX,
    RC_INT | RC_RDX,
    0,
    0,
    0,
    RC_RSI,
    RC_RDI,
    RC_R8,
    RC_R9,
    RC_R10,
    RC_R11,
    0, 0, 0, 0,
    RC_FLOAT | RC_XMM0,
    RC_FLOAT | RC_XMM1,
    RC_FLOAT | RC_XMM2,
    RC_FLOAT | RC_XMM3,
    RC_FLOAT | RC_XMM4,
    RC_FLOAT | RC_XMM5,
    RC_XMM6,
    RC_XMM7,
    RC_ST0
};

static unsigned long func_sub_sp_offset;
static int func_ret_sub;

#define REX_BASE(r) (((r) >> 3) & 1)
#define REG_VALUE(r) ((r) & 7)
#define FUNC_PROLOG_SIZE 11

void g(int c)
{
    int ind1;
    if (nocode_wanted)
        return;
    ind1 = ind + 1;
    if ((unsigned long)ind1 > cur_text_section->data_allocated)
        section_realloc(cur_text_section, ind1);
    cur_text_section->data[ind] = c;
    ind = ind1;
}

void o(unsigned int c)
{
    while (c) {
        g(c);
        c = c >> 8;
    }
}

void gen_le16(int v)
{
    g(v);
    g(v >> 8);
}

void gen_le32(int c)
{
    g(c);
    g(c >> 8);
    g(c >> 16);
    g(c >> 24);
}

void gen_le64(int64_t c)
{
    g(c);
    g(c >> 8);
    g(c >> 16);
    g(c >> 24);
    g(c >> 32);
    g(c >> 40);
    g(c >> 48);
    g(c >> 56);
}

void orex(int ll, int r, int r2, int b)
{
    if ((r & VL_MASK) >= VL_CONST)
        r = 0;
    if ((r2 & VL_MASK) >= VL_CONST)
        r2 = 0;
    if (ll || REX_BASE(r) || REX_BASE(r2))
        o(0x40 | REX_BASE(r) | (REX_BASE(r2) << 2) | (ll << 3));
    o(b);
}

void gsym_addr(int t, int a)
{
    while (t) {
        unsigned char *ptr = cur_text_section->data + t;
        uint32_t n = read32le(ptr);
        write32le(ptr, a < 0 ? -a : a - t - 4);
        t = n;
    }
}

int is64_type(int t)
{
    return ((t & TY_MASK) == TY_PTR ||
            (t & TY_MASK) == TY_FUNC ||
            (t & TY_MASK) == TY_I64);
}

static int oad(int c, int s)
{
    int t;
    if (nocode_wanted)
        return s;
    o(c);
    t = ind;
    gen_le32(s);
    return t;
}

void gen_addr32(int r, Sym *sym, int c)
{
    if (r & VF_SYM)
        greloca(cur_text_section, sym, ind, R_X86_64_32S, c), c = 0;
    gen_le32(c);
}

void gen_addr64(int r, Sym *sym, int64_t c)
{
    if (r & VF_SYM)
        greloca(cur_text_section, sym, ind, R_X86_64_64, c), c = 0;
    gen_le64(c);
}

static void gen_addrpc32(int r, Sym *sym, int c)
{
    if (r & VF_SYM)
        greloca(cur_text_section, sym, ind, R_X86_64_PC32, c - 4), c = 4;
    gen_le32(c - 4);
}

static void gen_gotpcrel(int r, Sym *sym, int c)
{
    greloca(cur_text_section, sym, ind, R_X86_64_GOTPCREL, -4);
    gen_le32(0);
    if (c) {
        orex(1, r, 0, 0x81);
        o(0xc0 + REG_VALUE(r));
        gen_le32(c);
    }
}

static void gen_modrm_impl(int op_reg, int r, Sym *sym, int c, int is_got)
{
    op_reg = REG_VALUE(op_reg) << 3;
    if ((r & VL_MASK) == VL_CONST) {
        if (!(r & VF_SYM)) {
            o(0x04 | op_reg);
            oad(0x25, c);
        } else {
            o(0x05 | op_reg);
            if (is_got) {
                gen_gotpcrel(r, sym, c);
            } else {
                gen_addrpc32(r, sym, c);
            }
        }
    } else if ((r & VL_MASK) == VL_LOCAL) {
        if (c == (char)c) {
            o(0x45 | op_reg);
            g(c);
        } else {
            oad(0x85 | op_reg, c);
        }
    } else if ((r & VL_MASK) >= R_MEM) {
        if (c) {
            g(0x80 | op_reg | REG_VALUE(r));
            gen_le32(c);
        } else {
            g(0x00 | op_reg | REG_VALUE(r));
        }
    } else {
        g(0x00 | op_reg | REG_VALUE(r));
    }
}

static void gen_modrm(int op_reg, int r, Sym *sym, int c)
{
    gen_modrm_impl(op_reg, r, sym, c, 0);
}

static void gen_modrm64(int opcode, int op_reg, int r, Sym *sym, int c)
{
    int is_got;
    is_got = (op_reg & R_MEM) && !(sym->type.t & SC_STATIC);
    orex(1, r, op_reg, opcode);
    gen_modrm_impl(op_reg, r, sym, c, is_got);
}

void load(int r, Val *sv)
{
    int v, t, ft, fc, fr;
    Val v1;

    fr = sv->r;
    ft = sv->type.t & ~TQ_DEFSIGN;
    fc = sv->c.i;
    if (fc != (long long)sv->c.i && (fr & VF_SYM))
        error("64 bit addend in load");

    ft &= ~(TQ_VOLATILE | TQ_CONST);

    if ((fr & VL_MASK) == VL_CONST && (fr & VF_SYM) &&
        (fr & VF_LVAL) && !(sv->sym->type.t & SC_STATIC)) {
        int tr = r | R_MEM;
        if (is_float(ft)) {
            tr = get_reg(RC_INT) | R_MEM;
        }
        gen_modrm64(0x8b, tr, fr, sv->sym, 0);
        fr = tr | VF_LVAL;
    }

    v = fr & VL_MASK;
    if (fr & VF_LVAL) {
        int b, ll;
        if (v == VL_LLOCAL) {
            v1.type.t = TY_PTR;
            v1.r = VL_LOCAL | VF_LVAL;
            v1.c.i = fc;
            fr = r;
            if (!(reg_classes[fr] & (RC_INT | RC_R11)))
                fr = get_reg(RC_INT);
            load(fr, &v1);
        }
        if (fc != (long long)sv->c.i) {
            v1.type.t = TY_I64;
            v1.r = VL_CONST;
            v1.c.i = sv->c.i;
            fr = r;
            if (!(reg_classes[fr] & (RC_INT | RC_R11)))
                fr = get_reg(RC_INT);
            load(fr, &v1);
            fc = 0;
        }
        ll = 0;
        if ((ft & TY_MASK) == TY_STRUCT) {
            int align;
            switch (type_size(&sv->type, &align)) {
            case 1: ft = TY_I8; break;
            case 2: ft = TY_I16; break;
            case 4: ft = TY_I32; break;
            case 8: ft = TY_I64; break;
            default:
                error("invalid aggregate type for register load");
                break;
            }
