        if ((ft & TY_MASK) == TY_F32) {
            b = 0x6e0f66;
            r = REG_VALUE(r);
        } else if ((ft & TY_MASK) == TY_F64) {
            b = 0x7e0ff3;
            r = REG_VALUE(r);
        } else if ((ft & TY_MASK) == TY_F80) {
            b = 0xdb, r = 5;
        } else if ((ft & TY_TYPEBITS) == TY_I8 || (ft & TY_TYPEBITS) == TY_BOOL) {
            b = 0xbe0f;
        } else if ((ft & TY_TYPEBITS) == (TY_I8 | TQ_UNSIGNED)) {
            b = 0xb60f;
        } else if ((ft & TY_TYPEBITS) == TY_I16) {
            b = 0xbf0f;
        } else if ((ft & TY_TYPEBITS) == (TY_I16 | TQ_UNSIGNED)) {
            b = 0xb70f;
        } else if ((ft & TY_TYPEBITS) == TY_VOID) {
            return;
        } else {
            ll = is64_type(ft);
            b = 0x8b;
        }
        if (ll) {
            gen_modrm64(b, r, fr, sv->sym, fc);
        } else {
            orex(ll, fr, r, b);
            gen_modrm(r, fr, sv->sym, fc);
        }
    } else {
        if (v == VL_CONST) {
            if (fr & VF_SYM) {
                if (sv->sym->type.t & SC_STATIC) {
                    orex(1, 0, r, 0x8d);
                    o(0x05 + REG_VALUE(r) * 8);
                    gen_addrpc32(fr, sv->sym, fc);
                } else {
                    orex(1, 0, r, 0x8b);
                    o(0x05 + REG_VALUE(r) * 8);
                    gen_gotpcrel(r, sv->sym, fc);
                }
            } else if (is64_type(ft)) {
                if (sv->c.i >> 32) {
                    orex(1, r, 0, 0xb8 + REG_VALUE(r));
                    gen_le64(sv->c.i);
                } else {
                    orex(0, r, 0, 0xb8 + REG_VALUE(r));
                    gen_le32(sv->c.i);
                }
            } else {
                orex(0, r, 0, 0xb8 + REG_VALUE(r));
                gen_le32(fc);
            }
        } else if (v == VL_LOCAL) {
            orex(1, 0, r, 0x8d);
            gen_modrm(r, VL_LOCAL, sv->sym, fc);
        } else if (v == VL_CMP) {
            if (fc & 0x100) {
                v = vtop->cmp_r;
                fc &= ~0x100;
                orex(0, r, 0, 0xb0 + REG_VALUE(r));
