                    o(0x100ff2);
                    o(0x44 + REG_VALUE(r) * 8);
                    o(0xf024);
                } else {
                    if ((ft & TY_MASK) == TY_F32) {
                        o(0x100ff3);
                    } else {
                        o(0x100ff2);
                    }
                    o(0xc0 + REG_VALUE(v) + REG_VALUE(r) * 8);
                }
            } else if (r == R_ST0) {
                o(0x110ff2);
                o(0x44 + REG_VALUE(r) * 8);
                o(0xf024);
                o(0xf02444dd);
            } else {
                orex(is64_type(ft), r, v, 0x89);
                o(0xc0 + REG_VALUE(r) + REG_VALUE(v) * 8);
            }
        }
    }
}

void store(int r, Val *v)
{
    int fr, bt, ft, fc;
    int op64 = 0;
    int pic = 0;

    fr = v->r & VL_MASK;
    ft = v->type.t;
    fc = v->c.i;
    if (fc != (long long)v->c.i && (fr & VF_SYM))
        error("64 bit addend in store");
    ft &= ~(TQ_VOLATILE | TQ_CONST);
    bt = ft & TY_MASK;

    if (fr == VL_CONST && (v->r & VF_SYM) && !(v->sym->type.t & SC_STATIC)) {
        o(0x1d8b4c);
        gen_gotpcrel(R_R11, v->sym, v->c.i);
        pic = is64_type(bt) ? 0x49 : 0x41;
    }

    if (bt == TY_F32) {
        o(0x66);
        o(pic);
        o(0x7e0f);
        r = REG_VALUE(r);
    } else if (bt == TY_F64) {
        o(0x66);
        o(pic);
        o(0xd60f);
        r = REG_VALUE(r);
    } else if (bt == TY_F80) {
        o(0xc0d9);
        o(pic);
        o(0xdb);
        r = 7;
