            !((vtop->r & VF_SYM) && vtop->sym->addrtaken);
        vtop--;
        vpushi(n);
        break;
    case KW_builtin_unreachable:
        parse_builtin_params(0, "");
        type.t = TY_VOID;
        vpush(&type);
        CODE_OFF();
        break;
    case KW_builtin_frame_address:
    case KW_builtin_return_address: {
        int tok1 = tok;
        long long level;
        next();
        skip('(');
        level = expr_const64();
        if (level < 0)
            error("%s only takes positive integers", tokname(tok1, 0));
        skip(')');
        type.t = TY_VOID;
        mk_pointer(&type);
        vset(&type, VL_LOCAL, 0);
        while (level--) {
            mk_pointer(&vtop->type);
            indir();
        }
        if (tok1 == KW_builtin_return_address) {
            vpushi(PTR_SIZE);
            gen_op('+');
            mk_pointer(&vtop->type);
            indir();
        }
        break;
    }
    case KW_builtin_va_arg_types:
        parse_builtin_params(0, "t");
        vpushi(classify_x86_64_va_arg(&vtop->type));
        vswap();
        vpop();
        break;
    case KW_atomic_store:
    case KW_atomic_load:
    case KW_atomic_exchange:
    case KW_atomic_compare_exchange:
    case KW_atomic_fetch_add:
    case KW_atomic_fetch_sub:
    case KW_atomic_fetch_or:
    case KW_atomic_fetch_xor:
    case KW_atomic_fetch_and:
    case KW_atomic_fetch_nand:
    case KW_atomic_add_fetch:
    case KW_atomic_sub_fetch:
    case KW_atomic_or_fetch:
    case KW_atomic_xor_fetch:
    case KW_atomic_and_fetch:
    case KW_atomic_nand_fetch:
        parse_atomic(tok);
        break;
    case T_INC:
    case T_DEC:
        t = tok;
        next();
        unary();
        inc(0, t);
        break;
    case '-':
        next();
        unary();
        if (is_float(vtop->type.t)) {
            gen_opif(T_NEG);
        } else {
            vpushi(0);
            vswap();
            gen_op('-');
        }
        break;
    case T_ANDAND:
        if (!opt.gnu_ext)
            goto tok_identifier;
        next();
        if (tok < KW_DEFINE)
            expect("label identifier");
        s = label_find(tok);
        if (!s) {
            s = label_push(&global_label_stack, tok, LABEL_FORWARD);
        } else {
            if (s->r == LABEL_DECLARED)
                s->r = LABEL_FORWARD;
        }
        if ((s->type.t & TY_MASK) != TY_PTR) {
            s->type.t = TY_VOID;
            mk_pointer(&s->type);
            s->type.t |= SC_STATIC;
        }
        vpushsym(&s->type, s);
        next();
        break;
    case KW_GENERIC: {
        Type controlling_type;
        int has_default = 0;
        int has_match = 0;
        int learn = 0;
        TokSeq *str = NULL;
        int saved_nocode_wanted = nocode_wanted;
        nocode_wanted &= ~CONST_WANTED_MASK;
        next();
        skip('(');
        expr_type(&controlling_type, expr_eq);
        convert_parameter_type(&controlling_type);
        nocode_wanted = saved_nocode_wanted;
        for (;;) {
            learn = 0;
            skip(',');
            if (tok == KW_DEFAULT) {
                if (has_default)
                    error("too many 'default'");
                has_default = 1;
                if (!has_match)
                    learn = 1;
                next();
            } else {
                Attr ad_tmp;
                int itmp;
                Type cur_type;
                parse_btype(&cur_type, &ad_tmp, 0);
                type_decl(&cur_type, &ad_tmp, &itmp, TYPE_ABSTRACT);
                if (is_compatible_types(&controlling_type, &cur_type)) {
                    if (has_match) {
                        error("type match twice");
                    }
                    has_match = 1;
                    learn = 1;
                }
            }
            skip(':');
            if (learn) {
                if (str)
                    tseq_free(str);
                skip_or_save_block(&str);
            } else {
                skip_or_save_block(NULL);
            }
            if (tok == ')')
                break;
        }
        if (!str) {
            char buf[60];
            type_to_str(buf, sizeof buf, &controlling_type, NULL);
            error("type '%s' does not match any association", buf);
        }
        push_reader(str, 1);
        next();
        expr_eq();
        if (tok != T_EOF)
            expect(",");
        pop_reader();
        next();
        break;
    }
    case KW___nan__:
        n = 0x7fc00000;
    special_math_val:
        vpushi(n);
        vtop->type.t = TY_F32;
        next();
        break;
    case KW___snan__:
        n = 0x7f800001;
        goto special_math_val;
    case KW___inf__:
        n = 0x7f800000;
        goto special_math_val;
    default:
    tok_identifier:
        if (tok < KW_DEFINE)
            error("expression expected before '%s'", tokname(tok, &tokc));
        t = tok;
        next();
        s = sym_find(t);
        if (!s || IS_ASM_SYM_(s)) {
            const char *name = tokname(t, NULL);
            if (tok != '(')
                error("'%s' undeclared", name);
            warning_opt(WOPT_IMPLICIT, "implicit declaration of function '%s'", name);
            s = external_global_sym(t, &func_old_type);
        }
        r = s->r;
        if ((r & VL_MASK) < VL_CONST)
            r = (r & ~VL_MASK) | VL_LOCAL;
        vset(&s->type, r, s->c);
        vtop->sym = s;
        if (r & VF_SYM) {
            vtop->c.i = 0;
        } else if (r == VL_CONST && IS_ENUMVAL(s->type.t)) {
            vtop->c.i = s->c;
        }
        break;
    }

    /* post operations */
    while (1) {
        if (tok == T_INC || tok == T_DEC) {
            inc(1, tok);
            next();
        } else if (tok == '.' || tok == T_ARROW) {
            int qualifiers, cumofs = 0;
            if (tok == T_ARROW)
                indir();
            qualifiers = vtop->type.t & (TQ_CONST | TQ_VOLATILE);
            test_lvalue();
            next();
            s = find_field(&vtop->type, tok, &cumofs);
            gaddrof();
            vtop->type = char_pointer_type;
            vpushi(cumofs);
            gen_op('+');
            vtop->type = s->type;
            vtop->type.t |= qualifiers;
            if (!(vtop->type.t & TQ_ARRAY)) {
                vtop->r |= VF_LVAL;
            }
            next();
        } else if (tok == '[') {
            next();
            gexpr();
            gen_op('+');
            indir();
            skip(']');
        } else if (tok == '(') {
            Val ret;
            Sym *sa;
            int nb_args, ret_nregs, ret_align, regsize, variadic;

            if ((vtop->type.t & TY_MASK) != TY_FUNC) {
                if ((vtop->type.t & (TY_MASK | TQ_ARRAY)) == TY_PTR) {
                    vtop->type = *pointed_type(&vtop->type);
                    if ((vtop->type.t & TY_MASK) != TY_FUNC)
                        goto error_func;
                } else {
                error_func:
                    expect("function pointer");
                }
            } else {
                vtop->r &= ~VF_LVAL;
            }
            s = vtop->type.ref;
            next();
            sa = s->next;
            nb_args = regsize = 0;
            ret.r2 = VL_CONST;
            memset(&ret.c, 0, sizeof ret.c);
            if ((s->type.t & TY_MASK) == TY_STRUCT) {
                variadic = (s->functype == FUNC_ELLIPSIS);
                ret_nregs = gfunc_sret(&s->type, variadic, &ret.type, &ret_align, &regsize);
                if (ret_nregs <= 0) {
                    size = type_size(&s->type, &align);
                    loc = (loc - size) & -align;
                    ret.type = s->type;
                    ret.r = VL_LOCAL | VF_LVAL;
                    vseti(VL_LOCAL, loc);
                    ret.c = vtop->c;
                    if (ret_nregs < 0)
                        vtop--;
                    else
                        nb_args++;
                }
            } else {
                ret_nregs = 1;
                ret.type = s->type;
            }
            if (ret_nregs > 0) {
                ret.c.i = 0;
                PUT_R_RET(&ret, ret.type.t);
            }
            if (tok != ')') {
                for (;;) {
                    expr_eq();
                    gfunc_param_typed(s, sa);
                    nb_args++;
                    if (sa)
                        sa = sa->next;
                    if (tok == ')')
                        break;
                    skip(',');
                }
            }
            if (sa)
                error("too few arguments to function");
            skip(')');
            gfunc_call(nb_args);

            if (ret_nregs < 0) {
                vset(&ret.type, ret.r, 0);
                vtop->c = ret.c;
            } else {
                n = ret_nregs;
                while (n > 1) {
                    int rc = reg_classes[ret.r] & ~(RC_INT | RC_FLOAT);
                    rc <<= --n;
                    for (r = 0; r < NB_REGS; ++r)
                        if (reg_classes[r] & rc)
                            break;
                    vset(&ret.type, r, 0);
                    vtop->c = ret.c;
                }
                vset(&ret.type, ret.r, 0);
                vtop->c = ret.c;
                vtop->r2 = ret.r2;
                if (((s->type.t & TY_MASK) == TY_STRUCT) && ret_nregs) {
                    int addr, offset;
                    size = type_size(&s->type, &align);
                    size = (size + regsize - 1) & -regsize;
                    if (ret_align > align)
                        align = ret_align;
                    loc = (loc - size) & -align;
                    addr = loc;
                    offset = 0;
                    for (;;) {
                        vset(&ret.type, VL_LOCAL | VF_LVAL, addr + offset);
                        vswap();
                        vstore();
                        vtop--;
                        if (--ret_nregs == 0)
                            break;
                        offset += regsize;
                    }
                    vset(&s->type, VL_LOCAL | VF_LVAL, addr);
                }
                t = s->type.t & TY_MASK;
                if (t == TY_I8 || t == TY_I16 || t == TY_BOOL) {
                    vtop->type.t = TY_I32;
                }
            }
            if (s->noreturn) {
                CODE_OFF();
            }
        } else {
            break;
        }
    }
}

static int precedence(int t)
{
    switch (t) {
    case T_OROR: return 1;
    case T_ANDAND: return 2;
    case '|': return 3;
    case '^': return 4;
    case '&': return 5;
    case T_EQ: case T_NE: return 6;
    case T_ULT: case T_UGE: return 7;
    case T_SHL: case T_SAR: return 8;
    case '+': case '-': return 9;
    case '*': case '/': case '%': return 10;
    default:
        if (t >= T_ULE && t <= T_GT)
            return 7;
        return 0;
    }
}

static void expr_landor(int op);

static void expr_infix(int p)
{
    int t = tok, p2;
    while ((p2 = precedence(t)) >= p) {
        if (t == T_OROR || t == T_ANDAND) {
            expr_landor(t);
        } else {
            next();
            unary();
            if (precedence(tok) > p2)
                expr_infix(p2 + 1);
            gen_op(t);
        }
        t = tok;
    }
}

static void expr_landor(int op)
{
    int t = 0, cc = 1, f = 0, i = op == T_ANDAND, c;
    for (;;) {
        c = f ? i : condition_3way();
        if (c < 0)
            save_regs(1), cc = 0;
        else if (c != i)
            nocode_wanted++, f = 1;
        if (tok != op)
            break;
        if (c < 0)
            t = gvtst(i, t);
        else
            vpop();
        next();
        unary();
        expr_infix(precedence(op) + 1);
    }
    if (cc || f) {
        vpop();
        vpushi(i ^ f);
        gsym(t);
        nocode_wanted -= f;
    } else {
        gvtst_set(i, t);
    }
}

void expr_lor(void)
{
    unary();
    expr_infix(1);
}

static void expr_cond(void)
{
    int tt, u, r1, r2, rc, t1, t2, islv, c, g_;
    Val sv;
    Type type;
    int ncw_prev;

    expr_lor();
    if (tok == '?') {
        next();
        c = condition_3way();
        g_ = (tok == ':' && opt.gnu_ext);
        tt = 0;
        if (!g_) {
            if (c < 0) {
                save_regs(1);
                tt = gvtst(1, 0);
            } else {
                vpop();
            }
        } else if (c < 0) {
            save_regs(1);
            gv_dup();
            tt = gvtst(0, 0);
        }
        ncw_prev = nocode_wanted;
        if (c == 0)
            nocode_wanted++;
        if (!g_)
            gexpr();
        if ((vtop->type.t & TY_MASK) == TY_FUNC)
            mk_pointer(&vtop->type);
        sv = *vtop;
        vtop--;
        if (g_) {
            u = tt;
        } else if (c < 0) {
            u = gjmp(0);
            gsym(tt);
        } else
            u = 0;
        nocode_wanted = ncw_prev;
        if (c == 1)
            nocode_wanted++;
        skip(':');
        expr_cond();
        if ((vtop->type.t & TY_MASK) == TY_FUNC)
            mk_pointer(&vtop->type);
        if (!combine_types_pub(&type, &sv, vtop, '?'))
            type_incompatibility_error(&sv.type, &vtop->type,
                "type mismatch in conditional expression (have '%s' and '%s')");
        if (c < 0 && is_cond_bool(vtop) && is_cond_bool(&sv)) {
            t1 = gvtst(0, 0);
            t2 = gjmp(0);
            gsym(u);
            vpushv(&sv);
            gvtst_set(0, t1);
            gvtst_set(1, t2);
            gen_cast(&type);
            return;
        }
        islv = (vtop->r & VF_LVAL) && (sv.r & VF_LVAL) && TY_STRUCT == (type.t & TY_MASK);
        if (c != 1) {
            gen_cast(&type);
            if (islv) {
                mk_pointer(&vtop->type);
                gaddrof();
            } else if (TY_STRUCT == (vtop->type.t & TY_MASK))
                gaddrof();
        }
        rc = rc_type(type.t);
        tt = r2 = 0;
        if (c < 0) {
            r2 = gv(rc);
            tt = gjmp(0);
        }
        gsym(u);
        nocode_wanted = ncw_prev;
        if (c != 0) {
            *vtop = sv;
            gen_cast(&type);
            if (islv) {
                mk_pointer(&vtop->type);
                gaddrof();
            } else if (TY_STRUCT == (vtop->type.t & TY_MASK))
                gaddrof();
        }
        if (c < 0) {
            r1 = gv(rc);
            move_reg(r2, r1, islv ? TY_PTR : type.t);
            vtop->r = r2;
            gsym(tt);
        }
        if (islv)
            indir();
    }
}

static int assign_op(int t)
{
    switch (t) {
    case T_ADDEQ: return '+';
    case T_SUBEQ: return '-';
    case T_MULEQ: return '*';
    case T_DIVEQ: return '/';
    case T_MODEQ: return '%';
    case T_ANDEQ: return '&';
    case T_OREQ: return '|';
    case T_XOREQ: return '^';
    case T_SHLEQ: return T_SHL;
    case T_SAREQ: return T_SAR;
    }
    return 0;
}

void expr_eq(void)
{
    int t;
    expr_cond();
    if ((t = tok) == '=' || assign_op(t)) {
        test_lvalue();
        next();
        if (t == '=') {
            expr_eq();
        } else {
            vdup();
            expr_eq();
            gen_op(assign_op(t));
        }
        vstore();
    }
}

void gexpr(void)
{
    while (1) {
        expr_eq();
        if (tok != ',')
            break;
        vpop();
        next();
    }
}

int expr_const1(void)
{
    nocode_wanted += CONST_WANTED_BIT;
    expr_cond();
    nocode_wanted -= CONST_WANTED_BIT;
    return 0;
}

long long expr_const64(void)
{
    long long c;
    expr_const1();
    if ((vtop->r & (VL_MASK | VF_LVAL | VF_SYM | VF_NONCONST)) != VL_CONST)
        expect("constant expression");
    c = vtop->c.i;
    vpop();
    return c;
}

int expr_const(void)
{
    int c;
    long long wc = expr_const64();
    c = wc;
    if (c != wc && (unsigned)c != wc)
        error("constant exceeds 32 bit");
    return c;
}
