/* expression parsing and code generation */
#include "gen.h"

#define TYPE_ABSTRACT 1
#define TYPE_DIRECT 2
#define TYPE_PARAM 4
#define TYPE_NEST 8

#define LABEL_DEFINED 0
#define LABEL_FORWARD 1
#define LABEL_DECLARED 2
#define LABEL_GONE 3

extern int global_expr;
extern int constant_p;
extern void decl_initializer_alloc(Type *type, Attr *ad, int r, int has_init, int v, int global);
extern void skip_or_save_block(TokSeq **str);
extern void parse_attribute(Attr *ad);
extern void convert_parameter_type(Type *pt);
extern void sym_to_attr(Attr *ad, Sym *s);
extern void push_reader_arr(const int *a, int *owned);
extern void parse_atomic(int atok);
extern int combine_types_pub(Type *dest, Val *op1, Val *op2, int op);
#define STMT_EXPR 2

int global_expr;
int constant_p;

void expr_type(Type *type, void (*expr_fn)(void))
{
    nocode_wanted++;
    expr_fn();
    *type = vtop->type;
    vpop();
    nocode_wanted--;
}

void parse_expr_type(Type *type)
{
    int n;
    Attr ad;
    skip('(');
    if (parse_btype(type, &ad, 0)) {
        type_decl(type, &ad, &n, TYPE_ABSTRACT);
    } else {
        expr_type(type, gexpr);
    }
    skip(')');
}

void parse_type(Type *type)
{
    Attr ad;
    int n;
    if (!parse_btype(type, &ad, 0)) {
        expect("type");
    }
    type_decl(type, &ad, &n, TYPE_ABSTRACT);
}

static void parse_builtin_params(int nc, const char *args)
{
    char c, sep = '(';
    Type type;
    if (nc)
        nocode_wanted++;
    next();
    if (*args == 0)
        skip(sep);
    while ((c = *args++)) {
        skip(sep);
        sep = ',';
        if (c == 't') {
            parse_type(&type);
            vpush(&type);
            continue;
        }
        expr_eq();
        type.ref = NULL;
        type.t = 0;
        switch (c) {
        case 'e':
            continue;
        case 'V':
            type.t = TQ_CONST;
        case 'v':
            type.t |= TY_VOID;
            mk_pointer(&type);
            break;
        case 'S':
            type.t = TQ_CONST;
        case 's':
            type.t |= char_type.t;
            mk_pointer(&type);
            break;
        case 'i':
            type.t = TY_I32;
            break;
        case 'l':
            type.t = TY_I64 | TQ_LONG | TQ_UNSIGNED;
            break;
        default:
            break;
        }
        gen_assign_cast(&type);
    }
    skip(')');
    if (nc)
        nocode_wanted--;
}

static Sym *find_field(Type *type, int v, int *cumofs)
{
    Sym *s = type->ref;
    int v1 = v | SYM_FIELD;
    if (!(v & SYM_FIELD)) {
        if ((type->t & TY_MASK) != TY_STRUCT)
            expect("struct or union");
        if (v < KW_DEFINE)
            expect("field name");
        if (s->c < 0)
            error("dereferencing incomplete type '%s'", tokname(s->v & ~SYM_STRUCT, 0));
    }
    while ((s = s->next) != NULL) {
        if (s->v == v1) {
            *cumofs = s->c;
            return s;
        }
        if ((s->type.t & TY_MASK) == TY_STRUCT && s->v >= (SYM_FIRST_ANOM | SYM_FIELD)) {
            Sym *ret = find_field(&s->type, v1, cumofs);
            if (ret) {
                *cumofs += s->c;
                return ret;
            }
        }
    }
    if (!(v & SYM_FIELD))
        error("field not found: %s", tokname(v, NULL));
    return s;
}

static int is_cond_bool(Val *sv)
{
    if ((sv->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST
        && (sv->type.t & TY_MASK) == TY_I32)
        return (unsigned)sv->c.i < 2;
    if (sv->r == VL_CMP)
        return 1;
    return 0;
}

static int condition_3way(void)
{
    int c = -1;
    if ((vtop->r & (VL_MASK | VF_LVAL)) == VL_CONST &&
        (!(vtop->r & VF_SYM) || !vtop->sym->weak)) {
        vdup();
        gen_cast_s(TY_BOOL);
        c = vtop->c.i;
        vpop();
    }
    return c;
}

static void gen_test_zero_(int op)
{
    if (vtop->r == VL_CMP) {
        Val *v = vtop;
        if (op == T_EQ) {
            if (v->cmp_op > 1)
                v->cmp_op ^= 1;
            else
                v->cmp_op = !v->cmp_op;
            int x = v->jtrue; v->jtrue = v->jfalse; v->jfalse = x;
        }
    } else {
        vpushi(0);
        gen_op(op);
    }
}

void gfunc_param_typed(Sym *func, Sym *arg)
{
    int func_type;
    Type type;
    func_type = func->functype;
    if (func_type == FUNC_OLD || (func_type == FUNC_ELLIPSIS && arg == NULL)) {
        if ((vtop->type.t & TY_MASK) == TY_F32) {
            gen_cast_s(TY_F64);
        } else if (vtop->type.t & TQ_BITFIELD) {
            type.t = vtop->type.t & (TY_MASK | TQ_UNSIGNED);
            type.ref = vtop->type.ref;
            gen_cast(&type);
        } else if (vtop->r & VF_MUSTCAST) {
            int sbt = ((vtop->r >> 10) & 3) == 2 ? TY_I64 : TY_I32;
            int dbt = vtop->type.t;
            vtop->r &= ~VF_MUSTCAST;
            vtop->type.t = sbt;
            gen_cast_s(dbt == TY_BOOL ? TY_I8 | TQ_UNSIGNED : dbt);
            vtop->type.t = dbt;
        }
    } else if (arg == NULL) {
        error("too many arguments to function");
    } else {
        type = arg->type;
        type.t &= ~TQ_CONST;
        gen_assign_cast(&type);
    }
}

static void type_incompatibility_error(Type *st, Type *dt, const char *fmt)
{
    char buf1[256], buf2[256];
    type_to_str(buf1, sizeof(buf1), st, NULL);
    type_to_str(buf2, sizeof(buf2), dt, NULL);
    error(fmt, buf1, buf2);
}

#define PUT_R_RET(sv, t) ((sv)->r = is_float(t) ? ((t & TY_MASK) == TY_F80 ? R_ST0 : R_XMM0) : R_RAX, (sv)->r2 = (((t) & TY_MASK) == TY_I128 ? R_RDX : ((t) & TY_MASK) == TY_F128 ? R_XMM1 : VL_CONST))

static int rc_type(int t)
{
    if (!is_float(t))
        return RC_INT;
    if ((t & TY_MASK) == TY_F80)
        return RC_ST0;
    return RC_FLOAT;
}

static int rc_ret(int t)
{
    if (!is_float(t))
        return RC_IRET;
    if ((t & TY_MASK) == TY_F80)
        return RC_ST0;
    return RC_FRET;
}

void unary(void)
{
    int n, t, align, size, r, sizeof_caller;
    Type type;
    Sym *s;
    Attr ad;

    sizeof_caller = in_sizeof;
    in_sizeof = 0;
    type.ref = NULL;
tok_next:
    switch (tok) {
    case KW_EXTENSION:
        next();
        goto tok_next;
    case T_WCHAR:
    case T_INT:
    case T_CHAR:
        t = TY_I32;
    push_tokc:
        type.t = t;
        {
            CVal cv;
            memset(&cv, 0, sizeof cv);
            if (t == TY_F32) cv.f = tokc.f;
            else if (t == TY_F64) cv.d = tokc.d;
            else if (t == TY_F80) cv.ld = tokc.ld;
            else cv.i = tokc.i;
            vset(&type, VL_CONST, 0);
            vtop->c = cv;
        }
        next();
        break;
    case T_UINT:
        t = TY_I32 | TQ_UNSIGNED;
        goto push_tokc;
    case T_LLONG:
        t = TY_I64;
        goto push_tokc;
    case T_ULLONG:
        t = TY_I64 | TQ_UNSIGNED;
        goto push_tokc;
    case T_FLOAT:
        t = TY_F32;
        goto push_tokc;
    case T_DOUBLE:
        t = TY_F64;
        goto push_tokc;
    case T_LDOUBLE:
        t = TY_F80;
        goto push_tokc;
    case T_LONG:
        t = TY_I64 | TQ_LONG;
        goto push_tokc;
    case T_ULONG:
        t = TY_I64 | TQ_LONG | TQ_UNSIGNED;
        goto push_tokc;
    case KW___FUNCTION__:
        if (!opt.gnu_ext)
            goto tok_identifier;
        /* fallthrough */
    case KW___func__:
        tok = T_STR;
        str_clear(&tokstr);
        str_puts(&tokstr, funcname);
        str_putc(&tokstr, 0);
        tokc.str.n = tokstr.len;
        tokc.str.s = tokstr.s;
        goto case_TOK_STR;
    case T_WSTR:
        t = TY_I32;
        goto str_init;
    case T_STR:
    case_TOK_STR:
        t = char_type.t;
    str_init:
        if (opt.w_write_strings & 1)
            t |= TQ_CONST;
        type.t = t;
        mk_pointer(&type);
        type.t |= TQ_ARRAY;
        memset(&ad, 0, sizeof(Attr));
        ad.section = rodata_section;
        decl_initializer_alloc(&type, &ad, VL_CONST, 2, 0, 0);
        break;
    case '(':
        next();
        if (parse_btype(&type, &ad, 0)) {
            type_decl(&type, &ad, &n, TYPE_ABSTRACT);
            skip(')');
            if (tok == '{') {
                if (global_expr)
                    r = VL_CONST;
                else
                    r = VL_LOCAL;
                if (!(type.t & TQ_ARRAY))
                    r |= VF_LVAL;
                memset(&ad, 0, sizeof(Attr));
                decl_initializer_alloc(&type, &ad, r, 1, 0, 0);
            } else if (sizeof_caller) {
                vpush(&type);
                return;
            } else {
                unary();
                gen_cast(&type);
            }
        } else if (tok == '{') {
            int saved_nocode_wanted = nocode_wanted;
            if ((nocode_wanted & CONST_WANTED_MASK) && !(nocode_wanted & unevalmask))
                expect("constant");
            if (0 == local_scope)
                error("statement expression outside of function");
            save_regs(0);
            block(STMT_EXPR);
            if (saved_nocode_wanted)
                nocode_wanted = saved_nocode_wanted;
            skip(')');
        } else {
            gexpr();
            skip(')');
        }
        break;
    case '*':
        next();
        unary();
        indir();
        break;
    case '&':
        next();
        unary();
        if ((vtop->type.t & TY_MASK) != TY_FUNC &&
            !(vtop->type.t & (TQ_ARRAY | TQ_VLA)))
            test_lvalue();
        if (vtop->sym)
            vtop->sym->addrtaken = 1;
        mk_pointer(&vtop->type);
        gaddrof();
        break;
    case '!':
        next();
        unary();
        gen_test_zero_(T_EQ);
        break;
    case '~':
        next();
        unary();
        vpushi(-1);
        gen_op('^');
        break;
    case '+':
        next();
        unary();
        if ((vtop->type.t & TY_MASK) == TY_PTR)
            error("pointer not accepted for unary plus");
        if (!is_float(vtop->type.t)) {
            vpushi(0);
            gen_op('+');
        }
        break;
    case KW_SIZEOF:
    case KW_ALIGNOF1:
    case KW_ALIGNOF2:
    case KW_ALIGNOF3:
        t = tok;
        next();
        in_sizeof++;
        expr_type(&type, unary);
        if (t == KW_SIZEOF) {
            vpush_type_size(&type, &align);
            gen_cast_s(TY_I64 | TQ_LONG | TQ_UNSIGNED);
        } else {
            type_size(&type, &align);
            s = NULL;
            if (vtop[1].r & VF_SYM)
                s = vtop[1].sym;
            if (s && s->aligned)
                align = 1 << (s->aligned - 1);
            vpushs(align);
        }
        break;
    case KW_builtin_expect:
        parse_builtin_params(0, "ee");
        vpop();
        break;
    case KW_builtin_types_compatible_p:
        parse_builtin_params(0, "tt");
        vtop[-1].type.t &= ~(TQ_CONST | TQ_VOLATILE);
        vtop[0].type.t &= ~(TQ_CONST | TQ_VOLATILE);
        n = is_compatible_types(&vtop[-1].type, &vtop[0].type);
        vtop -= 2;
        vpushi(n);
        break;
    case KW_builtin_choose_expr: {
        long long c;
        next();
        skip('(');
        c = expr_const64();
        skip(',');
        if (!c)
            nocode_wanted++;
        expr_eq();
        if (!c) {
            vpop();
            nocode_wanted--;
        }
        skip(',');
        if (c)
            nocode_wanted++;
        expr_eq();
        if (c) {
            vpop();
            nocode_wanted--;
        }
        skip(')');
        break;
    }
    case KW_builtin_constant_p:
        constant_p = 1;
        parse_builtin_params(1, "e");
        n = constant_p &&
            (vtop->r & (VL_MASK | VF_LVAL)) == VL_CONST &&
            !((vtop->r & VF_SYM) && vtop->sym->addrtaken);
        vtop--;
        vpushi(n);
        break;
    case KW_builtin_unreachable:
        parse_builtin_params(0, "");
        type.t = TY_VOID;
        vpush(&type);
        CODE_OFF();
        break;
    case KW_builtin_frame_address:
    case KW_builtin_return_address: {
        int tok1 = tok;
        long long level;
        next();
        skip('(');
        level = expr_const64();
        if (level < 0)
            error("%s only takes positive integers", tokname(tok1, 0));
        skip(')');
        type.t = TY_VOID;
        mk_pointer(&type);
        vset(&type, VL_LOCAL, 0);
        while (level--) {
            mk_pointer(&vtop->type);
            indir();
        }
        if (tok1 == KW_builtin_return_address) {
            vpushi(PTR_SIZE);
            gen_op('+');
            mk_pointer(&vtop->type);
            indir();
        }
        break;
    }
    case KW_builtin_va_arg_types:
        parse_builtin_params(0, "t");
        vpushi(classify_x86_64_va_arg(&vtop->type));
        vswap();
        vpop();
        break;
    case KW_atomic_store:
    case KW_atomic_load:
    case KW_atomic_exchange:
    case KW_atomic_compare_exchange:
    case KW_atomic_fetch_add:
    case KW_atomic_fetch_sub:
    case KW_atomic_fetch_or:
    case KW_atomic_fetch_xor:
    case KW_atomic_fetch_and:
    case KW_atomic_fetch_nand:
    case KW_atomic_add_fetch:
    case KW_atomic_sub_fetch:
    case KW_atomic_or_fetch:
    case KW_atomic_xor_fetch:
    case KW_atomic_and_fetch:
    case KW_atomic_nand_fetch:
        parse_atomic(tok);
        break;
    case T_INC:
    case T_DEC:
        t = tok;
        next();
        unary();
        inc(0, t);
        break;
    case '-':
        next();
        unary();
        if (is_float(vtop->type.t)) {
            gen_opif(T_NEG);
        } else {
            vpushi(0);
            vswap();
            gen_op('-');
        }
        break;
    case T_ANDAND:
        if (!opt.gnu_ext)
            goto tok_identifier;
        next();
        if (tok < KW_DEFINE)
            expect("label identifier");
        s = label_find(tok);
        if (!s) {
            s = label_push(&global_label_stack, tok, LABEL_FORWARD);
        } else {
            if (s->r == LABEL_DECLARED)
                s->r = LABEL_FORWARD;
        }
        if ((s->type.t & TY_MASK) != TY_PTR) {
            s->type.t = TY_VOID;
            mk_pointer(&s->type);
            s->type.t |= SC_STATIC;
        }
        vpushsym(&s->type, s);
        next();
        break;
    case KW_GENERIC: {
        Type controlling_type;
        int has_default = 0;
        int has_match = 0;
        int learn = 0;
        TokSeq *str = NULL;
        int saved_nocode_wanted = nocode_wanted;
        nocode_wanted &= ~CONST_WANTED_MASK;
        next();
        skip('(');
        expr_type(&controlling_type, expr_eq);
        convert_parameter_type(&controlling_type);
        nocode_wanted = saved_nocode_wanted;
        for (;;) {
            learn = 0;
            skip(',');
            if (tok == KW_DEFAULT) {
                if (has_default)
                    error("too many 'default'");
                has_default = 1;
                if (!has_match)
                    learn = 1;
                next();
            } else {
                Attr ad_tmp;
                int itmp;
                Type cur_type;
                parse_btype(&cur_type, &ad_tmp, 0);
                type_decl(&cur_type, &ad_tmp, &itmp, TYPE_ABSTRACT);
                if (is_compatible_types(&controlling_type, &cur_type)) {
                    if (has_match) {
                        error("type match twice");
                    }
                    has_match = 1;
                    learn = 1;
                }
            }
            skip(':');
            if (learn) {
                if (str)
                    tseq_free(str);
                skip_or_save_block(&str);
            } else {
                skip_or_save_block(NULL);
            }
            if (tok == ')')
                break;
        }
        if (!str) {
            char buf[60];
            type_to_str(buf, sizeof buf, &controlling_type, NULL);
            error("type '%s' does not match any association", buf);
        }
        push_reader(str, 1);
        next();
        expr_eq();
        if (tok != T_EOF)
            expect(",");
        pop_reader();
        next();
        break;
    }
    case KW___nan__:
        n = 0x7fc00000;
    special_math_val:
        vpushi(n);
        vtop->type.t = TY_F32;
        next();
        break;
    case KW___snan__:
        n = 0x7f800001;
        goto special_math_val;
    case KW___inf__:
        n = 0x7f800000;
        goto special_math_val;
    default:
    tok_identifier:
        if (tok < KW_DEFINE)
            error("expression expected before '%s'", tokname(tok, &tokc));
        t = tok;
        next();
        s = sym_find(t);
        if (!s || IS_ASM_SYM_(s)) {
            const char *name = tokname(t, NULL);
            if (tok != '(')
                error("'%s' undeclared", name);
            warning_opt(WOPT_IMPLICIT, "implicit declaration of function '%s'", name);
            s = external_global_sym(t, &func_old_type);
        }
        r = s->r;
        if ((r & VL_MASK) < VL_CONST)
            r = (r & ~VL_MASK) | VL_LOCAL;
        vset(&s->type, r, s->c);
        vtop->sym = s;
        if (r & VF_SYM) {
            vtop->c.i = 0;
        } else if (r == VL_CONST && IS_ENUMVAL(s->type.t)) {
            vtop->c.i = s->c;
        }
        break;
    }

    /* post operations */
    while (1) {
        if (tok == T_INC || tok == T_DEC) {
            inc(1, tok);
            next();
        } else if (tok == '.' || tok == T_ARROW) {
            int qualifiers, cumofs = 0;
            if (tok == T_ARROW)
                indir();
            qualifiers = vtop->type.t & (TQ_CONST | TQ_VOLATILE);
            test_lvalue();
            next();
            s = find_field(&vtop->type, tok, &cumofs);
            gaddrof();
            vtop->type = char_pointer_type;
            vpushi(cumofs);
            gen_op('+');
            vtop->type = s->type;
            vtop->type.t |= qualifiers;
            if (!(vtop->type.t & TQ_ARRAY)) {
                vtop->r |= VF_LVAL;
            }
            next();
        } else if (tok == '[') {
            next();
            gexpr();
            gen_op('+');
            indir();
            skip(']');
        } else if (tok == '(') {
            Val ret;
            Sym *sa;
            int nb_args, ret_nregs, ret_align, regsize, variadic;

            if ((vtop->type.t & TY_MASK) != TY_FUNC) {
                if ((vtop->type.t & (TY_MASK | TQ_ARRAY)) == TY_PTR) {
                    vtop->type = *pointed_type(&vtop->type);
                    if ((vtop->type.t & TY_MASK) != TY_FUNC)
                        goto error_func;
                } else {
                error_func:
                    expect("function pointer");
                }
            } else {
                vtop->r &= ~VF_LVAL;
            }
            s = vtop->type.ref;
            next();
            sa = s->next;
            nb_args = regsize = 0;
            ret.r2 = VL_CONST;
            memset(&ret.c, 0, sizeof ret.c);
            if ((s->type.t & TY_MASK) == TY_STRUCT) {
                variadic = (s->functype == FUNC_ELLIPSIS);
                ret_nregs = gfunc_sret(&s->type, variadic, &ret.type, &ret_align, &regsize);
                if (ret_nregs <= 0) {
                    size = type_size(&s->type, &align);
                    loc = (loc - size) & -align;
                    ret.type = s->type;
                    ret.r = VL_LOCAL | VF_LVAL;
                    vseti(VL_LOCAL, loc);
                    ret.c = vtop->c;
                    if (ret_nregs < 0)
                        vtop--;
                    else
                        nb_args++;
                }
            } else {
                ret_nregs = 1;
                ret.type = s->type;
            }
            if (ret_nregs > 0) {
                ret.c.i = 0;
                PUT_R_RET(&ret, ret.type.t);
            }
            if (tok != ')') {
                for (;;) {
                    expr_eq();
                    gfunc_param_typed(s, sa);
                    nb_args++;
                    if (sa)
                        sa = sa->next;
                    if (tok == ')')
                        break;
                    skip(',');
                }
            }
            if (sa)
                error("too few arguments to function");
            skip(')');
            gfunc_call(nb_args);

            if (ret_nregs < 0) {
                vset(&ret.type, ret.r, 0);
                vtop->c = ret.c;
            } else {
                n = ret_nregs;
                while (n > 1) {
                    int rc = reg_classes[ret.r] & ~(RC_INT | RC_FLOAT);
                    rc <<= --n;
                    for (r = 0; r < NB_REGS; ++r)
                        if (reg_classes[r] & rc)
                            break;
                    vset(&ret.type, r, 0);
                    vtop->c = ret.c;
                }
                vset(&ret.type, ret.r, 0);
                vtop->c = ret.c;
                vtop->r2 = ret.r2;
                if (((s->type.t & TY_MASK) == TY_STRUCT) && ret_nregs) {
                    int addr, offset;
                    size = type_size(&s->type, &align);
                    size = (size + regsize - 1) & -regsize;
                    if (ret_align > align)
                        align = ret_align;
                    loc = (loc - size) & -align;
                    addr = loc;
                    offset = 0;
                    for (;;) {
                        vset(&ret.type, VL_LOCAL | VF_LVAL, addr + offset);
                        vswap();
                        vstore();
                        vtop--;
                        if (--ret_nregs == 0)
                            break;
                        offset += regsize;
                    }
                    vset(&s->type, VL_LOCAL | VF_LVAL, addr);
                }
                t = s->type.t & TY_MASK;
                if (t == TY_I8 || t == TY_I16 || t == TY_BOOL) {
                    vtop->type.t = TY_I32;
                }
            }
            if (s->noreturn) {
                CODE_OFF();
            }
        } else {
            break;
        }
    }
}

static int precedence(int t)
{
    switch (t) {
    case T_OROR: return 1;
    case T_ANDAND: return 2;
    case '|': return 3;
    case '^': return 4;
    case '&': return 5;
    case T_EQ: case T_NE: return 6;
    case T_ULT: case T_UGE: return 7;
    case T_SHL: case T_SAR: return 8;
    case '+': case '-': return 9;
    case '*': case '/': case '%': return 10;
    default:
        if (t >= T_ULE && t <= T_GT)
            return 7;
        return 0;
    }
}

static void expr_landor(int op);

static void expr_infix(int p)
{
    int t = tok, p2;
    while ((p2 = precedence(t)) >= p) {
        if (t == T_OROR || t == T_ANDAND) {
            expr_landor(t);
        } else {
            next();
            unary();
            if (precedence(tok) > p2)
                expr_infix(p2 + 1);
            gen_op(t);
        }
        t = tok;
    }
}

static void expr_landor(int op)
{
    int t = 0, cc = 1, f = 0, i = op == T_ANDAND, c;
    for (;;) {
        c = f ? i : condition_3way();
        if (c < 0)
            save_regs(1), cc = 0;
        else if (c != i)
            nocode_wanted++, f = 1;
        if (tok != op)
            break;
        if (c < 0)
            t = gvtst(i, t);
        else
            vpop();
        next();
        unary();
        expr_infix(precedence(op) + 1);
    }
    if (cc || f) {
        vpop();
        vpushi(i ^ f);
        gsym(t);
        nocode_wanted -= f;
    } else {
        gvtst_set(i, t);
    }
}

void expr_lor(void)
{
    unary();
    expr_infix(1);
}

static void expr_cond(void)
{
    int tt, u, r1, r2, rc, t1, t2, islv, c, g_;
    Val sv;
    Type type;
    int ncw_prev;

    expr_lor();
    if (tok == '?') {
        next();
        c = condition_3way();
        g_ = (tok == ':' && opt.gnu_ext);
        tt = 0;
        if (!g_) {
            if (c < 0) {
                save_regs(1);
                tt = gvtst(1, 0);
            } else {
                vpop();
            }
        } else if (c < 0) {
            save_regs(1);
            gv_dup();
            tt = gvtst(0, 0);
        }
        ncw_prev = nocode_wanted;
        if (c == 0)
            nocode_wanted++;
        if (!g_)
            gexpr();
        if ((vtop->type.t & TY_MASK) == TY_FUNC)
            mk_pointer(&vtop->type);
        sv = *vtop;
        vtop--;
        if (g_) {
            u = tt;
        } else if (c < 0) {
            u = gjmp(0);
            gsym(tt);
        } else
            u = 0;
        nocode_wanted = ncw_prev;
        if (c == 1)
            nocode_wanted++;
        skip(':');
        expr_cond();
        if ((vtop->type.t & TY_MASK) == TY_FUNC)
            mk_pointer(&vtop->type);
        if (!combine_types_pub(&type, &sv, vtop, '?'))
            type_incompatibility_error(&sv.type, &vtop->type,
                "type mismatch in conditional expression (have '%s' and '%s')");
        if (c < 0 && is_cond_bool(vtop) && is_cond_bool(&sv)) {
            t1 = gvtst(0, 0);
            t2 = gjmp(0);
            gsym(u);
            vpushv(&sv);
            gvtst_set(0, t1);
            gvtst_set(1, t2);
            gen_cast(&type);
            return;
        }
        islv = (vtop->r & VF_LVAL) && (sv.r & VF_LVAL) && TY_STRUCT == (type.t & TY_MASK);
        if (c != 1) {
            gen_cast(&type);
            if (islv) {
                mk_pointer(&vtop->type);
                gaddrof();
            } else if (TY_STRUCT == (vtop->type.t & TY_MASK))
                gaddrof();
        }
        rc = rc_type(type.t);
        tt = r2 = 0;
        if (c < 0) {
            r2 = gv(rc);
            tt = gjmp(0);
        }
        gsym(u);
        nocode_wanted = ncw_prev;
        if (c != 0) {
