/* ------------------------------------------------------------ token saving */
void skip_or_save_block(TokSeq **str)
{
    int braces = tok == '{';
    int level = 0;
    if (str)
        *str = tseq_new();
    while (1) {
        int t = tok;
        if (level == 0
            && (t == ',' || t == ';' || t == '}' || t == ')' || t == ']'))
            break;
        if (t == T_EOF) {
            if (str || level > 0)
                error("unexpected end of file");
            else
                break;
        }
        if (str)
            tseq_add_cur(*str);
        next();
        if (t == '{' || t == '(' || t == '[') {
            ++level;
        } else if (t == '}' || t == ')' || t == ']') {
            --level;
            if (level == 0 && braces && t == '}')
                break;
        }
    }
    if (str) {
        tseq_add(*str, -1);
        tseq_add(*str, 0);
    }
}

/* parse a string (possibly concatenated) */
static Str mult_str;
static char *parse_mult_str(const char *msg)
{
    if (tok != T_STR)
        expect(msg);
    str_clear(&mult_str);
    while (tok == T_STR) {
        str_putn(&mult_str, tokc.str.s, tokc.str.n - 1);
        next();
    }
    str_putc(&mult_str, 0);
    return mult_str.s;
}

int asm_label_instr(void)
{
    int v;
    char *astr;
    next();
    skip('(');
    astr = parse_mult_str("string constant");
    skip(')');
    v = ident_tok(astr);
    return v;
}

/* ------------------------------------------------------------ attributes */
void parse_attribute(Attr *ad)
{
    int t, n;
    char *astr;
redo:
    if (tok != KW_ATTRIBUTE1 && tok != KW_ATTRIBUTE2)
        return;
    next();
    skip('(');
    skip('(');
    while (tok != ')') {
        if (tok < T_IDENT)
            expect("attribute name");
        t = tok;
        next();
        switch (t) {
        case KW_CLEANUP1:
        case KW_CLEANUP2: {
            Sym *s;
            skip('(');
            s = sym_find(tok);
            if (!s) {
                warning_opt(WOPT_IMPLICIT, "implicit declaration of function '%s'", tokname(tok, &tokc));
                s = external_global_sym(tok, &func_old_type);
            } else if ((s->type.t & TY_MASK) != TY_FUNC)
                error("'%s' is not declared as function", tokname(tok, &tokc));
            ad->cleanup_func = s;
            next();
            skip(')');
            break;
        }
        case KW_CONSTRUCTOR1:
        case KW_CONSTRUCTOR2:
            ad->ctor = 1;
            break;
        case KW_DESTRUCTOR1:
        case KW_DESTRUCTOR2:
            ad->dtor = 1;
            break;
        case KW_ALWAYS_INLINE1:
        case KW_ALWAYS_INLINE2:
            ad->alwinl = 1;
            break;
        case KW_SECTION1:
        case KW_SECTION2:
            skip('(');
            astr = parse_mult_str("section name");
            ad->section = find_section(astr);
            skip(')');
            break;
        case KW_ALIAS1:
        case KW_ALIAS2:
            skip('(');
            astr = parse_mult_str("alias(\"target\")");
            ad->alias_target = ident_tok(astr);
            skip(')');
            break;
        case KW_VISIBILITY1:
        case KW_VISIBILITY2:
            skip('(');
            astr = parse_mult_str("visibility(\"default|hidden|internal|protected\")");
            if (!strcmp(astr, "default"))
                ad->visibility = STV_DEFAULT;
            else if (!strcmp(astr, "hidden"))
                ad->visibility = STV_HIDDEN;
            else if (!strcmp(astr, "internal"))
                ad->visibility = STV_INTERNAL;
            else if (!strcmp(astr, "protected"))
                ad->visibility = STV_PROTECTED;
            else
                expect("visibility(\"default|hidden|internal|protected\")");
            skip(')');
            break;
        case KW_ALIGNED1:
        case KW_ALIGNED2:
            if (tok == '(') {
                next();
                n = expr_const();
                if (n <= 0 || (n & (n - 1)) != 0)
                    error("alignment must be a positive power of two");
                skip(')');
            } else {
                n = MAX_ALIGN;
            }
            ad->aligned = exact_log2p1(n);
            if (n != 1 << (ad->aligned - 1))
                error("alignment of %d is larger than implemented", n);
            break;
        case KW_PACKED1:
        case KW_PACKED2:
            ad->packed = 1;
            break;
        case KW_WEAK1:
        case KW_WEAK2:
            ad->weak = 1;
            break;
        case KW_NODEBUG1:
        case KW_NODEBUG2:
            ad->nodebug = 1;
            break;
        case KW_UNUSED1:
        case KW_UNUSED2:
            break;
        case KW_NORETURN1:
        case KW_NORETURN2:
            ad->noreturn = 1;
            break;
        case KW_CDECL1:
        case KW_CDECL2:
        case KW_CDECL3:
            ad->func_call = 0;
            break;
        case KW_STDCALL1:
        case KW_STDCALL2:
        case KW_STDCALL3:
            ad->func_call = 1;
            break;
        case KW_MODE:
            skip('(');
            switch (tok) {
            case KW_MODE_DI:
                ad->mode = TY_I64 + 1;
                break;
            case KW_MODE_QI:
                ad->mode = TY_I8 + 1;
                break;
            case KW_MODE_HI:
                ad->mode = TY_I16 + 1;
                break;
            case KW_MODE_SI:
            case KW_MODE_word:
                ad->mode = TY_I32 + 1;
                break;
            default:
                warning("__mode__(%s) not supported\n", tokname(tok, NULL));
                break;
            }
            next();
            skip(')');
            break;
        case KW_DLLEXPORT:
            ad->dllexport = 1;
            break;
        case KW_NODECORATE:
            break;
        case KW_DLLIMPORT:
            ad->dllimport = 1;
            break;
        default:
            warning_opt(WOPT_UNSUPPORTED, "'%s' attribute ignored", tokname(t, NULL));
            if (tok == '(') {
                int parenthesis = 0;
                do {
                    if (tok == '(')
                        parenthesis++;
                    else if (tok == ')')
                        parenthesis--;
                    next();
                } while (parenthesis && tok != -1);
            }
            break;
        }
        if (tok != ',')
            break;
        next();
    }
    skip(')');
    skip(')');
    goto redo;
}

static void merge_symattr(Sym *s, Attr *ad)
{
    if (ad->aligned && !s->aligned) s->aligned = ad->aligned;
    if (ad->packed) s->packed = 1;
    if (ad->weak) s->weak = 1;
    if (ad->visibility && !s->visibility) s->visibility = ad->visibility;
    if (ad->nodebug) s->nodebug = 1;
    if (ad->dllimport) s->dllimport = 1;
    if (ad->dllexport) s->dllexport = 1;
}

static void set_symattr(Sym *s, Attr *ad)
{
    s->aligned = ad->aligned;
    s->packed = ad->packed;
    s->weak = ad->weak;
    s->visibility = ad->visibility;
    s->nodebug = ad->nodebug;
    s->dllimport = ad->dllimport;
    s->dllexport = ad->dllexport;
}

static void merge_funcattr(Sym *f, Attr *ad)
{
    if (ad->func_call && !f->func_call) f->func_call = ad->func_call;
    if (ad->noreturn) f->noreturn = 1;
    if (ad->ctor) f->ctor = 1;
    if (ad->dtor) f->dtor = 1;
    if (ad->alwinl) f->alwinl = 1;
}

static void merge_funcattr_sym(Sym *f, Sym *g)
{
    if (g->func_call && !f->func_call) f->func_call = g->func_call;
    if (g->noreturn) f->noreturn = 1;
    if (g->ctor) f->ctor = 1;
    if (g->dtor) f->dtor = 1;
    if (g->alwinl) f->alwinl = 1;
}

void sym_to_attr(Attr *ad, Sym *s)
{
    if (s->aligned && !ad->aligned) ad->aligned = s->aligned;
    if (s->packed) ad->packed = 1;
    if (s->weak) ad->weak = 1;
    if (s->visibility && !ad->visibility) ad->visibility = s->visibility;
    if (s->nodebug) ad->nodebug = 1;
    if (s->dllimport) ad->dllimport = 1;
    if (s->dllexport) ad->dllexport = 1;
    if ((s->type.t & TY_MASK) == TY_FUNC && s->type.ref) {
        Sym *f = s->type.ref;
        if (f->func_call && !ad->func_call) ad->func_call = f->func_call;
        if (f->noreturn) ad->noreturn = 1;
        if (f->ctor) ad->ctor = 1;
        if (f->dtor) ad->dtor = 1;
        if (f->alwinl) ad->alwinl = 1;
    }
}

/* ------------------------------------------------------------ struct layout */
static void check_fields(Type *type, int check)
{
    Sym *s = type->ref;
    while ((s = s->next) != NULL) {
        int v = s->v & ~SYM_FIELD;
        if (v < SYM_FIRST_ANOM) {
            Ident *id = ident_of(v);
            if (check && (id->tok & SYM_FIELD))
                error("duplicate member '%s'", tokname(v, NULL));
            id->tok ^= SYM_FIELD;
        } else if ((s->type.t & TY_MASK) == TY_STRUCT)
            check_fields(&s->type, check);
    }
}

static void struct_layout(Type *type, Attr *ad)
{
    int size, align, maxalign, offset, c, bit_pos, bit_size;
    int packed, a, bt, prevbt, prev_bit_size;
    int pcc = !opt.ms_bitfields;
    int pragma_pack = *pack_sp;
    Sym *f;

    maxalign = 1;
    offset = 0;
    c = 0;
    bit_pos = 0;
    prevbt = TY_STRUCT;
    prev_bit_size = 0;

    for (f = type->ref->next; f; f = f->next) {
        if (f->type.t & TQ_BITFIELD)
            bit_size = BIT_SIZE(f->type.t);
        else
            bit_size = -1;
        size = type_size(&f->type, &align);
        a = f->aligned ? 1 << (f->aligned - 1) : 0;
        packed = 0;

        if (pcc && bit_size == 0) {
        } else {
            if (pcc && (f->packed || ad->packed))
                align = packed = 1;
            if (pragma_pack) {
                packed = 1;
                if (pragma_pack < align)
                    align = pragma_pack;
                if (pcc && pragma_pack < a)
                    a = 0;
            }
        }
        if (a)
            align = a;

        if (type->ref->type.t == TY_UNION) {
            if (pcc && bit_size >= 0)
                size = (bit_size + 7) >> 3;
            offset = 0;
            if (size > c)
                c = size;
        } else if (bit_size < 0) {
            if (pcc)
                c += (bit_pos + 7) >> 3;
            c = (c + align - 1) & -align;
            offset = c;
            if (size > 0)
                c += size;
            bit_pos = 0;
            prevbt = TY_STRUCT;
            prev_bit_size = 0;
        } else {
            if (pcc) {
                if (bit_size == 0) {
                new_field:
                    c = (c + ((bit_pos + 7) >> 3) + align - 1) & -align;
                    bit_pos = 0;
                } else if (f->aligned) {
                    goto new_field;
                } else if (!packed) {
                    int a8 = align * 8;
                    int ofs = ((c * 8 + bit_pos) % a8 + bit_size + a8 - 1) / a8;
                    if (ofs > size / align)
                        goto new_field;
                }
                if (size == 8 && bit_size <= 32)
                    f->type.t = (f->type.t & ~TY_MASK) | TY_I32, size = 4;
                while (bit_pos >= align * 8)
                    c += align, bit_pos -= align * 8;
                offset = c;
                if (f->v & SYM_FIRST_ANOM)
                    align = 1;
            } else {
                bt = f->type.t & TY_MASK;
                if ((bit_pos + bit_size > size * 8)
                    || (bit_size > 0) == (bt != prevbt)) {
                    c = (c + align - 1) & -align;
                    offset = c;
                    bit_pos = 0;
                    if (bit_size || prev_bit_size)
                        c += size;
                }
                if (bit_size == 0 && prevbt != bt)
                    align = 1;
                prevbt = bt;
                prev_bit_size = bit_size;
            }
            f->type.t = (f->type.t & ~(0x3f << TY_SSHIFT)) | (bit_pos << TY_SSHIFT);
            bit_pos += bit_size;
        }
        if (align > maxalign)
            maxalign = align;
        f->c = offset;
        f->r = 0;
    }

    if (pcc)
        c += (bit_pos + 7) >> 3;

    a = bt = ad->aligned ? 1 << (ad->aligned - 1) : 1;
    if (a < maxalign)
        a = maxalign;
    type->ref->r = a;
    if (pragma_pack && pragma_pack < maxalign && 0 == pcc) {
        a = pragma_pack;
        if (a < bt)
            a = bt;
    }
    c = (c + a - 1) & -a;
    type->ref->c = c;

    for (f = type->ref->next; f; f = f->next) {
        int s, px, cx, c0;
        Type t;
        if (0 == (f->type.t & TQ_BITFIELD))
            continue;
        f->type.ref = f;
        f->auxtype_ = -1;
        bit_size = BIT_SIZE(f->type.t);
        if (bit_size == 0)
            continue;
        bit_pos = BIT_POS(f->type.t);
        size = type_size(&f->type, &align);
        if (bit_pos + bit_size <= size * 8 && f->c + size <= c)
            continue;
        c0 = -1, s = align = 1;
        t.t = TY_I8;
        t.ref = NULL;
        for (;;) {
            px = f->c * 8 + bit_pos;
            cx = (px >> 3) & -align;
            px = px - (cx << 3);
            if (c0 == cx)
                break;
            s = (px + bit_size + 7) >> 3;
            if (s > 4) {
                t.t = TY_I64;
            } else if (s > 2) {
                t.t = TY_I32;
            } else if (s > 1) {
                t.t = TY_I16;
            } else {
                t.t = TY_I8;
            }
            s = type_size(&t, &align);
            c0 = cx;
        }
        if (px + bit_size <= s * 8 && cx + s <= c) {
            f->c = cx;
            bit_pos = px;
            f->type.t = (f->type.t & ~(0x3f << TY_SSHIFT)) | (bit_pos << TY_SSHIFT);
            if (s != size)
                f->auxtype_ = t.t;
        } else {
            f->auxtype_ = TY_STRUCT;
        }
    }
}

static void struct_decl(Type *type, int u)
{
    int v, c, size, align, flexible;
    int bit_size, bsize, bt;
    Sym *s, *ss, **ps;
    Attr ad, ad1;
    Type type1, btype;

    memset(&ad, 0, sizeof ad);
    next();
    parse_attribute(&ad);
    if (tok != '{') {
        v = tok;
        next();
        if (v < T_IDENT)
            expect("struct/union/enum name");
        s = struct_find(v);
        if (s && (s->scope == local_scope || tok != '{')) {
            if (u == s->type.t)
                goto do_decl;
            if (u == TY_ENUM && IS_ENUM(s->type.t))
                goto do_decl;
            error("redeclaration of '%s'", tokname(v, NULL));
        }
    } else {
        v = anon_sym++;
    }
    type1.t = u == TY_ENUM ? u | TY_I32 | TQ_UNSIGNED : u;
    type1.ref = NULL;
    s = sym_push(v | SYM_STRUCT, &type1, 0, -1);
    s->r = 0;
do_decl:
    type->t = s->type.t;
    type->ref = s;

    if (tok == '{') {
        next();
        if (s->c != -1)
            error("struct/union/enum already defined");
        s->c = -2;
        ps = &s->next;
        if (u == TY_ENUM) {
            long long ll = 0, pl = 0, nl = 0;
            Type t;
            t.ref = s;
            t.t = TY_I32 | SC_STATIC | TY_ENUMVAL;
            for (;;) {
                v = tok;
                if (v < KW_DEFINE)
                    expect("identifier");
                ss = sym_find(v);
                if (ss && !local_stack)
                    error("redefinition of enumerator '%s'", tokname(v, NULL));
                next();
                if (tok == '=') {
                    next();
                    ll = expr_const64();
                }
                ss = sym_push(v, &t, VL_CONST, 0);
                ss->c = ll;
                *ps = ss, ps = &ss->next;
                if (ll < nl)
                    nl = ll;
                if (ll > pl)
                    pl = ll;
                if (tok != ',')
                    break;
                next();
                ll++;
                if (tok == '}')
                    break;
            }
            skip('}');
            t.t = TY_I32;
            if (nl >= 0) {
                if (pl != (unsigned)pl)
                    t.t = TY_I64 | TQ_LONG;
                t.t |= TQ_UNSIGNED;
            } else if (pl != (int)pl || nl != (int)nl)
                t.t = TY_I64 | TQ_LONG;
            s->type.t = type->t = t.t | TY_ENUM;
            s->c = 0;
            for (ss = s->next; ss; ss = ss->next) {
                ll = ss->c;
                if (ll == (int)ll)
                    continue;
                if (t.t & TQ_UNSIGNED) {
                    ss->type.t |= TQ_UNSIGNED;
                    if (ll == (unsigned)ll)
                        continue;
                }
                ss->type.t = (ss->type.t & ~TY_MASK) | TY_I64 | TQ_LONG;
            }
        } else {
            c = 0;
            flexible = 0;
            while (tok != '}') {
                if (!parse_btype(&btype, &ad1, 0)) {
                    skip(';');
                    continue;
                }
                while (1) {
                    if (flexible)
                        error("flexible array member '%s' not at the end of struct", tokname(v, NULL));
                    bit_size = -1;
                    v = 0;
                    type1 = btype;
                    if (tok != ':') {
                        if (tok != ';')
                            type_decl(&type1, &ad1, &v, TYPE_DIRECT);
                        if (v == 0) {
                            if ((type1.t & TY_MASK) != TY_STRUCT)
                                expect("identifier");
                            else {
                                int v2 = btype.ref->v;
                                if (!(v2 & SYM_FIELD) && (v2 & ~SYM_STRUCT) < SYM_FIRST_ANOM) {
                                    if (opt.ms_ext == 0)
                                        expect("identifier");
                                }
                            }
                        }
                        if (type_size(&type1, &align) < 0) {
                            if ((u == TY_STRUCT) && (type1.t & TQ_ARRAY) && c)
                                flexible = 1;
                            else
                                error("field '%s' has incomplete type", tokname(v, NULL));
                        }
                        if ((type1.t & TY_MASK) == TY_FUNC ||
                            (type1.t & TY_MASK) == TY_VOID ||
                            (type1.t & SC_MASK))
                            error("invalid type for '%s'", tokname(v, NULL));
                    }
                    if (tok == ':') {
                        next();
                        bit_size = expr_const();
                        if (bit_size < 0)
                            error("negative width in bit-field '%s'", tokname(v, NULL));
                        if (v && bit_size == 0)
                            error("zero width for bit-field '%s'", tokname(v, NULL));
                        parse_attribute(&ad1);
                    }
                    size = type_size(&type1, &align);
                    if (bit_size >= 0) {
                        bt = type1.t & TY_MASK;
                        if (bt != TY_I32 && bt != TY_I8 && bt != TY_I16 &&
                            bt != TY_BOOL && bt != TY_I64)
                            error("bitfields must have scalar type");
                        bsize = size * 8;
                        if (bit_size > bsize) {
                            error("width of '%s' exceeds its type", tokname(v, NULL));
                        } else if (bit_size == bsize && !ad.packed && !ad1.packed) {
                        } else if (bit_size == 64) {
                            error("field width 64 not implemented");
                        } else {
                            type1.t = (type1.t & ~TY_SMASK) | TQ_BITFIELD | (bit_size << (TY_SSHIFT + 6));
                        }
                    }
                    if (v != 0 || (type1.t & TY_MASK) == TY_STRUCT) {
                        c = 1;
                    }
                    if (v == 0 && ((type1.t & TY_MASK) == TY_STRUCT || bit_size >= 0)) {
                        v = anon_sym++;
                    }
                    if (v) {
                        ss = sym_push(v | SYM_FIELD, &type1, 0, 0);
                        set_symattr(ss, &ad1);
                        *ps = ss;
                        ps = &ss->next;
                    }
                    if (tok == ';' || tok == T_EOF)
                        break;
                    skip(',');
                }
                skip(';');
            }
            skip('}');
            parse_attribute(&ad);
            if (ad.cleanup_func) {
                warning("attribute '__cleanup__' ignored on type");
            }
            check_fields(type, 1);
            check_fields(type, 0);
            struct_layout(type, &ad);
        }
    }
}

/* ------------------------------------------------------------ base types */
static void parse_btype_qualify(Type *type, int qualifiers)
{
    while (type->t & TQ_ARRAY) {
        type->ref = sym_push(SYM_FIELD, &type->ref->type, 0, type->ref->c);
        type = &type->ref->type;
    }
    type->t |= qualifiers;
}

int parse_btype(Type *type, Attr *ad, int ignore_label)
{
    int t, u, bt, st, type_found, typespec_found, g, n;
    Sym *s;
    Type type1;

    memset(ad, 0, sizeof(Attr));
    type_found = 0;
    typespec_found = 0;
    t = TY_I32;
    bt = st = -1;
    type->ref = NULL;

    while (1) {
        switch (tok) {
        case KW_EXTENSION:
            next();
            continue;
        case KW_CHAR:
            u = TY_I8;
        basic_type:
            next();
        basic_type1:
            if (u == TY_I16 || u == TQ_LONG) {
                if (st != -1 || (bt != -1 && bt != TY_I32))
                tmbt:
                    error("too many basic types");
                st = u;
            } else {
                if (bt != -1 || (st != -1 && u != TY_I32))
                    goto tmbt;
                bt = u;
            }
            if (u != TY_I32)
                t = (t & ~(TY_MASK | TQ_LONG)) | u;
            typespec_found = 1;
            break;
        case KW_VOID:
            u = TY_VOID;
            goto basic_type;
        case KW_SHORT:
            u = TY_I16;
            goto basic_type;
        case KW_INT:
            u = TY_I32;
            goto basic_type;
        case KW_ALIGNAS: {
            Attr ad1;
            next();
            skip('(');
            memset(&ad1, 0, sizeof(Attr));
            if (parse_btype(&type1, &ad1, 0)) {
                type_decl(&type1, &ad1, &n, TYPE_ABSTRACT);
                if (ad1.aligned)
                    n = 1 << (ad1.aligned - 1);
                else
                    type_size(&type1, &n);
            } else {
                n = expr_const();
                if (n < 0 || (n & (n - 1)) != 0)
                    error("alignment must be a positive power of two");
            }
            skip(')');
            ad->aligned = exact_log2p1(n);
            continue;
        }
        case KW_LONG:
            if ((t & TY_MASK) == TY_F64) {
                t = (t & ~(TY_MASK | TQ_LONG)) | TY_F80;
            } else if ((t & (TY_MASK | TQ_LONG)) == TQ_LONG) {
                t = (t & ~(TY_MASK | TQ_LONG)) | TY_I64;
            } else {
                u = TQ_LONG;
                goto basic_type;
            }
            next();
            break;
        case KW_BOOL:
            u = TY_BOOL;
            goto basic_type;
        case KW_COMPLEX:
            error("_Complex is not yet supported");
        case KW_FLOAT:
            u = TY_F32;
            goto basic_type;
        case KW_DOUBLE:
            if ((t & (TY_MASK | TQ_LONG)) == TQ_LONG) {
                t = (t & ~(TY_MASK | TQ_LONG)) | TY_F80;
            } else {
                u = TY_F64;
                goto basic_type;
            }
            next();
            break;
        case KW_ENUM:
            struct_decl(&type1, TY_ENUM);
        basic_type2:
            u = type1.t;
            type->ref = type1.ref;
            goto basic_type1;
        case KW_STRUCT:
            struct_decl(&type1, TY_STRUCT);
            goto basic_type2;
        case KW_UNION:
            struct_decl(&type1, TY_UNION);
            goto basic_type2;
        case KW_ATOMIC:
            next();
            type->t = t;
            parse_btype_qualify(type, TQ_VOLATILE);
            t = type->t;
            if (tok == '(') {
                parse_expr_type(&type1);
                type1.t &= ~(SC_MASK & ~SC_TYPEDEF);
                if (type1.ref)
                    sym_to_attr(ad, type1.ref);
                goto basic_type2;
            }
            break;
        case KW_CONST1:
        case KW_CONST2:
        case KW_CONST3:
            type->t = t;
            parse_btype_qualify(type, TQ_CONST);
            t = type->t;
            next();
            break;
        case KW_VOLATILE1:
        case KW_VOLATILE2:
        case KW_VOLATILE3:
            type->t = t;
            parse_btype_qualify(type, TQ_VOLATILE);
            t = type->t;
            next();
            break;
        case KW_SIGNED1:
        case KW_SIGNED2:
        case KW_SIGNED3:
            if ((t & (TQ_DEFSIGN | TQ_UNSIGNED)) == (TQ_DEFSIGN | TQ_UNSIGNED))
                error("signed and unsigned modifier");
            t |= TQ_DEFSIGN;
            next();
            typespec_found = 1;
            break;
        case KW_REGISTER:
        case KW_AUTO:
        case KW_RESTRICT1:
        case KW_RESTRICT2:
        case KW_RESTRICT3:
            next();
            break;
        case KW_UNSIGNED:
            if ((t & (TQ_DEFSIGN | TQ_UNSIGNED)) == TQ_DEFSIGN)
                error("signed and unsigned modifier");
            t |= TQ_DEFSIGN | TQ_UNSIGNED;
            next();
            typespec_found = 1;
            break;
        case KW_EXTERN:
            g = SC_EXTERN;
            goto storage;
        case KW_STATIC:
            g = SC_STATIC;
            goto storage;
        case KW_TYPEDEF:
            g = SC_TYPEDEF;
        storage:
            if (t & (SC_EXTERN | SC_STATIC | SC_TYPEDEF) & ~g)
                error("multiple storage classes");
            t |= g;
            next();
            break;
        case KW_INLINE1:
        case KW_INLINE2:
        case KW_INLINE3:
            t |= SC_INLINE;
            next();
            break;
        case KW_NORETURN:
            next();
            ad->noreturn = 1;
            break;
        case KW_ATTRIBUTE1:
        case KW_ATTRIBUTE2:
            parse_attribute(ad);
            if (ad->mode) {
                u = ad->mode - 1;
                t = (t & ~(TY_MASK | TQ_LONG)) | u;
            }
            continue;
        case KW_TYPEOF1:
        case KW_TYPEOF2:
        case KW_TYPEOF3:
            next();
            parse_expr_type(&type1);
            type1.t &= ~(SC_MASK & ~SC_TYPEDEF);
            if (type1.ref)
                sym_to_attr(ad, type1.ref);
            goto basic_type2;
        case KW_THREAD_LOCAL:
            error("_Thread_local is not implemented");
        default:
            if (typespec_found)
                goto the_end;
            s = sym_find(tok);
            if (!s || !(s->type.t & SC_TYPEDEF))
                goto the_end;
            n = tok, next();
            if (tok == ':' && ignore_label) {
                unget_tok(n);
                goto the_end;
            }
            t &= ~(TY_MASK | TQ_LONG);
            u = t & ~(TQ_CONST | TQ_VOLATILE), t ^= u;
            type->t = (s->type.t & ~SC_TYPEDEF) | u;
            type->ref = s->type.ref;
            if (t)
                parse_btype_qualify(type, t);
            t = type->t;
            sym_to_attr(ad, s);
            typespec_found = 1;
            st = bt = -2;
            break;
        }
        type_found = 1;
    }
the_end:
    if (opt.char_unsigned) {
        if ((t & (TQ_DEFSIGN | TY_MASK)) == TY_I8)
            t |= TQ_UNSIGNED;
    }
    bt = t & (TY_MASK | TQ_LONG);
    if (bt == TQ_LONG)
        t |= TY_I64;
    type->t = t;
    return type_found;
}

void convert_parameter_type(Type *pt)
{
    pt->t &= ~(TQ_CONST | TQ_VOLATILE);
    pt->t &= ~(TQ_ARRAY | TQ_VLA);
    if ((pt->t & TY_MASK) == TY_FUNC) {
        mk_pointer(pt);
    }
}

/* ------------------------------------------------------------ declarators */
static int post_type(Type *type, Attr *ad, int storage, int td)
{
    int n, l, t1, arg_size, align;
    Sym **plast, *s, *first;
    Attr ad1;
    Type pt;
    TokSeq *vla_array_tok = NULL;

    if (tok == '(') {
        next();
        if (TYPE_DIRECT == (td & (TYPE_DIRECT | TYPE_ABSTRACT)))
            return 0;
        if (tok == ')')
            l = 0;
        else if (parse_btype(&pt, &ad1, 0))
            l = FUNC_NEW;
        else if (td & (TYPE_DIRECT | TYPE_ABSTRACT)) {
            sym_to_attr(ad, NULL ? NULL : &(Sym){0});
            /* merge attributes */
            if (ad1.aligned && !ad->aligned) ad->aligned = ad1.aligned;
            if (ad1.packed) ad->packed = 1;
            if (ad1.noreturn) ad->noreturn = 1;
            return 0;
        } else
            l = FUNC_OLD;

        first = NULL;
        plast = &first;
        arg_size = 0;
        ++local_scope;
        if (l) {
            for (;;) {
                if (l != FUNC_OLD) {
                    if ((pt.t & TY_MASK) == TY_VOID && tok == ')')
                        break;
                    type_decl(&pt, &ad1, &n, TYPE_DIRECT | TYPE_ABSTRACT | TYPE_PARAM);
                    if ((pt.t & TY_MASK) == TY_VOID)
                        error("parameter declared as void");
                    if (n == 0)
                        n = SYM_FIELD;
                } else {
                    n = tok;
                    pt.t = TY_VOID;
                    pt.ref = NULL;
                    next();
                }
                if (n < KW_DEFINE)
                    expect("identifier");
                convert_parameter_type(&pt);
                arg_size += (type_size(&pt, &align) + PTR_SIZE - 1) / PTR_SIZE;
                s = sym_push(n, &pt, VL_LOCAL | VF_LVAL, 0);
                *plast = s;
                plast = &s->next;
                if (tok == ')')
                    break;
                skip(',');
                if (l == FUNC_NEW && tok == T_ELLIPSIS) {
                    l = FUNC_ELLIPSIS;
                    next();
                    break;
                }
                if (l == FUNC_NEW && !parse_btype(&pt, &ad1, 0))
                    error("invalid type");
            }
        } else
            l = FUNC_OLD;
        skip(')');
        if (first) {
            sym_pop(local_stack ? &local_stack : &global_stack, first->prev, 1);
            for (s = first; s; s = s->next)
                s->v |= SYM_FIELD;
        }
        --local_scope;
        type->t &= ~TQ_CONST;
        if (tok == '[') {
            next();
            skip(']');
            mk_pointer(type);
        }
        s = sym_push(SYM_FIELD, type, 0, 0);
        s->aligned = ad->aligned;
        s->packed = ad->packed;
        s->weak = ad->weak;
        s->visibility = ad->visibility;
        s->func_call = ad->func_call;
        s->noreturn = ad->noreturn;
        s->ctor = ad->ctor;
        s->dtor = ad->dtor;
        s->alwinl = ad->alwinl;
        s->functype = l;
        s->next = first;
        type->t = TY_FUNC;
        type->ref = s;
    } else if (tok == '[') {
        int saved_nocode_wanted = nocode_wanted;
        next();
        n = -1;
        t1 = 0;
        if (td & TYPE_PARAM) while (1) {
            switch (tok) {
            case KW_RESTRICT1: case KW_RESTRICT2: case KW_RESTRICT3:
            case KW_CONST1:
            case KW_VOLATILE1:
            case KW_STATIC:
            case '*':
                next();
                continue;
            default:
                break;
            }
            if (tok != ']') {
                nocode_wanted = 1;
                skip_or_save_block(&vla_array_tok);
                unget_tok(0);
                push_reader(vla_array_tok, 2);
                next();
                gexpr();
                pop_reader();
                next();
                goto check;
            }
            break;
        } else if (tok != ']') {
            if (!local_stack || (storage & SC_STATIC))
                vpushi(expr_const());
            else {
                nocode_wanted = 0;
                gexpr();
            }
        check:
            if ((vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST) {
                n = vtop->c.i;
                if (n < 0)
                    error("invalid array size");
            } else {
                if (!is_integer_btype(vtop->type.t & TY_MASK))
                    error("size of variable length array should be an integer");
                n = 0;
                t1 = TQ_VLA;
            }
        }
        skip(']');
        post_type(type, ad, storage, (td & ~(TYPE_DIRECT | TYPE_ABSTRACT)) | TYPE_NEST);

        if ((type->t & TY_MASK) == TY_FUNC)
            error("declaration of an array of functions");
        if ((type->t & TY_MASK) == TY_VOID || type_size(type, &align) < 0)
            error("declaration of an array of incomplete type elements");

        t1 |= type->t & TQ_VLA;

        if (t1 & TQ_VLA) {
            if (n < 0) {
                if (td & TYPE_NEST)
                    error("need explicit inner array size in VLAs");
            } else {
                loc -= type_size(&int_type, &align);
                loc &= -align;
                n = loc;
                vpush_type_size(type, &align);
                gen_op('*');
                vset(&int_type, VL_LOCAL | VF_LVAL, n);
                vswap();
                vstore();
            }
        }
        if (n != -1)
            vpop();
        nocode_wanted = saved_nocode_wanted;

        s = sym_push(SYM_FIELD, type, 0, n);
        type->t = (t1 ? TQ_VLA : TQ_ARRAY) | TY_PTR;
        type->ref = s;
        if (vla_array_tok) {
            if ((t1 & TQ_VLA) && (td & TYPE_NEST))
                s->vla_tokens_ = vla_array_tok;
            else
                tseq_free(vla_array_tok);
        }
    }
    return 1;
}

static Type *type_decl_(Type *type, Attr *ad, int *v, int td)
{
    Type *post, *ret;
    int qualifiers, storage;

    storage = type->t & SC_MASK;
    type->t &= ~SC_MASK;
    post = ret = type;

    while (tok == '*') {
        qualifiers = 0;
    redo:
        next();
        switch (tok) {
        case KW_ATOMIC:
            qualifiers |= TQ_VOLATILE;
            goto redo;
        case KW_CONST1:
        case KW_CONST2:
        case KW_CONST3:
            qualifiers |= TQ_CONST;
            goto redo;
        case KW_VOLATILE1:
        case KW_VOLATILE2:
        case KW_VOLATILE3:
            qualifiers |= TQ_VOLATILE;
            goto redo;
        case KW_RESTRICT1:
        case KW_RESTRICT2:
        case KW_RESTRICT3:
            goto redo;
        case KW_ATTRIBUTE1:
        case KW_ATTRIBUTE2:
            parse_attribute(ad);
            break;
        }
        mk_pointer(type);
        type->t |= qualifiers;
        if (ret == type)
            ret = pointed_type(type);
    }

    if (tok == '(') {
        if (!post_type(type, ad, 0, td)) {
            parse_attribute(ad);
            post = type_decl_(type, ad, v, td);
            skip(')');
        } else
            goto abstract;
    } else if (tok >= T_IDENT && (td & TYPE_DIRECT)) {
        *v = tok;
        next();
    } else {
    abstract:
        if (!(td & TYPE_ABSTRACT))
            expect("identifier");
        *v = 0;
    }
    post_type(post, ad, post != ret ? 0 : storage, td & ~(TYPE_DIRECT | TYPE_ABSTRACT));
    parse_attribute(ad);
    type->t |= storage;
    return ret;
}

void type_decl(Type *type, Attr *ad, int *v, int td)
{
    type_decl_(type, ad, v, td);
}
