static void decl_design_delrels(Section *sec, int c, int size)
{
    ElfW(Rela) *rel, *rel2, *rel_end;
    if (!sec || !sec->reloc)
        return;
    rel = rel2 = (ElfW(Rela) *)sec->reloc->data;
    rel_end = (ElfW(Rela) *)(sec->reloc->data + sec->reloc->data_offset);
    while (rel < rel_end) {
        if (rel->r_offset >= (unsigned long)c && rel->r_offset < (unsigned long)(c + size)) {
            sec->reloc->data_offset -= sizeof *rel;
        } else {
            if (rel2 != rel)
                memcpy(rel2, rel, sizeof *rel);
            ++rel2;
        }
        ++rel;
    }
}

static void decl_design_flex(InitParams *p, Sym *ref, int index)
{
    if (ref == p->flex_array_ref) {
        if (index >= ref->c)
            ref->c = index + 1;
    } else if (ref->c < 0)
        error("flexible array has zero size in this context");
}

void init_putv_p(InitParams *p, Type *type, unsigned long c);

static int decl_designator(InitParams *p, Type *type, unsigned long c,
                           Sym **cur_field, int flags, int al)
{
    Sym *s, *f;
    int index, index_last, align, l, nb_elems, elem_size;
    unsigned long corig = c;

    elem_size = 0;
    nb_elems = 1;

    if (flags & DIF_HAVE_ELEM)
        goto no_designator;

    if (opt.gnu_ext && tok >= KW_DEFINE) {
        l = tok, next();
        if (tok == ':')
            goto struct_field;
        unget_tok(l);
    }

    while (nb_elems == 1 && (tok == '[' || tok == '.')) {
        if (tok == '[') {
            if (!(type->t & TQ_ARRAY))
                expect("array type");
            next();
            index = index_last = expr_const();
            if (tok == T_ELLIPSIS && opt.gnu_ext) {
                next();
                index_last = expr_const();
            }
            skip(']');
            s = type->ref;
            decl_design_flex(p, s, index_last);
            if (index < 0 || index_last >= s->c || index_last < index)
                error("index exceeds array bounds or range is empty");
            if (cur_field)
                (*cur_field)->c = index_last;
            type = pointed_type(type);
            elem_size = type_size(type, &align);
            c += index * elem_size;
            nb_elems = index_last - index + 1;
        } else {
            int cumofs;
            next();
            l = tok;
        struct_field:
            next();
            f = find_field_pub(type, l, &cumofs);
            if (cur_field)
                *cur_field = f;
            type = &f->type;
            c += cumofs;
        }
        cur_field = NULL;
    }
    if (!cur_field) {
        if (tok == '=') {
            next();
        } else if (!opt.gnu_ext) {
            expect("=");
        }
    } else {
    no_designator:
        if (type->t & TQ_ARRAY) {
            index = (*cur_field)->c;
            s = type->ref;
            decl_design_flex(p, s, index);
            if (index >= s->c)
                error("too many initializers");
            type = pointed_type(type);
            elem_size = type_size(type, &align);
            c += index * elem_size;
        } else {
            f = *cur_field;
            while (f && (f->v & SYM_FIRST_ANOM) && is_integer_btype(f->type.t & TY_MASK))
                *cur_field = f = f->next;
            if (!f)
                error("too many initializers");
            type = &f->type;
            c += f->c;
        }
    }

    if (!elem_size)
        elem_size = type_size(type, &align);

    if (!(flags & DIF_SIZE_ONLY) && (long)(c - corig) < al) {
        decl_design_delrels(p->sec, c, elem_size * nb_elems);
        flags &= ~DIF_CLEAR;
    }

    decl_initializer(p, type, c, flags & ~DIF_FIRST);

    if (!(flags & DIF_SIZE_ONLY) && nb_elems > 1) {
        Sym aref;
        Type t1;
        int i;
        memset(&aref, 0, sizeof aref);
        if (p->sec || (type->t & TQ_ARRAY)) {
            aref.c = elem_size;
            t1.t = TY_STRUCT, t1.ref = &aref;
            type = &t1;
        }
        if (p->sec)
            vpush_ref(type, p->sec, c, elem_size);
        else
            vset(type, VL_LOCAL | VF_LVAL, c);
        for (i = 1; i < nb_elems; i++) {
            vdup();
            init_putv_p(p, type, c + elem_size * i);
        }
        vpop();
    }

    c += nb_elems * elem_size;
    if ((long)(c - corig) > al)
        al = c - corig;
    return al;
}

void init_putv_p(InitParams *p, Type *type, unsigned long c)
{
