                int bit_pos, bit_size, bits, n;
                unsigned char *pp, v, m;
                bit_pos = BIT_POS(vtop->type.t);
                bit_size = BIT_SIZE(vtop->type.t);
                pp = (unsigned char *)ptr + (bit_pos >> 3);
                bit_pos &= 7, bits = 0;
                while (bit_size) {
                    n = 8 - bit_pos;
                    if (n > bit_size)
                        n = bit_size;
                    v = val >> bits << bit_pos;
                    m = ((1 << n) - 1) << bit_pos;
                    *pp = (*pp & ~m) | (v & m);
                    bits += n, bit_size -= n, bit_pos = 0, ++pp;
                }
            } else
                switch (bt) {
                case TY_BOOL:
                    *(char *)ptr = val != 0;
                    break;
                case TY_I8:
                    *(char *)ptr = val;
                    break;
                case TY_I16:
                    write16le(ptr, val);
                    break;
                case TY_F32:
                    write32le(ptr, val);
                    break;
                case TY_F64:
                    write64le(ptr, val);
                    break;
                case TY_F80:
                    memcpy(ptr, &vtop->c.ld, 10);
                    break;
                case TY_I64:
                case TY_PTR:
                    if (vtop->r & VF_SYM)
                        greloca(sec, vtop->sym, c, R_X86_64_64, val);
                    else
                        write64le(ptr, val);
                    break;
                case TY_I32:
                    write32le(ptr, val);
                    break;
                default:
                    break;
                }
        }
        vtop--;
    } else {
        vset(&dtype, VL_LOCAL | VF_LVAL, c);
        vswap();
        vstore();
        vpop();
    }
}

/* used by gv() to store float constants */
void init_putv_rodata(Type *type, Section *sec, unsigned long c)
{
    InitParams p;
    memset(&p, 0, sizeof p);
    p.sec = sec;
    init_putv_p(&p, type, c);
}

static void decl_initializer(InitParams *p, Type *type, unsigned long c, int flags)
{
    int len, n, no_oblock, i;
    int size1, align1;
    Sym *s, *f;
    Sym indexsym;
    Type *t1;

    if (!(flags & DIF_HAVE_ELEM) && tok != '{' &&
        tok != T_WSTR && tok != T_STR &&
        (!(flags & DIF_SIZE_ONLY) || (type->t & TY_MASK) == TY_STRUCT)) {
        int ncw_prev = nocode_wanted;
        if ((flags & DIF_SIZE_ONLY) && !p->sec)
            ++nocode_wanted;
        parse_init_elem(!p->sec ? EXPR_ANY : EXPR_CONST);
        nocode_wanted = ncw_prev;
        flags |= DIF_HAVE_ELEM;
    }

    if (type->t & TQ_ARRAY) {
        no_oblock = 1;
        if (((flags & DIF_FIRST) && tok != T_WSTR && tok != T_STR) || tok == '{') {
            skip('{');
            no_oblock = 0;
        }

        s = type->ref;
        n = s->c;
        t1 = pointed_type(type);
        size1 = type_size(t1, &align1);

        if ((tok == T_WSTR && (t1->t & TY_MASK) == TY_I32) ||
            (tok == T_STR && (t1->t & TY_MASK) == TY_I8)) {
            len = 0;
            str_clear(&initstr);
            if (size1 != (tok == T_STR ? 1 : 4))
                error("unhandled string literal merging");
            while (tok == T_STR || tok == T_WSTR) {
                if (initstr.len)
                    initstr.len -= size1;
                if (tok == T_STR)
                    len += tokc.str.n;
                else
                    len += tokc.str.n / 4;
                len--;
                str_putn(&initstr, tokc.str.s, tokc.str.n);
                next();
            }
            if (tok != ')' && tok != '}' && tok != ',' && tok != ';' && tok != T_EOF) {
                unget_tok(size1 == 1 ? T_STR : T_WSTR);
                tokc.str.n = initstr.len;
                tokc.str.s = initstr.s;
                goto do_init_array;
            }

            decl_design_flex(p, s, len);
            if (!(flags & DIF_SIZE_ONLY)) {
                int nb = n, ch;
                if (len < nb)
                    nb = len;
                if (len > nb)
                    warning("initializer-string for array is too long");
                if (p->sec && size1 == 1) {
                    if (!NODATA_WANTED)
                        memcpy(p->sec->data + c, initstr.s, nb);
                } else {
                    for (i = 0; i < n; i++) {
                        if (i >= nb) {
                            if (flags & DIF_CLEAR)
                                break;
                            if (n - i >= 4) {
                                init_putz(p, c + i * size1, (n - i) * size1);
                                break;
                            }
                            ch = 0;
                        } else if (size1 == 1)
                            ch = ((unsigned char *)initstr.s)[i];
                        else
                            ch = ((int *)initstr.s)[i];
                        vpushi(ch);
                        init_putv_p(p, t1, c + i * size1);
                    }
                }
            }
        } else {
        do_init_array:
            memset(&indexsym, 0, sizeof indexsym);
            indexsym.c = 0;
            f = &indexsym;
        do_init_list:
            if (!(flags & (DIF_CLEAR | DIF_SIZE_ONLY))) {
                init_putz(p, c, n * size1);
                flags |= DIF_CLEAR;
            }
            len = 0;
            decl_design_flex(p, s, len);
            while (tok != '}' || (flags & DIF_HAVE_ELEM)) {
                len = decl_designator(p, type, c, &f, flags, len);
                flags &= ~DIF_HAVE_ELEM;
                if (type->t & TQ_ARRAY) {
                    ++indexsym.c;
                    if (no_oblock && len >= n * size1)
                        break;
                } else {
                    if (s->type.t == TY_UNION)
                        f = NULL;
                    else
                        f = f->next;
                    if (no_oblock && f == NULL)
                        break;
                }
                if (tok == '}')
                    break;
                skip(',');
            }
        }
        if (!no_oblock)
            skip('}');
    } else if ((flags & DIF_HAVE_ELEM)
               && is_compatible_unqualified_types(type, &vtop->type)) {
        goto one_elem;
    } else if ((type->t & TY_MASK) == TY_STRUCT) {
        no_oblock = 1;
        if ((flags & DIF_FIRST) || tok == '{') {
            skip('{');
            no_oblock = 0;
        }
        s = type->ref;
        f = s->next;
        n = s->c;
        size1 = 1;
        goto do_init_list;
    } else if (tok == '{') {
        if (flags & DIF_HAVE_ELEM)
            skip(';');
        next();
        decl_initializer(p, type, c, flags & ~DIF_HAVE_ELEM);
        skip('}');
    } else
    one_elem:
        if ((flags & DIF_SIZE_ONLY)) {
            if (flags & DIF_HAVE_ELEM)
                vpop();
            else
                skip_or_save_block(NULL);
        } else {
            if (!(flags & DIF_HAVE_ELEM)) {
                if (tok != T_STR && tok != T_WSTR)
                    expect("string constant");
                parse_init_elem(!p->sec ? EXPR_ANY : EXPR_CONST);
            }
            if (!p->sec && (flags & DIF_CLEAR)
                && (vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST
                && vtop->c.i == 0
                && btype_size(type->t & TY_MASK))
                vpop();
            else
                init_putv_p(p, type, c);
        }
}

/* ------------------------------------------------------------ storage */
static void patch_type(Sym *sym, Type *type)
{
    if (!(type->t & SC_EXTERN) || IS_ENUMVAL(sym->type.t)) {
        if (!(sym->type.t & SC_EXTERN))
            error("redefinition of '%s'", tokname(sym->v, NULL));
        sym->type.t &= ~SC_EXTERN;
    }

    if (IS_ASM_SYM_(sym)) {
        sym->type.t = type->t & (sym->type.t | ~SC_STATIC);
        sym->type.ref = type->ref;
        if ((type->t & TY_MASK) != TY_FUNC && !(type->t & TQ_ARRAY))
            sym->r |= VF_LVAL;
    }

    if (!is_compatible_types(&sym->type, type)) {
        error("incompatible types for redefinition of '%s'", tokname(sym->v, NULL));
    } else if ((sym->type.t & TY_MASK) == TY_FUNC) {
        int static_proto = sym->type.t & SC_STATIC;
        if ((type->t & SC_STATIC) && !static_proto
            && !((type->t | sym->type.t) & SC_INLINE))
            warning("static storage ignored for redefinition of '%s'", tokname(sym->v, NULL));
        if ((type->t | sym->type.t) & SC_INLINE) {
            if (!((type->t ^ sym->type.t) & SC_INLINE)
                || ((type->t | sym->type.t) & SC_STATIC))
                static_proto |= SC_INLINE;
        }
        if (0 == (type->t & SC_EXTERN)) {
            Sym f = *sym->type.ref;
            sym->type.t = (type->t & ~(SC_STATIC | SC_INLINE)) | static_proto;
            sym->type.ref = type->ref;
            {
                Sym *r = sym->type.ref;
                if (f.func_call && !r->func_call) r->func_call = f.func_call;
                if (f.noreturn) r->noreturn = 1;
                if (f.ctor) r->ctor = 1;
                if (f.dtor) r->dtor = 1;
                if (f.alwinl) r->alwinl = 1;
            }
        } else {
            sym->type.t &= ~SC_INLINE | static_proto;
        }
        if (sym->type.ref->functype == FUNC_OLD && type->ref->functype != FUNC_OLD) {
            sym->type.ref = type->ref;
        }
    } else {
        if ((sym->type.t & TQ_ARRAY) && type->ref->c >= 0) {
            sym->type.ref->c = type->ref->c;
        }
        if ((type->t ^ sym->type.t) & SC_STATIC)
            warning("storage mismatch for redefinition of '%s'", tokname(sym->v, NULL));
    }
}

static void patch_storage(Sym *sym, Attr *ad, Type *type)
{
    if (type)
        patch_type(sym, type);
    sym->weak |= ad->weak;
    if (ad->visibility) {
        int vis = sym->visibility;
        int vis2 = ad->visibility;
        if (vis == STV_DEFAULT)
            vis = vis2;
        else if (vis2 != STV_DEFAULT)
            vis = (vis < vis2) ? vis : vis2;
        sym->visibility = vis;
    }
    if (ad->aligned)
        sym->aligned = ad->aligned;
    if (ad->asm_label)
        sym->asm_label = ad->asm_label;
    update_storage(sym);
}

static Sym *sym_copy(Sym *s0, Sym **ps)
{
    Sym *s;
    s = xcalloc(sizeof(Sym));
    *s = *s0;
    s->prev = *ps, *ps = s;
    if (s->v < SYM_FIRST_ANOM) {
        Sym **pp = &ident_of(s->v)->sym_id;
        s->shadow = *pp, *pp = s;
    }
    return s;
}

static void sym_copy_ref(Sym *s, Sym **ps)
{
    int bt = s->type.t & TY_MASK;
    if (bt == TY_FUNC || bt == TY_PTR || (bt == TY_STRUCT && s->scope)) {
        Sym **sp = &s->type.ref;
        for (s = *sp, *sp = NULL; s; s = s->next) {
            Sym *s2 = sym_copy(s, ps);
            sp = &(*sp = s2)->next;
            sym_copy_ref(s2, ps);
        }
    }
}

static Sym *external_sym(int v, Type *type, int r, Attr *ad)
{
    Sym *s;
    s = sym_find(v);
    while (s && s->scope)
        s = s->shadow;
    if (!s) {
        s = global_identifier_push(v, type->t, 0);
        s->r |= r;
        s->aligned = ad->aligned;
        s->packed = ad->packed;
        s->weak = ad->weak;
        s->visibility = ad->visibility;
        s->nodebug = ad->nodebug;
        s->dllimport = ad->dllimport;
        s->dllexport = ad->dllexport;
        s->asm_label = ad->asm_label;
        s->type.ref = type->ref;
        if (local_stack)
            sym_copy_ref(s, &global_stack);
    } else {
        patch_storage(s, ad, type);
    }
    if (local_stack && (s->type.t & TY_MASK) != TY_FUNC)
        s = sym_copy(s, &local_stack);
    return s;
}

/* ------------------------------------------------------------ allocation */
void decl_initializer_alloc(Type *type, Attr *ad, int r, int has_init, int v, int global)
{
    int size, align, addr = 0;
    TokSeq *init_str = NULL;
    Section *sec;
    Sym *flexible_array;
    Sym *sym;
    int saved_nocode_wanted = nocode_wanted;
    InitParams p;
    memset(&p, 0, sizeof p);

    if (v && (r & VL_MASK) == VL_CONST)
        nocode_wanted |= DATA_ONLY_WANTED;

    flexible_array = NULL;
    size = type_size(type, &align);

    if (size < 0) {
        type->ref = sym_push(SYM_FIELD, &type->ref->type, 0, type->ref->c);
        p.flex_array_ref = type->ref;
    } else if (has_init && (type->t & TY_MASK) == TY_STRUCT) {
        Sym *field = type->ref->next;
        if (field) {
            while (field->next)
                field = field->next;
            if (field->type.t & TQ_ARRAY && field->type.ref->c < 0) {
                flexible_array = field;
                p.flex_array_ref = field->type.ref;
                size = -1;
            }
        }
    }

    if (size < 0) {
        if (!has_init)
            error("unknown type size");
        if (has_init == 2) {
            init_str = tseq_new();
            while (tok == T_STR || tok == T_WSTR) {
                tseq_add_cur(init_str);
                next();
            }
            tseq_add(init_str, -1);
            tseq_add(init_str, 0);
        } else
            skip_or_save_block(&init_str);
        unget_tok(0);

        push_reader(init_str, 2);
        next();
        decl_initializer(&p, type, 0, DIF_FIRST | DIF_SIZE_ONLY);
        mac_ptr = init_str->a;
        next();

        size = type_size(type, &align);
        if (size < 0)
            error("unknown type size");
        if (flexible_array && flexible_array->type.ref->c > 0)
            size += flexible_array->type.ref->c * pointed_size(&flexible_array->type);
    }

    if (ad->aligned) {
        int speca = 1 << (ad->aligned - 1);
        if (speca > align)
            align = speca;
    } else if (ad->packed) {
        align = 1;
    }

    if (!v && NODATA_WANTED)
        size = 0, align = 1;

    if ((r & VL_MASK) == VL_LOCAL) {
        sec = NULL;
        loc = (loc - size) & -align;
        addr = loc;
        p.local_offset = addr + size;
        if (v) {
            if (ad->asm_label) {
                int reg = asm_parse_regvar(ad->asm_label);
                if (reg >= 0)
                    r = (r & ~VL_MASK) | reg;
            }
            sym = sym_push(v, type, r, addr);
            if (ad->cleanup_func)
                scope_add_cleanup(sym, ad->cleanup_func);
            sym->aligned = ad->aligned;
            sym->packed = ad->packed;
            sym->weak = ad->weak;
            sym->visibility = ad->visibility;
        } else {
            vset(type, r, addr);
        }
    } else {
        sym = NULL;
        if (v && global) {
            sym = sym_find(v);
            if (sym) {
                if (p.flex_array_ref && (sym->type.t & type->t & TQ_ARRAY)
                    && sym->type.ref->c > type->ref->c) {
                    type->ref->c = sym->type.ref->c;
                    size = type_size(type, &align);
                }
                patch_storage(sym, ad, type);
                if (!has_init && sym->elfsym && elfsym(sym)->st_shndx != SHN_UNDEF)
                    goto no_alloc;
            }
        }

        sec = ad->section;
        if (!sec) {
            Type *tp = type;
            while ((tp->t & (TY_MASK | TQ_ARRAY)) == (TY_PTR | TQ_ARRAY))
                tp = &tp->ref->type;
            if (tp->t & TQ_CONST) {
                sec = rodata_section;
            } else if (has_init) {
                sec = data_section;
            } else if (opt.nocommon)
                sec = bss_section;
        }

        if (sec) {
            addr = section_add(sec, size, align);
        } else {
            addr = align;
            sec = common_section;
        }

        if (v) {
            if (!sym) {
                sym = sym_push(v, type, r | VF_SYM, 0);
                patch_storage(sym, ad, NULL);
            }
            put_extern_sym(sym, sec, addr, size);
        } else {
            vpush_ref(type, sec, addr, size);
            sym = vtop->sym;
            vtop->r |= r;
        }
    }

    if (type->t & TQ_VLA) {
        if (NODATA_WANTED)
            goto no_alloc;
        scope_vla_decl(type, addr);
    } else if (has_init) {
        p.sec = sec;
        decl_initializer(&p, type, addr, DIF_FIRST);
        if (flexible_array)
            flexible_array->type.ref->c = -1;
    }

no_alloc:
    if (init_str) {
        pop_reader();
        tseq_free(init_str);
        next();
    }
    nocode_wanted = saved_nocode_wanted;
}

/* ------------------------------------------------------------ functions */
typedef struct InlineFunc {
    TokSeq *func_str;
    Sym *sym;
    char filename[1];
} InlineFunc;

static PVec inline_fns;
extern void check_func_return_pub(void);

void gen_function(Sym *sym)
{
    scope_new_func();
    nocode_wanted = 0;
    ind = cur_text_section->data_offset;
    if (sym->aligned) {
        size_t newoff = section_add(cur_text_section, 0, 1 << (sym->aligned - 1));
        gen_fill_nops(newoff - ind);
    }
    funcname = tokname(sym->v, NULL);
    funcname = xstrdup(funcname);
    func_ind = ind;
    func_vt = sym->type.ref->type;
    func_var = sym->type.ref->functype == FUNC_ELLIPSIS;

    put_extern_sym(sym, cur_text_section, ind, 0);

    if (sym->type.ref->ctor || sym->type.ref->dtor) {
        extern void add_init_array(const char *sec, Sym *sym);
        if (sym->type.ref->ctor)
            add_init_array(".init_array", sym);
        if (sym->type.ref->dtor)
            add_init_array(".fini_array", sym);
    }

    sym_push2(&local_stack, SYM_FIELD, 0, 0);
    local_scope = 1;
    gfunc_prolog(sym);
    local_scope = 0;
    rsym = 0;
    clear_temp_local_var_list();
    func_vla_arg(sym);
    block_pub(0);
    gsym(rsym);
    nocode_wanted = 0;
    sym_pop(&local_stack, NULL, 0);
    gfunc_epilog();
    eh_frame_func(func_ind, ind - func_ind);
    elfsym(sym)->st_size = ind - func_ind;
    cur_text_section->data_offset = ind;
    local_scope = 0;
    label_pop(&global_label_stack, NULL, 0);
    cleanups_reset();
    cur_text_section = NULL;
    funcname = "";
    func_vt.t = TY_VOID;
    func_var = 0;
    ind = 0;
    func_ind = -1;
    nocode_wanted = DATA_ONLY_WANTED;
    check_vstack();
    next();
}

void gen_inline_functions(void)
{
    Sym *sym;
    int inline_generated, i;
    InlineFunc *fn;
    src_open_buf(":inline:", "", 0);
    file->line = file->up ? file->up->line : 1;
    do {
        inline_generated = 0;
        for (i = 0; i < inline_fns.n; ++i) {
            fn = inline_fns.v[i];
            sym = fn->sym;
            if (sym && (sym->elfsym || !(sym->type.t & SC_INLINE))) {
                fn->sym = NULL;
                push_reader(fn->func_str, 2);
                next();
                cur_text_section = text_section;
                gen_function(sym);
                pop_reader();
                inline_generated = 1;
            }
        }
    } while (inline_generated);
    {
        SrcFile *f = file;
        file = f->up;
        free(f->buf);
        free(f->true_name);
        free(f);
    }
}

void free_inline_functions(void)
{
    for (int i = 0; i < inline_fns.n; i++) {
        InlineFunc *fn = inline_fns.v[i];
        if (fn->func_str) tseq_free(fn->func_str);
        free(fn);
    }
    free(inline_fns.v);
    memset(&inline_fns, 0, sizeof inline_fns);
}

static void do_Static_assert(void)
{
    int c;
    const char *msg;
    next();
    skip('(');
    c = expr_const();
    msg = "_Static_assert fail";
    if (tok == ',') {
        next();
        msg = (char *)xstrdup(parse_mult_str_pub("string constant"));
    }
    skip(')');
    if (c == 0)
        error("%s", msg);
    skip(';');
}

int decl(int l)
{
    int v, has_init, r, oldint;
    Type type, btype;
    Sym *sym;
    Attr ad, adbase;

    while (1) {
        oldint = 0;
        if (!parse_btype(&btype, &adbase, l == VL_LOCAL)) {
            if (l == VL_JMP)
                return 0;
            if (tok == ';' && l != VL_CMP) {
                next();
                continue;
            }
            if (tok == KW_STATIC_ASSERT) {
                do_Static_assert();
                continue;
            }
            if (l != VL_CONST)
                break;
            if (tok == KW_ASM1 || tok == KW_ASM2 || tok == KW_ASM3) {
                asm_global_instr();
                continue;
            }
            if (tok >= KW_DEFINE) {
                btype.t = TY_I32;
                oldint = 1;
            } else {
                if (tok != T_EOF)
                    expect("declaration");
                break;
            }
        }

        if (tok == ';') {
            if ((btype.t & TY_MASK) == TY_STRUCT) {
                v = btype.ref->v;
                if (!(v & SYM_FIELD) && (v & ~SYM_STRUCT) >= SYM_FIRST_ANOM)
                    warning("useless type defines no instances");
                next();
                continue;
            }
            if (IS_ENUM(btype.t)) {
                next();
                continue;
            }
            warning("useless type defines no instances");
            next();
            continue;
        }

        while (1) {
            type = btype;
            ad = adbase;
            type_decl(&type, &ad, &v, TYPE_DIRECT);
            if (oldint && (type.t & TY_MASK) != TY_FUNC)
                warning("type defaults to int");
            if ((type.t & TY_MASK) == TY_FUNC) {
                if ((type.t & SC_STATIC) && (l != VL_CONST))
                    error("function without file scope cannot be static");
                sym = type.ref;
                if (sym->functype == FUNC_OLD && l == VL_CONST) {
                    func_vt = type;
                    decl(VL_CMP);
                }
            }

            if (opt.gnu_ext && (tok == KW_ASM1 || tok == KW_ASM2 || tok == KW_ASM3)) {
                ad.asm_label = asm_label_instr();
                parse_attribute(&ad);
            }

            if (tok == '{') {
                if (l != VL_CONST)
                    error("cannot use local functions");
                if ((type.t & TY_MASK) != TY_FUNC)
                    expect("function definition");
                sym = type.ref;
                while ((sym = sym->next) != NULL) {
                    if (!(sym->v & ~SYM_FIELD))
                        expect("identifier");
                    if (sym->type.t == TY_VOID)
                        sym->type = int_type;
                }
                {
                    Sym *f = type.ref;
                    if (ad.func_call && !f->func_call) f->func_call = ad.func_call;
                    if (ad.noreturn) f->noreturn = 1;
                    if (ad.ctor) f->ctor = 1;
                    if (ad.dtor) f->dtor = 1;
                    if (ad.alwinl) f->alwinl = 1;
                }
                type.t &= ~SC_EXTERN;
                sym = external_sym(v, &type, 0, &ad);
                if (sym->type.t & SC_INLINE) {
                    InlineFunc *fn;
                    fn = xcalloc(sizeof *fn + strlen(file->name));
                    strcpy(fn->filename, file->name);
                    fn->sym = sym;
                    pvec_push(&inline_fns, fn);
                    skip_or_save_block(&fn->func_str);
                } else {
                    cur_text_section = ad.section;
                    if (!cur_text_section)
                        cur_text_section = text_section;
                    else if (cur_text_section->sh_num > bss_section->sh_num)
                        cur_text_section->sh_flags = text_section->sh_flags;
                    gen_function(sym);
                }
                break;
            } else {
                if (l == VL_CMP) {
                    for (sym = func_vt.ref->next; sym; sym = sym->next)
                        if ((sym->v & ~SYM_FIELD) == v)
                            goto found;
                    error("declaration for parameter '%s' but no such parameter", tokname(v, NULL));
                found:
                    if (type.t & SC_MASK)
                        error("storage class specified for '%s'", tokname(v, NULL));
                    if (sym->type.t != TY_VOID)
                        error("redefinition of parameter '%s'", tokname(v, NULL));
                    convert_parameter_type(&type);
                    sym->type = type;
                } else if (type.t & SC_TYPEDEF) {
                    sym = sym_find(v);
                    if (sym && sym->scope == local_scope) {
                        if (!is_compatible_types(&sym->type, &type)
                            || !(sym->type.t & SC_TYPEDEF))
                            error("incompatible redefinition of '%s'", tokname(v, NULL));
                        sym->type = type;
                    } else {
                        sym = sym_push(v, &type, 0, 0);
                    }
                    sym->aligned = ad.aligned;
                    sym->packed = ad.packed;
                    sym->weak = ad.weak;
                    sym->visibility = ad.visibility;
                    if ((type.t & TY_MASK) == TY_FUNC) {
                        Sym *f = sym->type.ref;
                        if (ad.func_call && !f->func_call) f->func_call = ad.func_call;
                        if (ad.noreturn) f->noreturn = 1;
                    }
                } else if ((type.t & TY_MASK) == TY_VOID && !(type.t & SC_EXTERN)) {
                    error("declaration of void object");
                } else {
                    r = 0;
                    if ((type.t & TY_MASK) == TY_FUNC) {
                        Sym *f = type.ref;
                        if (ad.func_call && !f->func_call) f->func_call = ad.func_call;
                        if (ad.noreturn) f->noreturn = 1;
                        if (ad.ctor) f->ctor = 1;
                        if (ad.dtor) f->dtor = 1;
                        if (ad.alwinl) f->alwinl = 1;
                    } else if (!(type.t & TQ_ARRAY)) {
                        r |= VF_LVAL;
                    }
                    has_init = (tok == '=');
                    if (has_init && (type.t & TQ_VLA))
                        error("variable length array cannot be initialized");
                    if (((type.t & SC_EXTERN) && (!has_init || l != VL_CONST))
                        || (type.t & TY_MASK) == TY_FUNC
                        || ((type.t & TQ_ARRAY) && !has_init && l == VL_CONST && type.ref->c < 0)) {
                        type.t |= SC_EXTERN;
                        sym = external_sym(v, &type, r, &ad);
                        if (ad.alias_target) {
                            Sym *alias_target = sym_find(ad.alias_target);
                            ElfW(Sym) *esym = elfsym(alias_target);
                            if (!esym)
                                error("unsupported forward __alias__ attribute");
                            put_extern_sym2(sym, esym->st_shndx, esym->st_value, esym->st_size, 1);
                        }
                    } else {
                        if (l == VL_CONST || (type.t & SC_STATIC))
                            r |= VL_CONST;
                        else
                            r |= VL_LOCAL;
                        if (has_init)
                            next();
                        else if (l == VL_CONST)
                            type.t |= SC_EXTERN;
                        decl_initializer_alloc(&type, &ad, r, has_init, v, l == VL_CONST);
                    }
                }
                if (tok != ',') {
                    if (l == VL_JMP)
                        return 1;
                    skip(';');
                    break;
                }
                next();
            }
        }
    }
    return 0;
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/gen_init.c <<'EOF'
/* initializers, declarations, function definitions */
#include "gen.h"

#define TYPE_ABSTRACT 1
#define TYPE_DIRECT 2
#define TYPE_PARAM 4
#define TYPE_NEST 8

#define DIF_FIRST     1
#define DIF_SIZE_ONLY 2
#define DIF_HAVE_ELEM 4
#define DIF_CLEAR     8

#define EXPR_CONST 1
#define EXPR_ANY   2

typedef struct InitParams {
    Section *sec;
    int local_offset;
    Sym *flex_array_ref;
} InitParams;

extern int global_expr;
extern void skip_or_save_block(TokSeq **str);
extern void parse_attribute(Attr *ad);
extern int asm_label_instr(void);
extern void convert_parameter_type(Type *pt);
extern void sym_to_attr(Attr *ad, Sym *s);
extern Sym *find_field_pub(Type *type, int v, int *cumofs);
extern void block_pub(int flags);
extern void push_reader_arr(const int *a, int *owned);
extern void eh_frame_func(unsigned long func_start, unsigned long func_size);
extern void scope_new_func(void);
extern void scope_add_cleanup(Sym *sym, Sym *func);
extern void scope_vla_decl(Type *type, int addr);
extern void func_vla_arg(Sym *sym);
extern void label_pop(Sym **ptop, Sym *slast, int keep);
extern void cleanups_reset(void);

static void decl_initializer(InitParams *p, Type *type, unsigned long c, int flags);
static Str initstr;

/* ------------------------------------------------------------ init helpers */
static void parse_init_elem(int expr_type)
{
    int saved_global_expr;
    switch (expr_type) {
    case EXPR_CONST:
        saved_global_expr = global_expr;
        global_expr = 1;
        expr_const1();
        global_expr = saved_global_expr;
        if (((vtop->r & (VL_MASK | VF_LVAL)) != VL_CONST
             && ((vtop->r & (VF_SYM | VF_LVAL)) != (VF_SYM | VF_LVAL)
                 || vtop->sym->v < SYM_FIRST_ANOM)))
            error("initializer element is not constant");
        break;
    case EXPR_ANY:
        expr_eq();
        break;
    }
}

static void init_putz(InitParams *p, unsigned long c, int size)
{
    if (p->sec) {
    } else {
        vpush_helper_func(KW_memset);
        vseti(VL_LOCAL, c);
        vpushi(0);
        vpushs(size);
        gfunc_call(3);
    }
}

static void decl_design_delrels(Section *sec, int c, int size)
{
    ElfW(Rela) *rel, *rel2, *rel_end;
    if (!sec || !sec->reloc)
        return;
    rel = rel2 = (ElfW(Rela) *)sec->reloc->data;
    rel_end = (ElfW(Rela) *)(sec->reloc->data + sec->reloc->data_offset);
    while (rel < rel_end) {
        if (rel->r_offset >= (unsigned long)c && rel->r_offset < (unsigned long)(c + size)) {
            sec->reloc->data_offset -= sizeof *rel;
        } else {
            if (rel2 != rel)
                memcpy(rel2, rel, sizeof *rel);
            ++rel2;
        }
        ++rel;
    }
}

static void decl_design_flex(InitParams *p, Sym *ref, int index)
{
    if (ref == p->flex_array_ref) {
        if (index >= ref->c)
            ref->c = index + 1;
    } else if (ref->c < 0)
        error("flexible array has zero size in this context");
}

void init_putv_p(InitParams *p, Type *type, unsigned long c);

static int decl_designator(InitParams *p, Type *type, unsigned long c,
                           Sym **cur_field, int flags, int al)
{
    Sym *s, *f;
    int index, index_last, align, l, nb_elems, elem_size;
    unsigned long corig = c;

    elem_size = 0;
    nb_elems = 1;

    if (flags & DIF_HAVE_ELEM)
        goto no_designator;

    if (opt.gnu_ext && tok >= KW_DEFINE) {
        l = tok, next();
        if (tok == ':')
            goto struct_field;
        unget_tok(l);
    }

    while (nb_elems == 1 && (tok == '[' || tok == '.')) {
        if (tok == '[') {
            if (!(type->t & TQ_ARRAY))
                expect("array type");
            next();
            index = index_last = expr_const();
            if (tok == T_ELLIPSIS && opt.gnu_ext) {
                next();
                index_last = expr_const();
            }
            skip(']');
            s = type->ref;
            decl_design_flex(p, s, index_last);
            if (index < 0 || index_last >= s->c || index_last < index)
                error("index exceeds array bounds or range is empty");
            if (cur_field)
                (*cur_field)->c = index_last;
            type = pointed_type(type);
            elem_size = type_size(type, &align);
            c += index * elem_size;
            nb_elems = index_last - index + 1;
        } else {
            int cumofs;
            next();
            l = tok;
        struct_field:
            next();
            f = find_field_pub(type, l, &cumofs);
            if (cur_field)
                *cur_field = f;
            type = &f->type;
            c += cumofs;
        }
        cur_field = NULL;
    }
    if (!cur_field) {
        if (tok == '=') {
            next();
        } else if (!opt.gnu_ext) {
            expect("=");
        }
    } else {
    no_designator:
        if (type->t & TQ_ARRAY) {
            index = (*cur_field)->c;
            s = type->ref;
            decl_design_flex(p, s, index);
            if (index >= s->c)
                error("too many initializers");
            type = pointed_type(type);
            elem_size = type_size(type, &align);
            c += index * elem_size;
        } else {
            f = *cur_field;
            while (f && (f->v & SYM_FIRST_ANOM) && is_integer_btype(f->type.t & TY_MASK))
                *cur_field = f = f->next;
            if (!f)
                error("too many initializers");
            type = &f->type;
            c += f->c;
        }
    }

    if (!elem_size)
        elem_size = type_size(type, &align);

    if (!(flags & DIF_SIZE_ONLY) && (long)(c - corig) < al) {
        decl_design_delrels(p->sec, c, elem_size * nb_elems);
        flags &= ~DIF_CLEAR;
    }

    decl_initializer(p, type, c, flags & ~DIF_FIRST);

    if (!(flags & DIF_SIZE_ONLY) && nb_elems > 1) {
        Sym aref;
        Type t1;
        int i;
        memset(&aref, 0, sizeof aref);
        if (p->sec || (type->t & TQ_ARRAY)) {
            aref.c = elem_size;
            t1.t = TY_STRUCT, t1.ref = &aref;
            type = &t1;
        }
        if (p->sec)
            vpush_ref(type, p->sec, c, elem_size);
        else
            vset(type, VL_LOCAL | VF_LVAL, c);
        for (i = 1; i < nb_elems; i++) {
            vdup();
            init_putv_p(p, type, c + elem_size * i);
        }
        vpop();
    }

    c += nb_elems * elem_size;
    if ((long)(c - corig) > al)
        al = c - corig;
    return al;
}

void init_putv_p(InitParams *p, Type *type, unsigned long c)
{
    int bt;
    void *ptr;
    Type dtype;
    int size, align;
    Section *sec = p->sec;
    uint64_t val;

    dtype = *type;
    dtype.t &= ~TQ_CONST;

    size = type_size(type, &align);
    if (type->t & TQ_BITFIELD)
        size = (BIT_POS(type->t) + BIT_SIZE(type->t) + 7) / 8;

    if (sec) {
        gen_assign_cast(&dtype);
        bt = type->t & TY_MASK;

        if ((vtop->r & VF_SYM)
            && bt != TY_PTR
            && (bt != TY_I64 || (type->t & TQ_BITFIELD))
            && !((vtop->r & VL_CONST) && vtop->sym->v >= SYM_FIRST_ANOM))
            error("initializer element is not computable at load time");

        if (NODATA_WANTED) {
            vtop--;
            return;
        }

        ptr = sec->data + c;
        val = vtop->c.i;

        if ((vtop->r & (VF_SYM | VL_CONST)) == (VF_SYM | VL_CONST) &&
            vtop->sym->v >= SYM_FIRST_ANOM &&
            (vtop->type.t & TY_MASK) != TY_PTR) {
            Section *ssec;
            ElfW(Sym) *esym;
            ElfW(Rela) *rel;
            esym = elfsym(vtop->sym);
            ssec = sections[esym->st_shndx];
            memmove(ptr, ssec->data + esym->st_value + (int)vtop->c.i, size);
            if (ssec->reloc) {
                unsigned long relofs = ssec->reloc->data_offset;
                while (relofs >= sizeof(*rel)) {
                    relofs -= sizeof(*rel);
                    rel = (ElfW(Rela) *)(ssec->reloc->data + relofs);
                    if (rel->r_offset >= esym->st_value + size)
                        continue;
                    if (rel->r_offset < esym->st_value)
                        break;
                    put_elf_reloca(symtab_section, sec,
                                   c + rel->r_offset - esym->st_value,
                                   ELFW(R_TYPE)(rel->r_info),
                                   ELFW(R_SYM)(rel->r_info),
                                   rel->r_addend);
                }
            }
        } else {
            if (type->t & TQ_BITFIELD) {
                int bit_pos, bit_size, bits, n;
                unsigned char *pp, v, m;
                bit_pos = BIT_POS(vtop->type.t);
                bit_size = BIT_SIZE(vtop->type.t);
                pp = (unsigned char *)ptr + (bit_pos >> 3);
                bit_pos &= 7, bits = 0;
                while (bit_size) {
                    n = 8 - bit_pos;
                    if (n > bit_size)
                        n = bit_size;
                    v = val >> bits << bit_pos;
                    m = ((1 << n) - 1) << bit_pos;
                    *pp = (*pp & ~m) | (v & m);
                    bits += n, bit_size -= n, bit_pos = 0, ++pp;
                }
            } else
                switch (bt) {
                case TY_BOOL:
                    *(char *)ptr = val != 0;
                    break;
                case TY_I8:
                    *(char *)ptr = val;
                    break;
                case TY_I16:
                    write16le(ptr, val);
                    break;
                case TY_F32:
                    write32le(ptr, val);
                    break;
                case TY_F64:
                    write64le(ptr, val);
                    break;
                case TY_F80:
                    memcpy(ptr, &vtop->c.ld, 10);
                    break;
                case TY_I64:
                case TY_PTR:
                    if (vtop->r & VF_SYM)
                        greloca(sec, vtop->sym, c, R_X86_64_64, val);
                    else
                        write64le(ptr, val);
                    break;
                case TY_I32:
                    write32le(ptr, val);
                    break;
                default:
                    break;
                }
        }
        vtop--;
    } else {
        vset(&dtype, VL_LOCAL | VF_LVAL, c);
        vswap();
        vstore();
        vpop();
    }
}

/* used by gv() to store float constants */
void init_putv_rodata(Type *type, Section *sec, unsigned long c)
{
    InitParams p;
    memset(&p, 0, sizeof p);
    p.sec = sec;
    init_putv_p(&p, type, c);
}

static void decl_initializer(InitParams *p, Type *type, unsigned long c, int flags)
{
    int len, n, no_oblock, i;
    int size1, align1;
    Sym *s, *f;
    Sym indexsym;
    Type *t1;

    if (!(flags & DIF_HAVE_ELEM) && tok != '{' &&
        tok != T_WSTR && tok != T_STR &&
        (!(flags & DIF_SIZE_ONLY) || (type->t & TY_MASK) == TY_STRUCT)) {
        int ncw_prev = nocode_wanted;
        if ((flags & DIF_SIZE_ONLY) && !p->sec)
            ++nocode_wanted;
        parse_init_elem(!p->sec ? EXPR_ANY : EXPR_CONST);
        nocode_wanted = ncw_prev;
        flags |= DIF_HAVE_ELEM;
    }

    if (type->t & TQ_ARRAY) {
        no_oblock = 1;
        if (((flags & DIF_FIRST) && tok != T_WSTR && tok != T_STR) || tok == '{') {
            skip('{');
            no_oblock = 0;
        }

        s = type->ref;
        n = s->c;
        t1 = pointed_type(type);
        size1 = type_size(t1, &align1);

        if ((tok == T_WSTR && (t1->t & TY_MASK) == TY_I32) ||
            (tok == T_STR && (t1->t & TY_MASK) == TY_I8)) {
            len = 0;
            str_clear(&initstr);
            if (size1 != (tok == T_STR ? 1 : 4))
                error("unhandled string literal merging");
            while (tok == T_STR || tok == T_WSTR) {
                if (initstr.len)
                    initstr.len -= size1;
                if (tok == T_STR)
                    len += tokc.str.n;
                else
                    len += tokc.str.n / 4;
                len--;
                str_putn(&initstr, tokc.str.s, tokc.str.n);
                next();
            }
            if (tok != ')' && tok != '}' && tok != ',' && tok != ';' && tok != T_EOF) {
                unget_tok(size1 == 1 ? T_STR : T_WSTR);
                tokc.str.n = initstr.len;
                tokc.str.s = initstr.s;
                goto do_init_array;
            }

            decl_design_flex(p, s, len);
            if (!(flags & DIF_SIZE_ONLY)) {
                int nb = n, ch;
                if (len < nb)
                    nb = len;
                if (len > nb)
                    warning("initializer-string for array is too long");
                if (p->sec && size1 == 1) {
                    if (!NODATA_WANTED)
                        memcpy(p->sec->data + c, initstr.s, nb);
                } else {
                    for (i = 0; i < n; i++) {
                        if (i >= nb) {
                            if (flags & DIF_CLEAR)
                                break;
                            if (n - i >= 4) {
                                init_putz(p, c + i * size1, (n - i) * size1);
                                break;
                            }
                            ch = 0;
                        } else if (size1 == 1)
                            ch = ((unsigned char *)initstr.s)[i];
                        else
                            ch = ((int *)initstr.s)[i];
                        vpushi(ch);
                        init_putv_p(p, t1, c + i * size1);
                    }
                }
            }
        } else {
        do_init_array:
            memset(&indexsym, 0, sizeof indexsym);
            indexsym.c = 0;
            f = &indexsym;
        do_init_list:
            if (!(flags & (DIF_CLEAR | DIF_SIZE_ONLY))) {
                init_putz(p, c, n * size1);
                flags |= DIF_CLEAR;
            }
            len = 0;
            decl_design_flex(p, s, len);
            while (tok != '}' || (flags & DIF_HAVE_ELEM)) {
                len = decl_designator(p, type, c, &f, flags, len);
                flags &= ~DIF_HAVE_ELEM;
                if (type->t & TQ_ARRAY) {
                    ++indexsym.c;
                    if (no_oblock && len >= n * size1)
                        break;
                } else {
                    if (s->type.t == TY_UNION)
                        f = NULL;
                    else
                        f = f->next;
                    if (no_oblock && f == NULL)
                        break;
                }
                if (tok == '}')
                    break;
                skip(',');
            }
        }
        if (!no_oblock)
            skip('}');
    } else if ((flags & DIF_HAVE_ELEM)
               && is_compatible_unqualified_types(type, &vtop->type)) {
        goto one_elem;
    } else if ((type->t & TY_MASK) == TY_STRUCT) {
        no_oblock = 1;
        if ((flags & DIF_FIRST) || tok == '{') {
            skip('{');
            no_oblock = 0;
        }
        s = type->ref;
        f = s->next;
        n = s->c;
        size1 = 1;
        goto do_init_list;
    } else if (tok == '{') {
        if (flags & DIF_HAVE_ELEM)
            skip(';');
        next();
        decl_initializer(p, type, c, flags & ~DIF_HAVE_ELEM);
        skip('}');
    } else
    one_elem:
        if ((flags & DIF_SIZE_ONLY)) {
            if (flags & DIF_HAVE_ELEM)
                vpop();
            else
                skip_or_save_block(NULL);
        } else {
            if (!(flags & DIF_HAVE_ELEM)) {
                if (tok != T_STR && tok != T_WSTR)
                    expect("string constant");
                parse_init_elem(!p->sec ? EXPR_ANY : EXPR_CONST);
            }
            if (!p->sec && (flags & DIF_CLEAR)
                && (vtop->r & (VL_MASK | VF_LVAL | VF_SYM)) == VL_CONST
                && vtop->c.i == 0
                && btype_size(type->t & TY_MASK))
                vpop();
            else
                init_putv_p(p, type, c);
        }
}

/* ------------------------------------------------------------ storage */
static void patch_type(Sym *sym, Type *type)
{
    if (!(type->t & SC_EXTERN) || IS_ENUMVAL(sym->type.t)) {
        if (!(sym->type.t & SC_EXTERN))
            error("redefinition of '%s'", tokname(sym->v, NULL));
        sym->type.t &= ~SC_EXTERN;
    }

    if (IS_ASM_SYM_(sym)) {
        sym->type.t = type->t & (sym->type.t | ~SC_STATIC);
        sym->type.ref = type->ref;
        if ((type->t & TY_MASK) != TY_FUNC && !(type->t & TQ_ARRAY))
            sym->r |= VF_LVAL;
    }

    if (!is_compatible_types(&sym->type, type)) {
        error("incompatible types for redefinition of '%s'", tokname(sym->v, NULL));
    } else if ((sym->type.t & TY_MASK) == TY_FUNC) {
        int static_proto = sym->type.t & SC_STATIC;
        if ((type->t & SC_STATIC) && !static_proto
            && !((type->t | sym->type.t) & SC_INLINE))
            warning("static storage ignored for redefinition of '%s'", tokname(sym->v, NULL));
        if ((type->t | sym->type.t) & SC_INLINE) {
            if (!((type->t ^ sym->type.t) & SC_INLINE)
                || ((type->t | sym->type.t) & SC_STATIC))
                static_proto |= SC_INLINE;
        }
        if (0 == (type->t & SC_EXTERN)) {
            Sym f = *sym->type.ref;
            sym->type.t = (type->t & ~(SC_STATIC | SC_INLINE)) | static_proto;
            sym->type.ref = type->ref;
            {
                Sym *r = sym->type.ref;
                if (f.func_call && !r->func_call) r->func_call = f.func_call;
                if (f.noreturn) r->noreturn = 1;
                if (f.ctor) r->ctor = 1;
                if (f.dtor) r->dtor = 1;
                if (f.alwinl) r->alwinl = 1;
            }
        } else {
            sym->type.t &= ~SC_INLINE | static_proto;
        }
        if (sym->type.ref->functype == FUNC_OLD && type->ref->functype != FUNC_OLD) {
            sym->type.ref = type->ref;
        }
    } else {
        if ((sym->type.t & TQ_ARRAY) && type->ref->c >= 0) {
            sym->type.ref->c = type->ref->c;
        }
        if ((type->t ^ sym->type.t) & SC_STATIC)
            warning("storage mismatch for redefinition of '%s'", tokname(sym->v, NULL));
    }
}

static void patch_storage(Sym *sym, Attr *ad, Type *type)
{
    if (type)
        patch_type(sym, type);
    sym->weak |= ad->weak;
    if (ad->visibility) {
        int vis = sym->visibility;
        int vis2 = ad->visibility;
        if (vis == STV_DEFAULT)
            vis = vis2;
        else if (vis2 != STV_DEFAULT)
            vis = (vis < vis2) ? vis : vis2;
        sym->visibility = vis;
    }
    if (ad->aligned)
        sym->aligned = ad->aligned;
    if (ad->asm_label)
        sym->asm_label = ad->asm_label;
    update_storage(sym);
}

static Sym *sym_copy(Sym *s0, Sym **ps)
{
    Sym *s;
    s = xcalloc(sizeof(Sym));
    *s = *s0;
    s->prev = *ps, *ps = s;
    if (s->v < SYM_FIRST_ANOM) {
        Sym **pp = &ident_of(s->v)->sym_id;
        s->shadow = *pp, *pp = s;
    }
    return s;
}

static void sym_copy_ref(Sym *s, Sym **ps)
{
    int bt = s->type.t & TY_MASK;
    if (bt == TY_FUNC || bt == TY_PTR || (bt == TY_STRUCT && s->scope)) {
        Sym **sp = &s->type.ref;
        for (s = *sp, *sp = NULL; s; s = s->next) {
            Sym *s2 = sym_copy(s, ps);
            sp = &(*sp = s2)->next;
            sym_copy_ref(s2, ps);
        }
    }
}

static Sym *external_sym(int v, Type *type, int r, Attr *ad)
{
    Sym *s;
    s = sym_find(v);
    while (s && s->scope)
        s = s->shadow;
    if (!s) {
        s = global_identifier_push(v, type->t, 0);
        s->r |= r;
        s->aligned = ad->aligned;
        s->packed = ad->packed;
        s->weak = ad->weak;
        s->visibility = ad->visibility;
        s->nodebug = ad->nodebug;
        s->dllimport = ad->dllimport;
        s->dllexport = ad->dllexport;
        s->asm_label = ad->asm_label;
        s->type.ref = type->ref;
        if (local_stack)
            sym_copy_ref(s, &global_stack);
    } else {
        patch_storage(s, ad, type);
    }
    if (local_stack && (s->type.t & TY_MASK) != TY_FUNC)
        s = sym_copy(s, &local_stack);
    return s;
}

/* ------------------------------------------------------------ allocation */
void decl_initializer_alloc(Type *type, Attr *ad, int r, int has_init, int v, int global)
{
    int size, align, addr = 0;
    TokSeq *init_str = NULL;
    Section *sec;
    Sym *flexible_array;
    Sym *sym;
    int saved_nocode_wanted = nocode_wanted;
    InitParams p;
    memset(&p, 0, sizeof p);

    if (v && (r & VL_MASK) == VL_CONST)
        nocode_wanted |= DATA_ONLY_WANTED;

    flexible_array = NULL;
    size = type_size(type, &align);

    if (size < 0) {
        type->ref = sym_push(SYM_FIELD, &type->ref->type, 0, type->ref->c);
        p.flex_array_ref = type->ref;
    } else if (has_init && (type->t & TY_MASK) == TY_STRUCT) {
        Sym *field = type->ref->next;
        if (field) {
            while (field->next)
                field = field->next;
            if (field->type.t & TQ_ARRAY && field->type.ref->c < 0) {
                flexible_array = field;
                p.flex_array_ref = field->type.ref;
                size = -1;
            }
        }
    }

    if (size < 0) {
        if (!has_init)
            error("unknown type size");
        if (has_init == 2) {
            init_str = tseq_new();
            while (tok == T_STR || tok == T_WSTR) {
                tseq_add_cur(init_str);
                next();
            }
            tseq_add(init_str, -1);
            tseq_add(init_str, 0);
        } else
            skip_or_save_block(&init_str);
        unget_tok(0);

        push_reader(init_str, 2);
        next();
        decl_initializer(&p, type, 0, DIF_FIRST | DIF_SIZE_ONLY);
        mac_ptr = init_str->a;
        next();

        size = type_size(type, &align);
        if (size < 0)
            error("unknown type size");
        if (flexible_array && flexible_array->type.ref->c > 0)
            size += flexible_array->type.ref->c * pointed_size(&flexible_array->type);
    }

    if (ad->aligned) {
        int speca = 1 << (ad->aligned - 1);
        if (speca > align)
            align = speca;
    } else if (ad->packed) {
        align = 1;
    }

    if (!v && NODATA_WANTED)
        size = 0, align = 1;

    if ((r & VL_MASK) == VL_LOCAL) {
        sec = NULL;
        loc = (loc - size) & -align;
        addr = loc;
        p.local_offset = addr + size;
        if (v) {
            if (ad->asm_label) {
                int reg = asm_parse_regvar(ad->asm_label);
                if (reg >= 0)
                    r = (r & ~VL_MASK) | reg;
            }
            sym = sym_push(v, type, r, addr);
            if (ad->cleanup_func)
                scope_add_cleanup(sym, ad->cleanup_func);
            sym->aligned = ad->aligned;
            sym->packed = ad->packed;
            sym->weak = ad->weak;
            sym->visibility = ad->visibility;
        } else {
            vset(type, r, addr);
        }
    } else {
        sym = NULL;
        if (v && global) {
            sym = sym_find(v);
            if (sym) {
                if (p.flex_array_ref && (sym->type.t & type->t & TQ_ARRAY)
                    && sym->type.ref->c > type->ref->c) {
                    type->ref->c = sym->type.ref->c;
                    size = type_size(type, &align);
                }
                patch_storage(sym, ad, type);
                if (!has_init && sym->elfsym && elfsym(sym)->st_shndx != SHN_UNDEF)
                    goto no_alloc;
            }
        }

        sec = ad->section;
        if (!sec) {
            Type *tp = type;
            while ((tp->t & (TY_MASK | TQ_ARRAY)) == (TY_PTR | TQ_ARRAY))
                tp = &tp->ref->type;
            if (tp->t & TQ_CONST) {
                sec = rodata_section;
            } else if (has_init) {
                sec = data_section;
            } else if (opt.nocommon)
                sec = bss_section;
        }

        if (sec) {
            addr = section_add(sec, size, align);
        } else {
            addr = align;
            sec = common_section;
        }

        if (v) {
            if (!sym) {
                sym = sym_push(v, type, r | VF_SYM, 0);
                patch_storage(sym, ad, NULL);
            }
            put_extern_sym(sym, sec, addr, size);
        } else {
            vpush_ref(type, sec, addr, size);
            sym = vtop->sym;
            vtop->r |= r;
        }
    }

    if (type->t & TQ_VLA) {
        if (NODATA_WANTED)
            goto no_alloc;
        scope_vla_decl(type, addr);
    } else if (has_init) {
        p.sec = sec;
        decl_initializer(&p, type, addr, DIF_FIRST);
        if (flexible_array)
            flexible_array->type.ref->c = -1;
    }

no_alloc:
    if (init_str) {
        pop_reader();
        tseq_free(init_str);
        next();
    }
    nocode_wanted = saved_nocode_wanted;
}

/* ------------------------------------------------------------ functions */
typedef struct InlineFunc {
    TokSeq *func_str;
    Sym *sym;
    char filename[1];
} InlineFunc;

static PVec inline_fns;
extern void check_func_return_pub(void);

void gen_function(Sym *sym)
{
    scope_new_func();
    nocode_wanted = 0;
    ind = cur_text_section->data_offset;
    if (sym->aligned) {
        size_t newoff = section_add(cur_text_section, 0, 1 << (sym->aligned - 1));
        gen_fill_nops(newoff - ind);
    }
    funcname = tokname(sym->v, NULL);
    funcname = xstrdup(funcname);
    func_ind = ind;
    func_vt = sym->type.ref->type;
    func_var = sym->type.ref->functype == FUNC_ELLIPSIS;

    put_extern_sym(sym, cur_text_section, ind, 0);

    if (sym->type.ref->ctor || sym->type.ref->dtor) {
        extern void add_init_array(const char *sec, Sym *sym);
        if (sym->type.ref->ctor)
            add_init_array(".init_array", sym);
        if (sym->type.ref->dtor)
            add_init_array(".fini_array", sym);
    }

    sym_push2(&local_stack, SYM_FIELD, 0, 0);
    local_scope = 1;
    gfunc_prolog(sym);
    local_scope = 0;
    rsym = 0;
    clear_temp_local_var_list();
    func_vla_arg(sym);
    block_pub(0);
    gsym(rsym);
    nocode_wanted = 0;
    sym_pop(&local_stack, NULL, 0);
    gfunc_epilog();
    eh_frame_func(func_ind, ind - func_ind);
    elfsym(sym)->st_size = ind - func_ind;
    cur_text_section->data_offset = ind;
    local_scope = 0;
    label_pop(&global_label_stack, NULL, 0);
    cleanups_reset();
    cur_text_section = NULL;
    funcname = "";
    func_vt.t = TY_VOID;
    func_var = 0;
    ind = 0;
    func_ind = -1;
    nocode_wanted = DATA_ONLY_WANTED;
    check_vstack();
    next();
}

void gen_inline_functions(void)
{
    Sym *sym;
    int inline_generated, i;
    InlineFunc *fn;
    src_open_buf(":inline:", "", 0);
    file->line = file->up ? file->up->line : 1;
    do {
        inline_generated = 0;
        for (i = 0; i < inline_fns.n; ++i) {
            fn = inline_fns.v[i];
            sym = fn->sym;
            if (sym && (sym->elfsym || !(sym->type.t & SC_INLINE))) {
                fn->sym = NULL;
                push_reader(fn->func_str, 2);
                next();
                cur_text_section = text_section;
                gen_function(sym);
                pop_reader();
                inline_generated = 1;
            }
        }
    } while (inline_generated);
    {
        SrcFile *f = file;
        file = f->up;
        free(f->buf);
        free(f->true_name);
        free(f);
    }
}

void free_inline_functions(void)
{
    for (int i = 0; i < inline_fns.n; i++) {
        InlineFunc *fn = inline_fns.v[i];
        if (fn->func_str) tseq_free(fn->func_str);
        free(fn);
    }
    free(inline_fns.v);
    memset(&inline_fns, 0, sizeof inline_fns);
}

static void do_Static_assert(void)
{
    int c;
    const char *msg;
    next();
    skip('(');
    c = expr_const();
    msg = "_Static_assert fail";
    if (tok == ',') {
        next();
        msg = (char *)xstrdup(parse_mult_str_pub("string constant"));
    }
    skip(')');
    if (c == 0)
        error("%s", msg);
    skip(';');
}

int decl(int l)
{
    int v, has_init, r, oldint;
    Type type, btype;
    Sym *sym;
    Attr ad, adbase;

    while (1) {
        oldint = 0;
        if (!parse_btype(&btype, &adbase, l == VL_LOCAL)) {
            if (l == VL_JMP)
                return 0;
            if (tok == ';' && l != VL_CMP) {
                next();
                continue;
            }
            if (tok == KW_STATIC_ASSERT) {
                do_Static_assert();
                continue;
            }
            if (l != VL_CONST)
                break;
            if (tok == KW_ASM1 || tok == KW_ASM2 || tok == KW_ASM3) {
                asm_global_instr();
                continue;
            }
            if (tok >= KW_DEFINE) {
                btype.t = TY_I32;
                oldint = 1;
            } else {
                if (tok != T_EOF)
                    expect("declaration");
                break;
            }
        }

        if (tok == ';') {
            if ((btype.t & TY_MASK) == TY_STRUCT) {
                v = btype.ref->v;
                if (!(v & SYM_FIELD) && (v & ~SYM_STRUCT) >= SYM_FIRST_ANOM)
                    warning("useless type defines no instances");
                next();
                continue;
            }
            if (IS_ENUM(btype.t)) {
                next();
                continue;
            }
            warning("useless type defines no instances");
            next();
            continue;
        }

        while (1) {
            type = btype;
            ad = adbase;
            type_decl(&type, &ad, &v, TYPE_DIRECT);
            if (oldint && (type.t & TY_MASK) != TY_FUNC)
                warning("type defaults to int");
            if ((type.t & TY_MASK) == TY_FUNC) {
                if ((type.t & SC_STATIC) && (l != VL_CONST))
                    error("function without file scope cannot be static");
                sym = type.ref;
                if (sym->functype == FUNC_OLD && l == VL_CONST) {
                    func_vt = type;
                    decl(VL_CMP);
                }
            }

            if (opt.gnu_ext && (tok == KW_ASM1 || tok == KW_ASM2 || tok == KW_ASM3)) {
                ad.asm_label = asm_label_instr();
                parse_attribute(&ad);
            }

            if (tok == '{') {
                if (l != VL_CONST)
                    error("cannot use local functions");
                if ((type.t & TY_MASK) != TY_FUNC)
                    expect("function definition");
                sym = type.ref;
                while ((sym = sym->next) != NULL) {
                    if (!(sym->v & ~SYM_FIELD))
                        expect("identifier");
                    if (sym->type.t == TY_VOID)
                        sym->type = int_type;
                }
                {
                    Sym *f = type.ref;
                    if (ad.func_call && !f->func_call) f->func_call = ad.func_call;
                    if (ad.noreturn) f->noreturn = 1;
                    if (ad.ctor) f->ctor = 1;
                    if (ad.dtor) f->dtor = 1;
                    if (ad.alwinl) f->alwinl = 1;
                }
                type.t &= ~SC_EXTERN;
                sym = external_sym(v, &type, 0, &ad);
                if (sym->type.t & SC_INLINE) {
                    InlineFunc *fn;
                    fn = xcalloc(sizeof *fn + strlen(file->name));
                    strcpy(fn->filename, file->name);
                    fn->sym = sym;
                    pvec_push(&inline_fns, fn);
                    skip_or_save_block(&fn->func_str);
                } else {
                    cur_text_section = ad.section;
                    if (!cur_text_section)
                        cur_text_section = text_section;
                    else if (cur_text_section->sh_num > bss_section->sh_num)
                        cur_text_section->sh_flags = text_section->sh_flags;
                    gen_function(sym);
                }
                break;
            } else {
                if (l == VL_CMP) {
                    for (sym = func_vt.ref->next; sym; sym = sym->next)
                        if ((sym->v & ~SYM_FIELD) == v)
                            goto found;
                    error("declaration for parameter '%s' but no such parameter", tokname(v, NULL));
                found:
                    if (type.t & SC_MASK)
                        error("storage class specified for '%s'", tokname(v, NULL));
                    if (sym->type.t != TY_VOID)
                        error("redefinition of parameter '%s'", tokname(v, NULL));
                    convert_parameter_type(&type);
                    sym->type = type;
                } else if (type.t & SC_TYPEDEF) {
                    sym = sym_find(v);
                    if (sym && sym->scope == local_scope) {
                        if (!is_compatible_types(&sym->type, &type)
                            || !(sym->type.t & SC_TYPEDEF))
                            error("incompatible redefinition of '%s'", tokname(v, NULL));
                        sym->type = type;
                    } else {
                        sym = sym_push(v, &type, 0, 0);
                    }
                    sym->aligned = ad.aligned;
                    sym->packed = ad.packed;
                    sym->weak = ad.weak;
                    sym->visibility = ad.visibility;
                    if ((type.t & TY_MASK) == TY_FUNC) {
                        Sym *f = sym->type.ref;
                        if (ad.func_call && !f->func_call) f->func_call = ad.func_call;
                        if (ad.noreturn) f->noreturn = 1;
                    }
                } else if ((type.t & TY_MASK) == TY_VOID && !(type.t & SC_EXTERN)) {
                    error("declaration of void object");
                } else {
                    r = 0;
                    if ((type.t & TY_MASK) == TY_FUNC) {
                        Sym *f = type.ref;
                        if (ad.func_call && !f->func_call) f->func_call = ad.func_call;
                        if (ad.noreturn) f->noreturn = 1;
                        if (ad.ctor) f->ctor = 1;
                        if (ad.dtor) f->dtor = 1;
                        if (ad.alwinl) f->alwinl = 1;
                    } else if (!(type.t & TQ_ARRAY)) {
                        r |= VF_LVAL;
                    }
                    has_init = (tok == '=');
                    if (has_init && (type.t & TQ_VLA))
                        error("variable length array cannot be initialized");
                    if (((type.t & SC_EXTERN) && (!has_init || l != VL_CONST))
                        || (type.t & TY_MASK) == TY_FUNC
                        || ((type.t & TQ_ARRAY) && !has_init && l == VL_CONST && type.ref->c < 0)) {
                        type.t |= SC_EXTERN;
                        sym = external_sym(v, &type, r, &ad);
                        if (ad.alias_target) {
                            Sym *alias_target = sym_find(ad.alias_target);
                            ElfW(Sym) *esym = elfsym(alias_target);
                            if (!esym)
                                error("unsupported forward __alias__ attribute");
                            put_extern_sym2(sym, esym->st_shndx, esym->st_value, esym->st_size, 1);
                        }
                    } else {
                        if (l == VL_CONST || (type.t & SC_STATIC))
                            r |= VL_CONST;
                        else
                            r |= VL_LOCAL;
                        if (has_init)
                            next();
                        else if (l == VL_CONST)
                            type.t |= SC_EXTERN;
                        decl_initializer_alloc(&type, &ad, r, has_init, v, l == VL_CONST);
                    }
                }
                if (tok != ',') {
                    if (l == VL_JMP)
                        return 1;
                    skip(';');
                    break;
                }
                next();
            }
        }
    }
    return 0;
}
