/* statements and scopes */
#include "gen.h"

#define STMT_EXPR 2
#define STMT_COMPOUND 4

#define LABEL_DEFINED 0
#define LABEL_FORWARD 1
#define LABEL_DECLARED 2
#define LABEL_GONE 3

extern void parse_attribute(Attr *ad);
extern int func_vla_dummy;

typedef struct Scope {
    struct Scope *prev;
    struct { int loc, locorig, num; } vla;
    struct { Sym *s; int n; } cl;
    int *bsym, *csym;
    Sym *lstk, *llstk;
} Scope;

static Scope *cur_scope, *loop_scope, *root_scope;
static Sym *all_cleanups, *pending_gotos;

typedef struct CaseT {
    long long v1, v2;
    int sym;
} CaseT;

typedef struct SwitchT {
    CaseT **p;
    int n;
    int cap;
    int def_sym;
