} SwitchT;

static SwitchT *cur_switch;
static Scope func_root;

void block(int flags);

void label_pop(Sym **ptop, Sym *slast, int keep)
{
    Sym *s, *s1;
    for (s = *ptop; s != slast; s = s1) {
        s1 = s->prev;
        if (s->r == LABEL_DECLARED) {
            warning_opt(WOPT_ALL, "label '%s' declared but not used", tokname(s->v, NULL));
        } else if (s->r == LABEL_FORWARD) {
            error("label '%s' used but not defined", tokname(s->v, NULL));
        } else {
            if (s->elfsym) {
                put_extern_sym(s, cur_text_section, s->jnext, 1);
            }
        }
        if (s->r != LABEL_GONE)
            ident_of(s->v)->sym_label = s->shadow;
        if (!keep)
            sym_free(s);
        else
            s->r = LABEL_GONE;
    }
    if (!keep)
        *ptop = slast;
}

void scope_new_func(void)
{
    memset(&func_root, 0, sizeof func_root);
    cur_scope = root_scope = &func_root;
    loop_scope = NULL;
    cur_switch = NULL;
}

void cleanups_reset(void)
{
    sym_pop(&all_cleanups, NULL, 0);
    pending_gotos = NULL;
}

void scope_add_cleanup(Sym *sym, Sym *func)
{
    Sym *cls = sym_push2(&all_cleanups, SYM_FIELD | ++cur_scope->cl.n, 0, 0);
    cls->shadow = sym;
    cls->cleanup_func = func;
    cls->ncl = cur_scope->cl.s;
    cur_scope->cl.s = cls;
}

void scope_vla_decl(Type *type, int addr)
{
    int a;
    if (cur_scope->vla.num == 0) {
        if (cur_scope->prev && cur_scope->prev->vla.num) {
            cur_scope->vla.locorig = cur_scope->prev->vla.loc;
        } else {
            gen_vla_sp_save(loc -= PTR_SIZE);
            cur_scope->vla.locorig = loc;
        }
    }
    vpush_type_size(type, &a);
    gen_vla_alloc(type, a);
    gen_vla_sp_save(addr);
    cur_scope->vla.loc = addr;
    cur_scope->vla.num++;
}

/* VLA size slots are stored in local variables */
void vpush_vla_size(Type *type)
{
    vset(&int_type, VL_LOCAL | VF_LVAL, type->ref->c);
    gen_cast_s(TY_I64 | TQ_LONG | TQ_UNSIGNED);
}

void func_vla_arg(Sym *sym)
{
    Sym *arg;
    for (arg = sym->type.ref->next; arg; arg = arg->next) {
        if ((arg->type.t & TY_MASK) == TY_PTR && (arg->type.ref->type.t & TQ_VLA)) {
            Sym *s = arg->type.ref;
            while (s && (s->type.t & TQ_VLA)) {
                if (s->vla_tokens_) {
                    /* evaluate size expression */
                    TokSeq *ts = s->vla_tokens_;
                    int align;
                    loc -= type_size(&int_type, &align);
                    loc &= -align;
                    int n = loc;
                    push_reader(ts, 2);
                    next();
                    gexpr();
                    pop_reader();
                    vpush_type_size(&s->type.ref->type, &align);
                    gen_op('*');
                    vset(&int_type, VL_LOCAL | VF_LVAL, n);
                    vswap();
                    vstore();
                    vpop();
                    s->type.ref->c = n;
                }
                s = s->type.ref;
            }
        }
    }
}

static void try_call_scope_cleanup(Sym *stop)
{
    Sym *cls = cur_scope->cl.s;
    for (; cls != stop; cls = cls->ncl) {
        Sym *fs = cls->cleanup_func;
        Sym *vs = cls->shadow;
        vpushsym(&fs->type, fs);
        vset(&vs->type, vs->r, vs->c);
        vtop->sym = vs;
        mk_pointer(&vtop->type);
        gaddrof();
        gfunc_call(1);
    }
}

static void try_call_cleanup_goto(Sym *cleanupstate)
{
    Sym *oc, *cc;
    int ocd, ccd;
    if (!cur_scope->cl.s)
        return;
    ocd = cleanupstate ? cleanupstate->v & ~SYM_FIELD : 0;
    for (ccd = cur_scope->cl.n, oc = cleanupstate; ocd > ccd; --ocd, oc = oc->ncl)
        ;
    for (cc = cur_scope->cl.s; ccd > ocd; --ccd, cc = cc->ncl)
        ;
    for (; cc != oc; cc = cc->ncl, oc = oc->ncl, --ccd)
        ;
    try_call_scope_cleanup(cc);
}

static void block_cleanup(Scope *o)
{
    int jmp = 0;
    Sym *g, **pg;
    for (pg = &pending_gotos; (g = *pg) && g->c > o->cl.n;) {
        if (g->shadow->r & LABEL_FORWARD) {
            Sym *pcl = g->next;
            if (!jmp)
                jmp = gjmp(0);
            gsym(pcl->jnext);
            try_call_scope_cleanup(o->cl.s);
            pcl->jnext = gjmp(0);
            if (!o->cl.n)
                goto remove_pending;
            g->c = o->cl.n;
            pg = &g->prev;
        } else {
        remove_pending:
            *pg = g->prev;
            sym_free(g);
        }
    }
    gsym(jmp);
    try_call_scope_cleanup(o->cl.s);
}

static void vla_restore(int l)
{
    if (l)
        gen_vla_sp_restore(l);
}

static void vla_leave(Scope *o)
{
    Scope *c = cur_scope, *v = NULL;
    for (; c != o && c; c = c->prev)
        if (c->vla.num)
            v = c;
    if (v)
        vla_restore(v->vla.locorig);
}

static void new_scope(Scope *o)
{
    *o = *cur_scope;
    o->prev = cur_scope;
    cur_scope = o;
    cur_scope->vla.num = 0;
    o->lstk = local_stack;
    o->llstk = local_label_stack;
    ++local_scope;
}

static void pop_local_syms(Sym *b, int keep)
{
    sym_pop(&local_stack, b, keep);
}

static void prev_scope(Scope *o, int is_expr)
{
    vla_leave(o->prev);
    if (o->cl.s != o->prev->cl.s)
        block_cleanup(o->prev);
    label_pop(&local_label_stack, o->llstk, is_expr);
    pop_local_syms(o->lstk, is_expr);
    cur_scope = o->prev;
    --local_scope;
}

static void leave_scope(Scope *o)
{
    if (!o)
        return;
    try_call_scope_cleanup(o->cl.s);
    vla_leave(o);
}

static void new_scope_s(Scope *o)
{
    o->lstk = local_stack;
    ++local_scope;
}

static void prev_scope_s(Scope *o)
{
    sym_pop(&local_stack, o->lstk, 0);
    --local_scope;
}

static void lblock(int *bsym, int *csym)
{
    Scope *lo = loop_scope, *co = cur_scope;
    int *b = co->bsym, *c = co->csym;
    if (csym) {
        co->csym = csym;
        loop_scope = co;
    }
    co->bsym = bsym;
    block(0);
    co->bsym = b;
    if (csym) {
        co->csym = c;
        loop_scope = lo;
    }
}

static int case_cmpi(const void *pa, const void *pb)
{
    long long a = (*(CaseT **)pa)->v1;
    long long b = (*(CaseT **)pb)->v1;
    return a < b ? -1 : a > b;
}

static int case_cmpu(const void *pa, const void *pb)
{
    uint64_t a = (uint64_t)(*(CaseT **)pa)->v1;
    uint64_t b = (uint64_t)(*(CaseT **)pb)->v1;
    return a < b ? -1 : a > b;
}

static void gtst_addr(int t, int a)
{
    gsym_addr(gvtst(0, t), a);
}

static void gcase(CaseT **base, int len, int *bsym)
{
    CaseT *p;
    int e;
    int ll = (vtop->type.t & TY_MASK) == TY_I64;
    while (len > 8) {
        p = base[len / 2];
        vdup();
        if (ll)
            vpushll(p->v2);
        else
            vpushi(p->v2);
        gen_op(T_LE);
        e = gvtst(1, 0);
        vdup();
        if (ll)
            vpushll(p->v1);
        else
            vpushi(p->v1);
        gen_op(T_GE);
        gtst_addr(0, p->sym);
        gcase(base, len / 2, bsym);
        gsym(e);
        e = len / 2 + 1;
        base += e;
        len -= e;
    }
    while (len--) {
        p = *base++;
        vdup();
        if (ll)
            vpushll(p->v2);
        else
            vpushi(p->v2);
        if (p->v1 == p->v2) {
            gen_op(T_EQ);
            gtst_addr(0, p->sym);
        } else {
            gen_op(T_LE);
            e = gvtst(1, 0);
            vdup();
            if (ll)
                vpushll(p->v1);
            else
                vpushi(p->v1);
            gen_op(T_GE);
            gtst_addr(0, p->sym);
            gsym(e);
        }
    }
    *bsym = gjmp(*bsym);
}

static void check_func_return(void)
{
    if ((func_vt.t & TY_MASK) == TY_VOID)
        return;
    if (!strcmp(funcname, "main") && (func_vt.t & TY_MASK) == TY_I32) {
        vpushi(0);
        gen_assign_cast(&func_vt);
        gfunc_return(&func_vt);
    } else {
        warning("function might return no value: '%s'", funcname);
    }
}

void block(int flags)
{
    int a, b, c, d, e, t;
    Scope o;
    Sym *s;

    if (flags & STMT_EXPR) {
        vpushi(0);
        vtop->type.t = TY_VOID;
    }

again:
    t = tok;
    if (IS_VALTOK(t))
        goto expr;
    next();

    if (t == KW_IF) {
        new_scope_s(&o);
        skip('(');
        gexpr();
        skip(')');
        a = gvtst(1, 0);
        block(0);
        if (tok == KW_ELSE) {
            d = gjmp(0);
            gsym(a);
            next();
            block(0);
            gsym(d);
        } else {
            gsym(a);
        }
        prev_scope_s(&o);
    } else if (t == KW_WHILE) {
        new_scope_s(&o);
        d = gind();
        skip('(');
        gexpr();
        skip(')');
        a = gvtst(1, 0);
        b = 0;
        lblock(&a, &b);
        gjmp_addr(d);
        gsym_addr(b, d);
        gsym(a);
        prev_scope_s(&o);
    } else if (t == '{') {
        new_scope(&o);
        while (tok == KW_LABEL) {
            do {
                next();
                if (tok < KW_DEFINE)
                    expect("label identifier");
                label_push(&local_label_stack, tok, LABEL_DECLARED);
                next();
            } while (tok == ',');
            skip(';');
        }
        while (tok != '}') {
            decl(VL_LOCAL);
            if (tok != '}') {
                if (flags & STMT_EXPR)
                    vpop();
                block(flags | STMT_COMPOUND);
            }
        }
        prev_scope(&o, flags & STMT_EXPR);
        if (local_scope)
            next();
        else if (!nocode_wanted)
            check_func_return();
    } else if (t == KW_RETURN) {
        b = (func_vt.t & TY_MASK) != TY_VOID;
        if (tok != ';') {
            gexpr();
            if (b) {
                gen_assign_cast(&func_vt);
            } else {
                if (vtop->type.t != TY_VOID)
                    warning("void function returns a value");
                vtop--;
            }
        } else if (b) {
            warning("'return' with no value");
            b = 0;
        }
        leave_scope(root_scope);
        if (b)
            gfunc_return(&func_vt);
        skip(';');
        if (tok != '}' || local_scope != 1)
            rsym = gjmp_acs(rsym);
        CODE_OFF();
    } else if (t == KW_BREAK) {
        if (!cur_scope->bsym)
            error("cannot break");
        if (cur_switch && cur_scope->bsym == cur_switch->bsym)
            leave_scope(cur_switch->scope);
        else
            leave_scope(loop_scope);
        *cur_scope->bsym = gjmp_acs(*cur_scope->bsym);
        skip(';');
    } else if (t == KW_CONTINUE) {
        if (!cur_scope->csym)
            error("cannot continue");
        leave_scope(loop_scope);
        *cur_scope->csym = gjmp_acs(*cur_scope->csym);
        skip(';');
    } else if (t == KW_FOR) {
        new_scope(&o);
        skip('(');
        if (tok != ';') {
            if (!decl(VL_JMP)) {
                gexpr();
                vpop();
            }
        }
        skip(';');
        a = b = 0;
        c = d = gind();
        if (tok != ';') {
            gexpr();
            a = gvtst(1, 0);
        }
        skip(';');
        if (tok != ')') {
            e = gjmp_acs(0);
            d = gind();
            gexpr();
            vpop();
            gjmp_addr_acs(c);
            gsym(e);
        }
        skip(')');
        lblock(&a, &b);
        gjmp_addr_acs(d);
        gsym_addr(b, d);
        gsym(a);
        prev_scope(&o, 0);
    } else if (t == KW_DO) {
        new_scope_s(&o);
        a = b = 0;
        d = gind();
        lblock(&a, &b);
        gsym(b);
        skip(KW_WHILE);
        skip('(');
        gexpr();
        skip(')');
        skip(';');
        c = gvtst(0, 0);
        gsym_addr(c, d);
        gsym(a);
        prev_scope_s(&o);
    } else if (t == KW_SWITCH) {
        SwitchT *sw;
        sw = xcalloc(sizeof *sw);
        sw->bsym = &a;
        sw->scope = cur_scope;
        sw->prev = cur_switch;
        sw->nocode_wanted = nocode_wanted;
        cur_switch = sw;

        new_scope_s(&o);
        skip('(');
        gexpr();
        skip(')');
        if (!is_integer_btype(vtop->type.t & TY_MASK))
            error("switch value not an integer");
        sw->sv = *vtop--;

        a = 0;
        b = gjmp_acs(0);
        lblock(&a, NULL);
        a = gjmp_acs(a);
        gsym(b);
        prev_scope_s(&o);

        if (sw->nocode_wanted)
            goto skip_switch;
        if (sw->sv.type.t & TQ_UNSIGNED)
            qsort(sw->p, sw->n, sizeof(void *), case_cmpu);
        else
            qsort(sw->p, sw->n, sizeof(void *), case_cmpi);
        for (b = 1; b < sw->n; b++)
            if (sw->sv.type.t & TQ_UNSIGNED
                ? (uint64_t)sw->p[b - 1]->v2 >= (uint64_t)sw->p[b]->v1
                : sw->p[b - 1]->v2 >= sw->p[b]->v1)
                error("duplicate case value");
        vpushv(&sw->sv);
        gv(RC_INT);
        d = 0, gcase(sw->p, sw->n, &d);
        vpop();
        if (sw->def_sym)
            gsym_addr(d, sw->def_sym);
        else
            gsym(d);
    skip_switch:
        gsym(a);
        for (int i = 0; i < sw->n; i++) free(sw->p[i]);
        free(sw->p);
        cur_switch = sw->prev;
        free(sw);
    } else if (t == KW_CASE) {
        CaseT *cr = xcalloc(sizeof(CaseT));
        if (!cur_switch)
            expect("switch");
        cr->v1 = cr->v2 = expr_const64();
        if (opt.gnu_ext && tok == T_ELLIPSIS) {
            next();
            cr->v2 = expr_const64();
            if ((!(cur_switch->sv.type.t & TQ_UNSIGNED) && cr->v2 < cr->v1)
                || (cur_switch->sv.type.t & TQ_UNSIGNED && (uint64_t)cr->v2 < (uint64_t)cr->v1))
                warning("empty case range");
        }
        if (!cur_switch->nocode_wanted)
            cr->sym = gind();
        if (cur_switch->n == cur_switch->cap) {
            cur_switch->cap = cur_switch->cap ? cur_switch->cap * 2 : 8;
            cur_switch->p = xrealloc(cur_switch->p, cur_switch->cap * sizeof(CaseT *));
        }
        cur_switch->p[cur_switch->n++] = cr;
        skip(':');
        goto block_after_label;
    } else if (t == KW_DEFAULT) {
        if (!cur_switch)
            expect("switch");
        if (cur_switch->def_sym)
            error("too many 'default'");
        cur_switch->def_sym = cur_switch->nocode_wanted ? 1 : gind();
        skip(':');
        goto block_after_label;
    } else if (t == KW_GOTO) {
        vla_restore(cur_scope->vla.locorig);
        if (tok == '*' && opt.gnu_ext) {
            next();
            gexpr();
            if ((vtop->type.t & TY_MASK) != TY_PTR)
                expect("pointer");
            ggoto();
        } else if (tok >= KW_DEFINE) {
            s = label_find(tok);
            if (!s)
                s = label_push(&global_label_stack, tok, LABEL_FORWARD);
            else if (s->r == LABEL_DECLARED)
                s->r = LABEL_FORWARD;
            if (s->r & LABEL_FORWARD) {
                if (cur_scope->cl.s && !nocode_wanted) {
                    sym_push2(&pending_gotos, SYM_FIELD, 0, cur_scope->cl.n);
                    pending_gotos->shadow = s;
                    s = sym_push2(&s->next, SYM_FIELD, 0, 0);
                    pending_gotos->next = s;
                }
                s->jnext = gjmp_acs(s->jnext);
            } else {
                try_call_cleanup_goto(s->cleanup_state);
                gjmp_addr_acs(s->jnext);
            }
            next();
        } else {
            expect("label identifier");
        }
        skip(';');
    } else if (t == KW_ASM1 || t == KW_ASM2 || t == KW_ASM3) {
        asm_instr();
    } else {
        if (tok == ':' && t >= KW_DEFINE) {
            next();
            s = label_find(t);
            if (s) {
                if (s->r == LABEL_DEFINED)
                    error("duplicate label '%s'", tokname(s->v, NULL));
                s->r = LABEL_DEFINED;
                if (s->next) {
                    Sym *pcl;
                    for (pcl = s->next; pcl; pcl = pcl->prev)
                        gsym(pcl->jnext);
                    sym_pop(&s->next, NULL, 0);
                } else
                    gsym(s->jnext);
            } else {
                s = label_push(&global_label_stack, t, LABEL_DEFINED);
            }
            s->jnext = gind();
            s->cleanup_state = cur_scope->cl.s;
        block_after_label: {
                Attr ad_tmp;
                memset(&ad_tmp, 0, sizeof ad_tmp);
                parse_attribute(&ad_tmp);
            }
            vla_restore(cur_scope->vla.loc);
            if (tok != '}') {
                if (0 == (flags & STMT_COMPOUND))
                    goto again;
            } else {
                warning_opt(WOPT_ALL, "deprecated use of label at end of compound statement");
            }
        } else {
            if (t != ';') {
                unget_tok(t);
            expr:
                if (flags & STMT_EXPR) {
                    vpop();
                    gexpr();
                } else {
                    gexpr();
                    vpop();
                }
                skip(';');
            }
        }
    }
}

void block_pub(int flags) { block(flags); }

void check_vstack(void)
{
    if (vtop != vstack - 1)
        error("internal compiler error: vstack leak (%d)", (int)(vtop - vstack + 1));
}

void gfunc_return(Type *func_type)
{
    if ((func_type->t & TY_MASK) == TY_STRUCT) {
        Type type, ret_type;
        int ret_align, ret_nregs, regsize;
        ret_nregs = gfunc_sret(func_type, func_var, &ret_type, &ret_align, &regsize);
        if (ret_nregs < 0) {
        } else if (0 == ret_nregs) {
            type = *func_type;
            mk_pointer(&type);
            vset(&type, VL_LOCAL | VF_LVAL, func_vc);
            indir();
            vswap();
            vstore();
        } else {
            int size, addr, align, rc, n;
            size = type_size(func_type, &align);
            if ((align & (ret_align - 1))
                && ((vtop->r & VL_MASK) < VL_CONST
                    || (vtop->c.i & (ret_align - 1)))) {
                loc = (loc - size) & -ret_align;
                addr = loc;
                type = *func_type;
                vset(&type, VL_LOCAL | VF_LVAL, addr);
                vswap();
                vstore();
                vpop();
                vset(&ret_type, VL_LOCAL | VF_LVAL, addr);
            }
            vtop->type = ret_type;
            rc = is_float(ret_type.t) ? RC_FRET : RC_IRET;
            for (n = ret_nregs; --n > 0;) {
                vdup();
                gv(rc);
                vswap();
                {
                    int t = vtop->type.t;
                    gaddrof();
                    vtop->type.t = TY_PTR;
                    vpushs(regsize);
                    gen_op('+');
                    vtop->r |= VF_LVAL;
                    vtop->type.t = t;
                }
                rc <<= 1;
            }
            gv(rc);
            vtop -= ret_nregs - 1;
        }
    } else {
        int t = func_type->t;
        gv(!is_float(t) ? RC_IRET : (t & TY_MASK) == TY_F80 ? RC_ST0 : RC_FRET);
    }
    vtop--;
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/gen_stmt.c <<'EOF'
/* statements and scopes */
#include "gen.h"

#define STMT_EXPR 2
#define STMT_COMPOUND 4

#define LABEL_DEFINED 0
#define LABEL_FORWARD 1
#define LABEL_DECLARED 2
#define LABEL_GONE 3

extern void parse_attribute(Attr *ad);
extern int func_vla_dummy;

typedef struct Scope {
    struct Scope *prev;
    struct { int loc, locorig, num; } vla;
    struct { Sym *s; int n; } cl;
    int *bsym, *csym;
    Sym *lstk, *llstk;
} Scope;

static Scope *cur_scope, *loop_scope, *root_scope;
static Sym *all_cleanups, *pending_gotos;

typedef struct CaseT {
    long long v1, v2;
    int sym;
} CaseT;

typedef struct SwitchT {
    CaseT **p;
    int n;
    int cap;
    int def_sym;
    int *bsym;
    Scope *scope;
    struct SwitchT *prev;
    Val sv;
    int nocode_wanted;
} SwitchT;

static SwitchT *cur_switch;
static Scope func_root;

void block(int flags);

void label_pop(Sym **ptop, Sym *slast, int keep)
{
    Sym *s, *s1;
    for (s = *ptop; s != slast; s = s1) {
        s1 = s->prev;
        if (s->r == LABEL_DECLARED) {
            warning_opt(WOPT_ALL, "label '%s' declared but not used", tokname(s->v, NULL));
        } else if (s->r == LABEL_FORWARD) {
            error("label '%s' used but not defined", tokname(s->v, NULL));
        } else {
            if (s->elfsym) {
                put_extern_sym(s, cur_text_section, s->jnext, 1);
            }
        }
        if (s->r != LABEL_GONE)
            ident_of(s->v)->sym_label = s->shadow;
        if (!keep)
            sym_free(s);
        else
            s->r = LABEL_GONE;
    }
    if (!keep)
        *ptop = slast;
}

void scope_new_func(void)
{
    memset(&func_root, 0, sizeof func_root);
    cur_scope = root_scope = &func_root;
    loop_scope = NULL;
    cur_switch = NULL;
}

void cleanups_reset(void)
{
    sym_pop(&all_cleanups, NULL, 0);
    pending_gotos = NULL;
}

void scope_add_cleanup(Sym *sym, Sym *func)
{
    Sym *cls = sym_push2(&all_cleanups, SYM_FIELD | ++cur_scope->cl.n, 0, 0);
    cls->shadow = sym;
    cls->cleanup_func = func;
    cls->ncl = cur_scope->cl.s;
    cur_scope->cl.s = cls;
}

void scope_vla_decl(Type *type, int addr)
{
    int a;
    if (cur_scope->vla.num == 0) {
        if (cur_scope->prev && cur_scope->prev->vla.num) {
            cur_scope->vla.locorig = cur_scope->prev->vla.loc;
        } else {
            gen_vla_sp_save(loc -= PTR_SIZE);
            cur_scope->vla.locorig = loc;
        }
    }
    vpush_type_size(type, &a);
    gen_vla_alloc(type, a);
    gen_vla_sp_save(addr);
    cur_scope->vla.loc = addr;
    cur_scope->vla.num++;
}

/* VLA size slots are stored in local variables */
void vpush_vla_size(Type *type)
{
    vset(&int_type, VL_LOCAL | VF_LVAL, type->ref->c);
    gen_cast_s(TY_I64 | TQ_LONG | TQ_UNSIGNED);
}

void func_vla_arg(Sym *sym)
{
    Sym *arg;
    for (arg = sym->type.ref->next; arg; arg = arg->next) {
        if ((arg->type.t & TY_MASK) == TY_PTR && (arg->type.ref->type.t & TQ_VLA)) {
            Sym *s = arg->type.ref;
            while (s && (s->type.t & TQ_VLA)) {
                if (s->vla_tokens_) {
                    /* evaluate size expression */
                    TokSeq *ts = s->vla_tokens_;
                    int align;
                    loc -= type_size(&int_type, &align);
                    loc &= -align;
                    int n = loc;
                    push_reader(ts, 2);
                    next();
                    gexpr();
                    pop_reader();
                    vpush_type_size(&s->type.ref->type, &align);
                    gen_op('*');
                    vset(&int_type, VL_LOCAL | VF_LVAL, n);
                    vswap();
                    vstore();
                    vpop();
                    s->type.ref->c = n;
                }
                s = s->type.ref;
            }
        }
    }
}

static void try_call_scope_cleanup(Sym *stop)
{
    Sym *cls = cur_scope->cl.s;
    for (; cls != stop; cls = cls->ncl) {
        Sym *fs = cls->cleanup_func;
        Sym *vs = cls->shadow;
        vpushsym(&fs->type, fs);
        vset(&vs->type, vs->r, vs->c);
        vtop->sym = vs;
        mk_pointer(&vtop->type);
        gaddrof();
        gfunc_call(1);
    }
}

static void try_call_cleanup_goto(Sym *cleanupstate)
{
    Sym *oc, *cc;
    int ocd, ccd;
    if (!cur_scope->cl.s)
        return;
    ocd = cleanupstate ? cleanupstate->v & ~SYM_FIELD : 0;
    for (ccd = cur_scope->cl.n, oc = cleanupstate; ocd > ccd; --ocd, oc = oc->ncl)
        ;
    for (cc = cur_scope->cl.s; ccd > ocd; --ccd, cc = cc->ncl)
        ;
    for (; cc != oc; cc = cc->ncl, oc = oc->ncl, --ccd)
        ;
    try_call_scope_cleanup(cc);
}

static void block_cleanup(Scope *o)
{
    int jmp = 0;
    Sym *g, **pg;
    for (pg = &pending_gotos; (g = *pg) && g->c > o->cl.n;) {
        if (g->shadow->r & LABEL_FORWARD) {
            Sym *pcl = g->next;
            if (!jmp)
                jmp = gjmp(0);
            gsym(pcl->jnext);
            try_call_scope_cleanup(o->cl.s);
            pcl->jnext = gjmp(0);
            if (!o->cl.n)
                goto remove_pending;
            g->c = o->cl.n;
            pg = &g->prev;
        } else {
        remove_pending:
            *pg = g->prev;
            sym_free(g);
        }
    }
    gsym(jmp);
    try_call_scope_cleanup(o->cl.s);
}

static void vla_restore(int l)
{
    if (l)
        gen_vla_sp_restore(l);
}

static void vla_leave(Scope *o)
{
    Scope *c = cur_scope, *v = NULL;
    for (; c != o && c; c = c->prev)
        if (c->vla.num)
            v = c;
    if (v)
        vla_restore(v->vla.locorig);
}

static void new_scope(Scope *o)
{
    *o = *cur_scope;
    o->prev = cur_scope;
    cur_scope = o;
    cur_scope->vla.num = 0;
    o->lstk = local_stack;
    o->llstk = local_label_stack;
    ++local_scope;
}

static void pop_local_syms(Sym *b, int keep)
{
    sym_pop(&local_stack, b, keep);
}

static void prev_scope(Scope *o, int is_expr)
{
    vla_leave(o->prev);
    if (o->cl.s != o->prev->cl.s)
        block_cleanup(o->prev);
    label_pop(&local_label_stack, o->llstk, is_expr);
    pop_local_syms(o->lstk, is_expr);
    cur_scope = o->prev;
    --local_scope;
}

static void leave_scope(Scope *o)
{
    if (!o)
        return;
    try_call_scope_cleanup(o->cl.s);
    vla_leave(o);
}

static void new_scope_s(Scope *o)
{
    o->lstk = local_stack;
    ++local_scope;
}

static void prev_scope_s(Scope *o)
{
    sym_pop(&local_stack, o->lstk, 0);
    --local_scope;
}

static void lblock(int *bsym, int *csym)
{
    Scope *lo = loop_scope, *co = cur_scope;
    int *b = co->bsym, *c = co->csym;
    if (csym) {
        co->csym = csym;
        loop_scope = co;
    }
    co->bsym = bsym;
    block(0);
    co->bsym = b;
    if (csym) {
        co->csym = c;
        loop_scope = lo;
    }
}

static int case_cmpi(const void *pa, const void *pb)
{
    long long a = (*(CaseT **)pa)->v1;
    long long b = (*(CaseT **)pb)->v1;
    return a < b ? -1 : a > b;
}

static int case_cmpu(const void *pa, const void *pb)
{
    uint64_t a = (uint64_t)(*(CaseT **)pa)->v1;
    uint64_t b = (uint64_t)(*(CaseT **)pb)->v1;
    return a < b ? -1 : a > b;
}

static void gtst_addr(int t, int a)
{
    gsym_addr(gvtst(0, t), a);
}

static void gcase(CaseT **base, int len, int *bsym)
{
    CaseT *p;
    int e;
    int ll = (vtop->type.t & TY_MASK) == TY_I64;
    while (len > 8) {
        p = base[len / 2];
        vdup();
        if (ll)
            vpushll(p->v2);
        else
            vpushi(p->v2);
        gen_op(T_LE);
        e = gvtst(1, 0);
        vdup();
        if (ll)
            vpushll(p->v1);
        else
            vpushi(p->v1);
        gen_op(T_GE);
        gtst_addr(0, p->sym);
        gcase(base, len / 2, bsym);
        gsym(e);
        e = len / 2 + 1;
        base += e;
        len -= e;
    }
    while (len--) {
        p = *base++;
        vdup();
        if (ll)
            vpushll(p->v2);
        else
            vpushi(p->v2);
        if (p->v1 == p->v2) {
            gen_op(T_EQ);
            gtst_addr(0, p->sym);
        } else {
            gen_op(T_LE);
            e = gvtst(1, 0);
            vdup();
            if (ll)
                vpushll(p->v1);
            else
                vpushi(p->v1);
            gen_op(T_GE);
            gtst_addr(0, p->sym);
            gsym(e);
        }
    }
    *bsym = gjmp(*bsym);
}

static void check_func_return(void)
{
    if ((func_vt.t & TY_MASK) == TY_VOID)
        return;
    if (!strcmp(funcname, "main") && (func_vt.t & TY_MASK) == TY_I32) {
        vpushi(0);
        gen_assign_cast(&func_vt);
        gfunc_return(&func_vt);
    } else {
        warning("function might return no value: '%s'", funcname);
    }
}

void block(int flags)
{
    int a, b, c, d, e, t;
    Scope o;
    Sym *s;

    if (flags & STMT_EXPR) {
        vpushi(0);
        vtop->type.t = TY_VOID;
    }

again:
    t = tok;
    if (IS_VALTOK(t))
        goto expr;
    next();

    if (t == KW_IF) {
        new_scope_s(&o);
        skip('(');
        gexpr();
        skip(')');
        a = gvtst(1, 0);
        block(0);
        if (tok == KW_ELSE) {
            d = gjmp(0);
            gsym(a);
            next();
            block(0);
            gsym(d);
        } else {
            gsym(a);
        }
        prev_scope_s(&o);
    } else if (t == KW_WHILE) {
        new_scope_s(&o);
        d = gind();
        skip('(');
        gexpr();
        skip(')');
        a = gvtst(1, 0);
        b = 0;
        lblock(&a, &b);
        gjmp_addr(d);
        gsym_addr(b, d);
        gsym(a);
        prev_scope_s(&o);
    } else if (t == '{') {
        new_scope(&o);
        while (tok == KW_LABEL) {
            do {
                next();
                if (tok < KW_DEFINE)
                    expect("label identifier");
                label_push(&local_label_stack, tok, LABEL_DECLARED);
                next();
            } while (tok == ',');
            skip(';');
        }
        while (tok != '}') {
            decl(VL_LOCAL);
            if (tok != '}') {
                if (flags & STMT_EXPR)
                    vpop();
                block(flags | STMT_COMPOUND);
            }
        }
        prev_scope(&o, flags & STMT_EXPR);
        if (local_scope)
            next();
        else if (!nocode_wanted)
            check_func_return();
    } else if (t == KW_RETURN) {
        b = (func_vt.t & TY_MASK) != TY_VOID;
        if (tok != ';') {
            gexpr();
            if (b) {
                gen_assign_cast(&func_vt);
            } else {
                if (vtop->type.t != TY_VOID)
                    warning("void function returns a value");
                vtop--;
            }
        } else if (b) {
            warning("'return' with no value");
            b = 0;
        }
        leave_scope(root_scope);
        if (b)
            gfunc_return(&func_vt);
        skip(';');
        if (tok != '}' || local_scope != 1)
            rsym = gjmp_acs(rsym);
        CODE_OFF();
    } else if (t == KW_BREAK) {
        if (!cur_scope->bsym)
            error("cannot break");
        if (cur_switch && cur_scope->bsym == cur_switch->bsym)
            leave_scope(cur_switch->scope);
        else
            leave_scope(loop_scope);
        *cur_scope->bsym = gjmp_acs(*cur_scope->bsym);
        skip(';');
    } else if (t == KW_CONTINUE) {
        if (!cur_scope->csym)
            error("cannot continue");
        leave_scope(loop_scope);
        *cur_scope->csym = gjmp_acs(*cur_scope->csym);
        skip(';');
    } else if (t == KW_FOR) {
        new_scope(&o);
        skip('(');
        if (tok != ';') {
            if (!decl(VL_JMP)) {
                gexpr();
                vpop();
            }
        }
        skip(';');
        a = b = 0;
        c = d = gind();
        if (tok != ';') {
            gexpr();
            a = gvtst(1, 0);
        }
        skip(';');
        if (tok != ')') {
            e = gjmp_acs(0);
            d = gind();
            gexpr();
            vpop();
            gjmp_addr_acs(c);
            gsym(e);
        }
        skip(')');
        lblock(&a, &b);
        gjmp_addr_acs(d);
        gsym_addr(b, d);
        gsym(a);
        prev_scope(&o, 0);
    } else if (t == KW_DO) {
        new_scope_s(&o);
        a = b = 0;
        d = gind();
        lblock(&a, &b);
        gsym(b);
        skip(KW_WHILE);
        skip('(');
        gexpr();
        skip(')');
        skip(';');
        c = gvtst(0, 0);
        gsym_addr(c, d);
        gsym(a);
        prev_scope_s(&o);
    } else if (t == KW_SWITCH) {
        SwitchT *sw;
        sw = xcalloc(sizeof *sw);
        sw->bsym = &a;
        sw->scope = cur_scope;
        sw->prev = cur_switch;
        sw->nocode_wanted = nocode_wanted;
        cur_switch = sw;

        new_scope_s(&o);
        skip('(');
        gexpr();
        skip(')');
        if (!is_integer_btype(vtop->type.t & TY_MASK))
            error("switch value not an integer");
        sw->sv = *vtop--;

        a = 0;
        b = gjmp_acs(0);
        lblock(&a, NULL);
        a = gjmp_acs(a);
        gsym(b);
        prev_scope_s(&o);

        if (sw->nocode_wanted)
            goto skip_switch;
        if (sw->sv.type.t & TQ_UNSIGNED)
            qsort(sw->p, sw->n, sizeof(void *), case_cmpu);
        else
            qsort(sw->p, sw->n, sizeof(void *), case_cmpi);
        for (b = 1; b < sw->n; b++)
            if (sw->sv.type.t & TQ_UNSIGNED
                ? (uint64_t)sw->p[b - 1]->v2 >= (uint64_t)sw->p[b]->v1
                : sw->p[b - 1]->v2 >= sw->p[b]->v1)
                error("duplicate case value");
        vpushv(&sw->sv);
        gv(RC_INT);
        d = 0, gcase(sw->p, sw->n, &d);
        vpop();
        if (sw->def_sym)
            gsym_addr(d, sw->def_sym);
        else
            gsym(d);
    skip_switch:
        gsym(a);
        for (int i = 0; i < sw->n; i++) free(sw->p[i]);
        free(sw->p);
        cur_switch = sw->prev;
        free(sw);
    } else if (t == KW_CASE) {
        CaseT *cr = xcalloc(sizeof(CaseT));
        if (!cur_switch)
            expect("switch");
        cr->v1 = cr->v2 = expr_const64();
        if (opt.gnu_ext && tok == T_ELLIPSIS) {
            next();
            cr->v2 = expr_const64();
            if ((!(cur_switch->sv.type.t & TQ_UNSIGNED) && cr->v2 < cr->v1)
                || (cur_switch->sv.type.t & TQ_UNSIGNED && (uint64_t)cr->v2 < (uint64_t)cr->v1))
                warning("empty case range");
        }
        if (!cur_switch->nocode_wanted)
            cr->sym = gind();
        if (cur_switch->n == cur_switch->cap) {
            cur_switch->cap = cur_switch->cap ? cur_switch->cap * 2 : 8;
            cur_switch->p = xrealloc(cur_switch->p, cur_switch->cap * sizeof(CaseT *));
        }
        cur_switch->p[cur_switch->n++] = cr;
        skip(':');
        goto block_after_label;
    } else if (t == KW_DEFAULT) {
        if (!cur_switch)
            expect("switch");
        if (cur_switch->def_sym)
            error("too many 'default'");
        cur_switch->def_sym = cur_switch->nocode_wanted ? 1 : gind();
        skip(':');
        goto block_after_label;
    } else if (t == KW_GOTO) {
        vla_restore(cur_scope->vla.locorig);
        if (tok == '*' && opt.gnu_ext) {
            next();
            gexpr();
            if ((vtop->type.t & TY_MASK) != TY_PTR)
                expect("pointer");
            ggoto();
        } else if (tok >= KW_DEFINE) {
            s = label_find(tok);
            if (!s)
                s = label_push(&global_label_stack, tok, LABEL_FORWARD);
            else if (s->r == LABEL_DECLARED)
                s->r = LABEL_FORWARD;
            if (s->r & LABEL_FORWARD) {
                if (cur_scope->cl.s && !nocode_wanted) {
                    sym_push2(&pending_gotos, SYM_FIELD, 0, cur_scope->cl.n);
                    pending_gotos->shadow = s;
                    s = sym_push2(&s->next, SYM_FIELD, 0, 0);
                    pending_gotos->next = s;
                }
                s->jnext = gjmp_acs(s->jnext);
            } else {
                try_call_cleanup_goto(s->cleanup_state);
                gjmp_addr_acs(s->jnext);
            }
            next();
        } else {
            expect("label identifier");
        }
        skip(';');
    } else if (t == KW_ASM1 || t == KW_ASM2 || t == KW_ASM3) {
        asm_instr();
    } else {
        if (tok == ':' && t >= KW_DEFINE) {
            next();
            s = label_find(t);
            if (s) {
                if (s->r == LABEL_DEFINED)
                    error("duplicate label '%s'", tokname(s->v, NULL));
                s->r = LABEL_DEFINED;
                if (s->next) {
                    Sym *pcl;
                    for (pcl = s->next; pcl; pcl = pcl->prev)
                        gsym(pcl->jnext);
                    sym_pop(&s->next, NULL, 0);
                } else
                    gsym(s->jnext);
            } else {
                s = label_push(&global_label_stack, t, LABEL_DEFINED);
            }
            s->jnext = gind();
            s->cleanup_state = cur_scope->cl.s;
        block_after_label: {
                Attr ad_tmp;
                memset(&ad_tmp, 0, sizeof ad_tmp);
                parse_attribute(&ad_tmp);
            }
            vla_restore(cur_scope->vla.loc);
            if (tok != '}') {
                if (0 == (flags & STMT_COMPOUND))
                    goto again;
            } else {
                warning_opt(WOPT_ALL, "deprecated use of label at end of compound statement");
            }
        } else {
            if (t != ';') {
                unget_tok(t);
            expr:
                if (flags & STMT_EXPR) {
                    vpop();
                    gexpr();
                } else {
                    gexpr();
                    vpop();
                }
                skip(';');
            }
        }
    }
}

void block_pub(int flags) { block(flags); }

void check_vstack(void)
{
    if (vtop != vstack - 1)
        error("internal compiler error: vstack leak (%d)", (int)(vtop - vstack + 1));
}

void gfunc_return(Type *func_type)
{
    if ((func_type->t & TY_MASK) == TY_STRUCT) {
        Type type, ret_type;
        int ret_align, ret_nregs, regsize;
        ret_nregs = gfunc_sret(func_type, func_var, &ret_type, &ret_align, &regsize);
        if (ret_nregs < 0) {
        } else if (0 == ret_nregs) {
            type = *func_type;
            mk_pointer(&type);
            vset(&type, VL_LOCAL | VF_LVAL, func_vc);
            indir();
            vswap();
            vstore();
        } else {
            int size, addr, align, rc, n;
            size = type_size(func_type, &align);
            if ((align & (ret_align - 1))
                && ((vtop->r & VL_MASK) < VL_CONST
                    || (vtop->c.i & (ret_align - 1)))) {
                loc = (loc - size) & -ret_align;
                addr = loc;
                type = *func_type;
                vset(&type, VL_LOCAL | VF_LVAL, addr);
                vswap();
                vstore();
                vpop();
                vset(&ret_type, VL_LOCAL | VF_LVAL, addr);
            }
            vtop->type = ret_type;
            rc = is_float(ret_type.t) ? RC_FRET : RC_IRET;
            for (n = ret_nregs; --n > 0;) {
                vdup();
                gv(rc);
                vswap();
                {
                    int t = vtop->type.t;
                    gaddrof();
                    vtop->type.t = TY_PTR;
                    vpushs(regsize);
                    gen_op('+');
                    vtop->r |= VF_LVAL;
                    vtop->type.t = t;
                }
                rc <<= 1;
            }
            gv(rc);
            vtop -= ret_nregs - 1;
        }
    } else {
        int t = func_type->t;
        gv(!is_float(t) ? RC_IRET : (t & TY_MASK) == TY_F80 ? RC_ST0 : RC_FRET);
    }
    vtop--;
}
