/* ------------------------------------------------------------ per file symbol merge */
static unsigned long file_first_sym;
static int symhash_disabled;

void elf_begin_file(void)
{
    Section *s = symtab_section;
    file_first_sym = s->data_offset / sizeof(ElfW(Sym));
    s->sh_offset = s->data_offset;
    s->link->sh_offset = s->link->data_offset;
    for (int i = 1; i < nb_sections; i++) {
        Section *sr = sections[i];
        if (sr->sh_type == SHT_RELA && sr->link == s)
            sr->sh_offset = sr->data_offset;
    }
    symhash_disabled = 1;
}

void elf_end_file(void)
{
    Section *s = symtab_section;
    int first_sym, nb_syms, *tr, i;
    first_sym = s->sh_offset / sizeof(ElfW(Sym));
    nb_syms = s->data_offset / sizeof(ElfW(Sym)) - first_sym;
    /* copy symbols and their names */
    ElfW(Sym) *copy = xmalloc((nb_syms + 1) * sizeof(ElfW(Sym)));
    memcpy(copy, (ElfW(Sym) *)s->data + first_sym, nb_syms * sizeof(ElfW(Sym)));
    unsigned long str_len = s->link->data_offset;
    char *strcopy = xmalloc(str_len + 1);
    memcpy(strcopy, s->link->data, str_len);
    s->data_offset = s->sh_offset;
    s->link->data_offset = s->link->sh_offset;
    symhash_disabled = 0;
    tr = xcalloc((nb_syms + 1) * sizeof *tr);
    for (i = 0; i < nb_syms; ++i) {
        ElfW(Sym) *sym = &copy[i];
        if (sym->st_shndx == SHN_UNDEF) {
            int sym_bind = ELFW(ST_BIND)(sym->st_info);
            int sym_type = ELFW(ST_TYPE)(sym->st_info);
            if (sym_bind == STB_LOCAL)
                sym_bind = STB_GLOBAL;
            if (sym_bind == STB_GLOBAL && opt.output_type == OUT_OBJ)
                sym_type = STT_NOTYPE;
            sym->st_info = ELFW(ST_INFO)(sym_bind, sym_type);
        }
        tr[i] = set_elf_sym(s, sym->st_value, sym->st_size, sym->st_info,
                            sym->st_other, sym->st_shndx, strcopy + sym->st_name);
    }
    for (i = 1; i < nb_sections; i++) {
        Section *sr = sections[i];
        if (sr->sh_type == SHT_RELA && sr->link == s) {
            ElfW(Rela) *rel = (ElfW(Rela) *)(sr->data + sr->sh_offset);
            ElfW(Rela) *rel_end = (ElfW(Rela) *)(sr->data + sr->data_offset);
            for (; rel < rel_end; ++rel) {
                int n = ELFW(R_SYM)(rel->r_info) - first_sym;
                if (n < 0)
                    continue;
                rel->r_info = ELFW(R_INFO)(tr[n], ELFW(R_TYPE)(rel->r_info));
            }
        }
    }
    free(tr);
    free(copy);
    free(strcopy);
}
