/* linker: loading objects, archives, shared libraries and ld scripts,
   symbol resolution and link-time diagnostics */
#include "cc.h"

extern int write_object_file(const char *filename);
extern int write_exe_file(const char *filename);
extern void eh_frame_end(void);
extern int compile_all(int start, int end, const char **first_file);
const char *bin_file_name; /* file being loaded, for diagnostics */

typedef struct DllRef {
    char *name;
    int level;
    int found;
    void *handle;
} DllRef;
PVec dll_refs;

/* print file open attempts in verbose mode */
void verbose_open(const char *name, int found)
{
    if ((opt.verbose == 2 && found) || opt.verbose == 3)
        printf("%s %*s%s\n", found ? "->" : "nf", (int)(inc_sp - inc_stack), "",
               strcmp(name, "-") ? name : "<stdin>");
}

static int try_open(const char *name)
{
    int fd = open(name, O_RDONLY);
    verbose_open(name, fd >= 0);
    return fd;
}

void *load_data(int fd, unsigned long off, unsigned long size)
{
    void *p = xmalloc(size + 1);
    lseek(fd, off, SEEK_SET);
    size_t got = 0;
    while (got < size) {
        ssize_t n = read(fd, (char *)p + got, size - got);
        if (n <= 0) break;
        got += n;
    }
    return p;
}

enum { BIN_NONE, BIN_REL, BIN_DYN, BIN_AR };

static int object_type(int fd, ElfW(Ehdr) *h)
{
    int size = read(fd, h, sizeof *h);
    if (size == (int)sizeof *h && 0 == memcmp(h, ELFMAG, 4)) {
        if (h->e_type == ET_REL)
            return BIN_REL;
        if (h->e_type == ET_DYN)
            return BIN_DYN;
    } else if (size >= 8) {
        if (0 == memcmp(h, "!<arch>\n", 8))
            return BIN_AR;
    }
    return BIN_NONE;
}

/* ------------------------------------------------------------ objects */
typedef struct SecMerge {
    unsigned long offset;
    Section *s;
    unsigned char new_section;
    unsigned char link_once;
} SecMerge;

int load_object(int fd, unsigned long file_offset)
{
    ElfW(Ehdr) ehdr;
    ElfW(Shdr) *shdr, *sh;
    unsigned long size, offset, offseti;
    int i, j, nb_syms, sym_index, ret = -1;
    char *strsec, *strtab = NULL;
    int *old_to_new_syms = NULL;
    char *sh_name, *name;
    SecMerge *sm_table, *sm;
    ElfW(Sym) *sym, *symtab = NULL;
    ElfW(Rela) *rel;
    Section *s;

    lseek(fd, file_offset, SEEK_SET);
    if (object_type(fd, &ehdr) != BIN_REL)
        goto invalid;
    if (ehdr.e_ident[5] != ELFDATA2LSB || ehdr.e_machine != EM_X86_64) {
    invalid:
        error_noabort("invalid object file");
        return -1;
    }
    shdr = load_data(fd, file_offset + ehdr.e_shoff, sizeof(ElfW(Shdr)) * ehdr.e_shnum);
    sm_table = xcalloc(sizeof(SecMerge) * ehdr.e_shnum);
    sh = &shdr[ehdr.e_shstrndx];
    strsec = load_data(fd, file_offset + sh->sh_offset, sh->sh_size);
    nb_syms = 0;
    for (i = 1; i < ehdr.e_shnum; i++) {
        sh = &shdr[i];
        if (sh->sh_type == SHT_SYMTAB) {
            if (symtab) {
                error_noabort("object must contain only one symtab");
                goto the_end;
            }
            nb_syms = sh->sh_size / sizeof(ElfW(Sym));
            symtab = load_data(fd, file_offset + sh->sh_offset, sh->sh_size);
            sm_table[i].s = symtab_section;
            sh = &shdr[sh->sh_link];
            strtab = load_data(fd, file_offset + sh->sh_offset, sh->sh_size);
        }
    }
    for (i = 1; i < ehdr.e_shnum; i++) {
        if (i == ehdr.e_shstrndx)
            continue;
        sh = &shdr[i];
        if (sh->sh_type == SHT_RELA)
            sh = &shdr[sh->sh_info];
        if (sh->sh_type != SHT_PROGBITS &&
            sh->sh_type != SHT_NOBITS &&
            sh->sh_type != SHT_PREINIT_ARRAY &&
            sh->sh_type != SHT_INIT_ARRAY &&
            sh->sh_type != SHT_FINI_ARRAY &&
            strcmp(strsec + sh->sh_name, ".stabstr"))
            continue;
        sh = &shdr[i];
        sh_name = strsec + sh->sh_name;
        if (sh->sh_addralign < 1)
            sh->sh_addralign = 1;
        for (j = 1; j < nb_sections; j++) {
            s = sections[j];
            if (!strcmp(s->name, sh_name)) {
                if (!strncmp(sh_name, ".gnu.linkonce", sizeof(".gnu.linkonce") - 1)) {
                    sm_table[i].link_once = 1;
                    goto next;
                }
                goto found;
            }
        }
        s = new_section(sh_name, sh->sh_type, sh->sh_flags & ~SHF_GROUP);
        s->sh_addralign = sh->sh_addralign;
        s->sh_entsize = sh->sh_entsize;
        sm_table[i].new_section = 1;
    found:
        if (sh->sh_type != (unsigned)s->sh_type) {
            error_noabort("invalid section type");
            goto the_end;
        }
        s->data_offset += -s->data_offset & (sh->sh_addralign - 1);
        if ((int)sh->sh_addralign > s->sh_addralign)
            s->sh_addralign = sh->sh_addralign;
        sm_table[i].offset = s->data_offset;
        sm_table[i].s = s;
        size = sh->sh_size;
        if (sh->sh_type != SHT_NOBITS) {
            unsigned char *ptr;
            void *d = load_data(fd, file_offset + sh->sh_offset, size);
            ptr = section_ptr_add(s, size);
            memcpy(ptr, d, size);
            free(d);
        } else {
            s->data_offset += size;
        }
    next:;
    }
    for (i = 1; i < ehdr.e_shnum; i++) {
        s = sm_table[i].s;
        if (!s || !sm_table[i].new_section)
            continue;
        sh = &shdr[i];
        if (sh->sh_link > 0)
            s->link = sm_table[sh->sh_link].s;
        if (sh->sh_type == SHT_RELA) {
            s->sh_info = sm_table[sh->sh_info].s->sh_num;
            sections[s->sh_info]->reloc = s;
        }
    }
    old_to_new_syms = xcalloc((nb_syms + 1) * sizeof(int));
    sym = symtab + 1;
    for (i = 1; i < nb_syms; i++, sym++) {
        if (sym->st_shndx != SHN_UNDEF && sym->st_shndx < SHN_LORESERVE) {
            sm = &sm_table[sym->st_shndx];
            if (sm->link_once) {
                if (ELFW(ST_BIND)(sym->st_info) != STB_LOCAL) {
                    name = strtab + sym->st_name;
                    sym_index = find_elf_sym(symtab_section, name);
                    if (sym_index)
                        old_to_new_syms[i] = sym_index;
                }
                continue;
            }
            if (!sm->s)
                continue;
            sym->st_shndx = sm->s->sh_num;
            sym->st_value += sm->offset;
        }
        name = strtab + sym->st_name;
        sym_index = set_elf_sym(symtab_section, sym->st_value, sym->st_size,
                                sym->st_info, sym->st_other, sym->st_shndx, name);
        old_to_new_syms[i] = sym_index;
    }
    for (i = 1; i < ehdr.e_shnum; i++) {
        s = sm_table[i].s;
        if (!s)
            continue;
        sh = &shdr[i];
        offset = sm_table[i].offset;
        size = sh->sh_size;
        if (s->sh_type == SHT_RELA) {
            offseti = sm_table[sh->sh_info].offset;
            for (rel = (ElfW(Rela) *)s->data + (offset / sizeof(*rel));
                 rel < (ElfW(Rela) *)s->data + ((offset + size) / sizeof(*rel));
                 rel++) {
                int type;
                unsigned si;
                type = ELFW(R_TYPE)(rel->r_info);
                si = ELFW(R_SYM)(rel->r_info);
                if (si >= (unsigned)nb_syms)
                    goto invalid_reloc;
                si = old_to_new_syms[si];
                if (!si && !sm_table[sh->sh_info].link_once) {
                invalid_reloc:
                    error_noabort("Invalid relocation entry [%2d] '%s' @ %.8x",
                                  i, strsec + sh->sh_name, (int)rel->r_offset);
                    goto the_end;
                }
                rel->r_info = ELFW(R_INFO)(si, type);
                rel->r_offset += offseti;
            }
        }
    }
    ret = 0;
the_end:
    free(symtab);
    free(strtab);
    free(old_to_new_syms);
    free(sm_table);
    free(strsec);
    free(shdr);
    return ret;
}

/* ------------------------------------------------------------ archives */
typedef struct ArHdr {
    char ar_name[16];
    char ar_date[12];
    char ar_uid[6];
    char ar_gid[6];
    char ar_mode[8];
    char ar_size[10];
    char ar_fmag[2];
} ArHdr;

static unsigned long long get_be(const uint8_t *b, int n)
{
    unsigned long long ret = 0;
    while (n)
        ret = (ret << 8) | *b++, --n;
    return ret;
}

static int read_ar_header(int fd, int offset, ArHdr *hdr)
{
    char *p, *e;
    int len;
    lseek(fd, offset, SEEK_SET);
    len = read(fd, hdr, sizeof(ArHdr));
    if (len != sizeof(ArHdr))
        return len ? -1 : len;
    p = hdr->ar_name;
    for (e = p + sizeof hdr->ar_name; e > p && e[-1] == ' ';)
        --e;
    *e = '\0';
    hdr->ar_size[sizeof hdr->ar_size - 1] = 0;
    return len;
}

static int load_alacarte(int fd, int size, int entrysize)
{
    int i, bound, nsyms, sym_index, len, ret = -1;
    unsigned long long off;
    uint8_t *data;
    const char *ar_names, *p;
    const uint8_t *ar_index;
    ElfW(Sym) *sym;
    ArHdr hdr;

    data = xmalloc(size);
    if (read(fd, data, size) != size)
        goto the_end;
    nsyms = get_be(data, entrysize);
    ar_index = data + entrysize;
    ar_names = (char *)ar_index + nsyms * entrysize;
    do {
        bound = 0;
        for (p = ar_names, i = 0; i < nsyms; i++, p += strlen(p) + 1) {
            Section *s = symtab_section;
            sym_index = find_elf_sym(s, p);
            if (!sym_index)
                continue;
            sym = &((ElfW(Sym) *)s->data)[sym_index];
            if (sym->st_shndx != SHN_UNDEF)
                continue;
            off = get_be(ar_index + i * entrysize, entrysize);
            len = read_ar_header(fd, off, &hdr);
            if (len <= 0 || memcmp(hdr.ar_fmag, "`\n", 2))
                goto the_end;
            off += len;
            if (opt.verbose == 2)
                printf("   -> %s\n", hdr.ar_name);
            if (load_object(fd, off) < 0)
                goto the_end;
            ++bound;
        }
    } while (bound);
    ret = 0;
the_end:
    free(data);
    return ret;
}

int load_archive(int fd, int alacarte)
{
    ArHdr hdr;
    int size, len;
    unsigned long file_offset;
    ElfW(Ehdr) ehdr;

    file_offset = sizeof("!<arch>\n") - 1;
    for (;;) {
        len = read_ar_header(fd, file_offset, &hdr);
        if (len == 0)
            return 0;
        if (len < 0) {
            error_noabort("invalid archive");
            return -1;
        }
        file_offset += len;
        size = strtol(hdr.ar_size, NULL, 0);
        size = (size + 1) & ~1;
        if (alacarte) {
            if (!strcmp(hdr.ar_name, "/"))
                return load_alacarte(fd, size, 4);
            if (!strcmp(hdr.ar_name, "/SYM64/"))
                return load_alacarte(fd, size, 8);
        } else if (hdr.ar_name[0] != '/') {
            lseek(fd, file_offset, SEEK_SET);
            if (object_type(fd, &ehdr) == BIN_REL) {
                if (load_object(fd, file_offset) < 0)
                    return -1;
            }
        }
        file_offset += size;
    }
}

/* ------------------------------------------------------------ shared libs */
static DllRef *add_dllref(const char *name, int level)
{
    for (int i = 0; i < dll_refs.n; i++) {
        DllRef *r = dll_refs.v[i];
        if (!strcmp(r->name, name)) {
            r->found = 1;
            if (level < r->level)
                r->level = level;
            return r;
        }
    }
    DllRef *r = xcalloc(sizeof *r);
    r->name = xstrdup(name);
    r->level = level;
    pvec_push(&dll_refs, r);
    return r;
}

int load_dll(int fd, const char *filename, int level)
{
    ElfW(Ehdr) ehdr;
    ElfW(Shdr) *shdr, *sh, *sh1;
    int i, nb_syms = 0, nb_dts = 0, sym_bind, ret = -1;
    ElfW(Sym) *sym, *dynsym = NULL;
    ElfW(Dyn) *dt, *dynamic = NULL;
    char *dynstr = NULL;
    const char *name, *soname;

    lseek(fd, 0, SEEK_SET);
    if (read(fd, &ehdr, sizeof(ehdr)) != sizeof(ehdr))
        return -1;
    if (ehdr.e_ident[5] != ELFDATA2LSB || ehdr.e_machine != EM_X86_64) {
        error_noabort("bad architecture");
        return -1;
    }
    shdr = load_data(fd, ehdr.e_shoff, sizeof(ElfW(Shdr)) * ehdr.e_shnum);
    for (i = 0, sh = shdr; i < ehdr.e_shnum; i++, sh++) {
        switch (sh->sh_type) {
        case SHT_DYNAMIC:
            nb_dts = sh->sh_size / sizeof(ElfW(Dyn));
            dynamic = load_data(fd, sh->sh_offset, sh->sh_size);
            break;
        case SHT_DYNSYM:
            nb_syms = sh->sh_size / sizeof(ElfW(Sym));
            dynsym = load_data(fd, sh->sh_offset, sh->sh_size);
            sh1 = &shdr[sh->sh_link];
            dynstr = load_data(fd, sh1->sh_offset, sh1->sh_size);
            break;
        default:
            break;
        }
    }
    if (!dynamic)
        goto the_end;
    soname = path_basename(filename);
    for (i = 0, dt = dynamic; i < nb_dts; i++, dt++) {
        if (dt->d_tag == DT_SONAME)
            soname = dynstr + dt->d_un.d_val;
    }
    if (add_dllref(soname, level)->found)
        goto ret_success;
    for (i = 1, sym = dynsym + 1; i < nb_syms; i++, sym++) {
        sym_bind = ELFW(ST_BIND)(sym->st_info);
        if (sym_bind == STB_LOCAL)
            continue;
        name = dynstr + sym->st_name;
        set_elf_sym(dynsymtab_section, sym->st_value, sym->st_size,
                    sym->st_info, sym->st_other, sym->st_shndx, name);
    }
ret_success:
    ret = 0;
the_end:
    free(dynstr);
    free(dynsym);
    free(dynamic);
    free(shdr);
    return ret;
}

/* ------------------------------------------------------------ ld scripts */
#define LD_TOK_NAME 256
#define LD_TOK_EOF (-1)

static unsigned char *ld_p;

static int ld_inp(void)
{
    int c = *ld_p;
    if (c == 0) return -1;
    ld_p++;
    return c;
}

static int ld_next(char *name, int name_size)
{
    int c, d, ret;
    char *q;
redo:
    c = ld_inp();
    switch (c) {
    case ' ': case '\t': case '\f': case '\v': case '\r': case '\n':
        goto redo;
    case '/':
        d = *ld_p;
        if (d == '*') {
            ld_p++;
            for (;;) {
                c = ld_inp();
                if (c == -1) break;
                if (c == '*' && *ld_p == '/') { ld_p++; break; }
            }
            goto redo;
        } else {
            q = name;
            *q++ = '/';
            goto parse_name;
        }
        break;
    case '\\':
    case 'a' ... 'z':
    case 'A' ... 'Z':
    case '_':
    case '.':
    case '$':
    case '~':
        q = name;
    parse_name:
        for (;;) {
            if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
                  (c >= '0' && c <= '9') ||
                  strchr("/.-_+=$:\\,~", c)))
                break;
            if ((q - name) < name_size - 1) {
                *q++ = c;
            }
            c = ld_inp();
        }
        if (c != -1) ld_p--;
        *q = '\0';
        ret = LD_TOK_NAME;
        break;
    case -1:
        ret = LD_TOK_EOF;
        break;
    default:
        ret = c;
        break;
    }
    return ret;
}

int add_library_ld(const char *name);
int add_file_bin(const char *filename, int flags);

static int ld_add_file(const char *filename)
{
    if (filename[0] == '/') {
        if (access(filename, F_OK) == 0)
            return add_file_bin(filename, 2);
        /* not found: tcc tries the name relative to library paths */
        filename = path_basename(filename);
    }
    return add_library_ld(filename);
}

static int ld_add_file_list(const char *cmd, int as_needed, PVec *grp)
{
    char filename[1024], libname[1024];
    int t, group, ret = 0;
    PVec libs = { 0 };
    group = !strcmp(cmd, "GROUP");
    if (!as_needed)
        new_undef_sym = 0;
    t = ld_next(filename, sizeof(filename));
    if (t != '(') {
        error_noabort("( expected");
        return -1;
    }
    t = ld_next(filename, sizeof(filename));
    for (;;) {
        libname[0] = '\0';
        if (t == LD_TOK_EOF) {
            error_noabort("unexpected end of file");
            ret = -1;
            goto lib_parse_error;
        } else if (t == ')') {
            break;
        } else if (t == '-') {
            t = ld_next(filename, sizeof(filename));
            if ((t != LD_TOK_NAME) || (filename[0] != 'l')) {
                error_noabort("library name expected");
                ret = -1;
                goto lib_parse_error;
            }
            pstrcpy(libname, sizeof libname, &filename[1]);
            if (opt.static_link)
                snprintf(filename, sizeof filename, "lib%s.a", libname);
            else
                snprintf(filename, sizeof filename, "lib%s.so", libname);
        } else if (t != LD_TOK_NAME) {
            error_noabort("filename expected");
            ret = -1;
            goto lib_parse_error;
        }
        if (!strcmp(filename, "AS_NEEDED")) {
            ret = ld_add_file_list(filename, 1, group ? &libs : grp);
            if (ret)
                goto lib_parse_error;
        } else {
            ret = ld_add_file(filename);
            if (ret)
                goto lib_parse_error;
            PVec *dst = group ? &libs : grp;
            if (dst) {
                pvec_push(dst, xstrdup(filename));
            }
        }
        t = ld_next(filename, sizeof(filename));
        if (t == ',')
            t = ld_next(filename, sizeof(filename));
    }
    if (group && !as_needed) {
        while (new_undef_sym) {
            new_undef_sym = 0;
            for (int i = 0; i < libs.n; i++)
                ld_add_file(libs.v[i]);
        }
    }
lib_parse_error:
    for (int i = 0; i < libs.n; i++) free(libs.v[i]);
    free(libs.v);
    return ret;
}

int load_ldscript(int fd)
{
    char cmd[64];
    char filename[1024];
    int t, ret;
    struct stat st;
    if (fstat(fd, &st) < 0) return -1;
    char *buf = load_data(fd, 0, st.st_size);
    buf[st.st_size] = 0;
    unsigned char *saved = ld_p;
    ld_p = (unsigned char *)buf;
    ret = 0;
    for (;;) {
        t = ld_next(cmd, sizeof(cmd));
        if (t == LD_TOK_EOF)
            break;
        else if (t != LD_TOK_NAME) {
            ret = -1;
            break;
        }
        if (!strcmp(cmd, "INPUT") || !strcmp(cmd, "GROUP")) {
            ret = ld_add_file_list(cmd, 0, NULL);
            if (ret)
                break;
        } else if (!strcmp(cmd, "OUTPUT_FORMAT") || !strcmp(cmd, "TARGET")) {
            t = ld_next(cmd, sizeof(cmd));
            if (t != '(') {
                error_noabort("( expected");
                ret = -1;
                break;
            }
            for (;;) {
                t = ld_next(filename, sizeof(filename));
                if (t == LD_TOK_EOF) {
                    error_noabort("unexpected end of file");
                    ret = -1;
                    goto done;
                } else if (t == ')') {
                    break;
                }
            }
        } else {
            ret = -1;
            break;
        }
    }
done:
    ld_p = saved;
    free(buf);
    return ret;
}

/* ------------------------------------------------------------ file adding */
/* flags: 1 = print error if not found, 2 = referenced dll */
int add_file_bin(const char *filename, int flags)
{
    ElfW(Ehdr) ehdr;
    int fd, obj_type, ret = -1;
    const char *saved = bin_file_name;
    fd = try_open(filename);
    if (fd < 0) {
        if (flags & 1)
            error_noabort("file '%s' not found", filename);
        return -2;
    }
    obj_type = object_type(fd, &ehdr);
    lseek(fd, 0, SEEK_SET);
    bin_file_name = filename;
    switch (obj_type) {
    case BIN_REL:
        ret = load_object(fd, 0);
        break;
    case BIN_AR:
        ret = load_archive(fd, !(opt.filetype_next & 0x80));
        break;
    case BIN_DYN:
        ret = load_dll(fd, filename, (flags & 2) != 0);
        break;
    default:
        ret = load_ldscript(fd);
        bin_file_name = saved;
        if (ret < 0)
            error_noabort("%s: unrecognized file type", filename);
        break;
    }
    bin_file_name = saved;
    close(fd);
    return ret;
}

int load_input_binary(const char *fn, int fd, int type)
{
    (void)type;
    close(fd);
    return add_file_bin(fn, 1) < 0 ? -1 : 0;
}

static int add_file_in_paths(PVec *paths, const char *fmt, const char *name, int flags)
{
    char buf[1024];
    for (int i = 0; i < paths->n; i++) {
        snprintf(buf, sizeof buf, fmt, (char *)paths->v[i], name);
        int ret = add_file_bin(buf, flags & ~1);
        if (ret != -2)
            return ret;
    }
    if (flags & 1)
        error_noabort("%s '%s' not found", (flags & 4) ? "library" : "file", name);
    return -2;
}

int add_library_ld(const char *libname)
{
    /* as ld: a library name from an ld script, search library paths */
    return add_file_in_paths(&opt.library_paths, "%s/%s", libname, 1);
}

int add_library(const char *libname)
{
    static const char *const libs[] = { "%s/lib%s.so", "%s/lib%s.a", NULL };
    const char *const *pp = opt.static_link ? libs + 1 : libs;
    while (*pp) {
        int ret = add_file_in_paths(&opt.library_paths, *pp, libname, 0);
        if (ret != -2)
            return ret;
        ++pp;
    }
    return -2;
}

int add_library_err(const char *libname)
{
    int ret = add_library(libname);
    if (ret == -2) {
        error_noabort("library '%s' not found", libname);
        return -1;
    }
    return ret;
}

int add_crt(const char *filename)
{
    return add_file_in_paths(&opt.crt_paths, "%s/%s", filename, 1);
}

int add_support(const char *filename)
{
    return add_file_in_paths(&opt.library_paths, "%s/%s", filename, 1);
}

/* ------------------------------------------------------------ link flow */
int libtcc1_missing;

void link_begin(void)
{
    /* called before compiling the input files */
    if (opt.output_type != OUT_OBJ && opt.output_type != OUT_PREPROCESS && !opt.nostdlib) {
        if (opt.output_type != OUT_DLL && opt.output_type != OUT_MEMORY)
            add_crt("crt1.o");
        if (opt.output_type != OUT_MEMORY)
            add_crt("crti.o");
    }
}

static void add_runtime(void)
{
    extern PVec pragma_libs;
    for (int i = 0; i < pragma_libs.n; i++)
        add_library_err(pragma_libs.v[i]);
    if (opt.output_type == OUT_MEMORY) {
        add_support("runmain.o");
    }
    if (!opt.nostdlib) {
        if (opt.pthread)
            add_library_err("pthread");
        add_library_err("c");
        if (add_support("libtcc1.a") < 0)
            libtcc1_missing = 1;
        if (opt.output_type != OUT_MEMORY)
            add_crt("crtn.o");
    }
}

static int check_undefined(int report)
{
    int n = symtab_section->data_offset / sizeof(ElfW(Sym));
    int nerr = 0;
    for (int i = 1; i < n; i++) {
        ElfW(Sym) *sym = &((ElfW(Sym) *)symtab_section->data)[i];
        if (sym->st_shndx != SHN_UNDEF)
            continue;
        if (ELFW(ST_BIND)(sym->st_info) == STB_LOCAL)
            continue;
        const char *name = (char *)symtab_section->link->data + sym->st_name;
        int di = find_elf_sym(dynsymtab_section, name);
        if (di)
            continue;
        if (ELFW(ST_BIND)(sym->st_info) == STB_WEAK || !strcmp(name, "_fp_hw"))
            continue;
        if (report)
            error_noabort("undefined symbol '%s'", name);
        nerr++;
    }
    return nerr;
}

static int sym_defined(const char *name)
{
    int i = find_elf_sym(symtab_section, name);
    if (!i) return 0;
    ElfW(Sym) *sym = &((ElfW(Sym) *)symtab_section->data)[i];
    return sym->st_shndx != SHN_UNDEF;
}

int link_and_output(const char *outfile, const char *first_file)
{
    (void)first_file;
    if (opt.output_type == OUT_OBJ)
        return write_object_file(outfile) ? 1 : 0;
    add_runtime();
    if (opt.output_type == OUT_DLL) {
        if (nb_errors) return 1;
        return write_exe_file(outfile) ? 1 : 0;
    }
    if (!opt.static_link || 1) {
        check_undefined(1);
    }
    if (nb_errors)
        return 1;
    return write_exe_file(outfile) ? 1 : 0;
}

int run_compiled(int argc, char **argv)
{
    (void)argc; (void)argv;
    add_runtime();
    if (libtcc1_missing)
        return 1;
    check_undefined(1);
    if (!sym_defined("_runmain") && !nb_errors) {
        error_noabort("_runmain not defined");
    } else if (!sym_defined("_runmain") && nb_errors) {
        if (!check_undefined(0))
            error_noabort("_runmain not defined");
    }
    if (nb_errors)
        return 1;
    error_noabort("-run is not supported");
    return 1;
}

int write_exe_file(const char *filename)
{
    int fd;
    unlink(filename);
    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0777);
    if (fd < 0) {
