#include <math.h>

#define MAX 100
#define SQUARE(x) ((x) * (x))

struct node { int key; struct node *left, *right; };

struct node *insert(struct node *root, int key) {
    if (!root) {
        root = calloc(1, sizeof *root);
        root->key = key;
        return root;
    }
    if (key < root->key) root->left = insert(root->left, key);
    else root->right = insert(root->right, key);
    return root;
}

void inorder(struct node *r) { if (!r) return; inorder(r->left); printf("%d ", r->key); inorder(r->right); }

int is_prime(int n) {
    if (n < 2) return 0;
    for (int i = 2; i * i <= n; i++) if (n % i == 0) return 0;
    return 1;
}

int count_words(const char *s) {
    int c = 0, in = 0;
    while (*s) { if (isspace((unsigned char)*s)) in = 0; else if (!in) { in = 1; c++; } s++; }
    return c;
}

int main(void) {
    struct node *root = NULL;
    int vals[] = { 50, 30, 70, 20, 40, 60, 80 };
    for (size_t i = 0; i < sizeof vals / sizeof vals[0]; i++) root = insert(root, vals[i]);
